        // COMMANDS ********************************************************************************
        public void ClearCommand()
        {
            CClear comm = new CClear();
            _commands.AddAndExecute(comm);
        }
        public void ClearResultsCommand()
        {
            CRemoveAllResults comm = new CRemoveAllResults();
