        //******************************************************************************************
        public void DeInitialize()
        {
            New();
            //
            _commands.Clear();
            _allResults.Clear();
        }
        public void Clear()
        {
            _form.CloseAllForms();
            _form.SetTitle(Globals.ProgramName);
            OpenedFileName = null;
            _savingFile = false;
            //
            if (_form != null)
            {
                _form.ClearControls();
                _form.SetCurrentView(_currentView);
            }
            //
            ClearModel();
            ClearResults();
            // Selection
            SetSelectByToDefault();
            _geometrySelectMode = GeometrySelectModeEnum.SelectLocation;
            _selection = new Selection();
            //
            _modelChanged = false;  // must be here since ClearResults can set it to true
        }
        public void ClearModel()
        {
            // Section view
            _sectionViews.ClearModelSectionViews();
            // Exploded view
            _explodedViews.ClearModelExplodedViews();
            // Rotation centers
            _viewNameRotationCenter.Clear();
            // New
            OrderedDictionary<string, EquationParameter> overriddenParameters = null;
            if (_model != null) overriddenParameters = _model.Parameters.OverriddenParameters;
            _model = new FeModel("Model-1", null, true, overriddenParameters);
            //
            SetNewModelProperties(_model.Properties.ModelSpace, _model.UnitSystem.UnitSystemType);   // update widgets
            //
            _annotateWithColor = AnnotateWithColorEnum.None;
            _showItemIds = ShowItemIdsEnum.None;
            _itemIdsSuppressed = false;
            _drawSymbolName = null;
            _jobs.Clear();
            ClearAllSelection();
            //
            _modelChanged = false;
        }
        public void ClearResults()
        {
            // A failed file read leaves the results collection null; the model is recreated the same way
            if (_allResults == null) _allResults = new ResultsCollection();
            // Section view
            _sectionViews.ClearResultsSectionViews();
            // Exploded view
            _explodedViews.ClearResultsExplodedViews();
            // Follower view
            ClearAllFollowerViews();
            // Annotations
            _annotations.RemoveAllResultArrowAnnotations();
            //
            if (_allResults != null && _allResults.Count > 0)
            {
                _modelChanged = true;
                _allResults.Clear();
            }
            //
            _currentFieldData = null;
            //
            if (_settings != null) _settings.ClearColorSpectrums();
            //
            _form.ClearResults();
            //
            if (_currentView == ViewGeometryModelResults.Results) _form.Clear3D();
            //
            ClearAllSelection();
        }
