        //******************************************************************************************
        public void New()
        {
            _currentView = ViewGeometryModelResults.Geometry;
            _openedPmxVersion = 0;
            _defaultMeshTypesDisabled = false;
            // Add and execute the clear command
            _commands.Clear();      // also calls _modelChanged - must be here
            ClearCommand();         // also calls _modelChanged = false; calls SetNewModelProperties()
            // Annotations
            _annotations = new AnnotationContainer(this);
            //
            _form.UpdateRecentFilesThreadSafe();
        }
        public string GetFileNameToOpen(string title)
        {
            return _form.GetFileNameToOpen(title);
        }
        public void Open(string fileName, string parameters = null)
        {
            string extension = Path.GetExtension(fileName).ToLower();
            //
            if (extension == ".pmx") OpenPmx(fileName, parameters);
            else if (extension == ".pmh") OpenPmh(fileName, parameters);
            else if (extension == ".frd") OpenFrd(fileName, parameters);
            else if (extension == ".dat") OpenDat(fileName, parameters);
            else if (extension == ".odb") OpenOdb(fileName, parameters);
            else if (extension == ".foam") OpenFoam(fileName);
            else throw new NotSupportedException();
            // Check validity
            CheckAndUpdateModelValidity();
            // Get first component of the first field for the last increment in the last step
            if (ResultsInitialized)
                CurrentFieldData = _allResults.CurrentResult.GetFirstComponentOfTheFirstFieldAtDefaultIncrement();
            //
            UpdateAfterPartsChanged(); // must be here before any drawing
            //
            UpdateExplodedView(false);
            // Settings
            if (parameters != null && (parameters.Contains(Globals.FromMonitorForm) ||
                                       parameters.Contains(Globals.FromLastSave))) { }
            else AddFileNameToRecentFiles(fileName);
        }
        private void OpenPmx(string fileName, string parameters = null)
        {
            Clear();
            // The 3D scene is empty after the clear and the current view must say so, or a selection
            // performed by the compatibility below is resolved on a scene that was never drawn
            _currentView = ViewGeometryModelResults.Geometry;
            //
            OpenedFileName = fileName;
            //
            Controller tmp = null;
            object[] data = null;
            string fileVersion;
            //
            data = TryReadCompressedPmx(fileName, out _model, out _allResults, out fileVersion);
            if (data != null && data.Length == 1 && ((string)data[0]).StartsWith("IncompatibleVersion"))
            {
                New();
                string[] versionData = ((string)data[0]).Split(new string[] { " " }, StringSplitOptions.RemoveEmptyEntries);
                if (versionData.Length == 2)
                    throw new CaeException("The file cannot be read. It is either corrupt or its version " + versionData[1] +
                                           " is incompatible with this version of PrePoMax.");
                return;
            }
            if (data == null) data = TryReadUncompressedPmx(fileName, out _model, out _allResults);
            if (data == null || data.Length < 3)
            {
                New();
                throw new CaeException("The file cannot be read. It is either corrupt or was created by a previous version.");
            }
            // Compatibility
            ApplyCompatibility();
            // Get controller
            tmp = (Controller)data[0];
            // Regeneration
            if (_batchRegenerationMode) tmp.BatchRegenerationMode = true;
            // Commands
            InitializeNewCommands(tmp._commands);
            // Annotations
            _annotations = new AnnotationContainer(tmp._annotations, this);
            // Jobs
            if (data[1] is OrderedDictionary<string, AnalysisJob> od)
            {
                _jobs = od;
                ResetUnfinishedJobStatuses();
            }
            // Settings
            ApplySettings(); // work folder and executable
            // Determine view
            _currentView = ViewGeometryModelResults.Geometry;
            if (_model != null && _model.Mesh != null && _model.Mesh.Parts.Count > 0)
                _currentView = ViewGeometryModelResults.Model;
            else if (_allResults.Count > 0) _currentView = ViewGeometryModelResults.Results;
            // Set view
            _form.SetCurrentView(_currentView);
            // Regenerate tree
            _form.RegenerateTree(false);
            // Set tree states
            if (data[2] is bool[][] states) _form.SetTreeExpandCollapseState(states);
            // Set pending side panels state; FrmMain restores it after the first draw
            if (parameters == null || !parameters.Contains(Globals.FromLastSave))
            {
                SidePanelsState sidePanelsState = data.Length > 3 ? data[3] as SidePanelsState : null;
                _form.SetPendingSidePanelsState(sidePanelsState);
            }
            // Set user views
            _form.UpdateUserViewsThreadSafe(_model.UserViews.Keys.ToArray());
        }
        private void ApplyCompatibility()
        {
            // Compatibility v2.2.2
            List<InitialVelocity> initialVelocities = new List<InitialVelocity>();
            if (_model != null && _model.InitialConditions != null)
            {
                foreach (var entry in _model.InitialConditions)
                {
                    if (entry.Value is InitialVelocity iv) initialVelocities.Add(iv);
                }
            }
            foreach (var initialVelocity in initialVelocities)
            {
                _model.InitialConditions.Remove(initialVelocity.Name);
                //
                InitialTranslationalVelocity itv = new InitialTranslationalVelocity(initialVelocity);
                itv.RegionType = RegionTypeEnum.Selection;
                itv.CreationData = initialVelocity.CreationData;
                foreach (var node in itv.CreationData.Nodes)
                {
                    if (node is SelectionNodeMouse snm) snm.SelectBy = vtkSelectBy.GeometryPart;
                }
                itv.CreationData.SelectItem = vtkSelectItem.Geometry;
                itv.CreationIds = initialVelocity.CreationIds;
                //
                AddInitialCondition(itv);
            }
            // Compatibility v2.3.4
            UpdateGeometryPartMassProperties(false);
            // Compatibility v2.6.3
            _defaultMeshTypesDisabled = _openedPmxVersion > 0 && _openedPmxVersion < 2_006_003;
            if (_defaultMeshTypesDisabled)
            {
                // The model tree is built after the compatibility, so the items are placed rather than added
                foreach (var netgenMesh in CreateNetgenMeshesForUncoveredParts())
                {
                    _model.Geometry.MeshSetupItems.Add(netgenMesh.Name, netgenMesh);
                    WriteNetgenMeshCompatibilityToOutput(netgenMesh);
                }
            }
        }
        /// <summary>
        /// Meshes a part the user defined no mesh setup item for by Netgen tetrahedra, whatever mesh its
        /// geometry supports, and with the Netgen settings of its meshing parameters rather than those of a
        /// Netgen item, which is how PrePoMax meshed before v2.6.3. It is turned on for a model read
        /// from a file written by such a version, and by the command that stands at the head of the command
        /// history of that model, so that regenerating it produces the mesh it was built with.
        /// </summary>
        public void DisableDefaultMeshTypes()
        {
            _defaultMeshTypesDisabled = true;
        }
        /// <summary>
        /// The solid and shell parts that no mesh setup item meshes, named as they are meshed - a compound part
        /// stands for its sub-parts, since they are meshed as one. A model built before v2.6.3 meshed every one
        /// of them by Netgen, a solid part by tetrahedra whatever mesh its geometry could carry, and with the
        /// Netgen settings its meshing parameters carried. So these are the parts such a model needs the Netgen
        /// item for: without it a solid part would now be swept or meshed transfinitely, a part would lose the
        /// Netgen settings it was meshed with, and the mesh the model was built on would change under the sets,
        /// the boundary conditions and the loads.
        /// </summary>
        private string[] GetPartNamesWithoutMesherSetupItem()
        {
            List<string> partNames = new List<string>();
            if (_model == null || _model.Geometry == null || _model.Geometry.Parts == null) return partNames.ToArray();
            //
            bool meshedByNetgen;
            BasePart meshablePart;
            GeometryPart part;
            string[] meshablePartNames;
            Dictionary<string, string> compoundPartNames = GetCompoundPartNamesBySubPartName();
            foreach (var entry in _model.Geometry.Parts)
            {
                part = entry.Value as GeometryPart;
                // A sub-part is meshed through the compound part that carries it
                if (part == null || compoundPartNames.ContainsKey(part.Name)) continue;
                //
                meshablePartNames = GetMeshablePartNames(new string[] { part.Name });
                if (meshablePartNames == null || meshablePartNames.Length == 0) continue;
                // Only a solid or a shell part is meshed by Netgen without an item
                meshedByNetgen = true;
                foreach (var meshablePartName in meshablePartNames)
                {
                    if (!_model.Geometry.Parts.TryGetValue(meshablePartName, out meshablePart) ||
                        (meshablePart.PartType != PartType.Solid && meshablePart.PartType != PartType.SolidAsShell &&
                         meshablePart.PartType != PartType.Shell))
                    {
                        meshedByNetgen = false;
                        break;
                    }
                }
                if (!meshedByNetgen) continue;
                if (GetUserMesherSetupItems(part.Name).Length > 0) continue;
                //
                partNames.Add(part.Name);
            }
            return partNames.ToArray();
        }
        /// <summary>
        /// Builds the Netgen items for the parts that are still without a mesh setup item, one for each set of
        /// Netgen settings the meshing parameters give those parts, or none when there is no such part. The
        /// parts are read from the model as it stands, so the command that closes the history of an older model
        /// reaches the same ones the reading of that model reached.
        /// </summary>
        private List<NetgenMesh> CreateNetgenMeshesForUncoveredParts()
        {
            List<NetgenMesh> netgenMeshes = new List<NetgenMesh>();
            if (_model == null || _model.Geometry == null || _model.Geometry.Parts == null) return netgenMeshes;
            //
            NetgenMesh partNetgenMesh;
            NetgenMesh netgenMesh;
            Dictionary<NetgenMesh, List<int>> partIdsByNetgenMesh = new Dictionary<NetgenMesh, List<int>>();
            foreach (var partName in GetPartNamesWithoutMesherSetupItem())
            {
                partNetgenMesh = new NetgenMesh("tmpName");
                partNetgenMesh.CopyNetgenValuesFrom(GetPartMeshingParameters(partName));
                //
                netgenMesh = netgenMeshes.FirstOrDefault(item => item.HasSameNetgenValues(partNetgenMesh));
                if (netgenMesh == null)
                {
                    netgenMesh = partNetgenMesh;
                    netgenMeshes.Add(netgenMesh);
                    partIdsByNetgenMesh.Add(netgenMesh, new List<int>());
                }
                partIdsByNetgenMesh[netgenMesh].AddRange(
                    _model.Geometry.GetPartIdsFomPartNames(GetMeshablePartNames(new string[] { partName })));
            }
            //
            Selection selection;
            HashSet<string> names = new HashSet<string>(_model.Geometry.MeshSetupItems.Keys);
            foreach (var item in netgenMeshes)
            {
                item.Name = names.GetNextNumberedKey("Netgen_Mesh");
                names.Add(item.Name);
                item.CreationIds = partIdsByNetgenMesh[item].ToArray();
                //
                selection = new Selection();
                selection.CurrentView = (int)ViewGeometryModelResults.Geometry;
                selection.SelectItem = vtkSelectItem.Part;
                selection.Add(new SelectionNodeIds(vtkSelectOperation.None, false, item.CreationIds));
                item.CreationData = selection;
            }
            //
            return netgenMeshes;
        }
        /// <summary>
        /// Adds the Netgen items of an older model while its command history is replayed. It is called by the
        /// command that closes the history of such a model.
        /// </summary>
        public NetgenMesh[] AddNetgenMeshesToUncoveredParts()
        {
            List<NetgenMesh> netgenMeshes = CreateNetgenMeshesForUncoveredParts();
            foreach (var netgenMesh in netgenMeshes)
            {
                AddMeshSetupItem(netgenMesh);
                WriteNetgenMeshCompatibilityToOutput(netgenMesh);
            }
            //
            return netgenMeshes.ToArray();
        }
        private void WriteNetgenMeshCompatibilityToOutput(NetgenMesh netgenMesh)
        {
            _form.WriteDataToOutput("Compatibility: the model was created by a version of PrePoMax in which a " +
                                    "part without a mesh setup item was meshed by Netgen with the Netgen " +
                                    "settings of the meshing parameters. The mesh setup item " + netgenMesh.Name +
                                    " was added to keep that mesh for " + netgenMesh.CreationIds.Length +
                                    " part/s.");
        }
        /// <summary>
        /// Gives the command history of a model built before v2.6.3 the two commands that keep its mesh. The
        /// first one heads the history and meshes every part without a mesh setup item by Netgen tetrahedra,
        /// the way that version did, which is what the meshing commands replayed after it need. The second
        /// one closes the history and adds the mesh setup item that says the same thing, which is what the
        /// model is left with and what it is read back by.
        /// The commands are written into the history once and are then part of it, so a model already
        /// carrying them only tells this session to mesh the way they do.
        /// </summary>
        private void AddDefaultMeshTypeCompatibilityCommands(CommandsCollection commandsCollection)
        {
            if (commandsCollection == null || commandsCollection.Commands == null) return;
            //
            foreach (var command in commandsCollection.Commands)
            {
                if (command is CDisableDefaultMeshTypes)
                {
                    _defaultMeshTypesDisabled = true;
                    return;
                }
            }
            if (!_defaultMeshTypesDisabled) return;
            //
            commandsCollection.InsertCommand(0, new CDisableDefaultMeshTypes());
            commandsCollection.InsertCommand(commandsCollection.Commands.Count,
                                             new CAddNetgenMeshToUncoveredParts());
        }
        private void InitializeNewCommands(CommandsCollection commandsCollection)
        {
            ApplyCompatibilityToCommands(commandsCollection);
            //
            _commands.EnableDisableUndoRedo -= _commands_CommandExecuted;
            _commands = new CommandsCollection(this, commandsCollection); // to recreate the history file
            _commands.WriteOutput = _form.WriteDataToOutput;
            _commands.EnableDisableUndoRedo += _commands_CommandExecuted;
            _commands.OnEnableDisableUndoRedo();
        }
        private void ApplyCompatibilityToCommands(CommandsCollection commandsCollection)
        {
            // Compatibility v2.6.3
            AddDefaultMeshTypeCompatibilityCommands(commandsCollection);
            // Compatibility v2.4.4
            if (commandsCollection != null)
            {
                foreach (var command in commandsCollection.Commands)
                {
                    if (command is CAddMeshSetupItem amsi && amsi.MeshSetupItem is FeMeshRefinement mr1)
                    {
                        amsi.MeshSetupItem = new LocalMeshSize(mr1);
                    }
                    else if (command is CReplaceMeshSetupItem rmsi && rmsi.MeshSetupItem is FeMeshRefinement mr2)
                    {
                        rmsi.MeshSetupItem = new LocalMeshSize(mr2);
                    }
                    else if (command is CAddResultHistoryOutput arho &&
                             arho.ResultHistoryOutput is ResultHistoryOutputFromEquation rhofe1)
                    {
                        rhofe1.FixHOFieldNames();
                    }
                    else if (command is CReplaceResultHistoryOutput rrho &&
                             rrho.NewResultHistoryOutput is ResultHistoryOutputFromEquation rhofe2)
                    {
                        rhofe2.FixHOFieldNames();
                    }
                }
            }
        }
        private void OpenPmh(string fileName, string parameters)
        {
            New();
            //
            InitializeNewCommands(null);
            _commands.ReadFromFile(fileName);
            //
            RegenerateTypeEnum regenerateType;
            if (parameters != null && (parameters.Contains(Globals.RegenerateAll) || parameters.Contains(Globals.FromFileOpenMenu)))
                regenerateType = RegenerateTypeEnum.All;
            else regenerateType = RegenerateTypeEnum.PreProcess;
            //
            ExecuteCommandsFromLastSave(regenerateType, false);
            //
            _commands.OnEnableDisableUndoRedo();
            // Model changed
            _modelChanged = true;
        }
        // Replays the history up to the current position, starting from the last saved file that holds the state the
        // commands before it build
        private bool ExecuteCommandsFromLastSave(RegenerateTypeEnum regenerateType, bool keepSessionState)
        {
            CSaveToPmx lastSave = _commands.GetLastSaveCommand(regenerateType);
            if (lastSave != null)
            {
                string fileName = Tools.GetGlobalPath(lastSave.FileName);
                string parameters = keepSessionState ? Globals.FromLastSave : null;
                CommandsCollection prevCommands = new CommandsCollection(this, _commands);
                bool opened = false;
                try
                {
                    // Form open redraws the scene
                    _form.Open(fileName, Open, !keepSessionState, parameters);
                    opened = true;
                }
                catch (Exception ex)
                {
                    _form.WriteDataToOutput("The saved file " + fileName + " could not be opened, so the whole " +
                                            "history is replayed: " + ex.Message);
                }
                //
                InitializeNewCommands(prevCommands);
                //
                if (opened)
                {
                    _commands.ExecuteAllCommandsFromLastSave(regenerateType, lastSave);
                    return true;
                }
            }
            //
            _commands.ExecuteAllCommands(false, false, regenerateType);
            return false;
        }
        private void OpenFrd(string fileName, string parameters)
        {
            FeResults results;
            bool useWearResults = _wearResults != null;
            bool readDatFile = !useWearResults && !(parameters != null && parameters.Contains(Globals.FromAbaqus));
            //
            _watch = Stopwatch.StartNew();
            //
            if (useWearResults)
            {
                results = _wearResults;
                _wearResults = null;
            }
            else
            {
                results = (FeResults)OpenByFunction(fileName, parameters, FrdFileReader.Read);
                if (results != null) results.FileName = fileName;    // fix file name if a copy was used
            }
            //
            bool resultsExist = results != null && results.Mesh != null;
            if (resultsExist) LoadResults(results, parameters, readDatFile);
            //
            _watch.Stop();
            _commands.SetLastOpenResultsTime(_watch.Elapsed);
            //
            if (!resultsExist)
            {
                if (_batchRegenerationMode) _commands.Errors.Add("The result file does not exist or is empty.");
                else throw new CaeException("The result file does not exist or is empty.");
            }
        }
        private void OpenDat(string fileName, string parameters, bool redraw = true)
        {
            try
            {
                if (_allResults.CurrentResult == null)
                    _allResults.Add(fileName, new FeResults(fileName, _model.UnitSystem));
                // This is also called in AppendResults
                HistoryResults results = (HistoryResults)OpenByFunction(fileName, parameters, ReadHistoryResults);
                _allResults.CurrentResult.SetHistory(results);
                // Wear
                _allResults.CurrentResult.ComputeWear(_model.StepCollection.GetSlipWearStepIds(),
                                                      _model.GetNodalSlipWearCoefficients(),
                                                      (int)_model.Properties.NumOfSmoothingSteps.Value,
                                                      null);
                //
                if (_allResults.CurrentResult.GetHistory() == null)
                {
                    MessageBoxes.ShowError("The dat file does not exist or is empty.");
                    return;
                }
                else
                {
                    if (redraw)
                    {
                        // Set the view but do not draw
                        _currentView = ViewGeometryModelResults.Results;
                        _form.SetCurrentView(_currentView);
                        // Regenerate tree
                        _form.RegenerateTree();
                    }
                    // Model changed
                    _modelChanged = true;
                }
            }
            // Do not throw error in order to open the results
            catch
            {
                MessageBoxes.ShowError($"Could not load {fileName}");
            }
        }
        private void OpenCel(string fileName, bool redraw = true)
        {
            Dictionary<int, FeElement> elements;
            Dictionary<string, FeElementSet> elementSets;
            FileInOut.Input.InpFileReader.ReadCel(fileName, out elements, out elementSets);
            //
            if (elements == null)
            {
                MessageBoxes.ShowError("The cel file does not exist or is empty.");
                return;
            }
            else
            {
                Dictionary<string, FeNodeSet> nodeSets = GetNodeSetsFromCelElements(_allResults.CurrentResult.Mesh.Nodes,
                                                                                    elements,
                                                                                    elementSets);
                _allResults.CurrentResult.Mesh.NodeSets.AddRange(nodeSets);
                //
                if (redraw)
                {
                    // Set the view but do not draw
                    _currentView = ViewGeometryModelResults.Results;
                    _form.SetCurrentView(_currentView);
                    // Regenerate tree
                    _form.RegenerateTree();

                }
                // Model changed
                _modelChanged = true;
            }
        }
        private void OpenNam(string fileName, bool redraw = true)
        {
            string[] nodeSetNames;
            int[][] nodeIds;
            FileInOut.Input.InpFileReader.ReadNam(fileName, out nodeSetNames, out nodeIds);
            //
            if (nodeSetNames == null || nodeSetNames.Length == 0)
            {
                MessageBoxes.ShowError("The file " + fileName + " does not exist or is empty.");
                return;
            }
            else
            {
                string name;
                HashSet<string> existingNames = _allResults.CurrentResult.Mesh.NodeSets.Keys.ToHashSet();
                Dictionary<string, FeNodeSet> nodeSets = new Dictionary<string, FeNodeSet>();
                HashSet<int> allNodeIds = CurrentResult.Mesh.Nodes.Keys.ToHashSet();
                for (int i = 0; i < nodeSetNames.Length; i++)
                {
                    name = nodeSetNames[i];
                    if (existingNames.Contains(name)) name = _allResults.CurrentResult.Mesh.NodeSets.GetNextNumberedKey(name);
                    //
                    nodeIds[i] = allNodeIds.Intersect(nodeIds[i]).ToArray();    // keep only existing nodes - exploded shell
                    nodeSets.Add(name, new FeNodeSet(name, nodeIds[i]));
                }
                _allResults.CurrentResult.Mesh.NodeSets.AddRange(nodeSets);
                //
                if (redraw)
                {
                    // Set the view but do not draw
                    _currentView = ViewGeometryModelResults.Results;
                    _form.SetCurrentView(_currentView);
                    // Regenerate tree
                    _form.RegenerateTree();

                }
                // Model changed
                _modelChanged = true;
            }
        }
        private void OpenOdb(string fileName, string parameters)
        {
            if (ConvertOdbToFrd(fileName))
            {
                if (parameters == null) parameters = Globals.FromAbaqus;
                else parameters += Globals.NameSeparator + Globals.FromAbaqus;
                //
                fileName = Path.Combine(Path.GetDirectoryName(fileName), Path.GetFileNameWithoutExtension(fileName) + ".frd");
                OpenFrd(fileName, parameters);
            }
        }
        // Abaqus
        public bool ConvertOdbToFrd(string fileName)
        {
            _form.WriteDataToOutput("");
            // Get the work directory
            string workDirectory = Path.GetDirectoryName(fileName);
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return false;
            }
            // Get the Abaqus executable
            string executable = _settings.Solver.AbaqusExe;
            if (executable == null || !File.Exists(executable))
            {
                MessageBoxes.ShowError("The Abaqus executable does not exist!");
                return false;
            }
            // Get the base script file
            string scriptFileName = Application.StartupPath + Globals.OdbToFrd;
            if (scriptFileName == null || !File.Exists(scriptFileName))
            {
                MessageBoxes.ShowError("The file " + scriptFileName + " does not exist!");
                return false;
            }
            //
            string argument = "cae noGUI=\"" + scriptFileName + "\" -- \"" + fileName + "\"";
            //
            bool jobCompleted;
            JobStatus jobStatus = _jobRunner.Run("OdbToFrd", executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            jobCompleted = jobStatus == JobStatus.OK;
            //
            if (jobCompleted)
            {
                return true;
            }
            else return false;
        }
        private void OpenFoam(string fileName)
        {
            FeResults results = OpenFoamFileReader.Read(fileName, _model.UnitSystem);
            if (results == null) throw new CaeException("The results file cannot be read.");
            // Load results
            _form.Clear3D();
            ClearResults();
            //
            _allResults.Add(results.FileName, results);
            // Model changed
            _modelChanged = true;
            // Redraw
            // Set the view but do not draw
            _currentView = ViewGeometryModelResults.Results;
            _form.SetCurrentView(_currentView);
            // Regenerate tree
            _form.RegenerateTree();
        }
        private object OpenByFunction(string fileName, string parameters, Func<string, object> Open)
        {
            object results = null;
            string oldFileName = fileName;
            bool useCopy = parameters != null && parameters.Contains(Globals.OpenRunningJobResults);
            //
            try
            {
                if (useCopy)
                {
                    fileName = fileName.Insert(fileName.Length - 4, "_copy");
                    File.Copy(oldFileName, fileName);
                }
                results = Open(fileName);
            }
            catch (Exception ex)
            {
                throw ex;
            }
            finally
            {
                if (useCopy) File.Delete(fileName);
            }
            //
            return results;
        }
        private void LoadResults(FeResults results, string parameters, bool readDatFile)
        {
            // Load results
            _form.Clear3D();
            if (_allResults.Count == 0) ClearResults();
            _allResults.Add(results.FileName, results);
            // Check if the meshes are the same and rename the parts
            if (_model.Mesh != null && _allResults.CurrentResult.Mesh != null &&
                _model.HashName == _allResults.CurrentResult.HashName)
            {
                SuppressExplodedView();
                //
                bool nodeCoordinatesChanged;
                ConvertPyramidsToEnum convertPyramidsTo = Settings.Solver.ConvertPyramidsTo;
                string[] mappedPartNames = _allResults.CurrentResult.CopyPartsFromMesh(_model.Mesh, convertPyramidsTo,
                                                                                       out nodeCoordinatesChanged);
                if (mappedPartNames.Length == _model.Mesh.Parts.Count)
                    _allResults.CurrentResult.CopyMeshItemsFromMesh(_model.Mesh, convertPyramidsTo);
                //
                WriteResultPartMappingToOutput(mappedPartNames, nodeCoordinatesChanged);
                //
                bool fromFileOpenMenu = parameters != null && parameters.Contains(Globals.FromFileOpenMenu);
                if (!fromFileOpenMenu)
                {
                    _allResults.CurrentResult.CopyFeatureItemsFromMesh(_model.Mesh, (int)ViewGeometryModelResults.Results);
                }
                //
                ResumeExplodedViews(false); // must be here after the parts were mapped
            }
            // Model changed
            _modelChanged = true;
            // Open .cel file
            if (_allResults.CurrentResult.FileName != null && _allResults.CurrentResult.FileName.Length > 0)
            {
                string celFileName = Path.GetFileNameWithoutExtension(_allResults.CurrentResult.FileName) + ".cel";
                celFileName = Path.Combine(Path.GetDirectoryName(_allResults.CurrentResult.FileName), celFileName);
                if (File.Exists(celFileName)) OpenCel(celFileName, false);
            }
            // Open .nam file
            if (_allResults.CurrentResult.FileName != null && _allResults.CurrentResult.FileName.Length > 0)
            {
                string namFileName = Path.GetFileNameWithoutExtension(_allResults.CurrentResult.FileName) +
                                     "_WarnNodeMissTiedContact.nam";
                namFileName = Path.Combine(Path.GetDirectoryName(_allResults.CurrentResult.FileName), namFileName);
                if (File.Exists(namFileName)) OpenNam(namFileName, false);
            }
            // Open .dat file
            if (readDatFile)
            {
                string datFileName = Path.GetFileNameWithoutExtension(_allResults.CurrentResult.FileName) + ".dat";
                datFileName = Path.Combine(Path.GetDirectoryName(_allResults.CurrentResult.FileName), datFileName);
                if (File.Exists(datFileName)) OpenDat(datFileName, parameters, false);
            }
            //
            UpdateAfterPartsChanged(); // must be here before any drawing
            // Redraw
            // Set the view but do not draw
            _currentView = ViewGeometryModelResults.Results;
            _form.SetCurrentView(_currentView);
            // Select result symbols
            _drawSymbolName = Globals.SymbolResult;
            _form.SelectOneNameInSymbolsNames(_drawSymbolName);
            // Regenerate tree
            _form.RegenerateTree();
        }
        private void WriteResultPartMappingToOutput(string[] mappedPartNames, bool nodeCoordinatesChanged)
        {
            HashSet<string> mappedNames = new HashSet<string>(mappedPartNames);
            //
            if (mappedNames.Count < _model.Mesh.Parts.Count)
            {
                _form.WriteDataToOutput("Result parts: the model mesh properties were applied to " + mappedNames.Count +
                                        " of " + _model.Mesh.Parts.Count + " model parts.");
                foreach (var entry in _model.Mesh.Parts)
                {
                    if (!mappedNames.Contains(entry.Key))
                        _form.WriteDataToOutput("Result parts: the model part " + entry.Key +
                                                " was not found in the result mesh.");
                }
            }
            //
            if (nodeCoordinatesChanged)
                _form.WriteDataToOutput("Result parts: the node coordinates in the result file are different from the " +
                                        "model mesh coordinates; the part volumes and areas were recomputed from the " +
                                        "result mesh.");
        }
        public void AppendResult(string fileName, string parameters = null)
        {
            if (_allResults != null && _allResults.Count == 0) Open(fileName);
            else
            {
                FeResults results = FrdFileReader.Read(fileName);
                // Open .dat file
                string datFileName = Path.GetFileNameWithoutExtension(results.FileName) + ".dat";
                datFileName = Path.Combine(Path.GetDirectoryName(results.FileName), datFileName);
                if (File.Exists(datFileName)) results.SetHistory(ReadHistoryResults(datFileName));
                // Check if the meshes are the same and rename the parts
                if (_allResults.CurrentResult.Mesh != null && results.Mesh != null)
                {
                    SuppressExplodedView();
                    //
                    bool nodeCoordinatesChanged;
                    ConvertPyramidsToEnum convertPyramidsTo = Settings.Solver.ConvertPyramidsTo;
                    string[] mappedPartNames = results.CopyPartsFromMesh(_allResults.CurrentResult.Mesh, convertPyramidsTo,
                                                                        out nodeCoordinatesChanged);
                    //
                    bool allPartsMapped = mappedPartNames.Length == _allResults.CurrentResult.Mesh.Parts.Count;
                    if (allPartsMapped) _allResults.CurrentResult.AddResults(results);
                    // First resume exploded view
                    ResumeExplodedViews(false); // must be here after the parts were mapped
                    //
                    if (!allPartsMapped)
                    {
                        // Do not show error!
                        throw new CaeException("The selected result file does not have the same mesh as the current result.");
                    }
                }
                //
                UpdateAfterPartsChanged(); // must be here before any drawing
                // Model changed
                _modelChanged = true;
                // Redraw
                // Set the view but do not draw
                _currentView = ViewGeometryModelResults.Results;
                _form.SetCurrentView(_currentView);
                // Regenerate tree
                _form.RegenerateTree();
                //
                // Get first component of the first field for the last increment in the last step
                if (ResultsInitialized)
                    CurrentFieldData = _allResults.CurrentResult.GetFirstComponentOfTheFirstFieldAtDefaultIncrement();
            }
        }
        private Dictionary<string, FeNodeSet> GetNodeSetsFromCelElements(Dictionary<int, FeNode> nodes,
                                                                         Dictionary<int, FeElement> elements,
                                                                         Dictionary<string, FeElementSet> elementSets)
        {
            int count = 0;
            HashSet<int> nodeIds = new HashSet<int>();
            Dictionary<string, FeNodeSet> nodeSets = new Dictionary<string, FeNodeSet>();
            //
            foreach (var entry in elementSets)
            {
                nodeIds.Clear();
                foreach (var elementId in entry.Value.Labels) nodeIds.UnionWith(elements[elementId].NodeIds);
                nodeIds.IntersectWith(nodes.Keys);
                nodeSets.Add(entry.Key, new FeNodeSet(entry.Key, nodeIds.ToArray()));
                count += nodeIds.Count();
            }
            //
            if (count == 0) MessageBoxes.ShowWarning("Turn on the 3D output option in the field outputs " +
                                                     "to enable viewing of the contact element nodes.");
            //
            return nodeSets;
        }
        private HistoryResults ReadHistoryResults(string fileName)
        {
            string[] errors;
            HistoryResults historyResults = DatFileReader.Read(fileName, out errors);
            // Report errors
            if (errors != null && errors.Length > 0)
            {
                _form.WriteDataToOutput("");
                _form.WriteDataToOutput("*** Warning ***");
                _form.WriteDataToOutput("");
                foreach (string error in errors) _form.WriteDataToOutput(error);
                //
                MessageBoxes.ShowWarning("Reading the .dat file " + fileName + " produced some errors. " +
                                         "Please see the output window for more details.");
            }
            return historyResults;
        }
        // Read pmx
        private void GetPmxFileVersion(string fileName, out string programmNameVersion, out string suffix)
        {
            programmNameVersion = null;
            suffix = null;
            //
            int major = 0;
            int minor = 0;
            int build = 0;
            try
            {
                byte[] versionBuffer = new byte[32];
                using (FileStream fs = new FileStream(fileName, FileMode.Open))
                {
                    fs.Read(versionBuffer, 0, 32);
                    programmNameVersion = Encoding.ASCII.GetString(versionBuffer).TrimEnd(new char[] { '\0' });
                    //
                    string[] versions = programmNameVersion.Split(new string[] { " ", ".", "v" },
                                                                  StringSplitOptions.RemoveEmptyEntries);
                    int.TryParse(versions[1], out major);
                    int.TryParse(versions[2], out minor);
                    int.TryParse(versions[3], out build);
                    //
                    suffix = $"_v{major}.{minor}.{build}";
                }
            }
            catch (Exception ex)
            {
            }
        }
        private object[] TryReadCompressedPmx(string fileName, out FeModel model, out ResultsCollection allResults,
                                              out string programmNameVersion)
        {
            model = null;
            allResults = null;
            programmNameVersion = null;
            _openedPmxVersion = 0;
            //
            int major = 0;
            int minor = 0;
            int build = 0;
            try
            {
                object[] data = null;
                Controller tmp = null;
                byte[] versionBuffer = new byte[32];
                using (FileStream fs = new FileStream(fileName, FileMode.Open))
                {
                    fs.Read(versionBuffer, 0, 32);
                    programmNameVersion = Encoding.ASCII.GetString(versionBuffer).TrimEnd(new char[] { '\0' });
                    //
                    if (programmNameVersion != Globals.ProgramName)
                    {
                        _form.WriteDataToOutput("Warning: The opened file is from an incompatible version: " + programmNameVersion);
                        _form.WriteDataToOutput("Some items might not be loaded correctly. Check the model.");
                    }
                    //
                    string[] versionNumbers = programmNameVersion.Split(new string[] { " ", ".", "v" },
                                                                  StringSplitOptions.RemoveEmptyEntries);

                    int.TryParse(versionNumbers[1], out major);
                    int.TryParse(versionNumbers[2], out minor);
                    int.TryParse(versionNumbers[3], out build);
                    //
                    int version = major * 1_000_000 + minor * 1000 + build;
                    _openedPmxVersion = version;
                    //
                    if (version < 2_000_006)
                        data = TryReadCompressedPmxBefore_2_0_6(fs, version, out model, out allResults);
                    else
                        data = TryReadCompressedPmxAfter_2_0_6(fs, version, out model, out allResults);
                    //
                    if (data == null || model == null)
                        throw new CaeException("IncompatibleVersion");
                    //
                    model.UpdateMeshPartsElementTypes(true);
                    //
                    if (version < 2_003_002 && model != null && model.Mesh != null) model.Mesh.ComputeVolumeArea();
                }
                return data;
            }
            catch (Exception ex)
            {
                if (ex.Message == "IncompatibleVersion")
                    return new object[] { ex.Message + string.Format(" {0}.{1}.{2}", major, minor, build) };
                else return null;
            }
        }
        private object[] TryReadCompressedPmxBefore_2_0_6(FileStream fs, int version, out FeModel model,
                                                          out ResultsCollection allResults)
        {
            model = null;
            allResults = null;
            //
            try
            {
                object[] data = null;
                Controller tmp = null;
                bool oldResults = false;
                //
                using (BinaryReader br = new BinaryReader(Tools.Decompress(fs)))
                {
                    data = Tools.LoadDumpFromFile<object[]>(br);
                    tmp = (Controller)data[0];
                    model = tmp._model;
                    // Compatibility v.1.3.5
                    Selection selection;
                    foreach (var entry in model.Geometry.Parts)
                    {
                        if (entry.Value is GeometryPart gp && gp.MeshingParameters != null)
                        {
                            gp.MeshingParameters.FactorMax = MeshingParameters.DefaultFactorMax;
                            gp.MeshingParameters.FactorMin = MeshingParameters.DefaultFactorMin;
                            gp.MeshingParameters.SetCheckName(true);
                            string name = model.Geometry.MeshSetupItems.GetNextNumberedKey("Meshing_Parameters");
                            gp.MeshingParameters.Name = name;
                            gp.MeshingParameters.Active = true;
                            gp.MeshingParameters.Visible = true;
                            gp.MeshingParameters.Valid = true;
                            gp.MeshingParameters.Internal = false;
                            //
                            gp.MeshingParameters.CreationIds = new int[] { gp.PartId };
                            selection = new Selection();
                            selection.CurrentView = (int)ViewGeometryModelResults.Geometry;
                            selection.SelectItem = vtkSelectItem.Part;
                            selection.Add(new SelectionNodeIds(vtkSelectOperation.None, false,
                                                                gp.MeshingParameters.CreationIds));
                            gp.MeshingParameters.CreationData = selection;
                            //
                            model.Geometry.MeshSetupItems.Add(gp.MeshingParameters.Name, gp.MeshingParameters.DeepClone());
                            gp.MeshingParameters = null;
                        }
                    }
                    // Compatibility v.1.3.3
                    if (tmp._allResults == null)
                    {
                        oldResults = true;
                        allResults = new ResultsCollection();
                        if (tmp._results != null)
                        {
                            if (tmp._results.HashName == null) tmp._results.HashName = tmp._results.FileName;
                            allResults.Add(tmp._results.HashName, tmp._results);
                        }
                    }
                    else allResults = tmp._allResults;
                    //
                    FeModel.ReadFromBinaryReader(model, br, version);
                    //
                    if (oldResults) FeResults.ReadFromBinaryReader(allResults.CurrentResult, br, version);
                    else if (ResultsCollection.ReadFromBinaryReader(allResults, br, version)) { }
                    else
                    {
                        _form.WriteDataToOutput("Warning: There were errors reading the results.");
                        _form.WriteDataToOutput("Some results might not be loaded correctly. Check the results.");
                    }
                }
                //
                return data;
            }
            catch (Exception ex)
            {
                if (ex.Message == "IncompatibleVersion") return new object[] { ex.Message };
                else return null;
            }
        }
        private object[] TryReadCompressedPmxAfter_2_0_6(FileStream fileStream, int version, out FeModel model,
                                                         out ResultsCollection allResults)
        {
            model = null;
            allResults = null;
            //
            try
            {
                object[] data = null;
                Controller tmp = null;
                //
                byte[] buffer = new byte[4];
                fileStream.Read(buffer, 0, buffer.Length);
                int length = BitConverter.ToInt32(buffer, 0);
                //
                buffer = new byte[length];
                fileStream.Read(buffer, 0, buffer.Length);
                //
                using (MemoryStream memoryStream = new MemoryStream(buffer))
                using (BinaryReader br = new BinaryReader(Tools.Decompress(memoryStream)))
                {
                    data = Tools.LoadDumpFromFile<object[]>(br);
                    tmp = (Controller)data[0];
                    model = tmp._model;
                    allResults = tmp._allResults;
                    //
                    FeModel.ReadFromBinaryReader(model, br, version);
                    //
                    if (!ResultsCollection.ReadFromFileStream(allResults, fileStream, version))
                    {
                        _form.WriteDataToOutput("Warning: There were errors reading the results.");
                        _form.WriteDataToOutput("Some results might not be loaded correctly. Check the results.");
                    }
                    //
                    UpdateNCalcParameters(false);
                }
                //
                return data;
            }
            catch (Exception ex)
            {
                if (ex.Message == "IncompatibleVersion") return new object[] { ex.Message };
                else return null;
            }
        }
        private object[] TryReadUncompressedPmx(string fileName, out FeModel model, out ResultsCollection allResults)
        {
            allResults = new ResultsCollection();
            //
            try
            {
                object[] data = null;
                Controller tmp = null;
                //
                using (FileStream fs = new FileStream(fileName, FileMode.Open))
                using (BinaryReader br = new BinaryReader(fs))
                {
                    data = Tools.LoadDumpFromFile<object[]>(br);
                    tmp = (Controller)data[0];
                    model = tmp._model;
                    allResults.Add(tmp._results.FileName, tmp._results);
                    //
                    FeModel.ReadFromBinaryReader(model, br, 0_000_000);
                    FeResults.ReadFromBinaryReader(allResults.CurrentResult, br, 0_000_000);
                }
                //
                model.UpdateMeshPartsElementTypes(true);
                //
                return data;
            }
            catch
            {
                model = null;
                return null;
            }
        }
        private void UpdateGeometryPartMassProperties(bool showError = true)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return;
            }
            //
            string visFileName;
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            //
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is GeometryPart gp)
                {
                    if (gp.IsCADPart && gp.MassProperties.CenterOfMass == null)
                    {
                        File.WriteAllText(brepFileName, gp.CADFileData);
                        visFileName = CreateVisFile(brepFileName, showError);
                        _model.UpdateGeometryPartMassPropertiesFromVisFile(visFileName, gp.Name);
                    }   
                }
            }
        }
        // Run history
        public void RunHistoryFile(string fileName)
        {
            ViewGeometryModelResults prevView = _currentView;
            //
            List<Command> commands;
            CommandsCollection.ReadFromFile(fileName, out commands);
            //
            _commands.AddAndExecute(commands);
            //
            ViewGeometryModelResults newView;
            Command lastCommand = _commands.GetLastExecutedCommand(RegenerateTypeEnum.All);
            if (lastCommand is null || lastCommand is SaveCommand) newView = prevView;
            else if (lastCommand is GeneralCommand) newView = _currentView;
            else if (lastCommand is PreprocessCommand) newView = ViewGeometryModelResults.Model;
            else if (lastCommand is AnalysisCommand) newView = ViewGeometryModelResults.Model;
            else if (lastCommand is PostprocessCommand) newView = ViewGeometryModelResults.Results;
            else throw new NotSupportedException();
            // Make sure the view is updated
            if (_currentView == newView)
            {
                if (newView == ViewGeometryModelResults.Geometry) _currentView = ViewGeometryModelResults.Model;
                else _currentView = ViewGeometryModelResults.Geometry;
            }
            // Set view
            CurrentView = newView;
        }
        // Import
        public string GetFileNameToImport(string title, bool onlyMaterials)
        {
            return _form.GetFileNameToImport(title, onlyMaterials);
        }
        public async Task ImportFileAsync(string fileName, bool onlyMaterials)
        {
            await Task.Run(() => ImportFileCommand(fileName, onlyMaterials));
        }
        public void ImportFile(string fileName, bool onlyMaterials)
        {
            if (!File.Exists(fileName)) throw new FileNotFoundException("The file: '" + fileName + "' does not exist.");
            //
            string extension = Path.GetExtension(fileName).ToLower();
            // Import
            if (extension == ".stl")
            {
                string[] addedPartNames = _model.ImportGeometryFromStlFile(fileName);
                if (addedPartNames == null)
                {
                    AutoClosingMessageBox.ShowError("There are errors in the imported geometry.", 3000);
                }
                else
                {
                    List<string> largeModels = new List<string>();
                    foreach (var partName in addedPartNames)
                    {
                        if (_model.Geometry.Parts[partName].Labels.Length > 1E5) largeModels.Add(partName);
                    }
                    if (largeModels.Count > 0)
                    {
                        _form.WriteDataToOutput("Feature edge detection was turned off due to a high number of .stl triangles.");
                        _form.WriteDataToOutput("Use the following menu to turn it back on: Geometry -> Find Model Edges by Angle");
                    }
                }
            }
            else if (extension == ".stp" || extension == ".step")
                ImportCADAssemblyFile(fileName, "STEP_ASSEMBLY_SPLIT_TO_COMPOUNDS");
            else if (extension == ".igs" || extension == ".iges")
                ImportCADAssemblyFile(fileName, "IGES_ASSEMBLY_SPLIT_TO_COMPOUNDS");
            else if (extension == ".brep")
                ImportCADAssemblyFile(fileName, "BREP_ASSEMBLY_SPLIT_TO_COMPOUNDS");
            else if (extension == ".vol")
                _model.ImportMeshFromVolFile(fileName);
            else if (extension == ".mesh")
                _model.ImportMeshFromMmgFile(fileName);
            else if (extension == ".inp" && onlyMaterials)
            {
                _errors = _model.ImportMaterialsFromInpFile(fileName, _form.WriteDataToOutput);
                _warnings = FileInOut.Input.InpFileReader.Warnings;
            }
            else if (extension == ".inp")
            {
                _errors = _model.ImportModelFromInpFile(fileName, _form.WriteDataToOutput);
                _warnings = FileInOut.Input.InpFileReader.Warnings;
            }
            else if (extension == ".unv")
                _model.ImportMeshFromUnvFile(fileName);
            else if (extension == ".obj")
                _model.ImportMeshFromObjFile(fileName);
            else if (extension == ".pmp")
                ImportParametersFromFile(fileName);
            else throw new NotSupportedException();
            //
            UpdateAfterImport(extension);
        }
        internal void UpdateAfterImport(string extension)
        {
            UpdateAfterPartsChanged(); // must be here before any drawing
            // Exploded view
            UpdateExplodedView(false);
            // Visualization
            if (extension == ".stl" || extension == ".stp" || extension == ".step" ||
                extension == ".igs" || extension == ".iges" || extension == ".brep")
            {
                _currentView = ViewGeometryModelResults.Geometry;
                _form.SetCurrentView(_currentView);
                DrawGeometry(false);
            }
            else if (extension == ".unv" || extension == ".vol" || extension == ".inp" || extension == ".mesh" ||
                     extension == ".obj")
            {
                // Element types
                _model.UpdateMeshPartsElementTypes(true);
                //
                _currentView = ViewGeometryModelResults.Model;
                _form.SetCurrentView(_currentView);
                DrawModel(false);
            }
            // Regenerate
            _form.RegenerateTree();
            //
            if (extension == ".inp") CheckAndUpdateModelValidity();  // must be here at the last place
        }
        public string[] ImportCADAssemblyFile(string assemblyFileName, string splitCommand,
                                              int numOfSplitFacesOverride = -1)
        {
            string[] filesToImport = SplitAssembly(assemblyFileName, splitCommand, numOfSplitFacesOverride);
            string[] addedPartNames;
            List<string> allAddedPartNames = new List<string>();
            //
            if (filesToImport != null)
            {
                foreach (var partFileName in filesToImport)
                {
                    try
                    {
                        if (Path.GetFileName(partFileName).ToLower().Contains("compound"))
                        {
                            ImportBrepCompoundPart(partFileName, null, null,
                                                   out string compoundPartName, out addedPartNames);
                        }
                        else
                        {
                            addedPartNames = ImportBrepPartFile(partFileName);
                        }
                        if (addedPartNames != null) allAddedPartNames.AddRange(addedPartNames);
                    }
                    catch (Exception ex)
                    {
                        string[] lines = ex.StackTrace.Split(new string[] { "\r", "\n" }, StringSplitOptions.RemoveEmptyEntries);
                        string error = ex.Message;
                        if (!(ex is CaeException))
                        {
                            for (int i = 0; i < lines.Length; i++)
                            {
                                if (lines[i].Contains("PrePoMax"))
                                {
                                    error += Environment.NewLine + lines[i];
                                    break;
                                }
                            }
                        }
                        _errors.Add("The file " + assemblyFileName + " could not be imported correctly: " +
                                    Environment.NewLine + error);
                    }
                    //
                    if (File.Exists(partFileName)) File.Delete(partFileName);
                }
            }
            //
            return allAddedPartNames.ToArray();
        }
        //
        public string[] SplitAssembly(string assemblyFileName, string splitCommand,
                                      int numOfSplitFacesOverride = -1)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string outFileName = Tools.GetNonExistentRandomFileName(workDirectory, ".brep");
            //
            string argumentSplit = "";
            int numOfSplitFaces = numOfSplitFacesOverride >= 1 ? numOfSplitFacesOverride :
                                                                _settings.General.NumOfSplitFaces;
            if (numOfSplitFaces > 1) argumentSplit = " " + numOfSplitFaces;

            string argument = splitCommand +
                              " \"" + assemblyFileName.ToUTF8() + "\"" +
                              " \"" + outFileName.ToUTF8() + "\"" +
                              argumentSplit;
            //
            JobStatus jobStatus = _jobRunner.Run("SplitStep", executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            //
            string brepFile;
            List<string> brepFiles = new List<string>();
            string outFileNameNoExtension = Path.GetFileNameWithoutExtension(outFileName);
            string searchPattern = "*" + outFileNameNoExtension + "*";
            //
            if (jobStatus == JobStatus.OK)
            {
                string[] allFiles = Directory.GetFiles(workDirectory, searchPattern);
                foreach (var fileName in allFiles)
                {
                    brepFile = Path.GetFileName(fileName);
                    if (brepFile.StartsWith(outFileNameNoExtension)) brepFiles.Add(fileName);
                }
                //
                return brepFiles.ToArray();
            }
            else
            {
                MessageBoxes.ShowError("Splitting the file: '" + assemblyFileName + "' failed." + Environment.NewLine +
                                       "The job " + executable + " ended with the status: " + jobStatus + "." +
                                       Environment.NewLine + "See the output window for the details.");
                return null;
            }
        }
        public void CreateAndImportCompoundPart(string[] partNames, out string compoundPartName, out string[] importedPartNames)
        {
            compoundPartName = null;
            importedPartNames = null;
            Guid? targetGroupId =
                GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts, partNames);
            //
            GeometryPart part;
            HashSet<PartType> stlPartTypes = new HashSet<PartType>();
            HashSet<PartType> cadPartTypes = new HashSet<PartType>();
            //
            string[] allPartNames = GetMeshablePartNames(partNames);
            foreach (var partName in allPartNames)
            {
                part = (GeometryPart)_model.Geometry.Parts[partName];
                if (part.IsCADPart) cadPartTypes.Add(part.PartType);
                else stlPartTypes.Add(part.PartType);
            }
            if (stlPartTypes.Count + cadPartTypes.Count != 1) throw new NotSupportedException();
            //
            if (stlPartTypes.Count > 0)
            {
                GeometryPart geometryPart;
                string[] mergedPartNames;
                FeMesh mesh = _model.Geometry.DeepCopy();
                mesh.MergeGeometryParts(partNames, out geometryPart, out mergedPartNames);
                // Hide parts
                HideGeometryParts(mergedPartNames);
                // Add parts
                importedPartNames =
                    _model.Geometry.AddPartsFromMesh(mesh, new string[] { geometryPart.Name }, null,
                                                     _model.GetReservedPartIds());
                MoveOrderedDictionaryItemsToGroup(_model.Geometry.Parts, importedPartNames, targetGroupId);
                //
                UpdateAfterImport(".stl");
                //
            }
            else if (cadPartTypes.Count > 0)
            {
                string[] createdFileNames = CreateBrepCompoundPart(partNames);
                //
                if (createdFileNames.Length == 1)
                {
                    string brepFileName = createdFileNames[0];
                    HideGeometryParts(partNames);
                    ImportBrepCompoundPart(brepFileName, partNames, targetGroupId,
                                           out compoundPartName, out importedPartNames);
                }
            }
            else throw new NotSupportedException();
        }
        public string[] CreateBrepCompoundPart(string[] partNames)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inFileName = Tools.GetNonExistentRandomFileName(workDirectory);
            string[] inFileNames = new string[partNames.Length];
            for (int i = 0; i < partNames.Length; i++)
                inFileNames[i] = inFileName + "_" + (i + 1).ToString().PadLeft(4, '0') + ".brep";
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            //
            if (File.Exists(brepFileName)) File.Delete(brepFileName);
            // Write CAD
            for (int i = 0; i < partNames.Length; i++)
                File.WriteAllText(inFileNames[i], ((GeometryPart)_model.Geometry.Parts[partNames[i]]).CADFileData);
            //
            string argument = "BREP_COMPOUND";
            for (int i = 0; i < inFileNames.Length; i++) argument += " \"" + inFileNames[i].ToUTF8() + "\"";
            argument += " \"" + brepFileName.ToUTF8() + "\"";
            //
            JobStatus jobStatus = _jobRunner.Run("CompoundPart", executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            //
            for (int i = 0; i < inFileNames.Length; i++)
            {
                if (File.Exists(inFileNames[i])) File.Delete(inFileNames[i]);
            }
            //
            if (jobStatus == JobStatus.OK) return new string[] { brepFileName };
            else return null;
        }
        private void ImportBrepCompoundPart(string brepFileName, string[] createdFromPartNames,
                                            Guid? targetGroupId, out string compoundPartName,
                                            out string[] importedPartNames, string keptCompoundPartName = null,
                                            int keptCompoundPartId = -1)
        {
            // A part written out of a compound has its closed faces divided, and the compound has to
            // carry the same division: the compound is what the mesher is given, and a face of a part
            // that the compound does not hold is a surface id the mesher cannot be asked for. The
            // division is therefore made once, on the whole shape, and the parts are taken from that
            string dividedBrepFileName = SplitClosedFacesOfBrep(brepFileName);
            try
            {
                ImportDividedBrepCompoundPart(dividedBrepFileName, createdFromPartNames, targetGroupId,
                                              out compoundPartName, out importedPartNames, keptCompoundPartName,
                                              keptCompoundPartId);
            }
            finally
            {
                if (dividedBrepFileName != brepFileName && File.Exists(dividedBrepFileName))
                    File.Delete(dividedBrepFileName);
            }
        }
        private void ImportDividedBrepCompoundPart(string dividedBrepFileName, string[] createdFromPartNames,
                                                   Guid? targetGroupId, out string compoundPartName,
                                                   out string[] importedPartNames, string keptCompoundPartName,
                                                   int keptCompoundPartId)
        {
            HashSet<string> oldPartNames = CaptureOrderedDictionaryItemNamesForGroupPlacement(
                _model.Geometry.Parts, targetGroupId);
            // A compound that replaces one keeps its name, which only the mesh part meshed from it may still hold
            if (keptCompoundPartName != null && !_model.Geometry.Parts.ContainsKey(keptCompoundPartName))
                compoundPartName = keptCompoundPartName;
            else compoundPartName = _model.GetPartAndPartGroupNames().GetNextNumberedKey("Compound");
            importedPartNames = ImportCADAssemblyFile(dividedBrepFileName, "BREP_ASSEMBLY_SPLIT_TO_PARTS", 1);
            //
            bool shellParts = true;
            BasePart part;
            foreach (var partName in importedPartNames)
            {
                part = _model.Geometry.Parts[partName];
                if (part.PartType != PartType.Shell)
                {
                    shellParts = false;
                    break;
                }
            }
            //
            if (shellParts)
            {
                foreach (var partName in importedPartNames)
                {
                    compoundPartName = _model.GetPartAndPartGroupNames().GetNextNumberedKey("Compound");
                    // Rename the part
                    PartProperties properties = _model.Geometry.Parts[partName].GetProperties();
                    properties.Name = compoundPartName;
                    ReplaceGeometryPartProperties(partName, properties);
                }
            }
            else
            {
                // Create compound part
                CompoundGeometryPart compPart = new CompoundGeometryPart(compoundPartName, createdFromPartNames,
                                                                         importedPartNames);
                double volume = 0;
                Vec3D cm = new Vec3D();
                for (int i = 0; i < importedPartNames.Length; i++)
                {
                    part = _model.Geometry.Parts[importedPartNames[i]];
                    //
                    if (part.PartType == PartType.Solid || part.PartType == PartType.SolidAsShell)
                    {
                        volume += part.MassProperties.Volume;
                        cm += new Vec3D(part.MassProperties.CenterOfMass) * part.MassProperties.Volume;
                    }
                    else throw new NotSupportedException();
                    //
                    compPart.BoundingBox.IncludeBox(part.BoundingBox);
                }
                cm *= (1 / volume);
                //
                PartMassProperties massProperties = compPart.MassProperties;
                massProperties.Volume = volume;
                massProperties.CenterOfMass = cm.Coor;
                compPart.MassProperties = massProperties;
                //
                compPart.CADFileDataFromFile(dividedBrepFileName);
                HashSet<int> reservedPartIds = _model.GetReservedPartIds();
                if (keptCompoundPartId > 0 && !_model.Geometry.GetAllPartIds().Contains(keptCompoundPartId))
                    compPart.PartId = keptCompoundPartId;
                else
                {
                    compPart.PartId = _model.Geometry.GetMaxPartId() + 1;
                    while (reservedPartIds.Contains(compPart.PartId)) compPart.PartId++;
                }
                _model.Geometry.SetPartColorFromColorTable(compPart);
                _model.Geometry.Parts.Add(compoundPartName, compPart);
            }
            //
            MoveAddedOrderedDictionaryItemsToGroup(_model.Geometry.Parts, oldPartNames, targetGroupId);
            UpdateAfterImport(".brep");
        }
        /// <summary>
        /// Has the mesher divide every closed face of the shape, the way a part written out of it is
        /// divided, and answers the file it wrote. A closed face divided solid by solid gives each solid
        /// a face the shape they came from does not have, so the shape and its parts are numbered
        /// differently and a face of a part names nothing in the shape. Dividing the whole shape at once
        /// also keeps a face two solids share shared. The file that came in is answered when there is
        /// nothing to divide or the division could not be made, since it is the same shape either way.
        /// </summary>
        private string SplitClosedFacesOfBrep(string brepFileName)
        {
            int numOfSplitFaces = _settings.General.NumOfSplitFaces;
            if (numOfSplitFaces <= 1) return brepFileName;
            //
            string workDirectory = _settings.GetWorkDirectory();
            if (workDirectory == null || !Directory.Exists(workDirectory)) return brepFileName;
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string dividedBrepFileName = Tools.GetNonExistentRandomFileName(workDirectory, ".brep");
            //
            string argument = "BREP_SPLIT_CLOSED_FACES " +
                              "\"" + brepFileName.ToUTF8() + "\" " +
                              "\"" + dividedBrepFileName.ToUTF8() + "\" " + numOfSplitFaces;
            //
            JobStatus jobStatus = _jobRunner.Run("SplitClosedFaces", executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            if (jobStatus != JobStatus.OK || !File.Exists(dividedBrepFileName)) return brepFileName;
            //
            return dividedBrepFileName;
        }
