        private void ExportCADGeometryPartsAsAssembly(string[] partNames, string fileName, string command)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inFileName = Tools.GetNonExistentRandomFileName(workDirectory);
            string[] inFileNames = new string[partNames.Length];
            for (int i = 0; i < partNames.Length; i++)
                inFileNames[i] = inFileName + "_" + (i + 1).ToString().PadLeft(4, '0') + ".brep";
            //
            if (File.Exists(fileName)) File.Delete(fileName);
            // Write CAD
            for (int i = 0; i < partNames.Length; i++)
                File.WriteAllText(inFileNames[i], ((GeometryPart)_model.Geometry.Parts[partNames[i]]).CADFileData);
            //
            string argument = command;
            for (int i = 0; i < inFileNames.Length; i++) argument += " \"" + inFileNames[i].ToUTF8() + "\"";
            argument += " \"" + fileName.ToUTF8() + "\"";
            //
            JobStatus jobStatus = _jobRunner.Run("Assembly", executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            //
            for (int i = 0; i < inFileNames.Length; i++)
            {
                if (File.Exists(inFileNames[i])) File.Delete(inFileNames[i]);
            }
            // Job completed
            if (jobStatus != JobStatus.OK) return;
            //
            foreach (var partName in partNames)
            {
                _form.WriteDataToOutput("Part " + partName + " exported to file: " + fileName);
            }
        }
        public void ExportCADGeometryPartAsStep(GeometryPart part, string fileName)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            //
            if (File.Exists(brepFileName)) File.Delete(brepFileName);
            if (File.Exists(fileName)) File.Delete(fileName);
            //
            File.WriteAllText(brepFileName, part.CADFileData);
            //
            string argument = "SAVE_BREP_AS_STEP " +
                              "\"" + brepFileName.ToUTF8() + "\" " +
                              "\"" + fileName.ToUTF8() + "\"";
            //
            JobStatus jobStatus = _jobRunner.Run(part.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK)
                _form.WriteDataToOutput("Part " + part.Name + " exported to file: " + fileName);
            else return;
        }
        public void ExportTo3mf(Export3mfFileProperties export3mfFileProperties)
        {
            vtkMaxActorData[] vtkMaxActorDatas = _form.GetVtkMaxActorData();
            vtkMaxLookupTable lookupTable = _form.GetLookupTable();
            double[] closestUpView = _form.GetClosestUpView();
            ThreeMFFileWriter.Write(export3mfFileProperties.FileName, vtkMaxActorDatas, lookupTable,
                                    export3mfFileProperties.EdgeThicknessRatio, closestUpView);
            //
            _form.WriteDataToOutput("Model exported to file: " + export3mfFileProperties.FileName);
        }
        public void ExportToStl(string[] partNames, string fileName)
        {
            ExportPartsToStl(DisplayedMesh, partNames, fileName, _currentView);
        }
        private void ExportPartsToStl(FeMesh mesh, string[] partNames, string fileName, ViewGeometryModelResults source)
        {
            SuppressExplodedView(partNames);
            //
            vtkMaxActorData data;
            List<double[][]> stlTriangles = new List<double[][]>();
            //
            for (int i = 0; i < partNames.Length; i++)
            {
                if (source == ViewGeometryModelResults.Geometry)
                {
                    data = GetGeometryPartActorData(mesh, mesh.Parts[partNames[i]], vtkRendererLayer.Base, false, false);
                }
                else if (source == ViewGeometryModelResults.Model)
                {
                    data = GetModelPartActorData(mesh, mesh.Parts[partNames[i]], vtkRendererLayer.Base, null);
                }
                else if (source == ViewGeometryModelResults.Results)
                {
                    data = GetResultPartActorData((ResultPart)mesh.Parts[partNames[i]], _currentFieldData);
                }
                else throw new NotSupportedException();
                //
                stlTriangles.AddRange(data.GetStlTriangles());
            }
            //
            StlFileWriter.Write(fileName, stlTriangles);
            ResumeExplodedViews(false);
            //
            foreach (var partName in partNames)
            {
                _form.WriteDataToOutput("Part " + partName + " exported to file: " + fileName);
            }
        }
