        private void ExportMeshPartsAsGmshMesh(string[] partNames, string fileName)
        {
            SuppressExplodedView(partNames);
            GmshMshFileWriter.Write(fileName, _model.Mesh, partNames);
            ResumeExplodedViews(false);
