        public double[] GetDefaultSectionViewNormal()
        {
            double[] vpn = GetViewPlaneNormal();
            double max = 0;
            int id = -1;
            for (int i = 0; i < 3; i++)
            {
                if (Math.Abs(vpn[i]) > max)
                {
                    max = Math.Abs(vpn[i]);
                    id = i;
                }
            }
            for (int i = 0; i < 3; i++)
            {
                if (i == id) vpn[i] = -Math.Round(vpn[i], MidpointRounding.AwayFromZero);
                else vpn[i] = 0;
            }
            return vpn;
        }
