                _form.RemoveFollowerView();
            }
        }
        // Rotation center
        public void RotationPointChanged(double[] rotationPoint)
        {
            string viewName;
            if (_currentView == ViewGeometryModelResults.Results && _allResults.CurrentResult.HashName != _model.HashName)
            {
                viewName = _currentView.ToString() + Globals.NameSeparator + _allResults.CurrentResult.HashName;
                _viewNameRotationCenter[viewName] = rotationPoint.ToArray();
                return;
            }
            //
            viewName = ViewGeometryModelResults.Geometry.ToString();
            _viewNameRotationCenter[viewName] = rotationPoint.ToArray();
            viewName = ViewGeometryModelResults.Model.ToString();
            _viewNameRotationCenter[viewName] = rotationPoint.ToArray();
            viewName = ViewGeometryModelResults.Results.ToString() + Globals.NameSeparator + _model.HashName;
            _viewNameRotationCenter[viewName] = rotationPoint.ToArray();
        }
        private void ApplyRotationPoint()
        {
            string viewName = _currentView.ToString();
            if (_currentView == ViewGeometryModelResults.Results)
                viewName += Globals.NameSeparator + _allResults.CurrentResult.HashName;
            //
            double[] rotationPoint = null;
            _viewNameRotationCenter.TryGetValue(viewName, out rotationPoint);
            _form.SetRotationPoint(rotationPoint);
        }
        // Parameterization
        public void ViewParameterization(int uLineCount = 3, int vLineCount = 3)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return;
            }
            //
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            //
            if (File.Exists(brepFileName)) File.Delete(brepFileName);
            //
            SuppressExplodedView();
            //
            FeMesh mesh = DisplayedMesh;
            foreach (var entry in mesh.Parts)
            {
                if (entry.Value is GeometryPart gp && gp.Visible)
                {
                    GmshData gmshData = new GmshData();
                    gmshData.GeometryFileName = brepFileName;
                    //
                    File.WriteAllText(brepFileName, gp.CADFileData);
                    //
                    GmshAPI gmsh = new GmshAPI(gmshData, _form.WriteDataToOutput);
                    string error = gmsh.GetCoordinatesFromParameterization(uLineCount, vLineCount);
                    if (error != null) throw new CaeException(error);
                    //
                    for (int i = 0; i < gmshData.ParameterizationLinesU.Length; i++)
                    {
                        DrawParameterizationLines(gp.Name + "parU" + i, gmshData.ParameterizationLinesU[i], Color.Red);
                        DrawParameterizationLines(gp.Name + "parV" + i, gmshData.ParameterizationLinesV[i], Color.Blue);
                    }
                }
            }
            //
            ResumeExplodedViews(false);
            //
            _form.Invalidate();
        }
        private void DrawParameterizationLines(string name, double[][][] lines, Color color)
        {
            List<double[]> nodeCoor = new List<double[]>();
            List<int[]> cells = new List<int[]>();
            List<int> cellTypes = new List<int>();
            int lineType = (int)vtkCellType.VTK_LINE;
            int offset;
            foreach (double[][] line in lines)
            {
                if (line == null || line.Length < 2) continue;
                //
                offset = nodeCoor.Count;
                nodeCoor.AddRange(line);
                for (int i = 0; i < line.Length - 1; i++)
                {
                    cells.Add(new int[] { offset + i, offset + i + 1 });
                    cellTypes.Add(lineType);
                }
            }
            if (cells.Count == 0) return;
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = name;
            data.Color = color;
            data.Layer = vtkRendererLayer.Base;
            data.LineWidth = 1;
            data.Pickable = false;
            data.DrawOnGeometry = true;
            data.SectionViewPossible = false;
            data.Geometry.Nodes.Coor = nodeCoor.ToArray();
            data.Geometry.Cells.CellNodeIds = cells.ToArray();
            data.Geometry.Cells.Types = cellTypes.ToArray();
            //
            ApplyLighting(data);
            _form.Add3DCells(data);
        }

