        {
            if (_model.Geometry == null) return null;
            //
            List<GeometryPart> parts = new List<GeometryPart>();
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is GeometryPart gp && !gp.IsCADPart) parts.Add(gp);
            }
            return parts.ToArray();
        }
        public GeometryPart[] GetCompoundParts()
        {
            if (_model.Geometry == null) return null;
            //
            List<CompoundGeometryPart> parts = new List<CompoundGeometryPart>();
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart cgp) parts.Add(cgp);
            }
            return parts.ToArray();
        }
        public GeometryPart[] GetSplitCells()
        {
            if (_model.Geometry == null) return null;
            //
            List<GeometryPart> cells = new List<GeometryPart>();
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit) continue;
                //
                for (int i = 0; i < compoundPart.SubPartNames.Length; i++)
                {
                    BasePart cell;
                    if (compoundPart.CellSubPartNames[i] != null &&
                        _model.Geometry.Parts.TryGetValue(compoundPart.SubPartNames[i], out cell))
                        cells.Add((GeometryPart)cell);
                }
            }
            return cells.ToArray();
        }
        // The bodies the compounds can fuse: every sub part of a compound and, of a split compound, its sub parts of
        // several cells too. A sub part of one cell is that cell and carries its name
        public NamedClass[] GetFusableBodies()
        {
            if (_model.Geometry == null) return null;
            //
            List<NamedClass> bodies = new List<NamedClass>();
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart)) continue;
                //
                foreach (string subPartName in compoundPart.GetSplitSubPartNames())
                {
                    if (compoundPart.GetCellNames(subPartName).Length > 1) bodies.Add(new EmptyNamedClass(subPartName));
                }
                foreach (string subPartName in compoundPart.SubPartNames)
                {
                    BasePart subPart;
                    if (_model.Geometry.Parts.TryGetValue(subPartName, out subPart)) bodies.Add(subPart);
                }
            }
            return bodies.ToArray();
        }
        // The compound a sub part, or a sub part of a split compound, belongs to
        public string GetCompoundPartNameOfBody(string bodyName)
        {
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart compoundPart &&
                    (compoundPart.SubPartNames.Contains(bodyName) || compoundPart.GetSplitSubPartNames().Contains(bodyName)))
                    return compoundPart.Name;
            }
            return null;
        }
        public GeometryPart[] GetGeometryPartsWithoutSubParts()
        {
            if (_model == null || _model.Geometry == null) return null;
            //
            List<GeometryPart> subParts = new List<GeometryPart>();
            List<GeometryPart> allParts = new List<GeometryPart>();
            foreach (var entry in _model.Geometry.Parts)
            {
                allParts.Add((GeometryPart)entry.Value);
                //
                if (entry.Value is CompoundGeometryPart cgp)
                {
                    for (int i = 0; i < cgp.SubPartNames.Length; i++)
                        subParts.Add((GeometryPart)_model.Geometry.Parts[cgp.SubPartNames[i]]);
                }
            }
            return allParts.Except(subParts).ToArray();
        }
        public string[] GetMeshablePartNames(string[] partNames)
        {
            if (_model.Geometry != null) return _model.Geometry.GetMeshablePartNames(partNames);
            else return null;
        }

        //******************************************************************************************
        public void ReplaceGeometryPartProperties(string oldPartName, PartProperties newPartProperties)
        {
            ReplaceGeometryPartProperties(oldPartName, newPartProperties, true);
        }
        private void ReplaceGeometryPartProperties(string oldPartName, PartProperties newPartProperties,
                                                   bool regenerateTree)
        {
            bool nameChanged = oldPartName != newPartProperties.Name;
            GeometryPart geomPart = GetGeometryPart(oldPartName);
            if (nameChanged)
            {
                HashSet<string> reservedNames = _model.GetReservedPartNames();
                // A cell may carry the name of its sub part, which is the only reservation of that name
                string cellSubPartName = GetSplitSubPartNameOfCell(oldPartName);
                if (cellSubPartName != null) reservedNames.Remove(cellSubPartName);
                CheckName(oldPartName, newPartProperties.Name, reservedNames, "part");
            }
            // Replace geometry part
            geomPart.SetProperties(newPartProperties);
            _model.Geometry.Parts.Replace(oldPartName, geomPart.Name, geomPart);
            // Rename compound sub-part names array
            if (oldPartName != newPartProperties.Name)
            {
                foreach (var entry in _model.Geometry.Parts)
                {
                    if (entry.Value is CompoundGeometryPart cgp)
                    {
                        for (int i = 0; i < cgp.SubPartNames.Length; i++)
                        {
                            if (cgp.SubPartNames[i] == oldPartName)
                            {
                                cgp.SubPartNames[i] = newPartProperties.Name;
                                // The only cell of a sub part is the sub part, so its name is the sub part's
                                if (cgp.CreatedBySplit && cgp.CellSubPartNames[i] == oldPartName &&
                                    cgp.GetCellNames(oldPartName).Length == 1)
                                    cgp.CellSubPartNames[i] = newPartProperties.Name;
                                break;
                            }
                        }
                        if (cgp.CreatedFromPartNames != null)
                        {
                            for (int i = 0; i < cgp.CreatedFromPartNames.Length; i++)
                            {
                                if (cgp.CreatedFromPartNames[i] == oldPartName)
                                {
                                    cgp.CreatedFromPartNames[i] = newPartProperties.Name;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            // Update
            if (nameChanged) _effectiveMeshTypes = null;
            if (!(geomPart is CompoundGeometryPart))
                _form.UpdateActor(oldPartName, geomPart.Name, GetDrawnGeometryPartColor(geomPart));
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, oldPartName, geomPart, null);
            // Annotations
            _annotations.DrawAnnotations();
            // Color legend
            AnnotateWithColorLegend();
            // Update the mesh part in pair with the geometry part properties
            if (_model.Mesh != null && _model.Mesh.Parts.ContainsKey(oldPartName))
            {
                string newPartName = geomPart.Name;
                MeshPart meshPart = GetModelPart(oldPartName);
                // Color
                meshPart.Color = geomPart.Color;
                // Rename
                if (oldPartName != geomPart.Name)
                {
                    meshPart.Name = newPartName;
                    _model.Mesh.Parts.Replace(oldPartName, meshPart.Name, meshPart);
                    // Update
                    _form.UpdateTreeNode(ViewGeometryModelResults.Model, oldPartName, meshPart, null);
                }
            }
            // Rename the finite element group paired with a meshed compound geometry part.
            bool compoundPartGroupRenamed =
                nameChanged && geomPart is CompoundGeometryPart compoundPart &&
                RenameModelPartGroup(compoundPart.LinkedGroupId, geomPart.Name);
            //
            UpdateAfterPartsChanged();
            if (nameChanged && _showItemIds.HasFlag(ShowItemIdsEnum.PartNames)) RedrawItemIds();
            if (compoundPartGroupRenamed && regenerateTree) _form?.RegenerateTree(false);
        }
        public void RenameGeometryPart(string oldPartName, string newPartName)
        {
            PartProperties newPartProperties = GetGeometryPart(oldPartName).GetProperties();
            newPartProperties.Name = newPartName;
            ReplaceGeometryPartProperties(oldPartName, newPartProperties);
        }
        public void RenameSplitSubPart(string compoundPartName, string oldSubPartName, string newSubPartName)
        {
            BasePart part;
            if (!_model.Geometry.Parts.TryGetValue(compoundPartName, out part) ||
                !(part is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit ||
                !compoundPart.CellSubPartNames.Contains(oldSubPartName))
                throw new CaeException("The part " + oldSubPartName + " of the compound part " + compoundPartName +
                                       " does not exist.");
            if (newSubPartName == oldSubPartName) return;
            //
            HashSet<string> reservedNames = new HashSet<string>(_model.GetReservedPartNames(),
                                                                StringComparer.OrdinalIgnoreCase);
            reservedNames.Remove(oldSubPartName);
            CheckName(oldSubPartName, newSubPartName, reservedNames, "part");
            //
            SetSplitSubPartName(compoundPart, oldSubPartName, newSubPartName);
            // The mesh part the sub part was meshed into carries its name
            if (_model.Mesh != null && _model.Mesh.Parts.ContainsKey(oldSubPartName))
            {
                MeshPart meshPart = GetModelPart(oldSubPartName);
                meshPart.Name = newSubPartName;
                _model.Mesh.Parts.Replace(oldSubPartName, meshPart.Name, meshPart);
                _form.UpdateActor(oldSubPartName, meshPart.Name, meshPart.Color);
                UpdateAfterPartsChanged();
            }
            //
            _form.RegenerateTree();
        }
        private void SetSplitSubPartName(CompoundGeometryPart compoundPart, string oldSubPartName,
                                         string newSubPartName)
        {
            string[] cellSubPartNames = compoundPart.CellSubPartNames;
            for (int i = 0; i < cellSubPartNames.Length; i++)
            {
                if (cellSubPartNames[i] == oldSubPartName) cellSubPartNames[i] = newSubPartName;
            }
            string[] subPartOrder = compoundPart.SplitSubPartOrder;
            for (int i = 0; subPartOrder != null && i < subPartOrder.Length; i++)
            {
                if (subPartOrder[i] == oldSubPartName) subPartOrder[i] = newSubPartName;
            }
            RenameSplitCells(compoundPart);
        }
        /// <summary>
        /// Puts the named cells of a split compound under one sub part, which is then meshed into one mesh part,
        /// so that the regions of a solid cut for different materials can be gathered as the materials need.
        /// The geometry is not changed. A sub part left without cells is gone.
        /// </summary>
        public void GroupSplitCells(string compoundPartName, string[] cellNames, string subPartName)
        {
            subPartName = GetGroupSplitCellsSubPartName(compoundPartName, cellNames, subPartName);
            CompoundGeometryPart compoundPart = (CompoundGeometryPart)_model.Geometry.Parts[compoundPartName];
            //
            string[] cellSubPartNames = compoundPart.CellSubPartNames;
            int[] cellSubPartIds = new int[cellSubPartNames.Length];
            for (int i = 0; i < cellSubPartNames.Length; i++)
            {
                if (cellSubPartNames[i] != null) cellSubPartIds[i] = GetSplitSubPartId(compoundPart, cellSubPartNames[i]);
            }
            // The cells that join a sub part take its color, so the grouping shows; a new sub part holds a part id
            // of its own and is colored by it
            bool existingSubPart = cellSubPartNames.Contains(subPartName);
            int subPartId;
            Color subPartColor = Color.Empty;
            if (existingSubPart)
            {
                subPartId = GetSplitSubPartId(compoundPart, subPartName);
                subPartColor = _model.Geometry.Parts[compoundPart.GetCellNames(subPartName)[0]].Color;
            }
            else
            {
                HashSet<int> reservedPartIds = _model.GetReservedPartIds();
                subPartId = 1;
                while (reservedPartIds.Contains(subPartId)) subPartId++;
            }
            //
            List<string> subPartOrder = compoundPart.GetSplitSubPartNames().ToList();
            if (!existingSubPart) subPartOrder.Add(subPartName);
            //
            HashSet<string> groupedCellNames = new HashSet<string>(cellNames);
            for (int i = 0; i < compoundPart.SubPartNames.Length; i++)
            {
                if (!groupedCellNames.Contains(compoundPart.SubPartNames[i])) continue;
                cellSubPartNames[i] = subPartName;
                cellSubPartIds[i] = subPartId;
            }
            compoundPart.CellSubPartNames = cellSubPartNames;
            compoundPart.CellSubPartIds = cellSubPartIds;
            compoundPart.SplitSubPartOrder = subPartOrder.Where(name => cellSubPartNames.Contains(name)).ToArray();
            RenameSplitCells(compoundPart);
            //
            foreach (string cellName in compoundPart.GetCellNames(subPartName))
            {
                BasePart cell = _model.Geometry.Parts[cellName];
                if (existingSubPart) cell.Color = subPartColor;
                else SetGeometryPartColorFromColorTable(cell);
                _form.UpdateActor(cell.Name, cell.Name, GetDrawnGeometryPartColor(cell));
            }
            _effectiveMeshTypes = null;
            //
            _form.RegenerateTree();
            //
            CheckAndUpdateModelValidity();
        }
        /// <summary>
        /// The sub part the named cells are to be put under. Without a name it is the largest sub part whose
        /// cells are all among them, so that a sub part picked together with further cells takes them in, and
        /// otherwise a new sub part named after the one the first cell belongs to. A grouping that would change
        /// nothing, or only the name of a sub part, is refused.
        /// </summary>
        public string GetGroupSplitCellsSubPartName(string compoundPartName, string[] cellNames, string subPartName)
        {
            BasePart part;
            if (compoundPartName == null || !_model.Geometry.Parts.TryGetValue(compoundPartName, out part) ||
                !(part is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit)
                throw new CaeException("The part " + compoundPartName + " is not a compound part made by a split.");
            if (cellNames == null || cellNames.Length == 0)
                throw new CaeException("Group cells: no cells of the compound part " + compoundPartName +
                                       " were selected.");
            //
            HashSet<string> groupedCellNames = new HashSet<string>();
            HashSet<string> groupedSubPartNames = new HashSet<string>();
            foreach (string cellName in cellNames)
            {
                int index = Array.IndexOf(compoundPart.SubPartNames, cellName);
                if (index < 0 || compoundPart.CellSubPartNames[index] == null)
                    throw new CaeException("Group cells: " + cellName + " is not a cell of the compound part " +
                                           compoundPartName + ".");
                groupedCellNames.Add(cellName);
                groupedSubPartNames.Add(compoundPart.CellSubPartNames[index]);
            }
            //
            string[] subPartNames = compoundPart.GetSplitSubPartNames();
            // The largest whole sub part is the one the others join, so that a sub part picked together with a
            // lone cell takes the cell in and not the other way round; a tie goes to the one named first
            string[] wholeSubPartNames = cellNames
                .Select(cellName => compoundPart.CellSubPartNames[Array.IndexOf(compoundPart.SubPartNames, cellName)])
                .Distinct()
                .Where(name => compoundPart.GetCellNames(name).All(cellName => groupedCellNames.Contains(cellName)))
                .OrderByDescending(name => compoundPart.GetCellNames(name).Length)
                .ToArray();
            if (subPartName == null)
            {
                if (wholeSubPartNames.Length > 0) subPartName = wholeSubPartNames[0];
                else
                {
                    string firstSubPartName = compoundPart.CellSubPartNames[Array.IndexOf(compoundPart.SubPartNames,
                                                                                          cellNames[0])];
                    subPartName = _model.GetReservedPartNames()
                                        .GetNextNumberedKey(NamedClass.GetNameWithoutLastValue(firstSubPartName));
                }
            }
            //
            if (subPartNames.Contains(subPartName))
            {
                if (groupedSubPartNames.Count == 1 && groupedSubPartNames.Contains(subPartName))
                    throw new CaeException("Group cells: the selected cells already belong to the sub-part " +
                                           subPartName + " of the compound part " + compoundPartName + ".");
            }
            else
            {
                CheckName(null, subPartName, _model.GetReservedPartNames(), "part");
                if (groupedSubPartNames.Count == 1 && wholeSubPartNames.Length == 1 &&
                    groupedCellNames.Count == compoundPart.GetCellNames(wholeSubPartNames[0]).Length)
                    throw new CaeException("Group cells: the selected cells are all the cells of the sub-part " +
                                           wholeSubPartNames[0] + " of the compound part " + compoundPartName +
                                           ". Rename the sub-part instead.");
            }
            return subPartName;
        }
        /// <summary>
        /// Makes one solid of the named bodies of a compound, which takes out the faces they share and heals the
        /// edges left on their outside, so cells come back as the solid the splits cut them from. A body is a sub
        /// part of the compound, or of a split compound a cell or a sub part, which stands for all of its cells.
        /// The compound keeps its name, its part id and the ids of its sub parts. Fusing the whole compound gives
        /// back a plain part carrying the name and the id of the sub part it ends in.
        /// </summary>
        public void FuseBodies(string compoundPartName, string[] bodyNames)
        {
            CheckFuseBodies(compoundPartName, bodyNames);
            CompoundGeometryPart compoundPart = (CompoundGeometryPart)_model.Geometry.Parts[compoundPartName];
            string[] cellNames = GetCellNamesOfBodies(compoundPart, bodyNames);
            //
            int[] solidIds = cellNames.Select(name => Array.IndexOf(compoundPart.SubPartNames, name) + 1)
                                      .Distinct().OrderBy(id => id).ToArray();
            string brepFileName = MergeCompoundGeometrySolids(compoundPart, solidIds);
            if (brepFileName == null)
                throw new CaeException("Fuse bodies: the cells " + string.Join(", ", cellNames) + " of the compound part " +
                                       compoundPartName + " could not be fused. The cells must touch over faces.");
            //
            _lastFusedSplitCellName = null;
            int numOfSolids = GetNumberOfSplitGeometrySolids(brepFileName);
            // One cell belongs to one sub part, so cells of several are grouped under one before the compound is
            // replaced. The kernel has fused them by then, so a fuse it refuses leaves the sub parts as they were.
            if (compoundPart.CreatedBySplit)
            {
                string[] fusedSubPartNames = cellNames
                    .Select(cellName => compoundPart.CellSubPartNames[Array.IndexOf(compoundPart.SubPartNames, cellName)])
                    .Distinct().ToArray();
                if (fusedSubPartNames.Length > 1)
                    GroupSplitCells(compoundPartName, cellNames, GetFuseSplitCellsSubPartName(compoundPart, cellNames));
            }
            bool rendering = _form.RenderingOn;
            bool screenUpdating = _form.ScreenUpdating;
            _form.RenderingOn = false;
            _form.ScreenUpdating = false;
            try
            {
                if (numOfSolids > 1 && !compoundPart.CreatedBySplit)
                    _lastFusedSplitCellName = ReplaceCompoundWithFusedSubParts(compoundPart, brepFileName, solidIds);
                else if (numOfSolids > 1)
                {
                    // The fused cell takes the place of the first of them and every other cell keeps its own, which
                    // is what a split reads to carry the sub parts and colors over to the pieces
                    List<string> origins = new List<string>();
                    for (int i = 1; i <= compoundPart.SubPartNames.Length; i++)
                    {
                        if (i == solidIds[0] || !solidIds.Contains(i)) origins.Add(i.ToString());
                    }
                    if (origins.Count != numOfSolids)
                        throw new CaeException("Fuse bodies: the modelling kernel returned " + numOfSolids +
                                               " solids for the compound part " + compoundPartName + " instead of " +
                                               origins.Count + ".");
                    File.WriteAllLines(GetSplitGeometryOriginsFileName(brepFileName), origins);
                    //
                    string resultPartName = ReplaceSplitGeometryPart(compoundPart, brepFileName);
                    if (resultPartName == null || !(_model.Geometry.Parts[resultPartName] is CompoundGeometryPart result))
                        throw new CaeException("Fuse bodies: the compound part " + compoundPartName +
                                               " could not be replaced.");
                    _lastFusedSplitCellName = result.SubPartNames[solidIds[0] - 1];
                }
                else if (compoundPart.CreatedBySplit)
                {
                    string subPartName = compoundPart.GetSplitSubPartNames()[0];
                    _lastFusedSplitCellName = ReplaceCompoundWithPart(compoundPart, brepFileName, subPartName,
                                                                      GetSplitSubPartId(compoundPart, subPartName),
                                                                      _model.Geometry.Parts[compoundPart.SubPartNames[solidIds[0] - 1]].Color);
                }
                else
                {
                    BasePart firstSubPart = _model.Geometry.Parts[compoundPart.SubPartNames[solidIds[0] - 1]];
                    _lastFusedSplitCellName = ReplaceCompoundWithPart(compoundPart, brepFileName, firstSubPart.Name,
                                                                      firstSubPart.PartId, firstSubPart.Color);
                }
            }
            finally
            {
                _form.ScreenUpdating = screenUpdating;
                if (screenUpdating) _form.RegenerateTree();
                _form.RenderingOn = rendering;
            }
            //
            _form.WriteDataToOutput("Fuse bodies: " + cellNames.Length + " cells of the compound part " + compoundPartName +
                                    " were fused into " + _lastFusedSplitCellName + ".");
            //
            ClearAllSelection();
            CheckAndUpdateModelValidity();
        }
        public void CheckFuseBodies(string compoundPartName, string[] bodyNames)
        {
            BasePart part;
            if (compoundPartName == null || !_model.Geometry.Parts.TryGetValue(compoundPartName, out part) ||
                !(part is CompoundGeometryPart compoundPart))
                throw new CaeException("The part " + compoundPartName + " is not a compound part.");
            if (bodyNames == null || bodyNames.Length == 0)
                throw new CaeException("Fuse bodies: no cells or sub-parts of the compound part " + compoundPartName +
                                       " were selected.");
            //
            string[] subPartNames = compoundPart.GetSplitSubPartNames();
            foreach (string bodyName in bodyNames)
            {
                if (!compoundPart.SubPartNames.Contains(bodyName) && !subPartNames.Contains(bodyName))
                    throw new CaeException("Fuse bodies: " + bodyName + " is not a sub-part or a cell of the " +
                                           "compound part " + compoundPartName + ".");
            }
            if (GetCellNamesOfBodies(compoundPart, bodyNames).Length < 2)
                throw new CaeException("Fuse bodies: the selected bodies of the compound part " + compoundPartName +
                                       " are only one solid, so there is nothing to fuse.");
        }
        /// <summary>
        /// The solids the named bodies of a compound hold, by the names the compound gives them: a solid stands for
        /// itself and a sub part of a split compound for all of its cells, each once, in the order they are named.
        /// </summary>
        private string[] GetCellNamesOfBodies(CompoundGeometryPart compoundPart, string[] bodyNames)
        {
            List<string> cellNames = new List<string>();
            foreach (string bodyName in bodyNames)
            {
                if (compoundPart.SubPartNames.Contains(bodyName)) cellNames.Add(bodyName);
                else cellNames.AddRange(compoundPart.GetCellNames(bodyName));
            }
            return cellNames.Distinct().ToArray();
        }
        /// <summary>
        /// The sub part a fused cell belongs to when the cells come from several: the largest of them whose cells
        /// are all fused, as a grouping chooses it, and otherwise the sub part of the first cell.
        /// </summary>
        private string GetFuseSplitCellsSubPartName(CompoundGeometryPart compoundPart, string[] cellNames)
        {
            HashSet<string> fusedCellNames = new HashSet<string>(cellNames);
            string[] cellSubPartNames = cellNames
                .Select(cellName => compoundPart.CellSubPartNames[Array.IndexOf(compoundPart.SubPartNames, cellName)])
                .Distinct().ToArray();
            string[] wholeSubPartNames = cellSubPartNames
                .Where(name => compoundPart.GetCellNames(name).All(cellName => fusedCellNames.Contains(cellName)))
                .OrderByDescending(name => compoundPart.GetCellNames(name).Length)
                .ToArray();
            return wholeSubPartNames.Length > 0 ? wholeSubPartNames[0] : cellSubPartNames[0];
        }
        /// <summary>
        /// A compound of which some sub parts were fused stays the compound it was: it keeps its name and part id,
        /// the sub parts that were not fused keep their names, part ids and colors, and the fused solid takes those
        /// of the first sub part fused. What was defined on a sub part that is kept stays defined on it.
        /// </summary>
        private string ReplaceCompoundWithFusedSubParts(CompoundGeometryPart compoundPart, string brepFileName,
                                                        int[] solidIds)
        {
            int[] keptSolidNumbers = Enumerable.Range(1, compoundPart.SubPartNames.Length)
                                               .Where(i => i == solidIds[0] || !solidIds.Contains(i)).ToArray();
            return ReplaceCompoundKeepingSubParts(compoundPart, brepFileName, keptSolidNumbers, "Fuse bodies", null);
        }
        /// <summary>
        /// A compound whose solids are the sub parts named by their numbers, in that order, keeps its name and part
        /// id, and each of those sub parts keeps its name, part id and color. The ids held besides are kept free for
        /// parts that are imported once the compound is replaced.
        /// </summary>
        private string ReplaceCompoundKeepingSubParts(CompoundGeometryPart compoundPart, string brepFileName,
                                                      int[] keptSolidNumbers, string operation,
                                                      IEnumerable<int> heldPartIds)
        {
            List<string> subPartNames = new List<string>();
            List<int> subPartIds = new List<int>();
            List<Color> subPartColors = new List<Color>();
            foreach (int i in keptSolidNumbers)
            {
                BasePart subPart = _model.Geometry.Parts[compoundPart.SubPartNames[i - 1]];
                subPartNames.Add(subPart.Name);
                subPartIds.Add(subPart.PartId);
                subPartColors.Add(subPart.Color);
            }
            //
            string compoundPartName;
            string[] importedPartNames;
            _model.HoldPartIds(subPartIds.Concat(new int[] { compoundPart.PartId })
                                         .Concat(heldPartIds ?? Enumerable.Empty<int>()));
            try
            {
                RemoveGeometryParts(new string[] { compoundPart.Name }, true, false);
                ImportBrepCompoundPart(brepFileName, null, null, out compoundPartName, out importedPartNames,
                                       compoundPart.Name, compoundPart.PartId);
            }
            finally
            {
                _model.ReleaseHeldPartIds();
            }
            if (importedPartNames == null || importedPartNames.Length != subPartNames.Count ||
                !(_model.Geometry.Parts[compoundPartName] is CompoundGeometryPart result))
                throw new CaeException(operation + ": the compound part " + compoundPart.Name + " could not be replaced.");
            // The sub parts are imported under new names, which may be the names others are to take back, so they
            // are moved out of the way first. They are not drawn under their final names yet, and only the mesh
            // parts meshed from them may still hold those names, so the names are given directly.
            string[] temporaryNames = new string[importedPartNames.Length];
            for (int i = 0; i < importedPartNames.Length; i++)
            {
                temporaryNames[i] = "Fuse_" + Guid.NewGuid().ToString("N");
                BasePart subPart = _model.Geometry.Parts[importedPartNames[i]];
                subPart.Name = temporaryNames[i];
                _model.Geometry.Parts.Replace(importedPartNames[i], temporaryNames[i], subPart);
            }
            for (int i = 0; i < importedPartNames.Length; i++)
            {
                BasePart subPart = _model.Geometry.Parts[temporaryNames[i]];
                subPart.Name = subPartNames[i];
                subPart.Color = subPartColors[i];
                _model.Geometry.Parts.Replace(temporaryNames[i], subPartNames[i], subPart);
                if (subPart.PartId != subPartIds[i] && !_model.GetReservedPartIds().Contains(subPartIds[i]))
                    _model.Geometry.ChangePartId(subPartNames[i], subPartIds[i]);
            }
            result.SubPartNames = subPartNames.ToArray();
            //
            UpdateAfterImport(".brep");
            return subPartNames[0];
        }
        /// <summary>
        /// The one solid left when a whole compound was fused is no longer a compound, so it becomes a plain part,
        /// with the name, the part id and the color it is given, and what was defined on the whole of the compound
        /// or of one of its sub parts is defined on it.
        /// </summary>
        private string ReplaceCompoundWithPart(CompoundGeometryPart compoundPart, string brepFileName, string subPartName,
                                               int subPartId, Color color, string operation = "Fuse bodies",
                                               IEnumerable<int> heldPartIds = null)
        {
            Dictionary<MeshSetupItem, string[]> coveredSubPartNames;
            Dictionary<MeshSetupItem, int[]> meshSetupItems = GetMeshSetupItemsCoveringCompound(compoundPart,
                                                                  out coveredSubPartNames);
            //
            string[] importedPartNames;
            _model.HoldPartIds(new int[] { subPartId }.Concat(heldPartIds ?? Enumerable.Empty<int>()));
            try
            {
                RemoveGeometryParts(new string[] { compoundPart.Name }, false, false);
                importedPartNames = ImportBrepPartFile(brepFileName);
            }
            finally
            {
                _model.ReleaseHeldPartIds();
            }
            if (importedPartNames == null || importedPartNames.Length != 1)
                throw new CaeException(operation + ": the solid left of the compound part " + compoundPart.Name +
                                       " could not be imported as one part.");
            //
            string partName = importedPartNames[0];
            if (subPartId > 0 && !_model.GetReservedPartIds().Contains(subPartId))
                _model.Geometry.ChangePartId(partName, subPartId);
            // The part takes the name the sub part held, which only the mesh part meshed from it may still hold, as a
            // compound that replaces one keeps its name; it is not drawn yet, so nothing else carries its name
            BasePart importedPart = _model.Geometry.Parts[partName];
            importedPart.Name = subPartName;
            importedPart.Color = color;
            _model.Geometry.Parts.Replace(partName, subPartName, importedPart);
            //
            int partId = _model.Geometry.Parts[subPartName].PartId;
            foreach (var entry in meshSetupItems)
            {
                MeshSetupItem meshSetupItem = entry.Key;
                meshSetupItem.CreationIds = entry.Value.Where(id => FeMesh.GetPartIdFromGeometryId(id) != compoundPart.PartId)
                                                       .Concat(new int[] { partId }).ToArray();
                meshSetupItem.CreationData.Nodes.Clear();
                meshSetupItem.CreationData.Add(new SelectionNodeIds(vtkSelectOperation.None, false,
                                                                    meshSetupItem.CreationIds));
                meshSetupItem.Valid = true;
            }
            // A part imported from a file is only added to the model, and a compound import draws its parts
            // itself, so the part that takes the place of the compound is drawn here, under its final name
            UpdateAfterImport(".brep");
            return subPartName;
        }
