        // A move replaces each part in place, so it keeps its name and part id, and a copy or a pattern adds new parts
        private void TransformGeometryParts(string[] partNames, GeometryTransform transform,
                                            Action<string[]> transformStlParts)
        {
            string transformName = transform.Type.ToString().ToLower();
            if (IsExplodedViewActive())
                throw new CaeException("The " + transformName + " transform can only be done when the exploded view " +
                                       "is turned off.");
            Guid? targetGroupId =
                GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts, partNames);
            HashSet<string> oldPartNames = CaptureOrderedDictionaryItemNamesForGroupPlacement(
                _model.Geometry.Parts, targetGroupId);
            bool copy = transform.NumberOfCopies > 0;
            // Split parts to groups
            GeometryPart geometryPart;
            List<string> cadPartNames = new List<string>();
            List<string> compoundPartNames = new List<string>();
            List<string> stlPartNames = new List<string>();
            foreach (var partName in partNames)
            {
                geometryPart = (GeometryPart)_model.Geometry.Parts[partName];
                if (geometryPart.IsCADPart)
                {
                    if (geometryPart is CompoundGeometryPart cgp) compoundPartNames.Add(partName);
                    else if (IsPartCompoundSubPart(partName))
                        throw new CaeException("The " + transformName + " transform cannot be done for the compound " +
                                               "sub-part '" + partName + "'.");
                    else cadPartNames.Add(partName);
                }
                else stlPartNames.Add(partName);
            }
            //
            int count = 0;
            string[] brepFileNames;
            string[] importedPartNames;
            CompoundGeometryPart compoundPart;
            CompoundGeometryPart newCompoundPart;
            // The parts reach the tree and the scene together at the end, so that the transform is one tree and one
            // redraw instead of several of each per part
            bool rendering = _form.RenderingOn;
            bool screenUpdating = _form.ScreenUpdating;
            _form.RenderingOn = false;
            _form.ScreenUpdating = false;
            try
            {
                // Transform CAD parts
                foreach (var partName in cadPartNames)
                {
                    geometryPart = (GeometryPart)_model.Geometry.Parts[partName];
                    //
                    brepFileNames = _netgenRunner.Transform(geometryPart, transform);
                    //
                    if (brepFileNames != null)
                    {
                        if (copy)
                        {
                            foreach (var brepFileName in brepFileNames)
                            {
                                importedPartNames = ImportBrepPartFile(brepFileName);
                                count++;
                            }
                        }
                        else ReplacePartGeometryFromFile(geometryPart, brepFileNames[0], true); // calls UpdateAfterPartsChanged
                    }
                    else ClearAllSelection();
                }
                // Transform Compound parts
                string newCompoundPartName;
                foreach (var partName in compoundPartNames)
                {
                    compoundPart = (CompoundGeometryPart)_model.Geometry.Parts[partName];
                    //
                    brepFileNames = _netgenRunner.Transform(compoundPart, transform);
                    //
                    if (brepFileNames != null)
                    {
                        foreach (var brepFileName in brepFileNames)
                        {
                            ImportBrepCompoundPart(brepFileName, compoundPart.SubPartNames, targetGroupId,
                                                   out newCompoundPartName, out importedPartNames);
                            newCompoundPart = (CompoundGeometryPart)_model.Geometry.Parts[newCompoundPartName];
                            newCompoundPart.CellSubPartNames = compoundPart.CellSubPartNames?.ToArray();
                            newCompoundPart.SplitSubPartOrder = compoundPart.SplitSubPartOrder?.ToArray();
                            //
                            if (copy) count++;
                            else SwapCompoundParts(partName, newCompoundPartName, true);
                        }
                    }
                    else ClearAllSelection();
                }
                // Transform stl parts
                if (stlPartNames.Count > 0)
                {
                    transformStlParts(stlPartNames.ToArray());
                    if (copy) count++;
                }
                //
                if (count > 0)
                    MoveAddedOrderedDictionaryItemsToGroup(_model.Geometry.Parts, oldPartNames, targetGroupId);
            }
            finally
            {
                _form.ScreenUpdating = screenUpdating;
                if (screenUpdating) _form.RegenerateTree();
                _form.RenderingOn = rendering;
            }
            //
            UpdateAfterPartsChanged(); // must be here before any drawing
            //
            DrawGeometry(false);
            //
            CheckAndUpdateModelValidity();
        }
        // End Transform
        public void CopyGeometryPartsToResults(string[] partNames)
        {
            HashSet<string> partNamesToCopy = new HashSet<string>(partNames);
            // Find all sub parts to copy except the compound parts
            foreach (var name in partNames)
            {
                if (_model.Geometry.Parts[name] is CompoundGeometryPart cgp)
                {
                    partNamesToCopy.Remove(cgp.Name);
                    partNamesToCopy.UnionWith(cgp.SubPartNames);
                }
            }
            //
            FeResults result = _allResults.CurrentResult;
            if (result != null && result.Mesh != null)
            {
                _model.Geometry.SuppressExplodedView();
                string[] addedPartNames = result.AddPartsFromMesh(_model.Geometry, partNamesToCopy.ToArray());
                _model.Geometry.ResumeExplodedView();
                // Update results exploded view
                UpdateCurrentResultExplodedView();
                //
                if (addedPartNames.Length > 0)
                {
                    _form.RegenerateTree();
                    CurrentView = ViewGeometryModelResults.Results;
                }
            }
            _modelChanged = true;
        }
        private Dictionary<string, bool[]> GetCompoundSubPartVisibilities()
        {
            BasePart subPart;
            bool[] visibilities;
            Dictionary<string, bool[]> subPartVisibilities = new Dictionary<string, bool[]>();
            //
            if (_model == null || _model.Geometry == null) return subPartVisibilities;
            //
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart)) continue;
                //
                visibilities = new bool[compoundPart.SubPartNames.Length];
                for (int i = 0; i < compoundPart.SubPartNames.Length; i++)
                {
                    if (_model.Geometry.Parts.TryGetValue(compoundPart.SubPartNames[i], out subPart))
                        visibilities[i] = subPart.Visible;
                }
                subPartVisibilities.Add(compoundPart.Name, visibilities);
            }
            return subPartVisibilities;
        }
        private void UpdateCompoundSharedModelEdges(Dictionary<string, bool[]> previousSubPartVisibilities)
        {
            if (_currentView != ViewGeometryModelResults.Geometry) return;
            if (_model == null || _model.Geometry == null) return;
            //
            BasePart subPart;
            bool[] previousVisibilities;
            PartExchangeData modelEdgesToDraw;
            //
            foreach (var entry in GetCompoundSubPartVisibilities())
            {
                if (!previousSubPartVisibilities.TryGetValue(entry.Key, out previousVisibilities)) continue;
                if (!IsSharedModelEdgeOwnerChanged(previousVisibilities, entry.Value)) continue;
                if (!(_model.Geometry.Parts[entry.Key] is CompoundGeometryPart compoundPart)) continue;
                //
                foreach (string subPartName in compoundPart.SubPartNames)
                {
                    if (!_model.Geometry.Parts.TryGetValue(subPartName, out subPart) || !subPart.Visible) continue;
                    if (!subPart.PartType.HasEdges() || subPart.Visualization == null ||
                        subPart.Visualization.EdgeCells == null) continue;
                    //
                    modelEdgesToDraw = GetModelEdgesToDraw(_model.Geometry, subPart);
                    if (modelEdgesToDraw == null)
                    {
                        modelEdgesToDraw = new PartExchangeData();
                        _model.Geometry.GetNodesAndCellsForModelEdges(subPart,
                                                                      out modelEdgesToDraw.Nodes.Ids,
                                                                      out modelEdgesToDraw.Nodes.Coor,
                                                                      out modelEdgesToDraw.Cells.CellNodeIds,
                                                                      out modelEdgesToDraw.Cells.Types);
                    }
                    _form.UpdateActorModelEdgesToDraw(subPartName, modelEdgesToDraw);
                }
            }
        }
        /// <summary>
        /// Whether the sub parts of a compound part were hidden or shown. The edges are read again for any
        /// change at all: what a sub part draws is what it was given the last time it was visible, which is
        /// not what the sub parts visible now would be given, so hiding them one by one and showing the
        /// compound part again would leave every one of them drawing the edges it shares.
        /// </summary>
        private bool IsSharedModelEdgeOwnerChanged(bool[] previousVisibilities, bool[] visibilities)
        {
            if (previousVisibilities.Length != visibilities.Length) return true;
            //
            for (int i = 0; i < visibilities.Length; i++)
            {
                if (previousVisibilities[i] != visibilities[i]) return true;
            }
            return false;
        }
        public void HideGeometryParts(string[] partNames)
        {
            BeforeHideShow();
            //
            bool hide;
            BasePart part;
            Dictionary<string, bool[]> subPartVisibilities = GetCompoundSubPartVisibilities();
            HashSet<string> partNamesToHide = new HashSet<string>(partNames);
            // Find all sub parts to hide
            foreach (var name in partNames)
            {
                part = _model.Geometry.Parts[name];
                if (part is CompoundGeometryPart cgp) partNamesToHide.UnionWith(cgp.SubPartNames);
            }
            // Hide still visible compound parts with all hidden component parts
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart cgp && cgp.Visible == true)
                {
                    hide = true;
                    for (int i = 0; i < cgp.SubPartNames.Length; i++)
                    {
                        // If sub part is visible and is not about to be hidden
                        if (_model.Geometry.Parts[cgp.SubPartNames[i]].Visible && !partNamesToHide.Contains(cgp.SubPartNames[i]))
                        {
                            hide = false;
                            break;
                        }
                    }
                    if (hide) partNamesToHide.Add(cgp.Name);
                }
            }
            // Perform hide
            foreach (var name in partNamesToHide)
            {
                part = _model.Geometry.Parts[name];
                part.Visible = false;
                _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, name, _model.Geometry.Parts[name], null, false);
            }
            UpdateCompoundSharedModelEdges(subPartVisibilities);
            _form.HideActors(partNamesToHide.ToArray(), false);
            // Update
            AnnotateWithColorLegend();
            // Annotations
            _annotations.DrawAnnotations();
            if (_currentView == ViewGeometryModelResults.Geometry) RedrawItemIds();
        }
        public void ShowGeometryParts(string[] partNames)
        {
            BeforeHideShow();
            //
            bool show;
            BasePart part;
            Dictionary<string, bool[]> subPartVisibilities = GetCompoundSubPartVisibilities();
            HashSet<string> partNamesToShow = new HashSet<string>(partNames);
            // Find all sub parts to show
            foreach (var name in partNames)
            {
                part = _model.Geometry.Parts[name];
                if (part is CompoundGeometryPart cgp) partNamesToShow.UnionWith(cgp.SubPartNames);
            }
            // Show still hidden compound parts with at leas one shown component part
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart cgp && cgp.Visible == false)
                {
                    show = false;
                    for (int i = 0; i < cgp.SubPartNames.Length; i++)
                    {
                        // If sub part is visible or is about to be shown
                        if (_model.Geometry.Parts[cgp.SubPartNames[i]].Visible || partNamesToShow.Contains(cgp.SubPartNames[i]))
                        {
                            show = true;
                            break;
                        }
                    }
                    if (show) partNamesToShow.Add(cgp.Name);
                }
            }
            // Perform show
            foreach (var name in partNamesToShow)
            {
                part = _model.Geometry.Parts[name];
                part.Visible = true;
                _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, name, _model.Geometry.Parts[name], null, false);
            }
            UpdateCompoundSharedModelEdges(subPartVisibilities);
            _form.ShowActors(partNamesToShow.ToArray(), false);
            // Update
            AnnotateWithColorLegend();
            // Annotations
            _annotations.DrawAnnotations();
            if (_currentView == ViewGeometryModelResults.Geometry) RedrawItemIds();
        }
