        public void RemoveGeometryParts(string[] partNames, bool keepGeometrySelections, bool checkValidity = true)
        {
            BasePart part;
            HashSet<string> partNamesToRemove = new HashSet<string>();
            HashSet<string> compoundPartNamesToRemove = new HashSet<string>();
            // Find all sub parts to remove
            foreach (var name in partNames)
            {
                part = _model.Geometry.Parts[name];
                if (part is CompoundGeometryPart cgp)
                {
                    compoundPartNamesToRemove.Add(part.Name);
                    partNamesToRemove.UnionWith(cgp.SubPartNames);
                }
                else partNamesToRemove.Add(part.Name);
            }
            // A sub part named on its own is one solid of the brep of its compound, so that brep has to
            // lose the solid as well, and the compound may stop being one
            List<CompoundGeometryPart> changedSplitCompounds = new List<CompoundGeometryPart>();
            bool compoundChanged = RemoveCompoundSubParts(partNamesToRemove, compoundPartNamesToRemove,
                                                          changedSplitCompounds);
            // The cell left alone by a split compound that goes takes the name of its sub part while the
            // compound still says whose cell it is
            foreach (var splitCompound in changedSplitCompounds)
            {
                if (compoundPartNamesToRemove.Contains(splitCompound.Name)) RenameSplitCells(splitCompound);
            }
            // Use a list fo remove the compound parts as last
            List<string> orderedPartsToRemove = new List<string>(partNamesToRemove);
            orderedPartsToRemove.AddRange(compoundPartNamesToRemove);
            //
            ViewGeometryModelResults view = ViewGeometryModelResults.Geometry;
            // Remove annotations
            _annotations.RemoveCurrentArrowAnnotationsByParts(partNamesToRemove.ToArray(), view);
            //
            string[] removedParts;
            _model.Geometry.RemoveParts(orderedPartsToRemove.ToArray(), out removedParts, keepGeometrySelections);
            //
            foreach (var name in removedParts) _form.RemoveTreeNode<GeometryPart>(view, name, null);
            // A sub part that outlived its compound was a node under it and has to be shown on its own,
            // which is a change of the shape of the tree rather than of one node
            if (compoundChanged) _form.RegenerateTree();
            //
            if (checkValidity) CheckAndUpdateModelValidity(true);
            //
            DrawGeometry(false);
            // The cells that are left are numbered again once the deleted ones have given up their names,
            // in the model and in the scene
            bool cellsRenamed = false;
            foreach (var splitCompound in changedSplitCompounds)
            {
                if (!_model.Geometry.Parts.ContainsKey(splitCompound.Name)) continue;
                RenameSplitCells(splitCompound);
                cellsRenamed = true;
            }
            if (cellsRenamed) _form.RegenerateTree();
        }
        /// <summary>
        /// Takes the sub parts that are being removed out of the compounds that hold them. A sub part is
        /// one solid of the compound brep, so the brep loses that solid too - and only that solid. Every
        /// other solid is left exactly as it was, which is why the parts built from them are not touched
        /// either: they keep their ids, their properties, their meshes and every geometry id already
        /// built on them. A compound left holding one sub part is no longer a compound and is removed,
        /// which leaves that sub part standing on its own; one left holding none goes with them.
        /// </summary>
        private bool RemoveCompoundSubParts(HashSet<string> partNamesToRemove,
                                            HashSet<string> compoundPartNamesToRemove,
                                            List<CompoundGeometryPart> changedSplitCompounds)
        {
            bool compoundChanged = false;
            //
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart)) continue;
                if (compoundPartNamesToRemove.Contains(compoundPart.Name)) continue;
                // The place of a sub part in the list is the number of its solid, which is the numbering
                // every other command that names a solid of a compound uses
                List<int> solidIds = new List<int>();
                List<string> remainingSubPartNames = new List<string>();
                for (int i = 0; i < compoundPart.SubPartNames.Length; i++)
                {
                    if (partNamesToRemove.Contains(compoundPart.SubPartNames[i])) solidIds.Add(i + 1);
                    else remainingSubPartNames.Add(compoundPart.SubPartNames[i]);
                }
                if (solidIds.Count == 0) continue;
                //
                compoundChanged = true;
                if (compoundPart.CreatedBySplit) changedSplitCompounds.Add(compoundPart);
                // One solid is not a compound and no solid is nothing, so either way the compound itself
                // goes and whatever is left of it stands on its own
                if (remainingSubPartNames.Count <= 1)
                {
                    compoundPart.SubPartNames = remainingSubPartNames.ToArray();
                    compoundPartNamesToRemove.Add(compoundPart.Name);
                    continue;
                }
                //
                if (RemoveCompoundGeometrySolids(compoundPart, solidIds.ToArray()))
                {
                    compoundPart.SubPartNames = remainingSubPartNames.ToArray();
                    UpdateCompoundPartMassProperties(compoundPart);
                }
                else
                {
                    // The compound still holds the solids, so it still holds the parts made from them
                    foreach (string subPartName in compoundPart.SubPartNames)
                        partNamesToRemove.Remove(subPartName);
                    _form.WriteDataToOutput("Delete: the geometry of the compound part " + compoundPart.Name +
                                            " could not be changed, so none of its parts was deleted.");
                }
            }
            return compoundChanged;
        }
        /// <summary>
        /// Has the mesher write the brep of the compound without the named solids. The solids that stay
        /// are written out as they are, so every face, edge and vertex of theirs keeps its number.
        /// </summary>
        private bool RemoveCompoundGeometrySolids(CompoundGeometryPart compoundPart, int[] solidIds)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return false;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            //
            if (File.Exists(brepFileName)) File.Delete(brepFileName);
            File.WriteAllText(brepFileName, compoundPart.CADFileData);
            //
            StringBuilder ids = new StringBuilder();
            foreach (int solidId in solidIds) ids.Append(" " + solidId);
            //
            string argument = "BREP_REMOVE_SOLIDS " +
                              "\"" + brepFileName.ToUTF8() + "\" " +
                              "\"" + brepFileName.ToUTF8() + "\"" + ids.ToString();
            //
            JobStatus jobStatus = _jobRunner.Run(compoundPart.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            if (jobStatus != JobStatus.OK) return false;
            //
            compoundPart.CADFileDataFromFile(brepFileName);
            return true;
        }
        /// <summary>
        /// Has the mesher write the brep of the compound with the named solids made one, and returns the file it
        /// wrote, or null when the solids could not be merged. The solids that are not named are written out as
        /// they are.
        /// </summary>
        private string MergeCompoundGeometrySolids(CompoundGeometryPart compoundPart, int[] solidIds)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string brepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            string originsFileName = GetSplitGeometryOriginsFileName(brepFileName);
            //
            if (File.Exists(brepFileName)) File.Delete(brepFileName);
            if (File.Exists(originsFileName)) File.Delete(originsFileName);
            File.WriteAllText(brepFileName, compoundPart.CADFileData);
            //
            StringBuilder ids = new StringBuilder();
            foreach (int solidId in solidIds) ids.Append(" " + solidId);
            //
            string argument = "BREP_MERGE_SOLIDS " +
                              "\"" + brepFileName.ToUTF8() + "\" " +
                              "\"" + brepFileName.ToUTF8() + "\"" + ids.ToString();
            //
            JobStatus jobStatus = _jobRunner.Run(compoundPart.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            return jobStatus == JobStatus.OK ? brepFileName : null;
        }
        /// <summary>
        /// The volume and the center of mass of a compound are those of its sub parts together. The
        /// bounding box is not recomputed here, since removing the parts does that for every compound.
        /// </summary>
        private void UpdateCompoundPartMassProperties(CompoundGeometryPart compoundPart)
        {
            double volume = 0;
            Vec3D centerOfMass = new Vec3D();
            //
            foreach (string subPartName in compoundPart.SubPartNames)
            {
                BasePart subPart;
                if (!_model.Geometry.Parts.TryGetValue(subPartName, out subPart)) continue;
                //
                volume += subPart.MassProperties.Volume;
                centerOfMass += new Vec3D(subPart.MassProperties.CenterOfMass) * subPart.MassProperties.Volume;
            }
            if (volume > 0) centerOfMass *= (1 / volume);
            //
            PartMassProperties massProperties = compoundPart.MassProperties;
            massProperties.Volume = volume;
            massProperties.CenterOfMass = centerOfMass.Coor;
            compoundPart.MassProperties = massProperties;
        }
        public void SwapGeometryPartsDictionaryPositions(string partName1, string partName2,
                                                         out GeometryPart part1, out GeometryPart part2)
        {
            part1 = (GeometryPart)_model.Geometry.Parts[partName1];
            part2 = (GeometryPart)_model.Geometry.Parts[partName2];
            // Swap in dictionary
            string tmpName = _model.Geometry.Parts.GetNextNumberedKey("tmpName");
            BasePart part = new BasePart(tmpName, -1, null, null, null);
            _model.Geometry.Parts.Replace(part1.Name, part.Name, part);
            _model.Geometry.Parts.Replace(part2.Name, part1.Name, part1);
            _model.Geometry.Parts.Replace(part.Name, part2.Name, part2);
            // Swap in tree
            _form.SwapTreeNode(_currentView, partName1, part1, partName2, part2, null);
        }
        public void SwapGeometryPartGeometries(string partName1, string partName2)
        {
            GeometryPart part1;
            GeometryPart part2;
            string tmpName = _model.Geometry.Parts.GetNextNumberedKey("tmpName");
            SwapGeometryPartsDictionaryPositions(partName1, partName2, out part1, out part2);
            // Swap Ids
            int partId = part1.PartId;
            _model.Geometry.ChangePartId(partName1, part2.PartId);
            _model.Geometry.ChangePartId(partName2, partId);
            // Swap colors
            (part2.Color, part1.Color) = (part1.Color, part2.Color);
            // Swap visibilities
            (part2.Visible, part1.Visible) = (part1.Visible, part2.Visible);
            // Swap element types
            List<Enum> element1Types = part1.GetElementTypeEnums();
            List<Enum> element2Types = part2.GetElementTypeEnums();
            part1.AddElementTypeEnums(element2Types);
            part2.AddElementTypeEnums(element1Types);
            // Swap names
            part1.Name = partName2;
            part2.Name = partName1;
            _model.Geometry.Parts.Replace(partName1, tmpName, part1);
            _model.Geometry.Parts.Replace(partName2, part2.Name, part2);
            _model.Geometry.Parts.Replace(tmpName, part1.Name, part1);
            // Update colors
            _form.UpdateActor(part1.Name, tmpName, Color.Gray);
            _form.UpdateActor(part2.Name, part1.Name, part1.Color);
            _form.UpdateActor(tmpName, part2.Name, part2.Color);
            // Update visibilities
            if (part1.Visible) _form.ShowActors(new string[] { part1.Name }, false);
            else _form.HideActors(new string[] { part1.Name }, false);
            if (part2.Visible) _form.ShowActors(new string[] { part2.Name }, false);
            else _form.HideActors(new string[] { part2.Name }, false);
            // Update geometry tree
            BasePart part = new BasePart(tmpName, -1, null, null, null);
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, partName1, part, null, false);
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, partName2, part2, null, false);
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, tmpName, part1, null, false);
            //
            UpdateMeshSetupItems(false);
            //
            CheckAndUpdateModelValidity();
            //
            UpdateTreeSelection();
            if (_currentView == ViewGeometryModelResults.Geometry) RedrawItemIds();
        }
        public void RegenerateCompoundParts(string[] compoundPartNames)
        {
            if (_model == null || _model.Geometry == null) return;
            //
            bool allPartsExist;
            string importedCompoundPartName;
            string[] importedPartNames;
            CompoundGeometryPart compoundPart;
            //
            foreach (var compoundPartName in compoundPartNames)
            {
                compoundPart = (CompoundGeometryPart)_model.Geometry.Parts[compoundPartName];
                if (compoundPart.CreatedFromPartNames != null && compoundPart.CreatedFromPartNames.Length > 1)
                {
                    allPartsExist = true;
                    foreach (var createdFromPartName in compoundPart.CreatedFromPartNames)
                    {
                        if (!_model.Geometry.Parts.ContainsKey(createdFromPartName))
                        {
                            allPartsExist = false;
                            break;
                        }
                    }
                    //
                    if (allPartsExist)
                    {
                        // Create compound part
                        CreateAndImportCompoundPart(compoundPart.CreatedFromPartNames, out importedCompoundPartName,
                                                    out importedPartNames);
                        //
                        SwapCompoundParts(compoundPartName, importedCompoundPartName, true);
                    }
                }
            }
            //
            _form.SelectBaseParts(compoundPartNames);
        }
        private void SwapCompoundParts(string oldCompoundPartName, string newCompoundPartName, bool removeOldCompoundPart)
        {
            Guid? targetGroupId =
                GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts,
                                                           new string[] { oldCompoundPartName });
            PartProperties properties;
            CompoundGeometryPart compoundPart;
            CompoundGeometryPart importedCompoundPart;
            GeometryPart[] subParts;
            GeometryPart[] importedSubParts;
            // Copy sub parts
            compoundPart = (CompoundGeometryPart)_model.Geometry.Parts[oldCompoundPartName];
            subParts = GetSubParts(oldCompoundPartName);
            // Get new parts
            importedCompoundPart = (CompoundGeometryPart)_model.Geometry.Parts[newCompoundPartName];
            importedSubParts = GetSubParts(newCompoundPartName);
            importedCompoundPart.CellSubPartNames = compoundPart.CellSubPartNames?.ToArray();
            importedCompoundPart.CellSubPartIds = compoundPart.CellSubPartIds?.ToArray();
            importedCompoundPart.SplitSubPartOrder = compoundPart.SplitSubPartOrder?.ToArray();
            if (subParts.Length != importedSubParts.Length)
                throw new CaeException("The regenerated compound part has a different number of sub-parts " +
                                       "than before the regeneration.");
            // Swap parts in the tree
            SwapGeometryPartsDictionaryPositions(oldCompoundPartName, newCompoundPartName, out _, out _);
            // Delete old compound part
            if (removeOldCompoundPart) RemoveGeometryParts(new string[] { oldCompoundPartName }, true);
            // Compound                                             
            // Update visibility
            importedCompoundPart.Visible = compoundPart.Visible;
            if (importedCompoundPart.Visible) _form.ShowActors(new string[] { newCompoundPartName }, false);
            else _form.HideActors(new string[] { newCompoundPartName }, false);
            // Update part id
            _model.Geometry.ChangePartId(newCompoundPartName, compoundPart.PartId);
            // Update properties
            properties = importedCompoundPart.GetProperties();
            properties.Name = oldCompoundPartName;
            properties.Color = compoundPart.Color;
            ReplaceGeometryPartProperties(newCompoundPartName, properties);
            // Sub parts                                            
            for (int i = 0; i < importedSubParts.Length; i++)
            {
                // Update visibility
                importedSubParts[i].Visible = subParts[i].Visible;
                if (importedSubParts[i].Visible) _form.ShowActors(new string[] { importedSubParts[i].Name }, false);
                else _form.HideActors(new string[] { importedSubParts[i].Name }, false);
                // Update part id
                _model.Geometry.ChangePartId(importedSubParts[i].Name, subParts[i].PartId);
                // Update properties
                properties = importedSubParts[i].GetProperties();
                properties.Name = subParts[i].Name;
                properties.Color = subParts[i].Color;
                ReplaceGeometryPartProperties(importedSubParts[i].Name, properties);
            }
            // Keep regenerated hidden subpart layout items with their compound parent.
            MoveOrderedDictionaryItemsToGroup(_model.Geometry.Parts, importedCompoundPart.SubPartNames,
                                              targetGroupId);
            //
            UpdateMeshSetupItems(false);
            //
            CheckAndUpdateModelValidity();
        }
        //
        private void UpdateCompoundTransparency()
        {
            // Check and set compound color for the transparency icon
            bool transparent;
            byte alpha;
            BasePart part;
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart cgp)
                {
                    transparent = false;
                    foreach (var subPartName in cgp.SubPartNames)
                    {
                        part = _model.Geometry.Parts[subPartName];
                        if (part.Color.A != 255)
                        {
                            transparent = true;
                            break;
                        }
                    }
                    // If there is a change in transparency
                    if (transparent == (entry.Value.Color.A == 255))
                    {
                        alpha = entry.Value.Color.A == 255 ? (byte)127 : (byte)255;
                        //
                        entry.Value.Color = Color.FromArgb(alpha, entry.Value.Color);
                        _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, entry.Key, entry.Value, null, false);
                    }
                }
            }
        }
