        }
        // The same face offset, drawn where it would land instead of being added to the model, so that an
        // offset can be judged before it is applied. It records nothing and changes nothing.
        public async Task PreviewOffsetFaceAsync(FaceOffset faceOffset)
        {
            ClearOffsetFacePreview();
            //
            _form.SetStateWorking(Globals.PreviewText, false);
            try
            {
                await Task.Run(() => OffsetFace(faceOffset, true));
            }
            finally
            {
                _form.SetStateReady(Globals.PreviewText);
            }
        }
        public void ClearOffsetFacePreview()
        {
            if (!_offsetFacePreviewDrawn) return;
            // Redrawing the selection clears the layer the preview was drawn on
            _offsetFacePreviewDrawn = false;
            HighlightSelection();
        }
        // The surfaces the user picked, lifted out of the parts that carry them and added to the model as
        // new shell parts. The parts they were taken from are left exactly as they were, so a face offset
        // adds and never changes.
        private void OffsetFace(FaceOffset faceOffset, bool preview)
        {
            // A preview runs while the user is still picking, so it takes the ids the dialog holds rather
            // than resolving the selection again, which would replace the selection being picked
            if (!preview)
            {
                if (faceOffset.CreationData == null)
                    throw new NotSupportedException("The surface selection does not contain any selection data.");
                // In order for the Regenerate history to work perform the selection
                _selection = faceOffset.CreationData.DeepCopy(true, false);
                faceOffset.CreationIds = GetSelectionIds();
                _selection.Clear();
            }
            //
            string error = faceOffset.CheckValidity();
            if (error != null) throw new CaeException(error);
            // The surfaces of one part become one new part, so the picks are gathered by the part that
            // carries them and named by the id the modelling kernel gave the face
            int[] itemTypePartIds;
            GeometryType geometryType;
            List<int> kernelFaceIds;
            List<int> partIds = new List<int>();
            Dictionary<int, List<int>> kernelFaceIdsByPartId = new Dictionary<int, List<int>>();
            // The part whose geometry is written to the mesher, and the solid of it the ids are numbered
            // inside. They are the picked part itself and zero, unless the picked part is a sub part of a
            // compound: a sub part carries no geometry of its own, so the compound is what is written and
            // the faces of the sub part are numbered inside the solid it was written out of
            Dictionary<int, string> sourcePartNameByPartId = new Dictionary<int, string>();
            Dictionary<int, int> solidNumberByPartId = new Dictionary<int, int>();
            // Everything picked on one geometry is offset in one go, so that the surfaces of several
            // sub parts of a compound are sewn together the way the surfaces of one part are
            List<string> sourcePartNames = new List<string>();
            Dictionary<string, List<int>> partIdsBySourcePartName = new Dictionary<string, List<int>>();
            Dictionary<string, string> compoundPartNames = GetCompoundPartNamesBySubPartName();
            int numOfSkippedSurfaces = 0;
            //
            foreach (int geometryId in faceOffset.CreationIds)
            {
                itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
                geometryType = (GeometryType)itemTypePartIds[1];
                BasePart part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
                //
                if (!geometryType.IsSurface() || !(part is GeometryPart geometryPart) || !geometryPart.IsCADPart ||
                    geometryPart is CompoundGeometryPart)
                {
                    numOfSkippedSurfaces++;
                    continue;
                }
                //
                if (!kernelFaceIdsByPartId.TryGetValue(itemTypePartIds[2], out kernelFaceIds))
                {
                    string sourcePartName;
                    int solidNumber;
                    if (!GetOffsetFaceSource(geometryPart, compoundPartNames, out sourcePartName,
                                                 out solidNumber))
                    {
                        numOfSkippedSurfaces++;
                        continue;
                    }
                    sourcePartNameByPartId.Add(itemTypePartIds[2], sourcePartName);
                    solidNumberByPartId.Add(itemTypePartIds[2], solidNumber);
                    kernelFaceIds = new List<int>();
                    kernelFaceIdsByPartId.Add(itemTypePartIds[2], kernelFaceIds);
                    partIds.Add(itemTypePartIds[2]);
                    //
                    List<int> sourcePartIds;
                    if (!partIdsBySourcePartName.TryGetValue(sourcePartName, out sourcePartIds))
                    {
                        sourcePartIds = new List<int>();
                        partIdsBySourcePartName.Add(sourcePartName, sourcePartIds);
                        sourcePartNames.Add(sourcePartName);
                    }
                    sourcePartIds.Add(itemTypePartIds[2]);
                }
                int kernelFaceId = GetSplitGeometryKernelId(geometryId);
                if (!kernelFaceIds.Contains(kernelFaceId)) kernelFaceIds.Add(kernelFaceId);
            }
            // The new parts are placed beside the parts whose geometry they were written out of, which
            // for a sub part is the compound rather than the sub part itself
            //
            Guid? targetGroupId =
                GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts, sourcePartNames.ToArray());
            HashSet<string> oldPartNames = CaptureOrderedDictionaryItemNamesForGroupPlacement(
                _model.Geometry.Parts, targetGroupId);
            //
            _lastGeometryOperationCounts = new Dictionary<string, int>();
            List<string> offsetPartNames = new List<string>();
            List<string> failedPartNames = new List<string>();
            // The new parts reach the tree and the scene together at the end, so that the face offset is
            // one redraw and one tree instead of one of each per part
            bool rendering = _form.RenderingOn;
            bool screenUpdating = _form.ScreenUpdating;
            _form.RenderingOn = false;
            _form.ScreenUpdating = false;
            try
            {
                foreach (string sourcePartName in sourcePartNames)
                {
                    GeometryPart sourcePart = (GeometryPart)_model.Geometry.Parts[sourcePartName];
                    List<int> sourcePartIds = partIdsBySourcePartName[sourcePartName];
                    //
                    List<int> solidNumbers = new List<int>();
                    List<int[]> groupKernelFaceIds = new List<int[]>();
                    foreach (int partId in sourcePartIds)
                    {
                        _lastGeometryOperationCounts[_model.Geometry.GetPartFromId(partId).Name] = 0;
                        solidNumbers.Add(solidNumberByPartId[partId]);
                        groupKernelFaceIds.Add(kernelFaceIdsByPartId[partId].ToArray());
                    }
                    // The new part is named after the part the surfaces were picked on, and after the part
                    // that carries the geometry when they were picked on several of its sub parts
                    string pickedPartName = sourcePartIds.Count == 1 ?
                                            _model.Geometry.GetPartFromId(sourcePartIds[0]).Name : sourcePartName;
                    //
                    string brepFileName = OffsetPartFaces(sourcePart, solidNumbers.ToArray(),
                                                             groupKernelFaceIds, faceOffset.Offset);
                    // A part the modelling kernel refuses must not stop the parts it does not refuse
                    if (brepFileName == null) { failedPartNames.Add(pickedPartName); continue; }
                    //
                    if (preview)
                    {
                        DrawOffsetFacePreview(brepFileName, sourcePartIds);
                        continue;
                    }
                    //
                    string[] partNames = ImportOffsetFaceParts(pickedPartName, brepFileName);
                    if (partNames.Length == 0) { failedPartNames.Add(pickedPartName); continue; }
                    //
                    offsetPartNames.AddRange(partNames);
                    foreach (int partId in sourcePartIds)
                        _lastGeometryOperationCounts[_model.Geometry.GetPartFromId(partId).Name] =
                            kernelFaceIdsByPartId[partId].Count;
                }
            }
            finally
            {
                _form.ScreenUpdating = screenUpdating;
                _form.RenderingOn = rendering;
            }
            //
            // A preview leaves the model alone: nothing is added, nothing is renamed and the selection the
            // user is still picking with stays as it is
            if (preview)
            {
                foreach (string partName in failedPartNames)
                    _form.WriteDataToOutput("Offset face preview: no surface was offset from the part " +
                                            partName + ".");
                return;
            }
            //
            _lastOffsetFacePartNames = offsetPartNames.ToArray();
            //
            if (offsetPartNames.Count > 0)
            {
                MoveAddedOrderedDictionaryItemsToGroup(_model.Geometry.Parts, oldPartNames, targetGroupId);
                UpdateAfterImport(".brep");
            }
            //
            WriteGeometryOperationReport("Offset face", "surfaces were offset");
            //
            foreach (string partName in offsetPartNames)
                _form.WriteDataToOutput("Offset face: the part " + partName + " was created.");
            foreach (string partName in failedPartNames)
                _form.WriteDataToOutput("Offset face: no surface was offset from the part " + partName + ".");
            if (numOfSkippedSurfaces > 0)
                _form.WriteDataToOutput("Offset face: " + numOfSkippedSurfaces + " selected surfaces do not " +
                                        "belong to a CAD part a surface can be offset from and were skipped.");
            //
            if (partIds.Count == 0)
                MessageBoxes.ShowWarning("Surfaces can only be offset from CAD parts.");
            //
            ClearAllSelection();
            CheckAndUpdateModelValidity();
        }
        // The offset geometry drawn where it would land. It is the geometry the operation itself would
        // add, read back from the file the mesher wrote, so what the user sees is what the face offset
        // makes and not an approximation of it.
        private void DrawOffsetFacePreview(string brepFileName, List<int> pickedPartIds)
        {
            string visFileName = CreateVisFile(brepFileName, false);
            if (visFileName == null) return;
            //
            CaeMesh.FeMesh previewMesh = FileInOut.Input.VisFileReader.Read(visFileName);
            if (previewMesh == null) return;
            //
            double[] offset = GetOffsetFacePreviewOffset(pickedPartIds);
            int count = 0;
            //
            foreach (var entry in previewMesh.Parts)
            {
                // The boundaries of the offset faces are what says where one face ends and the next
                // begins, which is the whole question an offset raises, so only they are drawn
                if (!entry.Value.PartType.HasEdges() || entry.Value.Visualization.EdgeCells == null) continue;
                //
                vtkMaxActorData data = new vtkMaxActorData();
                data.Name = "offsetFacePreview" + count++;
                // The preview is highlighted as the other previews are, so a pick that changes the selection
                // also takes it off the screen
                data.Layer = vtkRendererLayer.Selection;
                data.Color = _settings.Pre.PrimaryHighlightColor;
                data.LineWidth = 2;
                data.CanHaveElementEdges = false;
                data.BackfaceCulling = false;
                data.Pickable = false;
                //
                previewMesh.GetNodesAndCellsForModelEdges(entry.Value, out data.Geometry.Nodes.Ids,
                                                          out data.Geometry.Nodes.Coor,
                                                          out data.Geometry.Cells.CellNodeIds,
                                                          out data.Geometry.Cells.Types);
                data.Geometry.Nodes.Coor = MoveOffsetFacePreviewCoor(data.Geometry.Nodes.Coor, offset);
                //
                ApplyLighting(data);
                _form.Add3DCells(data);
                _offsetFacePreviewDrawn = true;
            }
        }
        // The exploded view offset the preview is drawn at. The picked parts carry it, and where they do
        // not all stand at the same one there is no single place the offset surface can be drawn at, so
        // it is drawn where the geometry itself is.
        private double[] GetOffsetFacePreviewOffset(List<int> pickedPartIds)
        {
            double[] offset = null;
            foreach (int partId in pickedPartIds)
            {
                BasePart part = _model.Geometry.GetPartFromId(partId);
                double[] partOffset = part == null ? null : part.Offset;
                if (partOffset == null) partOffset = new double[3];
                //
                if (offset == null) offset = partOffset;
                else if (offset[0] != partOffset[0] || offset[1] != partOffset[1] || offset[2] != partOffset[2])
                    return null;
            }
            return offset;
        }
        private static double[][] MoveOffsetFacePreviewCoor(double[][] nodeCoor, double[] offset)
        {
            if (nodeCoor == null || offset == null) return nodeCoor;
            if (offset[0] == 0 && offset[1] == 0 && offset[2] == 0) return nodeCoor;
            //
            double[][] movedCoor = new double[nodeCoor.Length][];
            for (int i = 0; i < nodeCoor.Length; i++)
            {
                movedCoor[i] = new double[] { nodeCoor[i][0] + offset[0], nodeCoor[i][1] + offset[1],
                                              nodeCoor[i][2] + offset[2] };
            }
            return movedCoor;
        }
        // The part the geometry is written out of, and the solid of it the picked faces are numbered
        // inside. A sub part of a compound is written as its compound, because it carries no geometry of
        // its own, and its place in the sub part list is the number of its solid - the order the solids
        // were written out of the compound in.
        private bool GetOffsetFaceSource(GeometryPart part, Dictionary<string, string> compoundPartNames,
                                             out string sourcePartName, out int solidNumber)
        {
            sourcePartName = part.Name;
            solidNumber = 0;
            //
            string compoundPartName;
            if (!compoundPartNames.TryGetValue(part.Name, out compoundPartName)) return true;
            //
            BasePart basePart;
            if (!_model.Geometry.Parts.TryGetValue(compoundPartName, out basePart) ||
                !(basePart is CompoundGeometryPart compoundPart)) return false;
            //
            int index = Array.IndexOf(compoundPart.SubPartNames, part.Name);
            if (index < 0) return false;
            //
            sourcePartName = compoundPartName;
            solidNumber = index + 1;
            return true;
        }
        // The picked faces arrive grouped by the solid of the written geometry they are numbered inside,
        // which is one group for a part of its own and one group per picked sub part for a compound.
        private string OffsetPartFaces(GeometryPart part, int[] solidNumbers, List<int[]> kernelFaceIds,
                                          double offset)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inputBrepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            string outputBrepFileName = inputBrepFileName;
            string faceIdsArgument = solidNumbers.Length.ToString();
            for (int i = 0; i < solidNumbers.Length; i++)
            {
                faceIdsArgument += " " + solidNumbers[i] + " " + kernelFaceIds[i].Length;
                foreach (int kernelFaceId in kernelFaceIds[i]) faceIdsArgument += " " + kernelFaceId;
            }
            //
            if (File.Exists(inputBrepFileName)) File.Delete(inputBrepFileName);
            //
            File.WriteAllText(inputBrepFileName, part.CADFileData);
            //
            string argument = "BREP_OFFSET_FACES " +
                              "\"" + inputBrepFileName.ToUTF8() + "\" " +
                              "\"" + outputBrepFileName.ToUTF8() + "\" " +
                              offset + " " +
                              faceIdsArgument;
            //
            JobStatus jobStatus = _jobRunner.Run(part.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK) return outputBrepFileName;
            else return null;
        }
        // The offset geometry is added as a part of its own, named after the part it was taken from so
        // that the two can be told apart in the tree. The offset surfaces that share no edge are written
        // to a file each, because a part imported from a file carries the whole file as its geometry and
        // would be meshed with the others.
        private string[] ImportOffsetFaceParts(string pickedPartName, string brepFileName)
        {
            string[] patchFileNames = SplitAssembly(brepFileName, "BREP_ASSEMBLY_SPLIT_TO_PARTS", 1);
            if (patchFileNames == null) return new string[0];
            //
            List<string> offsetPartNames = new List<string>();
            foreach (string patchFileName in patchFileNames)
            {
                string[] importedPartNames = ImportBrepPartFile(patchFileName);
                if (File.Exists(patchFileName)) File.Delete(patchFileName);
                if (importedPartNames == null) continue;
                //
                foreach (string importedPartName in importedPartNames)
                {
                    BasePart importedPart;
                    if (!_model.Geometry.Parts.TryGetValue(importedPartName, out importedPart)) continue;
                    //
                    string offsetPartName = GetOffsetFacePartName(pickedPartName);
                    importedPart.Name = offsetPartName;
                    _model.Geometry.Parts.Replace(importedPartName, offsetPartName, importedPart);
                    //
                    offsetPartNames.Add(offsetPartName);
                }
            }
            return offsetPartNames.ToArray();
        }
        private string GetOffsetFacePartName(string sourcePartName)
        {
            return _model.GetReservedPartNames().GetNextNumberedKey(sourcePartName + "_Offset");
        }
        private bool ReplacePartGeometryFromFile(GeometryPart part, string fileName, bool keepGeometrySelections)
        {
            int count = 0;
            string[] importedFileNames = null;
            string extension = Path.GetExtension(fileName);
            //
            while (importedFileNames == null && count < 5)  // Check for timeout
            {
                if (extension == ".brep") importedFileNames = ImportBrepPartFile(fileName, false);
                else if (extension == ".stl") importedFileNames = _model.ImportGeometryFromStlFile(fileName);
                else throw new NotSupportedException();
                count++;
            }
            if (importedFileNames == null)
            {
                throw new CaeException("Importing geometry file during the replace of the geometry part failed.");
            }
            else if (importedFileNames.Length == 1)
            {
                //_form.ScreenUpdating = false;
                // Add the imported part to the model tree
                UpdateAfterImport(extension);
                // Copy old part properties to the new part
                GeometryPart newPart = (GeometryPart)_model.Geometry.Parts[importedFileNames[0]];
                newPart.Name = part.Name;
                newPart.Color = part.Color;
                newPart.AddElementTypeEnums(part.GetElementTypeEnums());
                // Switch old and new part in the dictionary
                _model.Geometry.Parts.Replace(part.Name, newPart.Name, newPart);
                part.Name = importedFileNames[0];
                _model.Geometry.Parts.Replace(importedFileNames[0], part.Name, part);
                // Remove old part
                RemoveGeometryParts(new string[] { part.Name }, keepGeometrySelections, false);
                _model.Geometry.ChangePartId(newPart.Name, part.PartId);
                //
                UpdateMeshSetupItems(false);
                //
                UpdateAfterImport(extension);
                //
                CheckAndUpdateModelValidity();
                //_form.ScreenUpdating = true;
            }
            else
            {
                UpdateAfterImport(extension);
                ClearAllSelection();
            }
            return true;
        }
        public void SplitAFaceUsingTwoPoints(GeometrySelection surfaceSelection, GeometrySelection verticesSelection)
        {
            if (surfaceSelection.CreationData != null && verticesSelection.CreationData != null)
            {
                // In order for the Regenerate history to work perform the selection
                _selection = surfaceSelection.CreationData.DeepCopy(true, false);
                surfaceSelection.GeometryIds = GetSelectionIds();
                _selection.Clear();
                //
                _selection = verticesSelection.CreationData.DeepCopy(true, false);
                verticesSelection.GeometryIds = GetSelectionIds();
                _selection.Clear();
            }
            else throw new NotSupportedException("The geometry selection does not contain any selection data.");
            //
            if (surfaceSelection.GeometryIds.Length != 1 || verticesSelection.GeometryIds.Length != 2)
                throw new CaeException("The selection does not contain 1 face and 2 vertices.");
            // Split
            int faceId;
            int node1Id;
            int node2Id;
            FeNode node1;
            FeNode node2;
            BasePart part1;
            BasePart part2;
            BasePart facePart;
            int[] itemTypePartIds;
            double[] offset;
            itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(surfaceSelection.GeometryIds[0]);
            facePart = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            faceId = itemTypePartIds[0];
            //
            itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(verticesSelection.GeometryIds[0]);
            part1 = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            node1Id = part1.Visualization.VertexNodeIds[itemTypePartIds[0]];
            //
            itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(verticesSelection.GeometryIds[1]);
            part2 = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            node2Id = part2.Visualization.VertexNodeIds[itemTypePartIds[0]];
            //
            node1 = _model.Geometry.Nodes[node1Id].DeepCopy();
            node2 = _model.Geometry.Nodes[node2Id];
            if (IsExplodedViewActive())
            {
                offset = part1.Offset;
                node1.X -= offset[0];
                node1.Y -= offset[1];
                node1.Z -= offset[2];
                //
                offset = part2.Offset;
                node2.X -= offset[0];
                node2.Y -= offset[1];
                node2.Z -= offset[2];
            }
            //
            _lastGeometryOperationCounts = new Dictionary<string, int>();
            if (facePart != null && facePart is GeometryPart gp && gp.IsCADPart)
            {
                // A split leaves the part with one face more, and the modelling kernel returns a shape
                // whether or not it made the cut, so the face count is what says it happened
                int facesBefore = gp.Visualization == null ? 0 : gp.Visualization.FaceCount;
                _lastGeometryOperationCounts[gp.Name] = 0;
                string brepFileName = SplitAFaceUsingTwoPoints(gp, faceId, node1, node2);
                //
                if (brepFileName != null)
                {
                    string partName = gp.Name;
                    ReplacePartGeometryFromFile(gp, brepFileName, true);
                    BasePart splitPart;
                    if (_model.Geometry.Parts.TryGetValue(partName, out splitPart) && splitPart.Visualization != null)
                        _lastGeometryOperationCounts[partName] = splitPart.Visualization.FaceCount - facesBefore;
                }
                else ClearAllSelection();
                //
                WriteGeometryOperationReport("Split face", "faces were added");
            }
            else MessageBoxes.ShowWarning("Faces on non-CAD parts cannot be split.");
            //
            CheckAndUpdateModelValidity();
        }
        private string SplitAFaceUsingTwoPoints(GeometryPart part, int faceId, FeNode node1, FeNode node2)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inputBrepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            string outputBrepFileName = inputBrepFileName;
            //
            if (File.Exists(inputBrepFileName)) File.Delete(inputBrepFileName);
            //
            File.WriteAllText(inputBrepFileName, part.CADFileData);
            //
            string argument = "BREP_SPLIT_A_FACE_USING_TWO_POINTS " +
                              "\"" + inputBrepFileName.ToUTF8() + "\" " +
                              "\"" + outputBrepFileName.ToUTF8() + "\" " +
                              (faceId + 1) + " " +
                              node1.X + " " + node1.Y + " " + node1.Z + " " +
                              node2.X + " " + node2.Y + " " + node2.Z;
            //
            JobStatus jobStatus = _jobRunner.Run(part.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK) return outputBrepFileName;
            else return null;
        }
        //
        private static readonly string[] _geometryFeatureSymbolNames = new string[]
        {
            "splitGeometryPlane", "splitGeometryPlaneBorder", "splitGeometryExtrusion",
            "splitGeometryExtrusionBorder"
        };
        // An actor may rename itself while it is being added - AddSphereActor appends a suffix of its
        // own - so every name that actually reached the renderer is collected and those are the names
        // that get removed, rather than the names the symbols were asked to use
        [NonSerialized] private HashSet<string> _geometryFeatureSymbolActorNames;
        [NonSerialized] private SplitToolSymbol _splitToolSymbolRecorder;
        // A face offset preview is drawn on the selection layer, which is cleared only as a whole
        [NonSerialized] private bool _offsetFacePreviewDrawn;
        // While a split dialog is open, the geometry and the annotations as they were before each of its splits,
        // with the command each split was recorded as, so that the splits can be undone without replaying the
        // history. Null while no split dialog keeps an undo.
        [NonSerialized] private Stack<(Command Command, FeMesh Geometry, AnnotationContainer Annotations)>
                                _splitGeometryUndoStates;
        // The exploded view offset the symbols of the feature are drawn at. The symbols are computed
        // from the geometry metadata, which holds the coordinates of the part itself, and are moved
        // onto the drawn part as they are handed to the renderer - the metadata is never touched
        [NonSerialized] private double[] _geometryFeatureSymbolOffset;
        // The parts faded while a geometry feature dialog is open. The fade is a display state only -
        // the part keeps its own color, so closing the dialog restores it without a command
        [NonSerialized] private HashSet<string> _geometryFeatureFadedPartNames;
        // While a geometry feature is picking points, hovering an edge previews the point that edge
        // would give instead of highlighting the edge
        [NonSerialized] private GeometryFeaturePointPickingEnum _geometryFeaturePointPicking;
        // A picked sub part normally stands for the whole compound it belongs to. A geometry feature cuts
        // the solids it is given, so there one pick means one sub part and an area selection is what names
        // several of them.
        [NonSerialized] private bool _pickCompoundSubPartsSeparately;
        public void SplitGeometry(GeometryFeature geometryFeature)
        {
            SplitGeometry(geometryFeature, false);
        }
        // The edges the split would make, drawn where it would make them, so that a tool can be judged
        // before it is applied. It records nothing and changes nothing.
        public async Task PreviewSplitGeometryAsync(GeometryFeature geometryFeature)
        {
            ThrowIfSplitGeometryOffsetsDiffer(geometryFeature);
            //
            _form.SetStateWorking(Globals.PreviewText, false);
            try
            {
                await Task.Run(() => SplitGeometry(geometryFeature, true));
            }
            finally
            {
                _form.SetStateReady(Globals.PreviewText);
            }
        }
        // The split a dialog asks for, run without holding the user interface thread, so that the progress
        // shows and the application answers while the modelling kernel works
        public async Task SplitGeometryCommandAsync(GeometryFeature geometryFeature)
        {
            bool stateSet = _form.SetStateWorking(Globals.SplittingGeometryText);
            try
            {
                await Task.Run(() => SplitGeometryCommand(geometryFeature));
            }
            finally
            {
                if (stateSet) _form.SetStateReady(Globals.SplittingGeometryText);
            }
        }
        public bool CanUndoSplitGeometry
        {
            get { return _splitGeometryUndoStates != null && _splitGeometryUndoStates.Count > 0; }
        }
        // A split dialog keeps its undo from the moment it opens until it closes. OK - New prepares the dialog
        // again without closing it, and the splits made before it stay undoable.
        public void BeginSplitGeometryUndo()
        {
            if (_splitGeometryUndoStates == null)
                _splitGeometryUndoStates = new Stack<(Command, FeMesh, AnnotationContainer)>();
        }
        public void EndSplitGeometryUndo()
        {
            _splitGeometryUndoStates = null;
        }
        // The geometry is put back as it was before the last split of the dialog and the history steps back past
        // the split, as Edit - Undo would, but without replaying the history
        public void UndoSplitGeometry()
        {
            if (!CanUndoSplitGeometry) return;
            //
            var state = _splitGeometryUndoStates.Peek();
            // The history must still end with the split, or the model put back would not be the model the
            // history builds
            if (_commands.LastExecutedCommand != state.Command)
            {
                _splitGeometryUndoStates.Clear();
                throw new CaeException("The command history changed after the split, so the split cannot be " +
                                       "undone here. Use Edit - Undo instead.");
            }
            _splitGeometryUndoStates.Pop();
            //
            Dictionary<string, bool>[] treeState = _form.GetStableTreeExpandCollapseState();
            _model.Geometry = state.Geometry;
            _annotations = new AnnotationContainer(state.Annotations, this);
            _commands.UndoWithoutRegeneration();
            //
            UpdateAfterPartsChanged();
            UpdateExplodedView(false);
            _currentView = ViewGeometryModelResults.Geometry;
            _form.SetCurrentView(_currentView);
            DrawGeometry(false);
            _form.RegenerateTree();
            _form.SetStableTreeExpandCollapseState(treeState);
            //
            _form.WriteDataToOutput(state.Command.Name + ": the split was undone.");
            //
            CheckAndUpdateModelValidity();
        }
        private void ThrowIfSplitGeometryOffsetsDiffer(GeometryFeature geometryFeature)
        {
            double[] offset;
            if (!TryGetSplitGeometryFeatureOffset(geometryFeature, out offset))
                throw new CaeException("The exploded view holds the parts of this operation at " +
                                       "different places, so the splitting tool would not cut where it " +
                                       "is drawn. Turn the exploded view off, or split only parts that " +
                                       "stand at the same offset.");
        }
        private void SplitGeometry(GeometryFeature geometryFeature, bool preview)
        {
            // A preview runs while the user is still picking, so it takes the ids and the values the dialog
            // holds rather than resolving the selections again, which would replace the selection being picked
            if (!preview)
            {
                // In order for the Regenerate history to work perform the selection
                if (geometryFeature.CreationData == null)
                    throw new NotSupportedException("The region selection does not contain any selection data.");
                //
                // The region is resolved the way it was picked: one sub part means one sub part. Without this
                // the resolution would expand it to every sub part of its compound, since by the time the
                // split runs the picker has long moved on to the splitter and no longer asks for sub parts.
                bool pickSubPartsSeparately = _pickCompoundSubPartsSeparately;
                _pickCompoundSubPartsSeparately = true;
                try
                {
                    geometryFeature.CreationIds = GetIdsFromSelection(geometryFeature.CreationData);
                }
                finally
                {
                    _pickCompoundSubPartsSeparately = pickSubPartsSeparately;
                }
                if (geometryFeature.SplitterData != null)
                    geometryFeature.SplitterIds = GetIdsFromSelection(geometryFeature.SplitterData);
                if (geometryFeature is SplitByExtrudedEdges edgeItem && edgeItem.DirectionData != null)
                    edgeItem.DirectionIds = GetIdsFromSelection(edgeItem.DirectionData);
                // The picked geometry gives the values again, so that a replay follows the regenerated
                // geometry instead of the numbers the geometry had when the operation was first applied
                UpdateSplitGeometryFromDirectionSelection(geometryFeature);
                UpdateSplitGeometryFromSplitterSelection(geometryFeature);
            }
            //
            string error = geometryFeature.CheckValidity();
            if (error != null) throw new CaeException(error);
            //
            int numOfSkippedParts;
            string[] partNames = GetSplitGeometryRegionPartNames(geometryFeature, out numOfSkippedParts);
            if (partNames.Length == 0)
                throw new CaeException(geometryFeature.SplitType == SplitTypeEnum.Shell ?
                                       "None of the selected surfaces belongs to a CAD part that can be " +
                                       "split." :
                                       "None of the selected parts is a CAD part that can be split.");
            // One tool is built for the whole region, so it is sized from the bounding box of all of its
            // parts here. A tool sized inside the mesher would come out different for each part.
            double[] extent = GetSplitGeometryRegionExtent(partNames);
            if (extent == null) throw new CaeException("The size of the parts to split could not be determined.");
            // The picks name the geometry they were made on only until the parts are replaced, so the
            // symbol the history shows is made now, and made again by every regenerate
            if (!preview) geometryFeature.ToolSymbol = GetSplitGeometryToolSymbol(geometryFeature, extent);
            //
            Dictionary<int, string> sourceBrepFileNames = WriteSplitGeometrySourceBreps(geometryFeature);
            try
            {
                if (preview) PreviewSplitGeometryParts(geometryFeature, partNames, extent, sourceBrepFileNames);
                else SplitGeometryParts(geometryFeature, partNames, extent, sourceBrepFileNames, numOfSkippedParts);
            }
            finally
            {
                DeleteSplitGeometrySourceBreps(sourceBrepFileNames);
            }
        }
        private void SplitGeometryParts(GeometryFeature geometryFeature, string[] partNames, double[] extent,
                                        Dictionary<int, string> sourceBrepFileNames, int numOfSkippedParts)
        {
            _lastGeometryOperationCounts = new Dictionary<string, int>();
            List<string> failedPartNames = new List<string>();
            List<string> refusedPartNames = new List<string>();
            //
            // A part is taken out of the scene and out of the model tree before the pieces it was cut
            // into are put back. Rendering and tree updating are held off until the whole region is done,
            // which turns that into one redraw and one tree, instead of a flicker through a scene the
            // part has left and the pieces have not yet reached.
            bool rendering = _form.RenderingOn;
            bool screenUpdating = _form.ScreenUpdating;
            bool stateSet = _form.SetStateWorking(Globals.SplittingGeometryText);
            _form.RenderingOn = false;
            _form.ScreenUpdating = false;
            try
            {
                foreach (string partName in partNames)
                {
                    BasePart basePart;
                    if (!_model.Geometry.Parts.TryGetValue(partName, out basePart) ||
                        !(basePart is GeometryPart part)) continue;
                    //
                    int facesBefore = GetGeometryPartFaceCount(partName);
                    _lastGeometryOperationCounts[partName] = 0;
                    //
                    int[] solidIds = GetSplitGeometrySolidIds(geometryFeature, partName);
                    List<int> targetSolids;
                    List<int[]> targetFaceIds;
                    GetSplitGeometryTargetFaces(geometryFeature, partName, out targetSolids,
                                                out targetFaceIds);
                    string brepFileName = SplitGeometryPart(part, geometryFeature, extent,
                                                            sourceBrepFileNames, solidIds, targetSolids,
                                                            targetFaceIds, false);
                    // A part the tool misses must not stop the parts it does not miss
                    if (brepFileName == null) { failedPartNames.Add(partName); continue; }
                    //
                    string resultPartName;
                    if (geometryFeature.SplitType == SplitTypeEnum.Shell)
                    {
                        // The faces were divided and the body they belong to was left whole, so the part
                        // is put back as itself. A result that is not the same body cannot be put back
                        // that way, and the part then keeps the geometry it had
                        if (!ReplaceSplitSurfacePart(part, brepFileName, out resultPartName))
                        {
                            refusedPartNames.Add(partName);
                            continue;
                        }
                    }
                    else
                    {
                        resultPartName = ReplaceSplitGeometryPart(part, brepFileName);
                        if (resultPartName == null) { failedPartNames.Add(partName); continue; }
                    }
                    //
                    _lastGeometryOperationCounts[partName] =
                        GetGeometryPartFaceCount(resultPartName) - facesBefore;
                }
            }
            finally
            {
                _form.ScreenUpdating = screenUpdating;
                // A replay of the history draws nothing until it ends, and the tree it leaves behind is
                // the one it builds then, so only a split the user asked for rebuilds the tree here
                if (screenUpdating) _form.RegenerateTree();
                if (stateSet) _form.SetStateReady(Globals.SplittingGeometryText);
                _form.RenderingOn = rendering;
            }
            //
            string operationName = geometryFeature.SplitType == SplitTypeEnum.Shell ?
                                   "Split shell" : "Split solid";
            WriteGeometryOperationReport(operationName, "faces were added");
            //
            foreach (string partName in failedPartNames)
                _form.WriteDataToOutput(operationName + ": the part " + partName + " was not split.");
            foreach (string partName in refusedPartNames)
                _form.WriteDataToOutput(operationName + ": the part " + partName + " was left as it was, " +
                                        "because splitting its surfaces did not give back the same body.");
            if (numOfSkippedParts > 0)
                _form.WriteDataToOutput(operationName + ": " + numOfSkippedParts + " selected parts are not " +
                                        "CAD parts and were skipped.");
            //
            ClearAllSelection();
            CheckAndUpdateModelValidity();
        }
        public void UpdateSplitGeometryFromSplitterSelection(GeometryFeature geometryFeature)
        {
            int[] ids = geometryFeature.SplitterIds;
            //
            if (geometryFeature is SplitByPlaneThreePoints threePoints)
            {
                if (ids == null) return;
                //
                double[] point;
                // Every pick means the point the entity it hit carries, so the points fill in the order
                // they are captured, not in the order of the picks: a pick that gives no point must not
                // leave a hole that the plane would then be built from
                int numberOfPoints = 0;
                for (int i = 0; i < ids.Length && numberOfPoints < 3; i++)
                {
                    if (TryGetSplitGeometryPoint(ids[i], out point))
                        threePoints.Points[numberOfPoints++] = point;
                }
                threePoints.NumberOfPoints = numberOfPoints;
            }
            else if (geometryFeature is SplitByLineTwoPoints twoPointLine)
            {
                if (ids == null) return;
                // Two points, captured the way the three of a plane are: a pick that gives no point
                // must not leave a hole that the line would then be drawn through
                double[] point;
                int numberOfPoints = 0;
                for (int i = 0; i < ids.Length && numberOfPoints < 2; i++)
                {
                    if (TryGetSplitGeometryPoint(ids[i], out point))
                        twoPointLine.Points[numberOfPoints++] = point;
                }
                twoPointLine.NumberOfPoints = numberOfPoints;
            }
            else if (geometryFeature is SplitByPointAndNormal pointAndNormal)
            {
                if (ids == null) return;
                // A pick is sorted by the kind of entity it hit, so a vertex and an edge can be picked in
                // one operation, and a circular edge gives the point and the normal by itself
                double[] point;
                double[] direction;
                Dictionary<int, SelectionNodeMouse> pickNodes =
                    GetSplitGeometryPickNodes(pointAndNormal.SplitterData);
                foreach (int id in ids)
                {
                    GeometryType geometryType = (GeometryType)FeMesh.GetItemTypePartIdsFromGeometryId(id)[1];
                    // An edge can mean either the point on it or the direction it runs in, and where the
                    // user clicked is what decides
                    if (geometryType.IsEdge())
                    {
                        bool nearPoint = IsSplitGeometryPickOnThePoint(id, pickNodes, pointAndNormal);
                        if (nearPoint && TryGetSplitGeometryPoint(id, out point)) pointAndNormal.Point = point;
                        else if (TryGetSplitGeometryDirection(id, out direction))
                            pointAndNormal.Normal = direction;
                    }
                    else
                    {
                        if (TryGetSplitGeometryPoint(id, out point)) pointAndNormal.Point = point;
                        if (TryGetSplitGeometryDirection(id, out direction)) pointAndNormal.Normal = direction;
                    }
                }
            }
            else if (geometryFeature is SplitByExtendedFace extendedFace)
            {
                if (ids == null) { extendedFace.FaceTypes = null; return; }
                //
                GeomFaceType[] faceTypes = new GeomFaceType[ids.Length];
                for (int i = 0; i < ids.Length; i++) faceTypes[i] = GetSplitGeometryFaceType(ids[i]);
                extendedFace.FaceTypes = faceTypes;
            }
            else if (geometryFeature is SplitByExtrudedEdges extrudedEdges)
            {
                UpdateSplitGeometryExtrusionDirection(extrudedEdges);
            }
        }
        /// <summary>
        /// The surface a picked face lies on, as the CAD metadata reports it.
        /// </summary>
        private GeomFaceType GetSplitGeometryFaceType(int geometryId)
        {
            BasePart part;
            GeometryType geometryType;
            int itemId;
            GeometryMetadataEntity entity = GetSplitGeometryMetadataEntity(geometryId, out part,
                                                                          out geometryType, out itemId);
            string[] text;
            GeomFaceType faceType;
            if (entity != null && entity.TryGetCanonicalText("type", out text) && text.Length == 1 &&
                Enum.TryParse(text[0], true, out faceType)) return faceType;
            //
            return GeomFaceType.Unknown;
        }
        public void UpdateSplitGeometryFromDirectionSelection(GeometryFeature geometryFeature)
        {
            if (!(geometryFeature is SplitByExtrudedEdges extrudedEdges)) return;
            //
            UpdateSplitGeometryExtrusionDirection(extrudedEdges);
        }
        /// <summary>
        /// Puts a splitting plane that has not been picked yet through the center of the bounding box of
        /// the parts it is to cut. A plane needs a point, and the one a new feature carries is the global
        /// origin, which is usually nowhere near the parts: the plane would be drawn off in space instead
        /// of through the geometry it is about to cut.
        /// </summary>
        public void SetSplitGeometryDefaultPlanePoint(GeometryFeature geometryFeature)
        {
            if (!(geometryFeature is SplitByPointAndNormal pointAndNormal)) return;
            // A picked point is what positions the plane, so only an unpicked one is placed here
            if (geometryFeature.SplitterIds != null && geometryFeature.SplitterIds.Length > 0) return;
            //
            int numOfSkippedParts;
            string[] partNames = GetSplitGeometryRegionPartNames(geometryFeature, out numOfSkippedParts);
            double[] extent = GetSplitGeometryRegionExtent(partNames);
            if (extent == null) return;
            // The extent is the bounding box grown by a margin on both sides, so its center is the center
            // of the box itself
            pointAndNormal.Point = new double[] { 0.5 * (extent[0] + extent[1]), 0.5 * (extent[2] + extent[3]),
                                                  0.5 * (extent[4] + extent[5]) };
        }
        public void DrawSplitGeometrySymbols(GeometryFeature geometryFeature, bool regionIsArmed,
                                             bool fadeOutsideRegion = true)
        {
            // Where the parts of the operation do not share one offset there is no one place the tool
            // can be drawn at, so it is drawn where the modelling kernel will use it, and the operation
            // is refused when it is applied
            double[] symbolOffset;
            TryGetSplitGeometryFeatureOffset(geometryFeature, out symbolOffset);
            _geometryFeatureSymbolOffset = symbolOffset;
            //
            // The selection layer colors what it holds with the selection color, so the tool symbol
            // lives on the overlay layer with the rest of the symbols and is removed by name
            _form.RemoveOverlayActors(_geometryFeatureSymbolNames);
            if (_geometryFeatureSymbolActorNames != null && _geometryFeatureSymbolActorNames.Count > 0)
            {
                _form.RemoveOverlayActors(_geometryFeatureSymbolActorNames.ToArray());
                _geometryFeatureSymbolActorNames.Clear();
            }
            //
            int numOfSkippedParts;
            string[] partNames = GetSplitGeometryRegionPartNames(geometryFeature, out numOfSkippedParts);
            // While the region is being picked it is shown by the ordinary selection highlight. Once the
            // picker moves on, that highlight belongs to the splitter geometry, so the region is shown by
            // fading everything that is not part of it instead.
            SetGeometryFeatureRegionFade(GetSplitGeometryPickedPartNames(geometryFeature),
                                         !regionIsArmed && fadeOutsideRegion);
            // Arming a picker cleared what was drawn, and installing its selection does not draw it, so
            // the selection of whichever target is armed is highlighted here. An entity that was taken as
            // a point is left out: the point marker is what stands for it, and highlighting the edge as
            // well would say the edge was selected.
            if (_geometryFeaturePointPicking == GeometryFeaturePointPickingEnum.None) HighlightSelection();
            else HighlightGeometryFeatureSelectionWithoutPoints(geometryFeature);
            //
            double[] extent = GetSplitGeometryRegionExtent(partNames);
            if (extent == null) return;
            //
            DrawSplitGeometryTool(geometryFeature, extent, regionIsArmed);
            //
            _form.UpdateScalarsAndRedraw();
        }
        private void DrawSplitGeometryTool(GeometryFeature geometryFeature, double[] extent, bool regionIsArmed)
        {
            // The tool is a large surface that lies between the mouse and the parts it is to cut, so it
            // is shown only once the region has been picked and the picker has moved on to the splitter
            if (geometryFeature is SplitByPlaneThreePoints threePoints)
            {
                if (!regionIsArmed)
                    DrawSplitGeometryPlaneSymbol(threePoints.GetPlaneOrigin(), threePoints.GetPlaneNormal(), extent);
                // The point an edge resolved to is nowhere near the place that was clicked, so it is
                // marked rather than left for the user to infer
                DrawSplitGeometryPointSymbols(threePoints);
            }
            else if (geometryFeature is SplitByPointAndNormal pointAndNormal)
            {
                if (!regionIsArmed)
                    DrawSplitGeometryPlaneSymbol(pointAndNormal.GetPlaneOrigin(), pointAndNormal.GetPlaneNormal(),
                                                 extent);
                DrawSplitGeometryPointSymbols(pointAndNormal);
            }
            else if (geometryFeature is SplitByLineTwoPoints twoPointLine)
            {
                // The line is drawn on the surface by the modelling kernel and is not known here, so
                // what is shown is the two points it will be drawn through
                DrawSplitGeometryPointSymbols(twoPointLine);
            }
            else if (geometryFeature is SplitByExtendedFace extendedFace && !regionIsArmed)
                DrawSplitGeometryExtendedFaceSymbol(extendedFace, extent);
            else if (geometryFeature is SplitByExtrudedEdges extrudedEdges && !regionIsArmed)
                DrawSplitGeometryExtrusionSymbol(extrudedEdges, extent);
        }
        /// <summary>
        /// The symbol the tool is drawn with, collected instead of drawn and held in the coordinates of the
        /// parts themselves, so that the exploded view does not end up in it.
        /// </summary>
        private SplitToolSymbol GetSplitGeometryToolSymbol(GeometryFeature geometryFeature, double[] extent)
        {
            double[] symbolOffset = _geometryFeatureSymbolOffset;
            _geometryFeatureSymbolOffset = null;
            _splitToolSymbolRecorder = new SplitToolSymbol();
            try
            {
                DrawSplitGeometryTool(geometryFeature, extent, false);
                return _splitToolSymbolRecorder.IsEmpty ? null : _splitToolSymbolRecorder;
            }
            catch
            {
                return null;
            }
            finally
            {
                _splitToolSymbolRecorder = null;
                _geometryFeatureSymbolOffset = symbolOffset;
            }
        }
        //
        /// <summary>
        /// Replaces the geometry of a split part and returns the name the result carries. A tool that only
        /// imprints a face leaves one solid and the part keeps its name. A tool that cuts a solid in two
        /// leaves a compound of solids, which PrePoMax meshes conformally only as a compound part, so the
        /// pieces are imported as parts of their own and gathered into one. The part that was cut is
        /// removed before they are imported, so the name and the id it held are free again and the pieces
        /// are numbered from the beginning: a part cut into five gives Solid_part-1 to Solid_part-5 and a
        /// compound named after the lowest number that is free, whatever the part that was cut was called.
        /// Importing first and removing afterwards leaves the numbering carrying every part the splits
        /// before it made and took away again, which is a different set of names each time an earlier
        /// command cuts a different number of pieces.
        /// </summary>
        private string ReplaceSplitGeometryPart(GeometryPart part, string brepFileName, IEnumerable<int> heldPartIds = null)
        {
            string partName = part.Name;
            //
            int numOfSolids = GetNumberOfSplitGeometrySolids(brepFileName);
            if (numOfSolids <= 1)
            {
                ReplacePartGeometryFromFile(part, brepFileName, true);
                return partName;
            }
            // Every cell keeps the sub part and the color of the solid it was cut from, which the mesher
            // names by its place in the part, the same place its sub part has in the compound
            string[] sourceSubPartNames;
            int[] sourceSubPartIds;
            Color[] sourceColors;
            GetSplitGeometrySourceSolids(part, out sourceSubPartNames, out sourceSubPartIds, out sourceColors);
            int[] origins = ReadSplitGeometryOrigins(brepFileName, numOfSolids, sourceSubPartNames.Length);
            if (origins == null) return null;
            // The pieces are imported from a brep file, so nothing of the part is needed once it is
            // written; the command history is what rebuilds the compound on a regenerate, so the
            // compound does not have to remember where it came from. The part is gone for good and its
            // ids go to the cells, so what was defined on it is let go as for a deleted part: a pick kept
            // for a replacement would land on whichever cell took its id
            Color partColor = part.Color;
            string[] subPartOrder = (part as CompoundGeometryPart)?.SplitSubPartOrder?.ToArray();
            Dictionary<MeshSetupItem, string[]> coveredSubPartNames;
            Dictionary<MeshSetupItem, int[]> compoundMeshSetupItems = GetMeshSetupItemsCoveringCompound(part,
                                                                          out coveredSubPartNames);
            // The parts the split cut and a compound that is cut again are still there to the user, so they keep
            // their part ids: the mesh parts meshed from them keep the ids that the selections made on them hold
            string keptCompoundPartName = part is CompoundGeometryPart ? partName : null;
            int keptCompoundPartId = part is CompoundGeometryPart ? part.PartId : -1;
            string compoundPartName;
            string[] importedPartNames;
            _model.HoldPartIds(sourceSubPartIds.Concat(new int[] { keptCompoundPartId })
                                               .Concat(heldPartIds ?? Enumerable.Empty<int>()));
            try
            {
                RemoveGeometryParts(new string[] { partName }, false, false);
                ImportBrepCompoundPart(brepFileName, null, null, out compoundPartName, out importedPartNames,
                                       keptCompoundPartName, keptCompoundPartId);
            }
            finally
            {
                _model.ReleaseHeldPartIds();
            }
            //
            BasePart basePart;
            if (!_model.Geometry.Parts.TryGetValue(compoundPartName, out basePart) ||
                !(basePart is CompoundGeometryPart compoundPart)) return compoundPartName;
            //
            compoundPart.Color = partColor;
            if (compoundPart.SubPartNames.Length != origins.Length)
            {
                _form.WriteDataToOutput("Split solid: the cells of the compound part " + compoundPartName +
                                        " could not be gathered under the parts they were cut from.");
                return compoundPartName;
            }
            //
            string[] cellSubPartNames = new string[origins.Length];
            int[] cellSubPartIds = new int[origins.Length];
            _effectiveMeshTypes = null;
            for (int i = 0; i < origins.Length; i++)
            {
                cellSubPartNames[i] = sourceSubPartNames[origins[i] - 1];
                cellSubPartIds[i] = sourceSubPartIds[origins[i] - 1];
                //
                BasePart cell = _model.Geometry.Parts[compoundPart.SubPartNames[i]];
                cell.Color = sourceColors[origins[i] - 1];
                _form.UpdateActor(cell.Name, cell.Name, GetDrawnGeometryPartColor(cell));
            }
            compoundPart.CellSubPartNames = cellSubPartNames;
            compoundPart.CellSubPartIds = cellSubPartIds;
            compoundPart.SplitSubPartOrder = subPartOrder;
            RenameSplitCells(compoundPart);
            // A compound that is split again is still the same body, so what was defined on the whole of a sub
            // part is defined on the whole of what it became
            foreach (var entry in compoundMeshSetupItems)
            {
                MeshSetupItem meshSetupItem = entry.Key;
                int[] cellPartIds = coveredSubPartNames[meshSetupItem]
                    .SelectMany(subPartName => compoundPart.GetCellNames(subPartName))
                    .Select(cellName => _model.Geometry.Parts[cellName].PartId).ToArray();
                meshSetupItem.CreationIds = entry.Value.Concat(cellPartIds).ToArray();
                meshSetupItem.CreationData.Nodes.Clear();
                meshSetupItem.CreationData.Add(new SelectionNodeIds(vtkSelectOperation.None, false,
                                                                    meshSetupItem.CreationIds));
                meshSetupItem.Valid = true;
            }
            //
            return compoundPartName;
        }
        /// <summary>
        /// The mesh setup items that mesh the whole of one or more sub parts of a compound part, each with the
        /// ids it holds of the parts that are not the cells of the compound, and the sub parts it covers. Only
        /// an item defined on parts can follow a compound into the cells of a split, which includes a sweep
        /// that finds its source surfaces automatically; one defined on surfaces or edges names faces the
        /// split has redrawn.
        /// </summary>
        private Dictionary<MeshSetupItem, int[]> GetMeshSetupItemsCoveringCompound(GeometryPart part,
            out Dictionary<MeshSetupItem, string[]> coveredSubPartNames)
        {
            Dictionary<MeshSetupItem, int[]> meshSetupItems = new Dictionary<MeshSetupItem, int[]>();
            coveredSubPartNames = new Dictionary<MeshSetupItem, string[]>();
            if (!(part is CompoundGeometryPart compoundPart)) return meshSetupItems;
            //
            GeometryPart[] cells = GetSubParts(compoundPart.Name);
            Dictionary<string, HashSet<int>> subPartCellIds = new Dictionary<string, HashSet<int>>();
            for (int i = 0; i < cells.Length; i++)
            {
                string subPartName = compoundPart.CellSubPartNames?[i] ?? cells[i].Name;
                HashSet<int> cellIds;
                if (!subPartCellIds.TryGetValue(subPartName, out cellIds))
                {
                    cellIds = new HashSet<int>();
                    subPartCellIds.Add(subPartName, cellIds);
                }
                cellIds.Add(cells[i].PartId);
            }
            HashSet<int> allCellIds = new HashSet<int>(cells.Select(cell => cell.PartId));
            //
            foreach (var entry in _model.Geometry.MeshSetupItems)
            {
                MeshSetupItem meshSetupItem = entry.Value;
                if (!(meshSetupItem is MeshingParameters || meshSetupItem is ShellMmg ||
                      meshSetupItem is ShellGmsh || meshSetupItem is ShellQuadWild ||
                      meshSetupItem is ThickenShellMesh || meshSetupItem is NetgenMesh ||
                      meshSetupItem is TetrahedralGmsh || meshSetupItem is TransfiniteMesh ||
                      (meshSetupItem is SweepMesh sweepMesh &&
                       sweepMesh.SourceType == SweepSourceTypeEnum.Automatic))) continue;
                if (meshSetupItem.CreationIds == null || meshSetupItem.CreationData == null) continue;
                if (!meshSetupItem.CreationIds.All(id => FeMesh.IsPartGeometryId(id))) continue;
                //
                HashSet<int> partIds = new HashSet<int>(FeMesh.GetPartIdsFromGeometryIds(meshSetupItem.CreationIds));
                bool wholeCompound = partIds.Contains(compoundPart.PartId);
                string[] subPartNames = subPartCellIds
                    .Where(subPart => wholeCompound || subPart.Value.IsSubsetOf(partIds))
                    .Select(subPart => subPart.Key).ToArray();
                if (subPartNames.Length == 0) continue;
                //
                meshSetupItems[meshSetupItem] = meshSetupItem.CreationIds
                    .Where(id => !allCellIds.Contains(FeMesh.GetPartIdFromGeometryId(id))).ToArray();
                coveredSubPartNames[meshSetupItem] = subPartNames;
            }
            return meshSetupItems;
        }
        private void GetSplitGeometrySourceSolids(GeometryPart part, out string[] subPartNames, out int[] subPartIds,
                                                  out Color[] colors)
        {
            if (part is CompoundGeometryPart compoundPart)
            {
                GeometryPart[] subParts = GetSubParts(compoundPart.Name);
                subPartNames = new string[subParts.Length];
                subPartIds = new int[subParts.Length];
                colors = new Color[subParts.Length];
                for (int i = 0; i < subParts.Length; i++)
                {
                    string cellSubPartName = compoundPart.CellSubPartNames?[i];
                    subPartNames[i] = cellSubPartName ?? subParts[i].Name;
                    subPartIds[i] = cellSubPartName == null ? subParts[i].PartId :
                                                              GetSplitSubPartId(compoundPart, cellSubPartName);
                    colors[i] = subParts[i].Color;
                }
            }
            else
            {
                subPartNames = new string[] { part.Name };
                subPartIds = new int[] { part.PartId };
                colors = new Color[] { part.Color };
            }
        }
        /// <summary>
        /// The part id of a sub part of a split compound. A compound saved before the sub parts held ids of their
        /// own is meshed with the id of the first cell of each, and that id is what the sub part then keeps.
        /// </summary>
        private int GetSplitSubPartId(CompoundGeometryPart compoundPart, string subPartName)
        {
            int subPartId = compoundPart.GetSplitSubPartId(subPartName);
            if (subPartId > 0) return subPartId;
            //
            string firstCellName = compoundPart.GetCellNames(subPartName).FirstOrDefault();
            BasePart firstCell;
            if (firstCellName != null && _model.Geometry.Parts.TryGetValue(firstCellName, out firstCell))
                return firstCell.PartId;
            return -1;
        }
        private static string GetSplitGeometryOriginsFileName(string brepFileName)
        {
            return brepFileName + ".origins";
        }
        /// <summary>
        /// The solid of the split part each solid of the result was cut from, numbered from one, as the
        /// mesher writes it beside the result. An answer that does not name one of the solids for every
        /// piece is no answer, since a cell gathered under the wrong part would be meshed with it.
        /// </summary>
        private int[] ReadSplitGeometryOrigins(string brepFileName, int numOfSolids, int numOfSourceSolids)
        {
            string originsFileName = GetSplitGeometryOriginsFileName(brepFileName);
            List<int> origins = new List<int>();
            if (File.Exists(originsFileName))
            {
                foreach (string line in File.ReadAllLines(originsFileName))
                {
                    int origin;
                    if (line.Trim().Length == 0) continue;
                    if (!int.TryParse(line.Trim(), out origin) || origin < 1 || origin > numOfSourceSolids)
                    {
                        origins = null;
                        break;
                    }
                    origins.Add(origin);
                }
            }
            if (origins == null || origins.Count != numOfSolids)
            {
                _form.WriteDataToOutput("Split solid: the mesher did not say which solid each piece of the split " +
                                        "came from.");
                return null;
            }
            return origins.ToArray();
        }
        /// <summary>
        /// Names the cells of a split compound after the sub part each of them belongs to, numbered in the
        /// order they have in the compound. A name another part already has is skipped, and the cells are
        /// first moved out of the way when one of them would take a name another of them still holds.
        /// </summary>
        private void RenameSplitCells(CompoundGeometryPart compoundPart)
        {
            if (!compoundPart.CreatedBySplit) return;
            //
            string[] cellNames = compoundPart.SubPartNames.ToArray();
            HashSet<string> cellNameSet = new HashSet<string>(cellNames, StringComparer.OrdinalIgnoreCase);
            HashSet<string> reservedNames = new HashSet<string>(_model.GetReservedPartNames(),
                                                                StringComparer.OrdinalIgnoreCase);
            reservedNames.ExceptWith(cellNames);
            // The name of a sub part is reserved for it, and its only cell is that sub part
            reservedNames.ExceptWith(compoundPart.GetSplitSubPartNames());
            //
            Dictionary<string, int> cellCounts = new Dictionary<string, int>();
            string[] newCellNames = new string[cellNames.Length];
            bool nameTakenByCell = false;
            for (int i = 0; i < cellNames.Length; i++)
            {
                string subPartName = compoundPart.CellSubPartNames[i];
                if (subPartName == null) { newCellNames[i] = cellNames[i]; continue; }
                //
                string newCellName;
                if (compoundPart.GetCellNames(subPartName).Length == 1) newCellName = subPartName;
                else
                {
                    int count;
                    cellCounts.TryGetValue(subPartName, out count);
                    do newCellName = subPartName + "_cell-" + (++count);
                    while (reservedNames.Contains(newCellName));
                    cellCounts[subPartName] = count;
                }
                reservedNames.Add(newCellName);
                newCellNames[i] = newCellName;
                //
                if (!string.Equals(newCellName, cellNames[i], StringComparison.OrdinalIgnoreCase) &&
                    cellNameSet.Contains(newCellName)) nameTakenByCell = true;
            }
            //
            if (nameTakenByCell)
            {
                for (int i = 0; i < cellNames.Length; i++)
                {
                    if (newCellNames[i] == cellNames[i]) continue;
                    string temporaryName = "Cell_" + Guid.NewGuid().ToString("N");
                    RenameSplitCell(cellNames[i], temporaryName);
                    cellNames[i] = temporaryName;
                }
            }
            for (int i = 0; i < cellNames.Length; i++)
            {
                if (newCellNames[i] != cellNames[i]) RenameSplitCell(cellNames[i], newCellNames[i]);
            }
        }
        private void RenameSplitCell(string oldCellName, string newCellName)
        {
            PartProperties properties = GetGeometryPart(oldCellName).GetProperties();
            properties.Name = newCellName;
            ReplaceGeometryPartProperties(oldCellName, properties, false);
        }
        private int GetGeometryPartFaceCount(string partName)
        {
            BasePart part;
            if (!_model.Geometry.Parts.TryGetValue(partName, out part)) return 0;
            //
            if (part is CompoundGeometryPart compoundPart)
            {
                int faceCount = 0;
                foreach (string subPartName in compoundPart.SubPartNames)
                {
                    BasePart subPart;
                    if (_model.Geometry.Parts.TryGetValue(subPartName, out subPart) && subPart.Visualization != null)
                        faceCount += subPart.Visualization.FaceCount;
                }
                return faceCount;
            }
            return part.Visualization == null ? 0 : part.Visualization.FaceCount;
        }
        /// <summary>
        /// Puts a surface split back. The faces were divided and nothing was added to the body or taken
        /// from it, so the part is replaced by itself: a shell part stays a shell part, a solid stays a
        /// solid and a compound keeps its sub parts, each with the name and the id it had. A result that
        /// is not the same body cannot be put back that way, and false is answered instead of leaving a
        /// part behind that nothing in the model refers to.
        /// </summary>
        private bool ReplaceSplitSurfacePart(GeometryPart part, string brepFileName, out string resultPartName)
        {
            resultPartName = part.Name;
            //
            int numOfSolids;
            int numOfShells;
            if (!TryGetSplitGeometryBodyCounts(brepFileName, out numOfSolids, out numOfShells)) return false;
            //
            if (part is CompoundGeometryPart compoundPart)
            {
                if (numOfSolids != compoundPart.SubPartNames.Length) return false;
                //
                Guid? targetGroupId =
                    GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts,
                                                              new string[] { compoundPart.Name });
                string newCompoundPartName;
                ImportBrepCompoundPart(brepFileName, compoundPart.SubPartNames, targetGroupId,
                                       out newCompoundPartName, out _);
                SwapCompoundParts(compoundPart.Name, newCompoundPartName, true);
                //
                return true;
            }
            // A part that is not a compound has to come back as the bodies it was: a shell that came apart,
            // or faces that are no longer a shell, would be parts the split invented. It is not always one
            // shell - a merge of shell parts holds one shell for each of them, and a solid with a cavity
            // holds two - so the result is compared with the part and not with one shell
            int numOfSolidsBefore;
            int numOfShellsBefore;
            if (!TryGetSplitGeometryPartBodyCounts(part, out numOfSolidsBefore, out numOfShellsBefore)) return false;
            if (numOfSolids != numOfSolidsBefore || numOfShells != numOfShellsBefore) return false;
            //
            ReplacePartGeometryFromFile(part, brepFileName, true);
            //
            return true;
        }
        /// <summary>
        /// The bodies a brep holds, as the visualization counts them: the solids, and the shells including
        /// the one a solid is made of. Together they say whether a split gave back the body it was given.
        /// </summary>
        private bool TryGetSplitGeometryBodyCounts(string brepFileName, out int numOfSolids, out int numOfShells)
        {
            numOfSolids = 0;
            numOfShells = 0;
            //
            string visFileName = CreateVisFile(brepFileName, false);
            if (visFileName == null || !File.Exists(visFileName)) return false;
            //
            const string solidsPrefix = "Number of solids:";
            const string shellsPrefix = "Number of shells:";
            bool solidsRead = false;
            bool shellsRead = false;
            foreach (string line in File.ReadLines(visFileName))
            {
                if (!solidsRead && line.StartsWith(solidsPrefix, StringComparison.Ordinal))
                    solidsRead = int.TryParse(line.Substring(solidsPrefix.Length).Trim(), out numOfSolids);
                else if (!shellsRead && line.StartsWith(shellsPrefix, StringComparison.Ordinal))
                    shellsRead = int.TryParse(line.Substring(shellsPrefix.Length).Trim(), out numOfShells);
                if (solidsRead && shellsRead) return true;
            }
            return false;
        }
        // The bodies of the part as it is, counted the way the result of its split is counted
        private bool TryGetSplitGeometryPartBodyCounts(GeometryPart part, out int numOfSolids, out int numOfShells)
        {
            numOfSolids = 0;
            numOfShells = 0;
            //
            string workDirectory = _settings.GetWorkDirectory();
            if (part.CADFileData == null || workDirectory == null || !Directory.Exists(workDirectory)) return false;
            //
            string brepFileName = Path.Combine(workDirectory, "splitBodies.brep");
            File.WriteAllText(brepFileName, part.CADFileData);
            try
            {
                return TryGetSplitGeometryBodyCounts(brepFileName, out numOfSolids, out numOfShells);
            }
            finally
            {
                if (File.Exists(brepFileName)) File.Delete(brepFileName);
            }
        }
        private int GetNumberOfSplitGeometrySolids(string brepFileName)
        {
            string visFileName = CreateVisFile(brepFileName, false);
            if (visFileName == null || !File.Exists(visFileName)) return 1;
            //
            const string prefix = "Number of solids:";
            foreach (string line in File.ReadLines(visFileName))
            {
                if (line.StartsWith(prefix, StringComparison.Ordinal))
                {
                    int numOfSolids;
                    if (int.TryParse(line.Substring(prefix.Length).Trim(), out numOfSolids)) return numOfSolids;
                    break;
                }
                if (line.StartsWith("Number of shells:", StringComparison.Ordinal)) break;
            }
            return 1;
        }
        /// <summary>
        /// Fades every visible geometry part that is not in the region to half opacity, or restores the
        /// parts a previous call faded. Only the actor color is touched, never the part color, so this
        /// leaves no trace in the model and needs no command.
        /// </summary>
        private void SetGeometryFeatureRegionFade(string[] regionPartNames, bool fadeTheRest)
        {
            if (_geometryFeatureFadedPartNames == null) _geometryFeatureFadedPartNames = new HashSet<string>();
            //
            HashSet<string> regionNames = new HashSet<string>(regionPartNames);
            //
            HashSet<string> namesToFade = new HashSet<string>();
            if (fadeTheRest && regionNames.Count > 0)
            {
                foreach (var entry in _model.Geometry.Parts)
                {
                    if (entry.Value is CompoundGeometryPart) continue;
                    if (!entry.Value.Visible || regionNames.Contains(entry.Key)) continue;
                    namesToFade.Add(entry.Key);
                }
            }
            // The fade dims the color the part is drawn with, which is the part color only while no color
            // annotation is on. Asking for the drawn color is what keeps the annotation through the fade
            // and puts it back afterwards, since the annotation never writes the part color itself.
            foreach (string partName in _geometryFeatureFadedPartNames.Except(namesToFade).ToArray())
            {
                Color drawnColor;
                if (TryGetGeometryFeatureDrawnPartColor(partName, out drawnColor))
                    _form.UpdateActor(partName, partName, drawnColor);
            }
            // Every part that is to be faded is faded again, and not only the ones that were not faded
            // before: a redraw - switching a color annotation on is one - draws them with their own
            // color again, and a fade that only looked at what had changed would take the remembered
            // names for faded parts and leave them opaque
            int alpha = 100;
            foreach (string partName in namesToFade)
            {
                Color drawnColor;
                if (TryGetGeometryFeatureDrawnPartColor(partName, out drawnColor))
                    _form.UpdateActor(partName, partName, Color.FromArgb(alpha, drawnColor));
            }
            //
            _geometryFeatureFadedPartNames = namesToFade;
        }
        /// <summary>
        /// Takes everything a geometry feature dialog drew off the screen - the tool symbols and the fade
        /// of the parts outside the region. Called when the dialog closes.
        /// </summary>
        public GeometryFeaturePointPickingEnum GeometryFeaturePointPicking
        {
            get { return _geometryFeaturePointPicking; }
            set { _geometryFeaturePointPicking = value; }
        }
        public bool PickCompoundSubPartsSeparately
        {
            get { return _pickCompoundSubPartsSeparately; }
            set { _pickCompoundSubPartsSeparately = value; }
        }
        /// <summary>
        /// The color the part is drawn with. A color annotation overrides the part color when the actor is
        /// built and never writes it back, so this is the only place that knows what is on the screen.
        /// </summary>
        /// <summary>
        /// The color a geometry part is drawn with: its own, unless a color annotation such as the mesh
        /// types or the face orientation is shown, and always with its own transparency. An actor given
        /// the part color while an annotation is on shows the part color until the next full redraw.
        /// </summary>
        private Color GetDrawnGeometryPartColor(BasePart part)
        {
            Color color = Color.Empty;
            Color backfaceColor = Color.Empty;
            GetPartColor(part, ref color, ref backfaceColor);
            return Color.FromArgb(part.Color.A, color);
        }
        private bool TryGetGeometryFeatureDrawnPartColor(string partName, out Color color)
        {
            color = Color.Empty;
            //
            BasePart part;
            if (!_model.Geometry.Parts.TryGetValue(partName, out part)) return false;
            //
            Color backfaceColor = Color.Empty;
            GetPartColor(part, ref color, ref backfaceColor);
            return true;
        }
        /// <summary>
        /// Resolves the region again from the picks it was made with. The split replaced the geometry
        /// the region named, and a part that was cut in two is gone by name, so the ids are found by
        /// picking at the stored positions rather than carried over.
        /// </summary>
        public void UpdateGeometryFeatureRegionIds(GeometryFeature geometryFeature)
        {
            if (geometryFeature == null || geometryFeature.CreationData == null) return;
            //
            Selection liveSelection = _selection;
            try
            {
                geometryFeature.CreationIds = GetIdsFromSelection(geometryFeature.CreationData);
            }
            catch
            {
                geometryFeature.CreationIds = new int[0];
            }
            finally
            {
                _selection = liveSelection;
            }
        }
        public void ClearGeometryFeatureSymbols()
        {
            _geometryFeatureSymbolOffset = null;
            _geometryFeaturePointPicking = GeometryFeaturePointPickingEnum.None;
            _pickCompoundSubPartsSeparately = false;
            _form.RemoveOverlayActors(_geometryFeatureSymbolNames);
            if (_geometryFeatureSymbolActorNames != null && _geometryFeatureSymbolActorNames.Count > 0)
            {
                _form.RemoveOverlayActors(_geometryFeatureSymbolActorNames.ToArray());
                _geometryFeatureSymbolActorNames.Clear();
            }
            SetGeometryFeatureRegionFade(new string[0], false);
        }
        /// <summary>
        /// Draws the symbol a split stored when it was applied, or clears it when there is none. A split from
        /// a file saved before the symbol was stored shows nothing until the history is regenerated.
        /// </summary>
        public void DrawSplitGeometryCommandSymbols(SplitToolSymbol toolSymbol)
        {
            ClearGeometryFeatureSymbols();
            // The tool and its points are drawn on the selection layer, which removing the symbols by name
            // does not reach
            HighlightSelection();
            if (toolSymbol != null && _currentView == ViewGeometryModelResults.Geometry)
            {
                for (int i = 0; i < toolSymbol.SurfaceNodeCoor.Count; i++)
                    DrawSplitGeometryToolSurface("splitGeometryCommandSurface" + i, toolSymbol.SurfaceNodeCoor[i],
                                                 toolSymbol.SurfaceCells[i]);
                for (int i = 0; i < toolSymbol.BorderNodeCoor.Count; i++)
                    DrawSplitGeometryToolBorder("splitGeometryCommandBorder" + i, toolSymbol.BorderNodeCoor[i],
                                                toolSymbol.BorderCells[i]);
                if (toolSymbol.Points.Count > 0)
                    DrawNodes("splitGeometryPoints", toolSymbol.Points.ToArray(), _settings.Pre.PrimaryHighlightColor,
                              vtkRendererLayer.Selection, _settings.Pre.NodeSymbolSize);
            }
            _form.UpdateScalarsAndRedraw();
        }
        /// <summary>
        /// The part a region id names. A region of parts names a part, a region of surfaces names one of
        /// its faces, and the part that face belongs to is the one that is split.
        /// </summary>
        private BasePart GetSplitGeometryRegionPart(GeometryFeature geometryFeature, int regionId)
        {
            if (geometryFeature.SplitType == SplitTypeEnum.Shell)
                return _model.Geometry.GetPartFromId(FeMesh.GetItemTypePartIdsFromGeometryId(regionId)[2]);
            //
            return _model.Geometry.GetPartFromId(regionId);
        }
        private string[] GetSplitGeometryRegionPartNames(GeometryFeature geometryFeature,
                                                         out int numOfSkippedParts)
        {
            numOfSkippedParts = 0;
            List<string> partNames = new List<string>();
            HashSet<string> skippedPartNames = new HashSet<string>();
            //
            if (geometryFeature.CreationIds == null) return partNames.ToArray();
            // What the user picks on a compound is one of its sub parts. The compound is what is sent
            // to the mesher, because its sub parts share faces and separating them would lose the
            // imprints; which of its solids are cut is said separately.
            Dictionary<string, string> compoundPartNames = GetCompoundPartNamesBySubPartName();
            HashSet<string> addedPartNames = new HashSet<string>();
            //
            foreach (int regionId in geometryFeature.CreationIds)
            {
                BasePart part = GetSplitGeometryRegionPart(geometryFeature, regionId);
                if (part is GeometryPart geometryPart && geometryPart.IsCADPart)
                {
                    string partName;
                    if (!compoundPartNames.TryGetValue(geometryPart.Name, out partName))
                        partName = geometryPart.Name;
                    if (addedPartNames.Add(partName)) partNames.Add(partName);
                }
                // Several surfaces of one part that cannot be split are one part that was skipped
                else if (part == null || skippedPartNames.Add(part.Name)) numOfSkippedParts++;
            }
            return partNames.ToArray();
        }
        /// <summary>
        /// The solids of a compound that the region named, numbered the way the mesher walks them. A
        /// compound part carries its sub parts in the order they were written out of its brep, so the
        /// place of a sub part in that list is the number of its solid. An empty answer means the whole
        /// part is cut, which is what picking the compound itself, or any part that is not one, means.
        /// </summary>
        private int[] GetSplitGeometrySolidIds(GeometryFeature geometryFeature, string partName)
        {
            // A region of surfaces names the faces that are divided, and the solid each of them belongs
            // to is named with the face, so there is no solid to name here
            if (geometryFeature.SplitType == SplitTypeEnum.Shell) return new int[0];
            //
            BasePart part;
            if (!_model.Geometry.Parts.TryGetValue(partName, out part) ||
                !(part is CompoundGeometryPart compoundPart)) return new int[0];
            if (geometryFeature.CreationIds == null) return new int[0];
            //
            List<int> solidIds = new List<int>();
            foreach (int partId in geometryFeature.CreationIds)
            {
                BasePart pickedPart = _model.Geometry.GetPartFromId(partId);
                if (pickedPart == null) continue;
                // The compound itself stands for all of its solids
                if (pickedPart.Name == compoundPart.Name) return new int[0];
                //
                int index = Array.IndexOf(compoundPart.SubPartNames, pickedPart.Name);
                if (index >= 0 && !solidIds.Contains(index + 1)) solidIds.Add(index + 1);
            }
            solidIds.Sort();
            // Naming every solid is the same as naming none, and says so in fewer words
            if (solidIds.Count == compoundPart.SubPartNames.Length) return new int[0];
            //
            return solidIds.ToArray();
        }
        /// <summary>
        /// The faces of one part that a region of surfaces names, grouped by the solid they belong to and
        /// numbered the way the modelling kernel numbers them. A compound is split as a whole while its
        /// faces are picked on its sub parts, so a face there is named by its solid and by its place in
        /// that solid; a part that is not a compound numbers its faces in itself, which is solid zero.
        /// </summary>
        private void GetSplitGeometryTargetFaces(GeometryFeature geometryFeature, string partName,
                                                 out List<int> targetSolids, out List<int[]> targetFaceIds)
        {
            targetSolids = new List<int>();
            targetFaceIds = new List<int[]>();
            //
            if (geometryFeature.SplitType != SplitTypeEnum.Shell) return;
            if (geometryFeature.CreationIds == null) return;
            //
            BasePart part;
            if (!_model.Geometry.Parts.TryGetValue(partName, out part)) return;
            CompoundGeometryPart compoundPart = part as CompoundGeometryPart;
            //
            List<int> solidNumbers = new List<int>();
            Dictionary<int, List<int>> kernelIdsBySolidNumber = new Dictionary<int, List<int>>();
            foreach (int geometryId in geometryFeature.CreationIds)
            {
                int facePartId = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId)[2];
                BasePart facePart = _model.Geometry.GetPartFromId(facePartId);
                if (facePart == null) continue;
                // The region can name faces on several parts, and this pass is about one of them
                int solidNumber = 0;
                if (compoundPart != null)
                {
                    int index = Array.IndexOf(compoundPart.SubPartNames, facePart.Name);
                    if (index < 0) continue;
                    solidNumber = index + 1;
                }
                else if (facePart.Name != partName) continue;
                //
                List<int> kernelIds;
                if (!kernelIdsBySolidNumber.TryGetValue(solidNumber, out kernelIds))
                {
                    kernelIds = new List<int>();
                    kernelIdsBySolidNumber.Add(solidNumber, kernelIds);
                    solidNumbers.Add(solidNumber);
                }
                int kernelId = GetSplitGeometryKernelId(geometryId);
                if (!kernelIds.Contains(kernelId)) kernelIds.Add(kernelId);
            }
            foreach (int solidNumber in solidNumbers)
            {
                targetSolids.Add(solidNumber);
                targetFaceIds.Add(kernelIdsBySolidNumber[solidNumber].ToArray());
            }
        }
        /// <summary>
        /// The parts the region actually names, as they are drawn. A compound is drawn as its sub parts, so
        /// picking the compound itself means all of them while picking one sub part means only that one -
        /// which is what lets the siblings fade while it is being cut.
        /// </summary>
        private string[] GetSplitGeometryPickedPartNames(GeometryFeature geometryFeature)
        {
            List<string> partNames = new List<string>();
            if (geometryFeature.CreationIds == null) return partNames.ToArray();
            //
            foreach (int regionId in geometryFeature.CreationIds)
            {
                BasePart part = GetSplitGeometryRegionPart(geometryFeature, regionId);
                if (part == null || partNames.Contains(part.Name)) continue;
                //
                if (part is CompoundGeometryPart compoundPart) partNames.AddRange(compoundPart.SubPartNames);
                else partNames.Add(part.Name);
            }
            return partNames.ToArray();
        }
        private double[] GetSplitGeometryRegionExtent(string[] partNames)
        {
            if (partNames == null || partNames.Length == 0) return null;
            //
            BoundingBox box = null;
            foreach (string partName in partNames)
            {
                BasePart part;
                if (!_model.Geometry.Parts.TryGetValue(partName, out part) || part.BoundingBox == null) continue;
                // The exploded view moves the box with the part, and the tool is built and used where
                // the modelling kernel holds the geometry, so the box is brought back onto the part
                BoundingBox partBox = new BoundingBox(part.BoundingBox);
                if (IsExplodedViewActive() && part.Offset != null) partBox.RemoveOffset(part.Offset);
                //
                if (box == null) box = partBox;
                else box.IncludeBox(partBox);
            }
            if (box == null) return null;
            // The tool has to reach past the geometry instead of ending exactly on it
            double margin = 0.1 * Math.Sqrt((box.MaxX - box.MinX) * (box.MaxX - box.MinX) +
                                            (box.MaxY - box.MinY) * (box.MaxY - box.MinY) +
                                            (box.MaxZ - box.MinZ) * (box.MaxZ - box.MinZ));
            if (margin <= 0) return null;
            //
            return new double[] { box.MinX - margin, box.MaxX + margin, box.MinY - margin, box.MaxY + margin,
                                  box.MinZ - margin, box.MaxZ + margin };
        }
        /// <summary>
        /// The brep of every part the picked splitter geometry lies on, keyed by part id. An id read from
        /// one part's brep means nothing in another's, and the picks do land on several parts: a compound
        /// is split as a whole while its pieces are what the user picks on. So the tool is given every one
        /// of those breps, each beside the ids that were read from it.
        /// </summary>
        private Dictionary<int, string> WriteSplitGeometrySourceBreps(GeometryFeature geometryFeature)
        {
            Dictionary<int, string> sourceBrepFileNames = new Dictionary<int, string>();
            // Only a tool that names geometry by id needs the part that geometry belongs to
            if (geometryFeature.ToolType == SplitGeometryToolTypeEnum.Plane ||
                geometryFeature.ToolType == SplitGeometryToolTypeEnum.TwoPointLine) return sourceBrepFileNames;
            if (geometryFeature.SplitterIds == null || geometryFeature.SplitterIds.Length == 0)
                return sourceBrepFileNames;
            //
            string workDirectory = _settings.GetWorkDirectory();
            if (workDirectory == null || !Directory.Exists(workDirectory)) return sourceBrepFileNames;
            //
            string baseName = Path.GetFileNameWithoutExtension(Globals.SplitSourceBrepFileName);
            string extension = Path.GetExtension(Globals.SplitSourceBrepFileName);
            //
            foreach (int geometryId in geometryFeature.SplitterIds)
            {
                int partId = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId)[2];
                if (sourceBrepFileNames.ContainsKey(partId)) continue;
                //
                BasePart part = _model.Geometry.GetPartFromId(partId);
                if (!(part is GeometryPart geometryPart) || !geometryPart.IsCADPart) continue;
                // The sources are written to files of their own, since the part being split uses the
                // standard one
                string sourceBrepFileName = Path.Combine(workDirectory, baseName +
                                                         (sourceBrepFileNames.Count + 1) + extension);
                if (File.Exists(sourceBrepFileName)) File.Delete(sourceBrepFileName);
                File.WriteAllText(sourceBrepFileName, geometryPart.CADFileData);
                //
                sourceBrepFileNames.Add(partId, sourceBrepFileName);
            }
            return sourceBrepFileNames;
        }
        private void DeleteSplitGeometrySourceBreps(Dictionary<int, string> sourceBrepFileNames)
        {
            foreach (string sourceBrepFileName in sourceBrepFileNames.Values)
            {
                if (File.Exists(sourceBrepFileName)) File.Delete(sourceBrepFileName);
            }
        }
        // Every part of the region is split as the operation would split it, and the edges each split made
        // are drawn together. Nothing of the result is taken in, so the model and the picks stay as they are.
        private void PreviewSplitGeometryParts(GeometryFeature geometryFeature, string[] partNames, double[] extent,
                                               Dictionary<int, string> sourceBrepFileNames)
        {
            List<double[][]> polylines = new List<double[][]>();
            List<string> failedPartNames = new List<string>();
            foreach (string partName in partNames)
            {
                BasePart basePart;
                if (!_model.Geometry.Parts.TryGetValue(partName, out basePart) ||
                    !(basePart is GeometryPart part)) continue;
                //
                int[] solidIds = GetSplitGeometrySolidIds(geometryFeature, partName);
                List<int> targetSolids;
                List<int[]> targetFaceIds;
                GetSplitGeometryTargetFaces(geometryFeature, partName, out targetSolids, out targetFaceIds);
                string edgesFileName = SplitGeometryPart(part, geometryFeature, extent, sourceBrepFileNames,
                                                         solidIds, targetSolids, targetFaceIds, true);
                double[][][] partPolylines = edgesFileName == null ? null :
                                             ReadSplitGeometryPreviewEdges(edgesFileName);
                if (partPolylines == null) failedPartNames.Add(partName);
                else polylines.AddRange(partPolylines);
            }
            // The parts of the operation share one exploded view offset, or the preview was refused
            double[] offset;
            TryGetSplitGeometryFeatureOffset(geometryFeature, out offset);
            DrawSplitGeometryPreview(polylines, offset);
            //
            string operationName = geometryFeature.SplitType == SplitTypeEnum.Shell ?
                                   "Split shell preview" : "Split solid preview";
            foreach (string partName in failedPartNames)
                _form.WriteDataToOutput(operationName + ": the part " + partName + " would not be split.");
        }
        private static string GetSplitGeometryPreviewFileName(string brepFileName)
        {
            return brepFileName + ".edges";
        }
        // The edges the mesher wrote for a preview, each one as the points it was sampled at
        private static double[][][] ReadSplitGeometryPreviewEdges(string edgesFileName)
        {
            if (!File.Exists(edgesFileName)) return null;
            //
            string[] lines = File.ReadAllLines(edgesFileName);
            List<double[][]> polylines = new List<double[][]>();
            char[] separators = new char[] { ' ', '\t' };
            int numOfPoints;
            for (int i = 0; i < lines.Length; i++)
            {
                if (!lines[i].StartsWith("Edge:") ||
                    !int.TryParse(lines[i].Substring(5).Trim(), out numOfPoints) ||
                    numOfPoints < 2 || i + numOfPoints >= lines.Length) continue;
                //
                double[][] points = new double[numOfPoints][];
                for (int j = 0; j < numOfPoints; j++)
                {
                    string[] values = lines[i + 1 + j].Split(separators, StringSplitOptions.RemoveEmptyEntries);
                    if (values.Length != 3) return null;
                    points[j] = new double[3];
                    for (int k = 0; k < 3; k++)
                        if (!double.TryParse(values[k], System.Globalization.NumberStyles.Float,
                                             System.Globalization.CultureInfo.InvariantCulture,
                                             out points[j][k])) return null;
                }
                polylines.Add(points);
                i += numOfPoints;
            }
            return polylines.ToArray();
        }
        // The preview is highlighted as the other previews are, so it is taken off the screen with the
        // selection by the next pick and by every redraw of the tool symbols
        private void DrawSplitGeometryPreview(List<double[][]> polylines, double[] offset)
        {
            List<double[]> nodeCoor = new List<double[]>();
            List<int[]> cells = new List<int[]>();
            List<int> cellTypes = new List<int>();
            int lineType = (int)vtkCellType.VTK_LINE;
            int firstNode;
            foreach (double[][] polyline in polylines)
            {
                firstNode = nodeCoor.Count;
                foreach (double[] point in polyline)
                {
                    if (offset == null) nodeCoor.Add(point);
                    else nodeCoor.Add(new double[] { point[0] + offset[0], point[1] + offset[1],
                                                     point[2] + offset[2] });
                }
                for (int i = 0; i < polyline.Length - 1; i++)
                {
                    cells.Add(new int[] { firstNode + i, firstNode + i + 1 });
                    cellTypes.Add(lineType);
                }
            }
            if (cells.Count == 0) return;
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = "splitGeometryPreview";
            data.Color = _settings.Pre.PrimaryHighlightColor;
            data.Layer = vtkRendererLayer.Selection;
            data.LineWidth = 2;
            data.CanHaveElementEdges = false;
            data.Pickable = false;
            data.Geometry.Nodes.Coor = nodeCoor.ToArray();
            data.Geometry.Cells.CellNodeIds = cells.ToArray();
            data.Geometry.Cells.Types = cellTypes.ToArray();
            //
            ApplyLighting(data);
            _form.Add3DCells(data);
        }
        private string SplitGeometryPart(GeometryPart part, GeometryFeature geometryFeature, double[] extent,
                                         Dictionary<int, string> sourceBrepFileNames, int[] solidIds,
                                         List<int> targetSolids, List<int[]> targetFaceIds, bool preview)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inputBrepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            // A preview writes the edges the split made in place of the result
            string outputFileName = preview ? GetSplitGeometryPreviewFileName(inputBrepFileName) :
                                              inputBrepFileName;
            string toolFileName = Path.Combine(workDirectory, Globals.SplitToolFileName);
            //
            if (File.Exists(inputBrepFileName)) File.Delete(inputBrepFileName);
            if (File.Exists(toolFileName)) File.Delete(toolFileName);
            if (File.Exists(outputFileName)) File.Delete(outputFileName);
            //
            string originsFileName = GetSplitGeometryOriginsFileName(inputBrepFileName);
            if (File.Exists(originsFileName)) File.Delete(originsFileName);
            //
            File.WriteAllText(inputBrepFileName, part.CADFileData);
            File.WriteAllText(toolFileName, GetSplitGeometryToolDefinition(geometryFeature, extent,
                                                                          sourceBrepFileNames, solidIds,
                                                                          targetSolids, targetFaceIds));
            //
            string argument = (preview ? "BREP_SPLIT_PREVIEW " : "BREP_SPLIT ") +
                              "\"" + inputBrepFileName.ToUTF8() + "\" " +
                              "\"" + outputFileName.ToUTF8() + "\" " +
                              "\"" + toolFileName.ToUTF8() + "\"";
            //
            JobStatus jobStatus = _jobRunner.Run(part.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK) return outputFileName;
            else return null;
        }
        private string GetSplitGeometryToolDefinition(GeometryFeature geometryFeature, double[] extent,
                                                      Dictionary<int, string> sourceBrepFileNames,
                                                      int[] solidIds, List<int> targetSolids,
                                                      List<int[]> targetFaceIds)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("Split tool format: 2");
            sb.AppendLine("Tool type: " + geometryFeature.ToolType.ToString());
            sb.AppendLine("Extent: " + SplitGeometryValuesToString(extent));
            if (geometryFeature.FuzzyValue > 0)
                sb.AppendLine("Fuzzy value: " + SplitGeometryValuesToString(new double[]
                                                                           { geometryFeature.FuzzyValue }));
            if (solidIds != null && solidIds.Length > 0)
            {
                StringBuilder solids = new StringBuilder();
                foreach (int solidId in solidIds) solids.Append(" " + solidId);
                sb.AppendLine("Solid ids:" + solids.ToString());
            }
            // A surface split divides the named faces and leaves the body they belong to whole. The solid
            // is named with every group, zero included, so that a group opens where the next solid begins
            if (geometryFeature.SplitType == SplitTypeEnum.Shell && targetSolids != null)
            {
                sb.AppendLine("Split target: Shell");
                for (int i = 0; i < targetSolids.Count; i++)
                {
                    sb.AppendLine("Target solid: " + targetSolids[i]);
                    StringBuilder faces = new StringBuilder();
                    foreach (int faceId in targetFaceIds[i]) faces.Append(" " + faceId);
                    sb.AppendLine("Target face ids:" + faces.ToString());
                }
            }
            //
            if (geometryFeature is SplitByPlaneThreePoints threePoints)
            {
                sb.AppendLine("Plane origin: " + SplitGeometryValuesToString(threePoints.GetPlaneOrigin()));
                sb.AppendLine("Plane normal: " + SplitGeometryValuesToString(threePoints.GetPlaneNormal()));
            }
            else if (geometryFeature is SplitByPointAndNormal pointAndNormal)
            {
                sb.AppendLine("Plane origin: " + SplitGeometryValuesToString(pointAndNormal.GetPlaneOrigin()));
                sb.AppendLine("Plane normal: " + SplitGeometryValuesToString(pointAndNormal.GetPlaneNormal()));
            }
            else if (geometryFeature is SplitByLineTwoPoints twoPointLine)
            {
                sb.AppendLine("Point 1: " + SplitGeometryValuesToString(twoPointLine.Points[0]));
                sb.AppendLine("Point 2: " + SplitGeometryValuesToString(twoPointLine.Points[1]));
            }
            else if (geometryFeature is SplitByExtendedFace extendedFace)
            {
                // A face that cannot be continued past its boundary is left out, which is also what the
                // symbols show, so the tool is what the user was looking at
                List<int> extendedIds = new List<int>();
                for (int i = 0; i < extendedFace.SplitterIds.Length; i++)
                    if (extendedFace.IsExtended(i)) extendedIds.Add(extendedFace.SplitterIds[i]);
                //
                AppendSplitGeometryKernelIdGroups(sb, "Face ids", extendedIds.ToArray(), sourceBrepFileNames);
                //
                if (extendedFace.Offset != 0)
                    sb.AppendLine("Offset: " + SplitGeometryValuesToString(new double[]
                                                                          { extendedFace.Offset }));
            }
            else if (geometryFeature is SplitByExtrudedEdges extrudedEdges)
            {
                AppendSplitGeometryKernelIdGroups(sb, "Edge ids", extrudedEdges.SplitterIds,
                                                  sourceBrepFileNames);
                //
                double[] offset;
                double[] vector;
                GetSplitGeometryExtrusion(extrudedEdges, extent, out offset, out vector);
                sb.AppendLine("Extrusion offset: " + SplitGeometryValuesToString(offset));
                sb.AppendLine("Extrusion vector: " + SplitGeometryValuesToString(vector));
            }
            //
            return sb.ToString();
        }
        private void GetSplitGeometryExtrusion(SplitByExtrudedEdges extrudedEdges, double[] extent,
                                               out double[] offset, out double[] vector)
        {
            double[] direction = extrudedEdges.GetExtrusionDirection();
            double start;
            double length;
            //
            if (extrudedEdges.LengthType == SplitExtrusionLengthTypeEnum.Value)
            {
                // A length the user gave is the reach in one direction, so sweeping both ways doubles it
                length = extrudedEdges.Length;
                start = extrudedEdges.BothDirections ? -length : 0;
                if (extrudedEdges.BothDirections) length *= 2;
            }
            else
            {
                // Through the region means from one side of the region to the other, measured along the
                // direction. Where the edges already lie inside the region only the rest of the way has
                // to be swept: a length measured from the edges outwards, or the diagonal of the box that
                // a direction independent length would have to be, reaches a whole region too far.
                double regionMin;
                double regionMax;
                GetSplitGeometryAxisRange(new double[] { 0, 0, 0 }, direction, extent, out regionMin, out regionMax);
                //
                double edgeMin;
                double edgeMax;
                if (!TryGetSplitGeometryEdgeRange(extrudedEdges.SplitterIds, direction, out edgeMin, out edgeMax))
                {
                    edgeMin = regionMin;
                    edgeMax = regionMax;
                }
                // Every point of every edge has to come out the far side, and the point that starts
                // furthest back is the one that decides how far the sweep has to travel
                if (extrudedEdges.BothDirections)
                {
                    start = regionMin - edgeMax;
                    length = (regionMax - regionMin) + (edgeMax - edgeMin);
                }
                else
                {
                    start = 0;
                    length = regionMax - edgeMin;
                    // Edges that sit past the far side of the region are not swept through it at all
                    if (length <= 0) length = regionMax - regionMin;
                }
            }
            //
            offset = new double[] { direction[0] * start, direction[1] * start, direction[2] * start };
            vector = new double[] { direction[0] * length, direction[1] * length, direction[2] * length };
        }
        /// <summary>
        /// How far along the direction the edges being swept reach. It is read from the drawn edges rather
        /// than from the geometry, because what is wanted is where they lie, not what they are.
        /// </summary>
        private bool TryGetSplitGeometryEdgeRange(int[] geometryIds, double[] direction, out double min,
                                                  out double max)
        {
            min = double.MaxValue;
            max = double.MinValue;
            if (geometryIds == null) return false;
            //
            foreach (int geometryId in geometryIds)
            {
                double[][] edgeCoor = GetSplitGeometryEdgeCoor(geometryId);
                if (edgeCoor == null) continue;
                //
                foreach (double[] coor in edgeCoor)
                {
                    double t = coor[0] * direction[0] + coor[1] * direction[1] + coor[2] * direction[2];
                    if (t < min) min = t;
                    if (t > max) max = t;
                }
            }
            return max >= min;
        }
        /// <summary>
        /// Writes the picked ids as the kernel numbers them, in groups under the brep each group was
        /// read from. The same number means a different entity in every brep, so a group without its
        /// source file would be read against the wrong shape - and geometry on a part that has no
        /// brep of its own cannot be used at all, so it is left out.
        /// </summary>
        private void AppendSplitGeometryKernelIdGroups(StringBuilder sb, string idsName, int[] geometryIds,
                                                       Dictionary<int, string> sourceBrepFileNames)
        {
            if (geometryIds == null) return;
            //
            List<int> partIds = new List<int>();
            Dictionary<int, List<int>> kernelIdsByPartId = new Dictionary<int, List<int>>();
            foreach (int geometryId in geometryIds)
            {
                int partId = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId)[2];
                List<int> kernelIds;
                if (!kernelIdsByPartId.TryGetValue(partId, out kernelIds))
                {
                    kernelIds = new List<int>();
                    kernelIdsByPartId.Add(partId, kernelIds);
                    partIds.Add(partId);
                }
                kernelIds.Add(GetSplitGeometryKernelId(geometryId));
            }
            foreach (int partId in partIds)
            {
                string sourceBrepFileName;
                if (!sourceBrepFileNames.TryGetValue(partId, out sourceBrepFileName)) continue;
                sb.AppendLine("Source file: " + sourceBrepFileName);
                //
                StringBuilder ids = new StringBuilder();
                foreach (int kernelId in kernelIdsByPartId[partId]) ids.Append(" " + kernelId);
                sb.AppendLine(idsName + ":" + ids.ToString());
            }
        }
        private static string SplitGeometryValuesToString(double[] values)
        {
            if (values == null) return "";
            //
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < values.Length; i++)
            {
                if (i > 0) sb.Append(" ");
                sb.Append(values[i].ToString("G17", System.Globalization.CultureInfo.InvariantCulture));
            }
            return sb.ToString();
        }
        /// <summary>
        /// Returns the id the modelling kernel gave the picked entity. The visualization is ordered by
        /// the kernel id but not equal to it, so the id is read from the map the renumbering left behind.
        /// Only a part from a file written before the map existed falls back to the ordering.
        /// </summary>
        private int GetSplitGeometryKernelId(int geometryId)
        {
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
            int itemId = itemTypePartIds[0];
            GeometryType geometryType = (GeometryType)itemTypePartIds[1];
            BasePart part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            //
            if (part != null && part.Visualization != null)
            {
                int[] kernelIds = null;
                if (geometryType.IsSurface()) kernelIds = part.Visualization.FaceKernelIds;
                else if (geometryType.IsEdge()) kernelIds = part.Visualization.EdgeKernelIds;
                //
                if (kernelIds != null && itemId >= 0 && itemId < kernelIds.Length && kernelIds[itemId] > 0)
                    return kernelIds[itemId];
            }
            return itemId + 1;
        }
        private GeometryMetadataEntity GetSplitGeometryMetadataEntity(int geometryId, out BasePart part,
                                                                      out GeometryType geometryType, out int itemId)
        {
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
            itemId = itemTypePartIds[0];
            geometryType = (GeometryType)itemTypePartIds[1];
            part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            //
            if (part == null || part.GeometryMetadata == null) return null;
            //
            string kind;
            if (geometryType.IsSurface()) kind = "face";
            else if (geometryType.IsEdge()) kind = "edge";
            else if (geometryType == GeometryType.Vertex) kind = "vertex";
            else return null;
            //
            return part.GeometryMetadata.GetEntity(kind, GetSplitGeometryKernelId(geometryId));
        }
        private bool TryGetSplitGeometryPoint(int geometryId, out double[] point)
        {
            point = null;
            //
            BasePart part;
            GeometryType geometryType;
            int itemId;
            GeometryMetadataEntity entity = GetSplitGeometryMetadataEntity(geometryId, out part, out geometryType,
                                                                          out itemId);
            // A vertex gives its own position, and it is the only one taken from the displayed nodes,
            // which carry the exploded view offset the modelling kernel knows nothing about
            if (geometryType == GeometryType.Vertex && part != null && part.Visualization != null)
            {
                int nodeId = part.Visualization.VertexNodeIds[itemId];
                FeNode node = _model.Geometry.Nodes[nodeId];
                point = new double[] { node.X, node.Y, node.Z };
                if (IsExplodedViewActive())
                {
                    point[0] -= part.Offset[0];
                    point[1] -= part.Offset[1];
                    point[2] -= part.Offset[2];
                }
                return true;
            }
            if (entity == null) return false;
            //
            double[] values;
            // Every edge gives the point that lies on itself, a complete circle included: the center
            // of a hole is reached by picking the cylindrical face, which gives its axis.
            if (geometryType.IsEdge())
            {
                if (entity.TryGetNumbers("midpoint", out values) && values.Length == 3)
                {
                    point = new double[] { values[0], values[1], values[2] };
                    return true;
                }
                // A straight edge is the one case where the midpoint can be computed rather than read: a
                // line is represented exactly by its end vertices, so their average is the CAD midpoint
                // and not an approximation of it. A curved edge waits for the metadata.
                return TryGetSplitGeometryStraightEdgeMidpoint(geometryId, out point);
            }
            // A sphere and a torus name their center outright
            if (entity.TryGetNumbers("center", out values) && values.Length == 3)
            {
                point = new double[] { values[0], values[1], values[2] };
                return true;
            }
            if (geometryType.IsSurface())
            {
                double[] centroid;
                if (!entity.TryGetCanonicalNumbers("centroid", out centroid) || centroid.Length != 3) return false;
                //
                string[] text;
                bool isPlane = entity.TryGetCanonicalText("type", out text) && text.Length == 1 &&
                               text[0] == "Plane";
                // The middle of a planar face lies on the face. The origin of its axis would not: that is
                // wherever the modelling kernel put the parametric origin of the surface.
                if (isPlane) { point = centroid; return true; }
                // The middle of a curved face lies off the face and is no use as a point. What is useful is
                // the axis the face turns around, taken at the height of the face - which is the middle
                // projected onto it. For a full cylinder the two are the same point; for half of one they
                // are not, and the projection is the one that stays on the axis.
                if (entity.TryGetNumbers("axis", out values) && values.Length == 6)
                {
                    point = ProjectPointOntoAxis(centroid, values);
                    return point != null;
                }
                // A face with no axis - a spline patch - carries no point worth reporting
                return false;
            }
            //
            return false;
        }
        private bool TryGetSplitGeometryStraightEdgeMidpoint(int geometryId, out double[] point)
        {
            point = null;
            //
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
            int itemId = itemTypePartIds[0];
            BasePart part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            if (part == null || part.Visualization == null) return false;
            // The edge type is filled from the CAD metadata, so it says what the curve is even when the
            // metadata of this part predates the midpoint property
            GeomCurveType[] edgeTypes = part.Visualization.EdgeTypes;
            if (edgeTypes == null || itemId < 0 || itemId >= edgeTypes.Length) return false;
            if (edgeTypes[itemId] != GeomCurveType.Line) return false;
            //
            int[] vertexNodeIds = part.Visualization.GetVertexNodeIdsForEdgeId(itemId);
            if (vertexNodeIds == null || vertexNodeIds.Length != 2) return false;
            //
            FeNode first = _model.Geometry.Nodes[vertexNodeIds[0]];
            FeNode second = _model.Geometry.Nodes[vertexNodeIds[1]];
            point = new double[] { 0.5 * (first.X + second.X), 0.5 * (first.Y + second.Y),
                                   0.5 * (first.Z + second.Z) };
            // The vertices are displayed nodes, so they carry the exploded view offset the metadata has not
            if (IsExplodedViewActive())
            {
                point[0] -= part.Offset[0];
                point[1] -= part.Offset[1];
                point[2] -= part.Offset[2];
            }
            return true;
        }
        /// <summary>
        /// The point of an axis closest to the given point. The axis is the six numbers of an axis
        /// property: an origin and a direction.
        /// </summary>
        private static double[] ProjectPointOntoAxis(double[] point, double[] axis)
        {
            double length = Math.Sqrt(axis[3] * axis[3] + axis[4] * axis[4] + axis[5] * axis[5]);
            if (length <= 0) return null;
            //
            double dx = axis[3] / length;
            double dy = axis[4] / length;
            double dz = axis[5] / length;
            //
            double distance = (point[0] - axis[0]) * dx + (point[1] - axis[1]) * dy + (point[2] - axis[2]) * dz;
            //
            return new double[] { axis[0] + distance * dx, axis[1] + distance * dy, axis[2] + distance * dz };
        }
        private bool TryGetSplitGeometryDirection(int geometryId, out double[] direction)
        {
            direction = null;
            //
            BasePart part;
            GeometryType geometryType;
            int itemId;
            GeometryMetadataEntity entity = GetSplitGeometryMetadataEntity(geometryId, out part, out geometryType,
                                                                          out itemId);
            if (entity == null) return false;
            // A line, a circle, a plane, a cylinder and a cone all carry their direction in the axis,
            // which is read from the geometry rather than fitted from the visualization
            double[] values;
            if (entity.TryGetNumbers("axis", out values) && values.Length == 6)
            {
                direction = new double[] { values[3], values[4], values[5] };
                return true;
            }
            if (entity.TryGetNumbers("extrusion_direction", out values) && values.Length == 3)
            {
                direction = new double[] { values[0], values[1], values[2] };
                return true;
            }
            return false;
        }
        private void UpdateSplitGeometryExtrusionDirection(SplitByExtrudedEdges extrudedEdges)
        {
            // A typed direction is the user's own and is never overwritten
            if (extrudedEdges.DirectionType == SplitExtrusionDirectionTypeEnum.Vector) return;
            //
            double[] direction = GetSplitGeometryPickedDirection(extrudedEdges.DirectionIds);
            // A direction that could not be read leaves the value at zero, which the validity check reports
            extrudedEdges.Direction = direction != null ? direction : new double[] { 0, 0, 0 };
        }
        /// <summary>
        /// The direction a picked selection stands for. One entity gives the direction it carries:
        /// the way a straight edge runs, the normal of a planar face, the axis of a cylinder or a
        /// cone. Two give the direction perpendicular to both, which for a planar face and an edge
        /// is the direction that lies in the face and crosses the edge - the one that cuts the face
        /// in two along that edge. Nothing is read from the edges being swept: which face of a
        /// corner is meant, and which edge of a chain, are questions only a pick can answer.
        /// </summary>
        private double[] GetSplitGeometryPickedDirection(int[] directionIds)
        {
            if (directionIds == null || directionIds.Length == 0) return null;
            //
            double[] first;
            if (!TryGetSplitGeometryDirection(directionIds[0], out first)) return null;
            if (directionIds.Length == 1) return first;
            if (directionIds.Length != 2) return null;
            //
            double[] second;
            if (!TryGetSplitGeometryDirection(directionIds[1], out second)) return null;
            //
            double[] direction = new double[] { first[1] * second[2] - first[2] * second[1],
                                                first[2] * second[0] - first[0] * second[2],
                                                first[0] * second[1] - first[1] * second[0] };
            // Two entities that run the same way name no direction between them
            double length = Math.Sqrt(direction[0] * direction[0] + direction[1] * direction[1] +
                                      direction[2] * direction[2]);
            if (length <= 1E-8) return null;
            //
            return new double[] { direction[0] / length, direction[1] / length, direction[2] / length };
        }
        // The splitting tool is drawn as a translucent blue surface with an opaque border of the same color.
        // The border cannot ride on the model edges of the surface actor, which are drawn at a lower opacity
        // than the surface and would come out fainter than what they frame.
        /// <summary>
        /// Marks the points the picked geometry resolved to. Only the picks that yield a point are marked,
        /// so a straight edge picked for its direction alone does not put a marker at the origin.
        /// </summary>
        private void HighlightGeometryFeatureSelectionWithoutPoints(GeometryFeature geometryFeature)
        {
            _form.Clear3DSelection();
            //
            int[] ids = GetSelectionIds(false);
            if (ids.Length == 0) return;
            //
            Dictionary<int, SelectionNodeMouse> pickNodes = GetSplitGeometryPickNodes(geometryFeature.SplitterData);
            List<int> idsToHighlight = new List<int>();
            foreach (int id in ids)
                if (!IsSplitGeometryPickOnThePoint(id, pickNodes, geometryFeature)) idsToHighlight.Add(id);
            //
            if (idsToHighlight.Count > 0) HighlightItemsByGeometryIds(idsToHighlight.ToArray(), true, false);
        }
        private void DrawSplitGeometryPointSymbols(GeometryFeature geometryFeature)
        {
            int[] geometryIds = geometryFeature.SplitterIds;
            if (geometryIds == null || geometryIds.Length == 0) return;
            //
            Dictionary<int, SelectionNodeMouse> pickNodes = GetSplitGeometryPickNodes(geometryFeature.SplitterData);
            List<double[]> coor = new List<double[]>();
            foreach (int geometryId in geometryIds)
            {
                if (!IsSplitGeometryPickOnThePoint(geometryId, pickNodes, geometryFeature)) continue;
                //
                // The marker stands where the point is drawn, not where the modelling kernel holds it
                double[] point;
                if (_splitToolSymbolRecorder != null)
                {
                    if (TryGetSplitGeometryPoint(geometryId, out point)) coor.Add(point);
                }
                else if (TryGetSplitGeometryDisplayPoint(geometryId, out point)) coor.Add(point);
            }
            if (coor.Count == 0) return;
            if (_splitToolSymbolRecorder != null) { _splitToolSymbolRecorder.AddPoints(coor.ToArray()); return; }
            //
            // A point that has been taken is part of the selection, so it is drawn on the selection layer:
            // that gives it the primary highlight color and the same two point sizes the hovered one gets,
            // and the clear that precedes every redraw of the feature takes it away again.
            DrawNodes("splitGeometryPoints", coor.ToArray(), _settings.Pre.PrimaryHighlightColor,
                      vtkRendererLayer.Selection, _settings.Pre.NodeSymbolSize);
        }
        private void DrawSplitGeometryPlaneSymbol(double[] origin, double[] normal, double[] extent,
                                                  int symbolIndex = 0)
        {
            if (origin == null || normal == null) return;
            //
            double[] first;
            double[] second;
            GetSplitGeometryPlaneDirections(normal, out first, out second);
            //
            // The shadow the region box casts on the plane is the smallest rectangle that still covers
            // the region, which is what keeps the symbol from reaching far past the parts it cuts
            double uMin, uMax, vMin, vMax;
            GetSplitGeometryExtentOnPlane(origin, first, second, extent, out uMin, out uMax,
                                          out vMin, out vMax);
            //
            double[][] nodeCoor = new double[4][];
            for (int i = 0; i < 4; i++)
            {
                double u = (i == 0 || i == 3) ? uMin : uMax;
                double v = (i == 0 || i == 1) ? vMin : vMax;
                nodeCoor[i] = new double[] { origin[0] + u * first[0] + v * second[0],
                                             origin[1] + u * first[1] + v * second[1],
                                             origin[2] + u * first[2] + v * second[2] };
            }
            //
            DrawSplitGeometryToolSurface("splitGeometryPlane" + symbolIndex, nodeCoor,
                                         new int[][] { new int[] { 0, 1, 2, 3 } });
            DrawSplitGeometryToolBorder("splitGeometryPlaneBorder" + symbolIndex, nodeCoor,
                                        new int[][] { new int[] { 0, 1 }, new int[] { 1, 2 },
                                                      new int[] { 2, 3 }, new int[] { 3, 0 } });
            //
            double uCenter = 0.5 * (uMin + uMax);
            double vCenter = 0.5 * (vMin + vMax);
            double[] center = new double[] { origin[0] + uCenter * first[0] + vCenter * second[0],
                                             origin[1] + uCenter * first[1] + vCenter * second[1],
                                             origin[2] + uCenter * first[2] + vCenter * second[2] };
            DrawSplitGeometryOffsetArrows("splitGeometryPlaneArrow" + symbolIndex, new double[][] { center },
                                          new double[][] { normal });
        }
        /// <summary>
        /// The way a positive offset moves the tool, drawn from points on it whether an offset is given or not,
        /// so that the sign is known before one is typed. It is a guide for the dialog and not part of the tool,
        /// so a recorded symbol leaves it out.
        /// </summary>
        private void DrawSplitGeometryOffsetArrows(string name, double[][] points, double[][] directions)
        {
            if (_splitToolSymbolRecorder != null) return;
            //
            List<double[]> arrowPoints = new List<double[]>();
            List<double[]> arrowNormals = new List<double[]>();
            for (int i = 0; i < points.Length; i++)
            {
                double[] normal = NormalizeSplitGeometryDirection(directions[i]);
                if (points[i] == null || normal == null) continue;
                arrowPoints.Add(points[i]);
                arrowNormals.Add(normal);
            }
            if (arrowPoints.Count == 0) return;
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = name;
            data.Color = _settings.Pre.SplitToolSymbolColor;
            data.Layer = vtkRendererLayer.Selection;
            data.KeepOwnColor = true;
            data.Pickable = false;
            data.Geometry.Nodes.Coor = GetSplitGeometrySymbolCoor(arrowPoints.ToArray());
            data.Geometry.Nodes.Normals = arrowNormals.ToArray();
            ApplyLighting(data);
            _form.AddOrientedArrowsActor(data, _settings.Pre.SymbolSize);
            RememberGeometryFeatureSymbolActor(data);
        }
        // A positive offset grows the radius of a surface turned around an axis. One arrow on a round surface
        // points nowhere in particular from most views, while four spread around a circle, each pointing away
        // from the axis, read as the surface growing from any side
        private void DrawSplitGeometryRadialOffsetArrows(string name, double[] center, double[] axis,
                                                         double[] first, double[] second, double distance,
                                                         double radius)
        {
            const int numOfArrows = 4;
            double[][] points = new double[numOfArrows][];
            double[][] directions = new double[numOfArrows][];
            for (int i = 0; i < numOfArrows; i++)
            {
                double angle = 2 * Math.PI * i / numOfArrows;
                points[i] = GetSplitGeometryRevolvedPoint(center, axis, first, second, distance, radius, angle);
                directions[i] = new double[] { Math.Cos(angle) * first[0] + Math.Sin(angle) * second[0],
                                               Math.Cos(angle) * first[1] + Math.Sin(angle) * second[1],
                                               Math.Cos(angle) * first[2] + Math.Sin(angle) * second[2] };
            }
            DrawSplitGeometryOffsetArrows(name, points, directions);
        }
        /// <summary>
        /// The tool an extended face makes is the whole surface the face lies on, carried past the
        /// boundary of the face, so that is what the symbol shows: a plane for a planar face, a tube for
        /// a cylindrical or conical one, and the closed sphere or torus for a face that lies on one.
        /// </summary>
        private void DrawSplitGeometryExtendedFaceSymbol(SplitByExtendedFace extendedFace, double[] extent)
        {
            if (extendedFace.SplitterIds == null) return;
            //
            for (int i = 0; i < extendedFace.SplitterIds.Length; i++)
            {
                // Only a face that will be extended gets a symbol, which is how the user sees that the
                // others are being left out
                if (extendedFace.IsExtended(i))
                    DrawSplitGeometryExtendedSurfaceSymbol(extendedFace.SplitterIds[i], extendedFace.FaceTypes[i],
                                                           extendedFace.Offset, extent, i);
            }
        }
        /// <summary>
        /// The surface a picked face is continued into, moved along its own normal by the offset. The
        /// symbol is offset the way the modelling kernel offsets the tool - a plane along its normal and
        /// the others by their radius - so the user cuts with what was drawn.
        /// </summary>
        private void DrawSplitGeometryExtendedSurfaceSymbol(int geometryId, GeomFaceType faceType, double offset,
                                                            double[] extent, int symbolIndex)
        {
            BasePart part;
            GeometryType geometryType;
            int itemId;
            GeometryMetadataEntity entity = GetSplitGeometryMetadataEntity(geometryId, out part,
                                                                          out geometryType, out itemId);
            if (entity == null) return;
            // Every surface that continues past its face either turns around an axis or stands on one
            double[] axis;
            if (!entity.TryGetNumbers("axis", out axis) || axis.Length != 6) return;
            //
            double[] origin = new double[] { axis[0], axis[1], axis[2] };
            double[] direction = new double[] { axis[3], axis[4], axis[5] };
            double[] values;
            double[] second;
            //
            if (faceType == GeomFaceType.Plane)
            {
                if (offset != 0)
                {
                    double[] normal = NormalizeSplitGeometryDirection(direction);
                    if (normal == null) return;
                    origin = new double[] { origin[0] + offset * normal[0], origin[1] + offset * normal[1],
                                            origin[2] + offset * normal[2] };
                }
                DrawSplitGeometryPlaneSymbol(origin, direction, extent, symbolIndex);
            }
            else if (faceType == GeomFaceType.Cylinder)
            {
                if (!entity.TryGetNumbers("radius", out values) || values.Length != 1) return;
                double radius = values[0] + offset;
                if (radius <= 0) return;
                DrawSplitGeometryTubeSymbol(origin, direction, extent, radius, 0, symbolIndex);
            }
            else if (faceType == GeomFaceType.Cone)
            {
                if (!entity.TryGetNumbers("reference_radius", out values) || values.Length != 1) return;
                if (!entity.TryGetNumbers("semi_angle_rad", out second) || second.Length != 1) return;
                // The offset is measured along the normal and the radius across the axis, and the two
                // stand at the half angle of the cone to each other
                double cosine = Math.Cos(second[0]);
                if (Math.Abs(cosine) <= 0) return;
                double radius = values[0] + offset / cosine;
                if (radius < 0) return;
                // The radius a cone reports belongs to the origin of its axis and grows along it
                DrawSplitGeometryTubeSymbol(origin, direction, extent, radius, Math.Tan(second[0]), symbolIndex);
            }
            else if (faceType == GeomFaceType.Sphere)
            {
                if (!entity.TryGetNumbers("radius", out values) || values.Length != 1) return;
                double radius = values[0] + offset;
                if (radius <= 0) return;
                DrawSplitGeometrySphereSymbol(origin, direction, radius, symbolIndex);
            }
            else if (faceType == GeomFaceType.Torus)
            {
                if (!entity.TryGetNumbers("major_radius", out values) || values.Length != 1) return;
                if (!entity.TryGetNumbers("minor_radius", out second) || second.Length != 1) return;
                double minorRadius = second[0] + offset;
                if (minorRadius <= 0 || minorRadius >= values[0]) return;
                DrawSplitGeometryTorusSymbol(origin, direction, values[0], minorRadius, symbolIndex);
            }
        }
        /// <summary>
        /// A straight line turned around an axis: a cylinder when the slope is zero, a cone otherwise. It
        /// is drawn over the whole part of the axis the region reaches, since that is as far as it cuts.
        /// </summary>
        private void DrawSplitGeometryTubeSymbol(double[] origin, double[] direction, double[] extent,
                                                 double referenceRadius, double slope, int symbolIndex = 0)
        {
            double[] axis = NormalizeSplitGeometryDirection(direction);
            if (axis == null) return;
            //
            double tMin;
            double tMax;
            GetSplitGeometryAxisRange(origin, axis, extent, out tMin, out tMax);
            //
            double firstRadius = referenceRadius + tMin * slope;
            double secondRadius = referenceRadius + tMax * slope;
            // Past the apex of a cone the radius turns negative, which would mirror the cone instead of
            // ending it, so the tube stops at the apex
            if (slope != 0)
            {
                double apex = -referenceRadius / slope;
                if (firstRadius < 0) { tMin = apex; firstRadius = 0; }
                if (secondRadius < 0) { tMax = apex; secondRadius = 0; }
            }
            if (tMax <= tMin || (firstRadius <= 0 && secondRadius <= 0)) return;
            //
            double[] first;
            double[] second;
            GetSplitGeometryPlaneDirections(axis, out first, out second);
            //
            int numOfSegments = 36;
            double[][] nodeCoor = new double[2 * numOfSegments][];
            for (int ring = 0; ring < 2; ring++)
            {
                double distance = ring == 0 ? tMin : tMax;
                double radius = ring == 0 ? firstRadius : secondRadius;
                for (int i = 0; i < numOfSegments; i++)
                {
                    nodeCoor[ring * numOfSegments + i] =
                        GetSplitGeometryRevolvedPoint(origin, axis, first, second, distance, radius,
                                                      2 * Math.PI * i / numOfSegments);
                }
            }
            //
            int[][] cells = new int[numOfSegments][];
            int[][] borderCells = new int[2 * numOfSegments][];
            for (int i = 0; i < numOfSegments; i++)
            {
                int next = (i + 1) % numOfSegments;
                cells[i] = new int[] { i, next, numOfSegments + next, numOfSegments + i };
                borderCells[i] = new int[] { i, next };
                borderCells[numOfSegments + i] = new int[] { numOfSegments + i, numOfSegments + next };
            }
            //
            DrawSplitGeometryToolSurface("splitGeometryTube" + symbolIndex, nodeCoor, cells);
            DrawSplitGeometryToolBorder("splitGeometryTubeBorder" + symbolIndex, nodeCoor, borderCells);
            // The arrows stand halfway along the part of the axis the tube is drawn over
            double middle = 0.5 * (tMin + tMax);
            double middleRadius = referenceRadius + middle * slope;
            if (middleRadius > 0)
                DrawSplitGeometryRadialOffsetArrows("splitGeometryTubeArrow" + symbolIndex, origin, axis, first,
                                                    second, middle, middleRadius);
        }
        /// <summary>
        /// The whole sphere, which is what a spherical face closes into when it is carried past its
        /// boundary. It needs no clipping to the region: a sphere is as large as it will ever be.
        /// </summary>
        private void DrawSplitGeometrySphereSymbol(double[] center, double[] direction, double radius,
                                                   int symbolIndex = 0)
        {
            double[] axis = NormalizeSplitGeometryDirection(direction);
            if (axis == null || radius <= 0) return;
            //
            double[] first;
            double[] second;
            GetSplitGeometryPlaneDirections(axis, out first, out second);
            //
            int numOfSegments = 36;
            int numOfRings = 18;
            double[][] nodeCoor = new double[(numOfRings + 1) * numOfSegments][];
            for (int j = 0; j <= numOfRings; j++)
            {
                double polar = Math.PI * j / numOfRings;
                double distance = radius * Math.Cos(polar);
                double ringRadius = radius * Math.Sin(polar);
                for (int i = 0; i < numOfSegments; i++)
                {
                    nodeCoor[j * numOfSegments + i] =
                        GetSplitGeometryRevolvedPoint(center, axis, first, second, distance, ringRadius,
                                                      2 * Math.PI * i / numOfSegments);
                }
            }
            //
            int[][] cells = new int[numOfRings * numOfSegments][];
            for (int j = 0; j < numOfRings; j++)
            {
                for (int i = 0; i < numOfSegments; i++)
                {
                    int next = (i + 1) % numOfSegments;
                    cells[j * numOfSegments + i] = new int[] { j * numOfSegments + i, j * numOfSegments + next,
                                                               (j + 1) * numOfSegments + next,
                                                               (j + 1) * numOfSegments + i };
                }
            }
            // A closed surface has no boundary to frame it, so the equator is drawn instead, which is also
            // what shows which way the sphere is turned
            int equator = (numOfRings / 2) * numOfSegments;
            int[][] borderCells = new int[numOfSegments][];
            for (int i = 0; i < numOfSegments; i++)
                borderCells[i] = new int[] { equator + i, equator + (i + 1) % numOfSegments };
            //
            DrawSplitGeometryToolSurface("splitGeometrySphere" + symbolIndex, nodeCoor, cells);
            DrawSplitGeometryToolBorder("splitGeometrySphereBorder" + symbolIndex, nodeCoor, borderCells);
            DrawSplitGeometryRadialOffsetArrows("splitGeometrySphereArrow" + symbolIndex, center, axis, first,
                                                second, 0, radius);
        }
        /// <summary>
        /// The whole torus, which is what a toroidal face closes into when it is carried past its
        /// boundary. Like a sphere it is already as large as it gets, so the region does not clip it.
        /// </summary>
        private void DrawSplitGeometryTorusSymbol(double[] center, double[] direction, double majorRadius,
                                                  double minorRadius, int symbolIndex = 0)
        {
            double[] axis = NormalizeSplitGeometryDirection(direction);
            if (axis == null || majorRadius <= 0 || minorRadius <= 0) return;
            //
            double[] first;
            double[] second;
            GetSplitGeometryPlaneDirections(axis, out first, out second);
            //
            int numOfSegments = 48;
            int numOfRings = 20;
            double[][] nodeCoor = new double[numOfRings * numOfSegments][];
            for (int j = 0; j < numOfRings; j++)
            {
                double tubeAngle = 2 * Math.PI * j / numOfRings;
                double ringRadius = majorRadius + minorRadius * Math.Cos(tubeAngle);
                double distance = minorRadius * Math.Sin(tubeAngle);
                for (int i = 0; i < numOfSegments; i++)
                {
                    nodeCoor[j * numOfSegments + i] =
                        GetSplitGeometryRevolvedPoint(center, axis, first, second, distance, ringRadius,
                                                      2 * Math.PI * i / numOfSegments);
                }
            }
            //
            int[][] cells = new int[numOfRings * numOfSegments][];
            for (int j = 0; j < numOfRings; j++)
            {
                int nextRing = (j + 1) % numOfRings;
                for (int i = 0; i < numOfSegments; i++)
                {
                    int next = (i + 1) % numOfSegments;
                    cells[j * numOfSegments + i] = new int[] { j * numOfSegments + i, j * numOfSegments + next,
                                                               nextRing * numOfSegments + next,
                                                               nextRing * numOfSegments + i };
                }
            }
            // The circle the tube starts from stands for the boundary a closed surface does not have
            int[][] borderCells = new int[numOfSegments][];
            for (int i = 0; i < numOfSegments; i++)
                borderCells[i] = new int[] { i, (i + 1) % numOfSegments };
            //
            DrawSplitGeometryToolSurface("splitGeometryTorus" + symbolIndex, nodeCoor, cells);
            DrawSplitGeometryToolBorder("splitGeometryTorusBorder" + symbolIndex, nodeCoor, borderCells);
            // A positive offset grows the tube of the torus, and on its outer circle that is away from the axis
            DrawSplitGeometryRadialOffsetArrows("splitGeometryTorusArrow" + symbolIndex, center, axis, first,
                                                second, 0, majorRadius + minorRadius);
        }
        private static double[] GetSplitGeometryRevolvedPoint(double[] origin, double[] axis, double[] first,
                                                              double[] second, double distance, double radius,
                                                              double angle)
        {
            double c = radius * Math.Cos(angle);
            double s = radius * Math.Sin(angle);
            //
            return new double[] { origin[0] + distance * axis[0] + c * first[0] + s * second[0],
                                  origin[1] + distance * axis[1] + c * first[1] + s * second[1],
                                  origin[2] + distance * axis[2] + c * first[2] + s * second[2] };
        }
        /// <summary>
        /// How far along the axis the region box reaches, measured from the origin of the axis.
        /// </summary>
        private static void GetSplitGeometryAxisRange(double[] origin, double[] axis, double[] extent,
                                                      out double tMin, out double tMax)
        {
            tMin = double.MaxValue;
            tMax = double.MinValue;
            //
            for (int i = 0; i < 8; i++)
            {
                double x = extent[i & 1] - origin[0];
                double y = extent[2 + ((i >> 1) & 1)] - origin[1];
                double z = extent[4 + ((i >> 2) & 1)] - origin[2];
                //
                double t = x * axis[0] + y * axis[1] + z * axis[2];
                if (t < tMin) tMin = t;
                if (t > tMax) tMax = t;
            }
            // A little past the region, so the end of the tube reads as the end of the symbol
            double margin = 0.03 * (tMax - tMin);
            tMin -= margin;
            tMax += margin;
        }
        private static double[] NormalizeSplitGeometryDirection(double[] direction)
        {
            if (direction == null || direction.Length != 3) return null;
            //
            double length = Math.Sqrt(direction[0] * direction[0] + direction[1] * direction[1] +
                                      direction[2] * direction[2]);
            if (length <= 0) return null;
            //
            return new double[] { direction[0] / length, direction[1] / length, direction[2] / length };
        }
        private void DrawSplitGeometryExtrusionSymbol(SplitByExtrudedEdges extrudedEdges, double[] extent)
        {
            if (extrudedEdges.SplitterIds == null || extrudedEdges.SplitterIds.Length == 0) return;
            if (extrudedEdges.GetExtrusionDirection() == null) return;
            //
            double[] offset;
            double[] vector;
            GetSplitGeometryExtrusion(extrudedEdges, extent, out offset, out vector);
            //
            List<double[]> nodeCoor = new List<double[]>();
            List<int[]> cells = new List<int[]>();
            List<int[]> borderCells = new List<int[]>();
            //
            foreach (int geometryId in extrudedEdges.SplitterIds)
            {
                double[][] edgeCoor = GetSplitGeometryEdgeCoor(geometryId);
                if (edgeCoor == null || edgeCoor.Length < 2) continue;
                //
                int first = nodeCoor.Count;
                foreach (double[] coor in edgeCoor)
                    nodeCoor.Add(new double[] { coor[0] + offset[0], coor[1] + offset[1], coor[2] + offset[2] });
                foreach (double[] coor in edgeCoor)
                    nodeCoor.Add(new double[] { coor[0] + offset[0] + vector[0], coor[1] + offset[1] + vector[1],
                                                coor[2] + offset[2] + vector[2] });
                //
                int count = edgeCoor.Length;
                for (int i = 0; i < count - 1; i++)
                {
                    cells.Add(new int[] { first + i, first + i + 1, first + count + i + 1, first + count + i });
                }
                borderCells.Add(new int[] { first, first + count });
                borderCells.Add(new int[] { first + count - 1, first + 2 * count - 1 });
                for (int i = 0; i < count - 1; i++)
                {
                    borderCells.Add(new int[] { first + i, first + i + 1 });
                    borderCells.Add(new int[] { first + count + i, first + count + i + 1 });
                }
            }
            if (cells.Count == 0) return;
            //
            DrawSplitGeometryToolSurface("splitGeometryExtrusion", nodeCoor.ToArray(), cells.ToArray());
            DrawSplitGeometryToolBorder("splitGeometryExtrusionBorder", nodeCoor.ToArray(),
                                        borderCells.ToArray());
        }
        private double[][] GetSplitGeometryEdgeCoor(int geometryId)
        {
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
            GeometryType geometryType = (GeometryType)itemTypePartIds[1];
            if (!geometryType.IsEdge()) return null;
            //
            BasePart part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
            if (part == null || part.Visualization == null) return null;
            //
            int[] nodeIds = part.Visualization.GetOrderedNodeIdsForEdgeId(itemTypePartIds[0]);
            if (nodeIds == null || nodeIds.Length < 2) return null;
            //
            double[][] coor = new double[nodeIds.Length][];
            for (int i = 0; i < nodeIds.Length; i++)
            {
                FeNode node = _model.Geometry.Nodes[nodeIds[i]];
                coor[i] = new double[] { node.X, node.Y, node.Z };
                if (IsExplodedViewActive())
                {
                    coor[i][0] -= part.Offset[0];
                    coor[i][1] -= part.Offset[1];
                    coor[i][2] -= part.Offset[2];
                }
            }
            return coor;
        }
        /// <summary>
        /// The coordinates of a symbol, moved onto the part as it is drawn. The symbol is computed from
        /// the geometry metadata, which holds the coordinates of the part itself, and the exploded view
        /// draws the part somewhere else; moving the finished symbol leaves the metadata alone, and the
        /// same coordinates are handed to two actors, so a copy is made rather than moving them in place.
        /// </summary>
        private double[][] GetSplitGeometrySymbolCoor(double[][] nodeCoor)
        {
            double[] offset = _geometryFeatureSymbolOffset;
            if (offset == null || nodeCoor == null) return nodeCoor;
            if (offset[0] == 0 && offset[1] == 0 && offset[2] == 0) return nodeCoor;
            //
            double[][] movedCoor = new double[nodeCoor.Length][];
            for (int i = 0; i < nodeCoor.Length; i++)
            {
                movedCoor[i] = new double[] { nodeCoor[i][0] + offset[0], nodeCoor[i][1] + offset[1],
                                              nodeCoor[i][2] + offset[2] };
            }
            return movedCoor;
        }
        /// <summary>
        /// The exploded view offset every part of the operation stands at, and false when they do not
        /// stand at one: the parts of the region and the parts the splitter and the direction were
        /// picked on. One tool means the same thing on all of them only while they share an offset.
        /// </summary>
        private bool TryGetSplitGeometryFeatureOffset(GeometryFeature geometryFeature, out double[] offset)
        {
            offset = null;
            if (geometryFeature == null || !IsExplodedViewActive()) return true;
            //
            List<string> partNames = new List<string>(GetSplitGeometryPickedPartNames(geometryFeature));
            AddSplitGeometryPartNames(geometryFeature.SplitterIds, partNames);
            if (geometryFeature is SplitByExtrudedEdges extrudedEdges)
                AddSplitGeometryPartNames(extrudedEdges.DirectionIds, partNames);
            //
            foreach (string partName in partNames)
            {
                BasePart part;
                if (!_model.Geometry.Parts.TryGetValue(partName, out part) || part.Offset == null) continue;
                //
                if (offset == null) offset = part.Offset;
                else if (part.Offset[0] != offset[0] || part.Offset[1] != offset[1] ||
                         part.Offset[2] != offset[2])
                {
                    offset = null;
                    return false;
                }
            }
            return true;
        }
        /// <summary>
        /// Takes back a pick that landed on a part the exploded view holds at another offset than the
        /// parts the operation already stands on. One tool is the same tool on all of them only while
        /// they stand together, so the pick is undone as it is made rather than building a tool that
        /// would be refused when it is applied, and the part it landed on is named.
        /// </summary>
        public bool DropSplitGeometryPickAtOtherOffset(GeometryFeature geometryFeature, int[] ids,
                                                       bool idsArePartIds,
                                                       FeatureSelectionTargetEnum selectionTarget)
        {
            if (geometryFeature == null || ids == null || ids.Length == 0) return false;
            if (!IsExplodedViewActive()) return false;
            // The offset the rest of the operation stands at. What the armed target held is replaced by
            // the ids that have just arrived, so it pins nothing: picking a part again, or picking
            // another one instead, has to be allowed to move the whole operation to that part
            List<string> standingPartNames = new List<string>();
            if (selectionTarget != FeatureSelectionTargetEnum.Region)
                standingPartNames.AddRange(GetSplitGeometryPickedPartNames(geometryFeature));
            if (selectionTarget != FeatureSelectionTargetEnum.Splitter)
                AddSplitGeometryPartNames(geometryFeature.SplitterIds, standingPartNames);
            if (selectionTarget != FeatureSelectionTargetEnum.Direction &&
                geometryFeature is SplitByExtrudedEdges extrudedEdges)
                AddSplitGeometryPartNames(extrudedEdges.DirectionIds, standingPartNames);
            //
            double[] offset = null;
            foreach (string standingPartName in standingPartNames)
            {
                BasePart standingPart;
                if (!_model.Geometry.Parts.TryGetValue(standingPartName, out standingPart) ||
                    standingPart.Offset == null) continue;
                //
                offset = standingPart.Offset;
                break;
            }
            //
            List<string> partNames = new List<string>();
            foreach (int id in ids)
            {
                BasePart part = idsArePartIds ? _model.Geometry.GetPartFromId(id) :
                                _model.Geometry.GetPartFromId(FeMesh.GetItemTypePartIdsFromGeometryId(id)[2]);
                if (part == null) continue;
                //
                if (part is CompoundGeometryPart compoundPart) partNames.AddRange(compoundPart.SubPartNames);
                else partNames.Add(part.Name);
            }
            //
            string otherPartName = null;
            foreach (string partName in partNames)
            {
                BasePart part;
                if (!_model.Geometry.Parts.TryGetValue(partName, out part) || part.Offset == null) continue;
                //
                if (offset == null) offset = part.Offset;
                else if (part.Offset[0] != offset[0] || part.Offset[1] != offset[1] ||
                         part.Offset[2] != offset[2])
                {
                    otherPartName = part.Name;
                    break;
                }
            }
            if (otherPartName == null) return false;
            //
            _form.WriteDataToOutput("Split: the part " + otherPartName + " was not taken, because the " +
                                    "exploded view holds it away from the parts this operation already " +
                                    "stands on, and one splitting tool cannot cut them both where it is " +
                                    "drawn.");
            RemoveLastSelectionNode();
            //
            return true;
        }
        private void AddSplitGeometryPartNames(int[] geometryIds, List<string> partNames)
        {
            if (geometryIds == null) return;
            //
            foreach (int geometryId in geometryIds)
            {
                int partId = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId)[2];
                BasePart part = _model.Geometry.GetPartFromId(partId);
                if (part != null && !partNames.Contains(part.Name)) partNames.Add(part.Name);
            }
        }
        private void DrawSplitGeometryToolSurface(string name, double[][] nodeCoor, int[][] cells)
        {
            if (_splitToolSymbolRecorder != null) { _splitToolSymbolRecorder.AddSurface(nodeCoor, cells); return; }
            //
            int[] cellTypes = new int[cells.Length];
            LinearQuadrilateralElement element = new LinearQuadrilateralElement(0, null);
            for (int i = 0; i < cells.Length; i++) cellTypes[i] = element.GetVtkCellType();
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = name;
            nodeCoor = GetSplitGeometrySymbolCoor(nodeCoor);
            data.Color = Color.FromArgb((int)Math.Round(255 * vtkMaxWidgetHighlight.SurfaceFillOpacity),
                                        vtkMaxWidgetHighlight.FillColor);
            data.Layer = vtkRendererLayer.Selection;
            data.DrawOnGeometry = true;
            data.KeepOwnColor = true;
            data.CanHaveElementEdges = false;
            data.BackfaceCulling = false;
            data.Pickable = false;
            data.Geometry.Nodes.Coor = nodeCoor;
            data.Geometry.Cells.CellNodeIds = cells;
            data.Geometry.Cells.Types = cellTypes;
            ApplyLighting(data);
            _form.Add3DCells(data);
            RememberGeometryFeatureSymbolActor(data);
        }
        private void DrawSplitGeometryToolBorder(string name, double[][] nodeCoor, int[][] cells)
        {
            if (_splitToolSymbolRecorder != null) { _splitToolSymbolRecorder.AddBorder(nodeCoor, cells); return; }
            //
            int[] cellTypes = new int[cells.Length];
            LinearBeamElement element = new LinearBeamElement(0, null);
            for (int i = 0; i < cells.Length; i++) cellTypes[i] = element.GetVtkCellType();
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = name;
            nodeCoor = GetSplitGeometrySymbolCoor(nodeCoor);
            data.Color = Color.FromArgb((int)Math.Round(255 * vtkMaxWidgetHighlight.WidgetBorderOpacity),
                                        _settings.Pre.SplitToolSymbolColor);
            data.Layer = vtkRendererLayer.Selection;
            data.DrawOnGeometry = true;
            data.KeepOwnColor = true;
            data.CanHaveElementEdges = false;
            data.Pickable = false;
            data.LineWidth = vtkMaxWidgetHighlight.WidgetBorderLineWidth;
            data.ActorRepresentation = vtkMaxActorRepresentation.Wire;
            data.Geometry.Nodes.Coor = nodeCoor;
            data.Geometry.Cells.CellNodeIds = cells;
            data.Geometry.Cells.Types = cellTypes;
            data.Lighting = false;
            data.UseGlobalLighting = false;
            data.Ambient = 0;
            data.Diffuse = 1;
            _form.Add3DCells(data);
            RememberGeometryFeatureSymbolActor(data);
        }
        private void RememberGeometryFeatureSymbolActor(vtkMaxActorData data)
        {
            if (_geometryFeatureSymbolActorNames == null) _geometryFeatureSymbolActorNames = new HashSet<string>();
            if (data.Name != null) _geometryFeatureSymbolActorNames.Add(data.Name);
        }
        private static void GetSplitGeometryExtentOnPlane(double[] origin, double[] first, double[] second,
                                                          double[] extent, out double uMin, out double uMax,
                                                          out double vMin, out double vMax)
        {
            uMin = double.MaxValue; uMax = double.MinValue;
            vMin = double.MaxValue; vMax = double.MinValue;
            //
            for (int i = 0; i < 8; i++)
            {
                double x = extent[i & 1] - origin[0];
                double y = extent[2 + ((i >> 1) & 1)] - origin[1];
                double z = extent[4 + ((i >> 2) & 1)] - origin[2];
                //
                double u = x * first[0] + y * first[1] + z * first[2];
                double v = x * second[0] + y * second[1] + z * second[2];
                //
                if (u < uMin) uMin = u;
                if (u > uMax) uMax = u;
                if (v < vMin) vMin = v;
                if (v > vMax) vMax = v;
            }
            // A little past the region, so the border reads as a border and not as an edge of the part
            double margin = 0.03 * Math.Max(uMax - uMin, vMax - vMin);
            uMin -= margin; uMax += margin; vMin -= margin; vMax += margin;
        }
        private static void GetSplitGeometryPlaneDirections(double[] normal, out double[] first, out double[] second)
        {
            double[] reference = Math.Abs(normal[2]) < 0.9 ? new double[] { 0, 0, 1 } : new double[] { 1, 0, 0 };
            //
            first = new double[] { normal[1] * reference[2] - normal[2] * reference[1],
                                   normal[2] * reference[0] - normal[0] * reference[2],
                                   normal[0] * reference[1] - normal[1] * reference[0] };
            double length = Math.Sqrt(first[0] * first[0] + first[1] * first[1] + first[2] * first[2]);
            first[0] /= length; first[1] /= length; first[2] /= length;
            //
            second = new double[] { normal[1] * first[2] - normal[2] * first[1],
                                    normal[2] * first[0] - normal[0] * first[2],
                                    normal[0] * first[1] - normal[1] * first[0] };
        }
        //
        public void Defeature(GeometrySelection geometrySelection)
        {
            if (geometrySelection.CreationData != null)
            {
                // In order for the Regenerate history to work perform the selection
                _selection = geometrySelection.CreationData.DeepCopy(true, false);
                geometrySelection.GeometryIds = GetSelectionIds();
                _selection.Clear();
            }
            else throw new NotSupportedException("The geometry selection does not contain any selection data.");
            // Defeature
            int[] itemTypePartIds;
            int partId;
            BasePart part;
            HashSet<int> faceIds;
            Dictionary<int, HashSet<int>> partIdFaceIds = new Dictionary<int, HashSet<int>>();
            //
            int faceId;
            int numOfNonSolidCADParts = 0;
            foreach (int id in geometrySelection.GeometryIds)
            {
                itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(id);
                partId = itemTypePartIds[2];
                part = _model.Geometry.GetPartFromId(partId);
                // Solid surface
                if (part != null && part is GeometryPart gp1 && gp1.IsCADPart &&
                    (part.PartType == PartType.Solid || part.PartType == PartType.SolidAsShell))
                {
                    // One-based CAD face numbering
                    faceId = itemTypePartIds[0] + 1;
                    if (partIdFaceIds.TryGetValue(partId, out faceIds)) faceIds.Add(faceId);
                    else partIdFaceIds.Add(partId, new HashSet<int>() { faceId });
                }
                else numOfNonSolidCADParts++;
            }
            //
            GeometryPart gp;
            string brepFileName;
            int numOfSolidParts = 0;
            Dictionary<string, int> faceCountsBefore = new Dictionary<string, int>();
            List<string> defeaturedPartNames = new List<string>();
            foreach (var entry in partIdFaceIds)
            {
                gp = (GeometryPart)_model.Geometry.GetPartFromId(entry.Key);
                // The part keeps its name across the replacement, so the face count is read back by name
                faceCountsBefore[gp.Name] = gp.Visualization == null ? 0 : gp.Visualization.FaceCount;
                defeaturedPartNames.Add(gp.Name);
                //
                brepFileName = _netgenRunner.Defeature(gp, entry.Value.ToArray());
                //
                if (brepFileName != null)
                {
                    string dividedBrepFileName = SplitClosedFacesOfBrep(brepFileName);
                    if (_settings.General.NumOfSplitFaces > 1 && dividedBrepFileName == brepFileName)
                        throw new CaeException("Defeaturing failed to split periodic faces on part '" + gp.Name + "'.");
                    try
                    {
                        ReplacePartGeometryFromFile(gp, dividedBrepFileName, true);
                    }
                    finally
                    {
                        if (dividedBrepFileName != brepFileName && File.Exists(dividedBrepFileName))
                            File.Delete(dividedBrepFileName);
                    }
                }
                else ClearAllSelection();
                //
                numOfSolidParts++;
            }
            _lastDefeaturedPartNames = defeaturedPartNames.ToArray();
            WriteDefeatureReport(faceCountsBefore);
            //
            string warning = "Defeaturing on shell parts or non-CAD parts is not possible.";
            if (numOfSolidParts <= 0)
                MessageBoxes.ShowWarning(warning);
            else if (numOfNonSolidCADParts > 0)
                MessageBoxes.ShowWarning(warning + Environment.NewLine + "Only defeaturing on CAD solid parts was done.");
            //
            CheckAndUpdateModelValidity();
        }
        // The modelling kernel returns a shape whether or not it closed anything, and gmsh only warns about
        // the features it could not close, so the face count is the one thing that says what was removed
        public Dictionary<string, int> GetGeometryPartFaceCounts()
        {
            Dictionary<string, int> faceCounts = new Dictionary<string, int>();
            if (_model == null || _model.Geometry == null) return faceCounts;
            //
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value.Visualization == null) continue;
                faceCounts[entry.Key] = entry.Value.Visualization.FaceCount;
            }
            return faceCounts;
        }
        // One line per part, so a part the operation skipped is named rather than left out of a total
        private void WriteGeometryOperationReport(string operation, string what)
        {
            int total = 0;
            int changedParts = 0;
            foreach (var entry in LastGeometryOperationCounts)
            {
                if (entry.Value > 0)
                {
                    total += entry.Value;
                    changedParts++;
                    _form.WriteDataToOutput(operation + ": " + entry.Value + " " + what + " on the part " +
                                            entry.Key + ".");
                }
                else _form.WriteDataToOutput(operation + ": nothing was done on the part " + entry.Key + ".");
            }
            _form.WriteDataToOutput(operation + " finished: " + total + " " + what + " on " + changedParts +
                                    " of the " + LastGeometryOperationCounts.Count + " selected parts.");
        }
        private void WriteDefeatureReport(Dictionary<string, int> faceCountsBefore)
        {
            int totalRemoved = 0;
            int changedParts = 0;
            BasePart part;
            foreach (var entry in faceCountsBefore)
            {
                int facesAfter = entry.Value;
                if (_model.Geometry.Parts.TryGetValue(entry.Key, out part) && part.Visualization != null)
                    facesAfter = part.Visualization.FaceCount;
                int removed = entry.Value - facesAfter;
                //
                if (removed > 0)
                {
                    totalRemoved += removed;
                    changedParts++;
                    _form.WriteDataToOutput("Defeature: the part " + entry.Key + " lost " + removed + " of its " +
                                            entry.Value + " faces.");
                }
                else
                {
                    _form.WriteDataToOutput("Defeature: the part " + entry.Key + " kept all " + entry.Value +
                                            " of its faces - nothing was removed. A feature is only closed when " +
                                            "every one of its faces is selected: a blind hole needs its bottom " +
                                            "face as well as its wall.");
                }
            }
            _form.WriteDataToOutput("Defeature finished: " + totalRemoved + " faces were removed from " +
                                    changedParts + " of the " + faceCountsBefore.Count + " selected parts.");
        }
        // The faces are taken out and the gap is left open, so a solid that loses a face becomes a shell.
        // The part is replaced in place and keeps its name and part id, whatever kind of body it becomes. A
        // compound holds only solids, so a sub part or a cell that loses a face leaves it as a shell part of
        // its own, keeping its name and part id, and the solids that lost nothing stay the compound. A body
        // that loses its last face is deleted with it, and one that falls into pieces that no longer touch
        // keeps the largest of them and gives every other piece a shell part of its own.
        public void DeleteCadPartFaces(GeometrySelection geometrySelection)
        {
            if (geometrySelection.CreationData != null)
            {
                // In order for the Regenerate history to work perform the selection
                _selection = geometrySelection.CreationData.DeepCopy(true, false);
                geometrySelection.GeometryIds = GetSelectionIds();
                _selection.Clear();
            }
            else throw new NotSupportedException("The geometry selection does not contain any selection data.");
            // A sub part of a compound carries no geometry of its own, so its faces are numbered inside the solid
            // it was written out of and the compound is what the faces are deleted from, once for all its sub
            // parts, so that a face two of them share is deleted from both
            int[] itemTypePartIds;
            BasePart part;
            List<int> kernelFaceIds;
            List<int> partIds = new List<int>();
            Dictionary<int, List<int>> kernelFaceIdsByPartId = new Dictionary<int, List<int>>();
            Dictionary<string, string> compoundPartNames = GetCompoundPartNamesBySubPartName();
            List<string> compoundNames = new List<string>();
            Dictionary<string, SortedDictionary<int, List<int>>> kernelFaceIdsBySolidByCompound =
                new Dictionary<string, SortedDictionary<int, List<int>>>();
            Dictionary<string, List<string>> pickedSubPartNamesByCompound = new Dictionary<string, List<string>>();
            int numOfSkippedFaces = 0;
            //
            foreach (int geometryId in geometrySelection.GeometryIds)
            {
                itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
                part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
                if (part == null || !((GeometryType)itemTypePartIds[1]).IsSurface()) continue;
                //
                string compoundName;
                if (compoundPartNames.TryGetValue(part.Name, out compoundName))
                {
                    int solidNumber;
                    if (!(part is GeometryPart subPart) ||
                        !GetOffsetFaceSource(subPart, compoundPartNames, out compoundName, out solidNumber))
                    {
                        numOfSkippedFaces++;
                        continue;
                    }
                    SortedDictionary<int, List<int>> kernelFaceIdsBySolid;
                    if (!kernelFaceIdsBySolidByCompound.TryGetValue(compoundName, out kernelFaceIdsBySolid))
                    {
                        kernelFaceIdsBySolid = new SortedDictionary<int, List<int>>();
                        kernelFaceIdsBySolidByCompound.Add(compoundName, kernelFaceIdsBySolid);
                        pickedSubPartNamesByCompound.Add(compoundName, new List<string>());
                        compoundNames.Add(compoundName);
                    }
                    if (!kernelFaceIdsBySolid.TryGetValue(solidNumber, out kernelFaceIds))
                    {
                        kernelFaceIds = new List<int>();
                        kernelFaceIdsBySolid.Add(solidNumber, kernelFaceIds);
                        pickedSubPartNamesByCompound[compoundName].Add(part.Name);
                    }
                    int subPartKernelFaceId = GetSplitGeometryKernelId(geometryId);
                    if (!kernelFaceIds.Contains(subPartKernelFaceId)) kernelFaceIds.Add(subPartKernelFaceId);
                    continue;
                }
                if (!(part is GeometryPart geometryPart) || !geometryPart.IsCADPart ||
                    geometryPart is CompoundGeometryPart)
                {
                    numOfSkippedFaces++;
                    continue;
                }
                //
                if (!kernelFaceIdsByPartId.TryGetValue(part.PartId, out kernelFaceIds))
                {
                    kernelFaceIds = new List<int>();
                    kernelFaceIdsByPartId.Add(part.PartId, kernelFaceIds);
                    partIds.Add(part.PartId);
                }
                int kernelFaceId = GetSplitGeometryKernelId(geometryId);
                if (!kernelFaceIds.Contains(kernelFaceId)) kernelFaceIds.Add(kernelFaceId);
            }
            //
            _lastGeometryOperationCounts = new Dictionary<string, int>();
            List<string> openedMessages = new List<string>();
            foreach (int partId in partIds)
            {
                GeometryPart geometryPart = (GeometryPart)_model.Geometry.GetPartFromId(partId);
                string partName = geometryPart.Name;
                int facesBefore = geometryPart.Visualization == null ? 0 : geometryPart.Visualization.FaceCount;
                _lastGeometryOperationCounts[partName] = 0;
                // A part carries only its own faces, so all of them selected is the whole part
                if (kernelFaceIdsByPartId[partId].Count >= facesBefore)
                {
                    RemoveGeometryParts(new string[] { partName }, false);
                    _lastGeometryOperationCounts[partName] = facesBefore;
                    openedMessages.Add("Delete cad part faces: the part " + partName + " was deleted with its last " +
                                       "face.");
                    continue;
                }
                //
                string brepFileName = DeleteCadPartFaces(geometryPart, kernelFaceIdsByPartId[partId].ToArray());
                if (brepFileName == null) continue;
                //
                string[] pieceFileNames = GetDeleteFacesPieceFileNames(brepFileName, 1,
                                                                       ReadDeleteFacesNumber(brepFileName + ".pieces"));
                ReplacePartGeometryFromFile(geometryPart, brepFileName, true);
                BasePart changedPart;
                int facesAfter = 0;
                if (_model.Geometry.Parts.TryGetValue(partName, out changedPart) && changedPart.Visualization != null)
                    facesAfter = changedPart.Visualization.FaceCount;
                //
                if (pieceFileNames.Length > 0)
                {
                    Guid? targetGroupId = GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts,
                                                                                    new string[] { partName });
                    HashSet<string> oldPartNames = CaptureOrderedDictionaryItemNamesForGroupPlacement(
                        _model.Geometry.Parts, targetGroupId);
                    string[] pieceNames = ImportDeleteFacesPieces(partName, pieceFileNames, ref facesAfter);
                    MoveAddedOrderedDictionaryItemsToGroup(_model.Geometry.Parts, oldPartNames, targetGroupId);
                    UpdateAfterImport(".brep");
                    openedMessages.Add(GetDeleteFacesPiecesMessage(partName, pieceNames));
                }
                _lastGeometryOperationCounts[partName] = facesBefore - facesAfter;
            }
            //
            foreach (string compoundName in compoundNames)
            {
                foreach (string pickedSubPartName in pickedSubPartNamesByCompound[compoundName])
                    _lastGeometryOperationCounts[pickedSubPartName] = 0;
                DeleteCompoundPartFaces((CompoundGeometryPart)_model.Geometry.Parts[compoundName],
                                        kernelFaceIdsBySolidByCompound[compoundName], openedMessages);
            }
            //
            if (partIds.Count + compoundNames.Count > 0)
                WriteGeometryOperationReport("Delete cad part faces", "faces were deleted");
            foreach (string message in openedMessages) _form.WriteDataToOutput(message);
            if (numOfSkippedFaces > 0)
                _form.WriteDataToOutput("Delete cad part faces: " + numOfSkippedFaces + " selected faces do not " +
                                        "belong to a CAD part and were skipped.");
            //
            if (partIds.Count + compoundNames.Count == 0)
                MessageBoxes.ShowWarning("Only faces of CAD parts can be deleted.");
            //
            ClearAllSelection();
            CheckAndUpdateModelValidity();
        }
        // The solids of the compound that lost no face stay the compound, which keeps its name and part id as they
        // keep theirs; one solid left gives way to a plain part, as a fused compound does. Every solid that lost a
        // face is imported as a shell part with the name, part id and color it had in the compound, and one that
        // lost every face, a face it shared with a neighbour included, is gone.
        private void DeleteCompoundPartFaces(CompoundGeometryPart compoundPart,
                                             SortedDictionary<int, List<int>> kernelFaceIdsBySolid,
                                             List<string> openedMessages)
        {
            string compoundName = compoundPart.Name;
            int numOfSolids = compoundPart.SubPartNames.Length;
            BasePart[] subParts = compoundPart.SubPartNames.Select(name => _model.Geometry.Parts[name]).ToArray();
            int[] facesBefore = subParts.Select(subPart => subPart.Visualization == null ? 0 :
                                                           subPart.Visualization.FaceCount).ToArray();
            //
            string brepFileName = DeleteCompoundPartFaces(compoundPart, kernelFaceIdsBySolid);
            if (brepFileName == null) return;
            int[][] openedLines = ReadDeleteCompoundFacesLines(brepFileName + ".opened");
            int[] openedSolidNumbers = openedLines.Select(line => line[0]).ToArray();
            int[] openedFileCounts = openedLines.Select(line => line.Length > 1 ? Math.Max(line[1], 1) : 1).ToArray();
            int[] removedSolidNumbers = ReadDeleteCompoundFacesLines(brepFileName + ".removed")
                                        .Select(line => line[0]).ToArray();
            if (openedSolidNumbers.Length + removedSolidNumbers.Length == 0 ||
                openedSolidNumbers.Concat(removedSolidNumbers).Any(i => i < 1 || i > numOfSolids))
                throw new CaeException("Delete cad part faces: the modelling kernel did not say which solids of the " +
                                       "compound part " + compoundName + " were opened.");
            int[] keptSolidNumbers = Enumerable.Range(1, numOfSolids)
                                               .Where(i => !openedSolidNumbers.Contains(i) &&
                                                           !removedSolidNumbers.Contains(i)).ToArray();
            foreach (int i in removedSolidNumbers)
            {
                _lastGeometryOperationCounts[subParts[i - 1].Name] = facesBefore[i - 1];
                openedMessages.Add("Delete cad part faces: the part " + subParts[i - 1].Name + " of the compound part " +
                                   compoundName + " was deleted with its last face.");
            }
            int[] openedPartIds = openedSolidNumbers.Select(i => subParts[i - 1].PartId).ToArray();
            //
            Guid? targetGroupId = GetLastOrderedDictionaryItemParentGroupId(_model.Geometry.Parts,
                                                                            new string[] { compoundName });
            HashSet<string> oldPartNames = CaptureOrderedDictionaryItemNamesForGroupPlacement(_model.Geometry.Parts,
                                                                                              targetGroupId);
            bool rendering = _form.RenderingOn;
            bool screenUpdating = _form.ScreenUpdating;
            _form.RenderingOn = false;
            _form.ScreenUpdating = false;
            try
            {
                if (keptSolidNumbers.Length > 1 && compoundPart.CreatedBySplit)
                {
                    File.WriteAllLines(GetSplitGeometryOriginsFileName(brepFileName),
                                       keptSolidNumbers.Select(i => i.ToString()));
                    if (ReplaceSplitGeometryPart(compoundPart, brepFileName, openedPartIds) == null)
                        throw new CaeException("Delete cad part faces: the compound part " + compoundName +
                                               " could not be replaced.");
                }
                else if (keptSolidNumbers.Length > 1)
                {
                    ReplaceCompoundKeepingSubParts(compoundPart, brepFileName, keptSolidNumbers, "Delete cad part faces",
                                                   openedPartIds);
                }
                else if (keptSolidNumbers.Length == 1)
                {
                    BasePart keptSubPart = subParts[keptSolidNumbers[0] - 1];
                    string partName = keptSubPart.Name;
                    int partId = keptSubPart.PartId;
                    if (compoundPart.CreatedBySplit)
                    {
                        partName = compoundPart.CellSubPartNames[keptSolidNumbers[0] - 1];
                        partId = GetSplitSubPartId(compoundPart, partName);
                    }
                    ReplaceCompoundWithPart(compoundPart, brepFileName, partName, partId, keptSubPart.Color,
                                            "Delete cad part faces", openedPartIds);
                }
                else
                {
                    _model.HoldPartIds(openedPartIds);
                    try
                    {
                        RemoveGeometryParts(new string[] { compoundName }, false, false);
                    }
                    finally
                    {
                        _model.ReleaseHeldPartIds();
                    }
                }
                // The opened solids are imported while their ids are held, so that none takes the id of another. The
                // first file of an opened solid is the largest of its pieces, which takes its place
                string[] importedPartNames = new string[openedSolidNumbers.Length];
                string[][] pieceFileNames = new string[openedSolidNumbers.Length][];
                _model.HoldPartIds(openedPartIds);
                try
                {
                    int fileNumber = 1;
                    for (int i = 0; i < openedSolidNumbers.Length; i++)
                    {
                        string[] names = ImportBrepPartFile(GetDeleteCompoundFacesFileName(brepFileName, fileNumber));
                        if (names == null || names.Length != 1)
                            throw new CaeException("Delete cad part faces: the part " +
                                                   subParts[openedSolidNumbers[i] - 1].Name + " of the compound part " +
                                                   compoundName + " could not be imported as a shell part.");
                        importedPartNames[i] = names[0];
                        pieceFileNames[i] = GetDeleteFacesPieceFileNames(brepFileName, fileNumber + 1,
                                                                         openedFileCounts[i] - 1);
                        fileNumber += openedFileCounts[i];
                    }
                }
                finally
                {
                    _model.ReleaseHeldPartIds();
                }
                // They are not drawn yet, so the names and ids are given directly
                for (int i = 0; i < openedSolidNumbers.Length; i++)
                {
                    BasePart subPart = subParts[openedSolidNumbers[i] - 1];
                    if (!_model.GetReservedPartIds().Contains(subPart.PartId))
                        _model.Geometry.ChangePartId(importedPartNames[i], subPart.PartId);
                    string partName = GetDeleteCompoundFacesPartName(subPart.Name, importedPartNames[i]);
                    BasePart importedPart = _model.Geometry.Parts[importedPartNames[i]];
                    importedPart.Name = partName;
                    importedPart.Color = subPart.Color;
                    _model.Geometry.Parts.Replace(importedPartNames[i], partName, importedPart);
                    //
                    int facesAfter = importedPart.Visualization == null ? 0 : importedPart.Visualization.FaceCount;
                    openedMessages.Add("Delete cad part faces: the part " + partName + " left the compound part " +
                                       compoundName + " as a shell part.");
                    if (pieceFileNames[i].Length > 0)
                    {
                        string[] pieceNames = ImportDeleteFacesPieces(partName, pieceFileNames[i], ref facesAfter);
                        openedMessages.Add(GetDeleteFacesPiecesMessage(partName, pieceNames));
                    }
                    _lastGeometryOperationCounts[partName] = facesBefore[openedSolidNumbers[i] - 1] - facesAfter;
                }
                MoveAddedOrderedDictionaryItemsToGroup(_model.Geometry.Parts, oldPartNames, targetGroupId);
                UpdateAfterImport(".brep");
            }
            finally
            {
                _form.ScreenUpdating = screenUpdating;
                if (screenUpdating) _form.RegenerateTree();
                _form.RenderingOn = rendering;
            }
        }
        private static int[][] ReadDeleteCompoundFacesLines(string fileName)
        {
            if (!File.Exists(fileName)) return new int[0][];
            return File.ReadAllLines(fileName).Where(line => line.Trim().Length > 0)
                       .Select(line => line.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries)
                                           .Select(int.Parse).ToArray()).ToArray();
        }
        private static int ReadDeleteFacesNumber(string fileName)
        {
            int[][] lines = ReadDeleteCompoundFacesLines(fileName);
            return lines.Length > 0 && lines[0].Length > 0 ? lines[0][0] : 0;
        }
        private static string[] GetDeleteFacesPieceFileNames(string brepFileName, int firstFileNumber, int numOfFiles)
        {
            string[] fileNames = new string[Math.Max(numOfFiles, 0)];
            for (int i = 0; i < fileNames.Length; i++)
                fileNames[i] = GetDeleteCompoundFacesFileName(brepFileName, firstFileNumber + i);
            return fileNames;
        }
        // The pieces of a body that no longer touch the largest of them, each a new shell part named after the body
        private string[] ImportDeleteFacesPieces(string bodyName, string[] pieceFileNames, ref int numOfFaces)
        {
            List<string> pieceNames = new List<string>();
            foreach (string pieceFileName in pieceFileNames)
            {
                string[] names = ImportBrepPartFile(pieceFileName);
                if (names == null || names.Length != 1)
                    throw new CaeException("Delete cad part faces: a piece of the part " + bodyName +
                                           " could not be imported as a shell part.");
                string pieceName = GetDeleteCompoundFacesPartName(bodyName, names[0]);
                BasePart piece = _model.Geometry.Parts[names[0]];
                piece.Name = pieceName;
                _model.Geometry.Parts.Replace(names[0], pieceName, piece);
                if (piece.Visualization != null) numOfFaces += piece.Visualization.FaceCount;
                pieceNames.Add(pieceName);
            }
            return pieceNames.ToArray();
        }
        private static string GetDeleteFacesPiecesMessage(string bodyName, string[] pieceNames)
        {
            return "Delete cad part faces: the part " + bodyName + " fell apart, and its pieces that no longer touch " +
                   "it became the parts " + string.Join(", ", pieceNames) + ".";
        }
        // An opened solid keeps its name unless a cell of the compound that stayed was renamed to it
        private string GetDeleteCompoundFacesPartName(string subPartName, string importedPartName)
        {
            HashSet<string> reservedPartNames = _model.GetReservedPartNames();
            reservedPartNames.Remove(importedPartName);
            string partName = subPartName;
            int count = 1;
            while (reservedPartNames.Contains(partName)) partName = subPartName + "-" + ++count;
            return partName;
        }
        // The mesher writes the opened solids and the pieces beside the output as <out>_000k.brep
        private static string GetDeleteCompoundFacesFileName(string brepFileName, int openedNumber)
        {
            return Path.Combine(Path.GetDirectoryName(brepFileName),
                                Path.GetFileNameWithoutExtension(brepFileName) + "_" + openedNumber.ToString("0000") +
                                Path.GetExtension(brepFileName));
        }
        private string DeleteCompoundPartFaces(CompoundGeometryPart compoundPart,
                                               SortedDictionary<int, List<int>> kernelFaceIdsBySolid)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inputBrepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            string outputBrepFileName = inputBrepFileName;
            // One face group per solid, the faces numbered inside it
            string faceIdsArgument = kernelFaceIdsBySolid.Count.ToString();
            foreach (var entry in kernelFaceIdsBySolid)
            {
                faceIdsArgument += " " + entry.Key + " " + entry.Value.Count;
                foreach (int kernelFaceId in entry.Value) faceIdsArgument += " " + kernelFaceId;
            }
            //
            if (File.Exists(inputBrepFileName)) File.Delete(inputBrepFileName);
            if (File.Exists(outputBrepFileName + ".opened")) File.Delete(outputBrepFileName + ".opened");
            if (File.Exists(outputBrepFileName + ".removed")) File.Delete(outputBrepFileName + ".removed");
            DeleteDeleteFacesPieceFiles(outputBrepFileName);
            //
            File.WriteAllText(inputBrepFileName, compoundPart.CADFileData);
            //
            string argument = "BREP_REMOVE_COMPOUND_FACES " +
                              "\"" + inputBrepFileName.ToUTF8() + "\" " +
                              "\"" + outputBrepFileName.ToUTF8() + "\" " +
                              faceIdsArgument;
            //
            JobStatus jobStatus = _jobRunner.Run(compoundPart.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK && File.Exists(outputBrepFileName + ".opened")) return outputBrepFileName;
            else return null;
        }
        private static void DeleteDeleteFacesPieceFiles(string brepFileName)
        {
            string pattern = Path.GetFileNameWithoutExtension(brepFileName) + "_????" + Path.GetExtension(brepFileName);
            foreach (string fileName in Directory.GetFiles(Path.GetDirectoryName(brepFileName), pattern))
                File.Delete(fileName);
        }
        private string DeleteCadPartFaces(GeometryPart part, int[] kernelFaceIds)
        {
            string workDirectory = _settings.GetWorkDirectory();
            //
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                MessageBoxes.ShowWorkDirectoryError();
                return null;
            }
            //
            string executable = Application.StartupPath + Globals.NetGenMesher;
            string inputBrepFileName = Path.Combine(workDirectory, Globals.BrepFileName);
            string outputBrepFileName = inputBrepFileName;
            // One face group, numbered in the shape itself
            string faceIdsArgument = "1 0 " + kernelFaceIds.Length;
            foreach (int kernelFaceId in kernelFaceIds) faceIdsArgument += " " + kernelFaceId;
            //
            if (File.Exists(inputBrepFileName)) File.Delete(inputBrepFileName);
            if (File.Exists(outputBrepFileName + ".pieces")) File.Delete(outputBrepFileName + ".pieces");
            DeleteDeleteFacesPieceFiles(outputBrepFileName);
            //
            File.WriteAllText(inputBrepFileName, part.CADFileData);
            //
            string argument = "BREP_REMOVE_FACES " +
                              "\"" + inputBrepFileName.ToUTF8() + "\" " +
                              "\"" + outputBrepFileName.ToUTF8() + "\" " +
                              faceIdsArgument;
            //
            JobStatus jobStatus = _jobRunner.Run(part.Name, executable, argument, workDirectory,
                                                 _form.WriteDataToOutput);
            // Job completed
            if (jobStatus == JobStatus.OK) return outputBrepFileName;
            else return null;
        }
