        public MeshingParameters GetPartMeshingParameters(string partName,
                                                          OrderedDictionary<string, MeshSetupItem> meshSetupItems = null)
        {
            HashSet<int> selectedPartIds;
            string[] meshAblePartNames = GetMeshablePartNames(new string[] { partName });
            int[] meshAblePartIds = _model.Geometry.GetPartIdsFomPartNames(meshAblePartNames);
            // The sizes the dialog would show for the same selection: a compound is meshed as a whole but
            // its size follows its original parts, even when splitting has turned them into cells.
            MeshingParameters meshingParameters = GetPartDefaultMeshingParameters(meshAblePartNames);
            if (meshingParameters == null) meshingParameters = GetPartDefaultMeshingParameters(partName);
            //
            if (meshSetupItems == null) meshSetupItems = _model.Geometry.MeshSetupItems;
            //
            foreach (var entry in meshSetupItems)
            {
                if (entry.Value is MeshingParameters mp && mp.Active && mp.Valid)
                {
                    if (mp.CreationIds != null && mp.CreationIds.Length > 0)
                    {
                        selectedPartIds = new HashSet<int>(FeMesh.GetPartIdsFromGeometryIds(mp.CreationIds));
                        //
                        if (selectedPartIds.Intersect(meshAblePartIds).Count() == meshAblePartIds.Length)
                            meshingParameters = mp.DeepCopy();
                    }
                }
            }
            // The Netgen settings are those of the Netgen item, and only an older model meshes a part without
            // one by the settings its meshing parameters carry
            NetgenMesh netgenMesh = GetUserMesherSetupItems(partName, meshSetupItems).FirstOrDefault() as NetgenMesh;
            if (netgenMesh == null && !_defaultMeshTypesDisabled) netgenMesh = new NetgenMesh("Default");
            if (netgenMesh != null) netgenMesh.CopyNetgenValuesTo(meshingParameters);
            // Allow a quad dominated mesh only for shells
            if (_model.Geometry.Parts[partName].PartType != PartType.Shell) meshingParameters.QuadDominated = false;
            //
            return meshingParameters;
        }
        public MeshingParameters GetDefaultMeshingParameters(string meshingParametersName)
        {
            MeshingParameters meshingParameters = _settings.Meshing.MeshingParameters.DeepClone();
            meshingParameters.Name = meshingParametersName;
            return meshingParameters;
        }
        public MeshingParameters GetPartDefaultMeshingParameters(string partName)
        {
            BasePart part = GetGeometryPart(partName);
            if (part == null) part = GetModelPart(partName);
            if (part == null) return null;
            //
            if (!ExecutableJobIdle) throw new Exception("The meshing is already in progress.");
            //
            MeshingParameters defaultMeshingParameters = GetDefaultMeshingParameters("Default");
            double factorMax = defaultMeshingParameters.FactorMax;
            double factorMin = defaultMeshingParameters.FactorMin;
            BoundingBox boundingBox = part.BoundingBox;
            string[] sizePartNames = GetMeshingSizePartNames(partName);
            if (sizePartNames.Length > 1)
            {
                boundingBox = new BoundingBox();
                foreach (string sizePartName in sizePartNames)
                    boundingBox.IncludeBox(_model.Geometry.Parts[sizePartName].BoundingBox);
            }
            double diagonal = boundingBox.GetDiagonal();
            //
            defaultMeshingParameters.MaxH = Tools.RoundToSignificantDigits(diagonal * factorMax, 2);
            defaultMeshingParameters.MinH = Tools.RoundToSignificantDigits(diagonal * factorMin, 2);
            //
            return defaultMeshingParameters;
        }
        private string[] GetMeshingSizePartNames(string partName)
        {
            // A split part is represented by cells, but its default size follows their combined bounds.
            if (_model.Geometry != null)
            {
                foreach (var entry in _model.Geometry.Parts)
                {
                    if (!(entry.Value is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit) continue;
                    int cellIndex = Array.IndexOf(compoundPart.SubPartNames, partName);
                    if (cellIndex >= 0 && compoundPart.CellSubPartNames[cellIndex] != null)
                        return compoundPart.GetCellNames(compoundPart.CellSubPartNames[cellIndex]);
                }
            }
            return new string[] { partName };
        }
        public ShellMmg GetPartDefaultShellMmg(string partName)
        {
            BasePart part = GetGeometryPart(partName);
            if (part == null) part = GetModelPart(partName);
            if (part == null) return null;
            //
            ShellMmg shellMmg = new ShellMmg("Default");
            shellMmg.Hausdorff = Tools.RoundToSignificantDigits(
                part.BoundingBox.GetDiagonal() * shellMmg.RelativeHausdorff, 2);
            return shellMmg;
        }
        public ShellMmg GetPartDefaultShellMmg(string[] partNames)
        {
            if (partNames == null || partNames.Length == 0) return null;
            double sumHausdorff = 0;
            ShellMmg shellMmg = null;
            foreach (string partName in partNames)
            {
                shellMmg = GetPartDefaultShellMmg(partName);
                if (shellMmg == null) return null;
                sumHausdorff += shellMmg.Hausdorff;
            }
            shellMmg.Hausdorff = Tools.RoundToSignificantDigits(sumHausdorff / partNames.Length, 2);
            return shellMmg;
        }
        public MeshingParameters GetPartDefaultMeshingParameters(string[] partNames)
        {
            double sumMax = 0;
            double sumMin = 0;
            MeshingParameters defaultMeshingParameters = null;
            HashSet<string> sizedSplitPartNames = new HashSet<string>();
            int sizePartCount = 0;
            foreach (var partName in partNames)
            {
                string[] sizePartNames = GetMeshingSizePartNames(partName);
                if (sizePartNames.Length > 1 && !sizedSplitPartNames.Add(sizePartNames[0])) continue;
                // Default parameters
                defaultMeshingParameters = GetPartDefaultMeshingParameters(partName);
                // If part is not found return null
                if (defaultMeshingParameters != null)
                {
                    sumMax += defaultMeshingParameters.MaxH;
                    sumMin += defaultMeshingParameters.MinH;
                    sizePartCount++;
                }
                // Part was not found
                else return null;
            }
            //
            defaultMeshingParameters.MaxH = Tools.RoundToSignificantDigits(sumMax / sizePartCount, 2);
            defaultMeshingParameters.MinH = Tools.RoundToSignificantDigits(sumMin / sizePartCount, 2);
            return defaultMeshingParameters;
        }
        //
        public void GetMeshItemSizes(string partName, ref GmshData gmshData,
                                     OrderedDictionary<string, MeshSetupItem> meshSetupItems = null)
        {
            HashSet<int> selectedPartIds;
            string[] meshAblePartNames = GetMeshablePartNames(new string[] { partName });
            int[] meshAblePartIds = _model.Geometry.GetPartIdsFomPartNames(meshAblePartNames);
            List<LocalMeshSize> localMeshSizes = new List<LocalMeshSize>();
            //
            if (meshSetupItems == null) meshSetupItems = _model.Geometry.MeshSetupItems;
            //
            foreach (var entry in meshSetupItems)
            {
                if (entry.Value is LocalMeshSize lms && lms.Active && lms.Valid)
                {
                    if (lms.CreationIds != null && lms.CreationIds.Length > 0)
                    {
                        selectedPartIds = new HashSet<int>(FeMesh.GetPartIdsFromGeometryIds(lms.CreationIds));
                        //
                        if (selectedPartIds.Intersect(meshAblePartIds).Count() > 0) localMeshSizes.Add(lms.DeepCopy());
                    }
                }
            }
            //
            int[] itemTypePartId;
            int itemId;
            int vertexNodeId;
            GeometryType geometryType;
            int partId;
            BasePart part;
            MeshingParameters meshingParameters;
            double minH;
            double maxH;
            int edgeId;
            double length;
            int numElements;
            gmshData.VertexNodeIdMeshSize = new Dictionary<int, double>();
            gmshData.EdgeIdNumElements = new Dictionary<int, int>();
            foreach (var localMeshSize in localMeshSizes)
            {
                foreach (int geometryId in localMeshSize.CreationIds)
                {
                    itemTypePartId = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
                    itemId = itemTypePartId[0];
                    geometryType = (GeometryType)itemTypePartId[1];
                    partId = itemTypePartId[2];
                    part = _model.Geometry.GetPartFromId(partId);
                    meshingParameters = GetPartMeshingParameters(part.Name, meshSetupItems);
                    minH = meshingParameters.MinH;
                    maxH = meshingParameters.MaxH;
                    //
                    if (geometryType == GeometryType.Vertex)
                    {
                        if (localMeshSize.Type == LocalMeshSizeTypeEnum.ElementSize)
                        {
                            vertexNodeId = part.Visualization.VertexNodeIds[itemId];
                            gmshData.VertexNodeIdMeshSize[vertexNodeId] = localMeshSize.GetMeshSize(-1, minH, maxH);
                        }
                    }
                    else if (geometryType.IsEdge())
                    {
                        length = part.Visualization.EdgeLengths[itemId];
                        numElements = localMeshSize.GetNumberOfElements(length, minH, maxH);
                        //
                        gmshData.EdgeIdNumElements[FeMesh.GmshTopologyId(itemId, partId)] = numElements;
                    }
                    else if (geometryType.IsSurface())
                    {
                        for (int i = 0; i < part.Visualization.FaceEdgeIds[itemId].Length; i++)
                        {
                            edgeId = part.Visualization.FaceEdgeIds[itemId][i];
                            length = part.Visualization.EdgeLengths[edgeId];
                            numElements = localMeshSize.GetNumberOfElements(length, minH, maxH);
                            //
                            gmshData.EdgeIdNumElements[FeMesh.GmshTopologyId(edgeId, partId)] = numElements;
                        }
                    }
                    else if (geometryType == GeometryType.Part)
                    {
                        for (int i = 0; i < part.Visualization.FaceCount; i++)
                        {
                            for (int j = 0; j < part.Visualization.FaceEdgeIds[i].Length; j++)
                            {
                                edgeId = part.Visualization.FaceEdgeIds[i][j];
                                length = part.Visualization.EdgeLengths[edgeId];
                                numElements = localMeshSize.GetNumberOfElements(length, minH, maxH);
                                //
                                gmshData.EdgeIdNumElements[FeMesh.GmshTopologyId(edgeId, partId)] = numElements;
                            }
                        }
                    }
                    else throw new NotSupportedException();
                }
            }
        }
