        public bool CreateMesh(string partName)
        {
            return CreateMeshes(new string[] { partName }, out _);
        }
        public bool CreateMeshes(string[] partNames, out string[] successfulPartNames)
        {
            Stopwatch totalWatch = Stopwatch.StartNew();
            MeshBatchPerformance performance = new MeshBatchPerformance();
            List<GeneratedMeshData> generatedMeshes = new List<GeneratedMeshData>();
            List<string> errors = new List<string>();
            HashSet<string> generatedMeshPartNames = new HashSet<string>();
            bool retainBatchDirectory = false;
            _lastMeshedPartNames = new string[0];
            _lastMeshedModelPartNames = new string[0];
            _lastMeshingErrors = new string[0];
            _lastInvertedElementPartNames = new string[0];
            successfulPartNames = new string[0];
            //
            string workDirectory = _settings.GetWorkDirectory();
            if (workDirectory == null || !Directory.Exists(workDirectory))
            {
                // The reason is recorded, not only shown, because a caller that is not a person has to
                // be able to read why nothing was meshed
                _lastMeshingErrors = new string[] { "The work directory does not exist." };
                MessageBoxes.ShowWorkDirectoryError();
                return false;
            }
            //
            int counter = 1;
            string batchDirectory;
            do
            {
                string directoryName = $"MeshBatch_{counter++:D4}";
                batchDirectory = Path.Combine(workDirectory, directoryName);
            }
            while (Directory.Exists(batchDirectory));
            //string batchDirectory = Path.Combine(workDirectory, "MeshBatch_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(batchDirectory);
            //
            try
            {
                string[] uniquePartNames = partNames.Where(name => name != null).Distinct().ToArray();
                for (int i = 0; i < uniquePartNames.Length; i++)
                {
                    string partName = uniquePartNames[i];
                    bool keepQuadWildFilesOnFailure = false;
                    try
                    {
                        if (!_model.Geometry.Parts.TryGetValue(partName, out BasePart basePart) ||
                            !(basePart is GeometryPart part))
                            throw new CaeException("The geometry part does not exist.");
                        ShellQuadWild shellQuadWild = GetActiveValidMesherSetupItems(part.Name)
                                                       .OfType<ShellQuadWild>().FirstOrDefault();
                        keepQuadWildFilesOnFailure = shellQuadWild != null && shellQuadWild.KeepFilesOnFailure;
                        //
                        string partDirectory = Path.Combine(batchDirectory, i.ToString("D4"));
                        Directory.CreateDirectory(partDirectory);
                        //
                        Stopwatch phaseWatch = Stopwatch.StartNew();
                        GeneratedMeshData generatedMesh;
                        try
                        {
                            generatedMesh = GenerateMesh(part, partDirectory);
                        }
                        finally
                        {
                            phaseWatch.Stop();
                            performance.Generation += phaseWatch.Elapsed.TotalSeconds;
                        }
                        //
                        if (generatedMesh == null)
                        {
                            if (keepQuadWildFilesOnFailure) retainBatchDirectory = true;
                            if (_jobRunner.WasKilled)
                            {
                                errors.Add("Mesh generation canceled.");
                                break;
                            }
                            errors.Add(partName + ": Mesh generation failed.");
                            continue;
                        }
                        if (generatedMesh.RetainWorkDirectory) retainBatchDirectory = true;
                        //
                        phaseWatch.Restart();
                        try
                        {
                            PrepareGeneratedMesh(generatedMesh);
                            ApplyThickenShellMesh(generatedMesh);
                            AddQuadWildDebugVisualization(generatedMesh);
                        }
                        finally
                        {
                            phaseWatch.Stop();
                            performance.Validation += phaseWatch.Elapsed.TotalSeconds;
                        }
                        //
                        string duplicateMeshPartName = generatedMesh.Mesh.Parts.Keys.FirstOrDefault(
                            name => generatedMeshPartNames.Contains(name));
                        if (duplicateMeshPartName != null)
                            throw new CaeException("More than one selected geometry part generates the mesh part '" +
                                                   duplicateMeshPartName + "'.");
                        //
                        generatedMeshPartNames.UnionWith(generatedMesh.Mesh.Parts.Keys);
                        generatedMeshes.Add(generatedMesh);
                    }
                    catch (Exception ex)
                    {
                        if (keepQuadWildFilesOnFailure) retainBatchDirectory = true;
                        errors.Add(partName + ": " + ex.Message);
                        if (_jobRunner.WasKilled)
                        {
                            errors.Add("Mesh generation canceled.");
                            break;
                        }
                    }
                }
                //
                if (generatedMeshes.Count > 0) CommitGeneratedMeshes(generatedMeshes, performance);
            }
            finally
            {
                try
                {
                    if (Directory.Exists(batchDirectory))
                    {
                        if (retainBatchDirectory)
                            _form.WriteDataToOutput("QuadWild meshing files retained for debugging: " +
                                                    batchDirectory);
                        else Directory.Delete(batchDirectory, true);
                    }
                }
                catch { }
            }
            //
            totalWatch.Stop();
            performance.Total = totalWatch.Elapsed.TotalSeconds;
            successfulPartNames = generatedMeshes.Select(item => item.GeometryPart.Name).ToArray();
            _lastMeshedPartNames = successfulPartNames;
            _lastMeshedModelPartNames = generatedMeshes.SelectMany(item => item.Mesh.Parts.Keys).ToArray();
            _lastMeshingErrors = errors.ToArray();
            WriteMeshBatchPerformance(performance);
            //
            if (errors.Count > 0)
            {
                _form.WriteDataToOutput("");
                foreach (string error in errors) _form.WriteErrorToOutput(error);
            }
            //
            return generatedMeshes.Count > 0;
        }
        private GeneratedMeshData GenerateMesh(GeometryPart part, string workDirectory)
        {
            if (part.IsCADPart) return CreateMeshFromBrep(part, workDirectory);
            else return CreateMeshFromStl(part, workDirectory);
        }
        private void PrepareGeneratedMesh(GeneratedMeshData generatedMesh)
        {
            GeometryPart part = generatedMesh.GeometryPart;
            MeshingParameters meshingParameters = GetPartMeshingParameters(part.Name);
            string extension = Path.GetExtension(generatedMesh.MeshFileName);
            bool convertToSecondOrder;
            if (generatedMesh.ConvertToSecondOrder.HasValue)
                convertToSecondOrder = generatedMesh.ConvertToSecondOrder.Value;
            else if (extension == ".mesh") convertToSecondOrder = meshingParameters.SecondOrder;
            else if (extension == ".inp") convertToSecondOrder = false;
            else if (extension == ".obj") convertToSecondOrder = meshingParameters.SecondOrder;
            else convertToSecondOrder = meshingParameters.SecondOrder && !meshingParameters.MidsideNodesOnGeometry;
            //
            if (convertToSecondOrder) _form.WriteDataToOutput("Converting mesh to second order...");
            //
            RevolveMesh revolveMesh = GetFull360RevolveMesh(part.Name);
            Dictionary<int, string> elementIdMaterialName;
            generatedMesh.Mesh = _model.PrepareGeneratedMeshFromMeshFile(generatedMesh.MeshFileName, part,
                                                                          convertToSecondOrder,
                                                                          meshingParameters.SplitCompoundMesh,
                                                                          meshingParameters.MergeCompoundParts,
                                                                          meshingParameters.MergeCells, revolveMesh, out elementIdMaterialName,
                                                                          GetSymmetricSweepMesh(part.Name));
            if (convertToSecondOrder) _form.WriteDataToOutput("Done.");
            generatedMesh.ElementIdMaterialName = elementIdMaterialName;
            //
            if (generatedMesh.QuadWildInputFileInfo != null)
            {
                _form.WriteDataToOutput("Recovering QuadWild model edges...");
                try
                {
                    QuadWildEdgeRecoveryInfo recoveryInfo =
                        QuadWildEdgeRecovery.Restore(generatedMesh.Mesh, part.Name,
                                                     generatedMesh.QuadWildInputFileInfo.ModelEdges,
                                                     generatedMesh.QuadWildInputFileInfo.ModelFaceEdgeIds,
                                                     elementIdMaterialName);
                    if (recoveryInfo.Success)
                    {
                        string fallback = recoveryInfo.UsedFallback
                                        ? " (adaptive fallback used: " + recoveryInfo.Warning + ")" : "";
                        _form.WriteDataToOutput("QuadWild model edges: " + recoveryInfo.EdgeCount +
                                                " edges, " + recoveryInfo.SegmentCount + " mesh segments" +
                                                fallback + ".");
                        if (recoveryInfo.FreeEdgeCount > 0)
                            _form.WriteDataToOutput("QuadWild free boundary: " + recoveryInfo.FreeEdgeCount +
                                                    " model edge/s recovered from the mesh boundary.");
                        if (recoveryInfo.FaceCount > 0)
                            _form.WriteDataToOutput("QuadWild model faces: " + recoveryInfo.FaceCount + " faces.");
                        if (recoveryInfo.FaceWarning != null)
                            _form.WriteDataToOutput("Warning: " + recoveryInfo.FaceWarning);
                    }
                    else
                    {
                        _form.WriteDataToOutput("Warning: QuadWild model edges could not be reconstructed. " +
                                                recoveryInfo.Warning + " The mesh will use automatically " +
                                                "detected edges.");
                    }
                }
                catch (Exception ex)
                {
                    // Edge recovery is supplementary. Never reject an otherwise valid QuadWild mesh because
                    // its source-edge topology cannot be mapped back to the final discretization.
                    _form.WriteDataToOutput("Warning: QuadWild model edges could not be reconstructed. " +
                                            ex.Message + " The mesh will use automatically detected edges.");
                }
            }
            List<string> relatedPartNames = new List<string>();
            if (part is CompoundGeometryPart compoundPart)
            {
                relatedPartNames.Add(compoundPart.Name);
                relatedPartNames.AddRange(compoundPart.SubPartNames);
                relatedPartNames.AddRange(compoundPart.GetSplitSubPartNames());
            }
            else relatedPartNames.Add(part.Name);
            // The parts of an earlier QuadWild debug visualization are replaced too
            if (generatedMesh.QuadWildInputFileInfo != null && _model.Mesh != null)
                relatedPartNames.AddRange(_model.Mesh.Parts.Keys.Where(name =>
                    QuadWildDebugVisualization.IsDebugItemName(name, part.Name)));
            generatedMesh.RelatedPartNames = relatedPartNames.ToArray();
        }
        private void AddQuadWildDebugVisualization(GeneratedMeshData generatedMesh)
        {
            if (generatedMesh.QuadWildDebugTracePrefix == null) return;
            if (GetActiveValidMeshSetupItems<ThickenShellMesh>(generatedMesh.GeometryPart.Name).Length > 0)
            {
                _form.WriteDataToOutput("Warning: the QuadWild debug visualization is skipped for a thickened shell mesh.");
                return;
            }
            try
            {
                QuadWildDebugVisualization.Add(generatedMesh.Mesh, generatedMesh.GeometryPart.Name,
                                               generatedMesh.QuadWildDebugTracePrefix,
                                               generatedMesh.QuadWildTriangularPreview,
                                               generatedMesh.QuadWildInputFileInfo,
                                               generatedMesh.ElementIdMaterialName, _form.WriteDataToOutput);
            }
            catch (Exception ex)
            {
                // The visualization only helps inspecting the mesh, so it never rejects it
                _form.WriteDataToOutput("Warning: the QuadWild debug visualization could not be created. " + ex.Message);
            }
        }
        /// <summary>
        /// The sweep mesh setup item that meshes the part, when it meshed only one symmetric piece of the part's cells
        /// and the others take mirror images of it.
        /// </summary>
        private SweepMesh GetSymmetricSweepMesh(string partName)
        {
            MeshSetupItem[] meshSetupItems = GetActiveValidMesherSetupItems(partName);
            if (meshSetupItems.Length > 0 && meshSetupItems[0] is SweepMesh sweepMesh && sweepMesh.HasSymmetry)
                return sweepMesh;
            else return null;
        }
        private RevolveMesh GetFull360RevolveMesh(string partName)
        {
            MeshSetupItem[] meshSetupItems = GetActiveValidMeshSetupItems<GmshSetupItem>(partName);
            if (meshSetupItems.Length > 0 && meshSetupItems[0] is RevolveMesh revolveMesh &&
                revolveMesh.CreateFull360Model)
                return revolveMesh;
            else return null;
        }
        private void ApplyThickenShellMesh(GeneratedMeshData generatedMesh)
        {
            MeshSetupItem[] meshSetupItems =
                GetActiveValidMeshSetupItems<ThickenShellMesh>(generatedMesh.GeometryPart.Name);
            if (meshSetupItems == null || meshSetupItems.Length == 0) return;
            //
            ThickenShellMesh thickenShellMesh = (ThickenShellMesh)meshSetupItems[meshSetupItems.Length - 1];
            string[] partNames = generatedMesh.Mesh.Parts.Keys.ToArray();
            Dictionary<int, Vec3D> nodeIdNormal;
            if (_model.Geometry.GetAllCADPartNames().Intersect(partNames).Count() == partNames.Length)
            {
                nodeIdNormal = _model.Geometry.GetNodeNormals(partNames, generatedMesh.Mesh,
                                                              thickenShellMesh.KeepModelEdges,
                                                              _gmshRunner.GeNormalsFromGeometryAtMeshNodes);
            }
            else
            {
                nodeIdNormal = generatedMesh.Mesh.GetNodeNormals(partNames, generatedMesh.Mesh,
                                                                 thickenShellMesh.KeepModelEdges,
                                                                 _gmshRunner.GeNormalsFromGeometryAtMeshNodes);
            }
            //
            string[] errors = generatedMesh.Mesh.ThickenShellMesh(partNames, nodeIdNormal,
                                                                  thickenShellMesh.Thickness,
                                                                  thickenShellMesh.NumberOfLayers,
                                                                  thickenShellMesh.Offset,
                                                                  false, out _);
            if (errors.Length > 0) throw new CaeException(errors[0]);
        }
        /// <summary>
        /// The geometry part a mesh part was meshed from. A sub part of a split compound is meshed from its
        /// cells and has no geometry part of its own, so its first cell stands for it: the mesh part takes
        /// that cell's color and element types, and the part id of the sub part.
        /// </summary>
        private GeometryPart GetGeometryPartOfMeshPart(string meshPartName)
        {
            BasePart part;
            if (_model.Geometry.Parts.TryGetValue(meshPartName, out part)) return part as GeometryPart;
            //
            CompoundGeometryPart splitCompoundPart = GetSplitCompoundOfSubPart(meshPartName);
            if (splitCompoundPart == null) return null;
            //
            string firstCellName = splitCompoundPart.GetCellNames(meshPartName).FirstOrDefault();
            return firstCellName == null ? null : GetGeometryPart(firstCellName);
        }
        private int GetPartIdOfMeshPart(string meshPartName, GeometryPart geometryPart)
        {
            // The only cell of a sub part is named after it, and is meshed as the sub part
            CompoundGeometryPart splitCompoundPart = GetSplitCompoundOfSubPart(meshPartName);
            int subPartId = splitCompoundPart == null ? -1 : GetSplitSubPartId(splitCompoundPart, meshPartName);
            return subPartId > 0 ? subPartId : geometryPart.PartId;
        }
        public string GetSplitSubPartNameOfCell(string cellName)
        {
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit) continue;
                int index = Array.IndexOf(compoundPart.SubPartNames, cellName);
                if (index >= 0) return compoundPart.CellSubPartNames[index];
            }
            return null;
        }
        private CompoundGeometryPart GetSplitCompoundOfSubPart(string subPartName)
        {
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart compoundPart && compoundPart.CreatedBySplit &&
                    compoundPart.CellSubPartNames.Contains(subPartName))
                    return compoundPart;
            }
            return null;
        }
        private void CommitGeneratedMeshes(List<GeneratedMeshData> generatedMeshes, MeshBatchPerformance performance)
        {
            OrderedDictionaryItemLayout<string> oldMeshPartLayout = null;
            HashSet<string> oldMeshPartNames = new HashSet<string>();
            if (_model.Mesh != null)
            {
                oldMeshPartNames = new HashSet<string>(_model.Mesh.Parts.Keys, _model.Mesh.Parts.Comparer);
                oldMeshPartLayout = _model.Mesh.Parts.GetItemLayoutSnapshot();
            }
            //
            HashSet<string> meshPartNamesToRemove = new HashSet<string>();
            foreach (GeneratedMeshData generatedMesh in generatedMeshes)
                meshPartNamesToRemove.UnionWith(generatedMesh.RelatedPartNames);
            //
            Stopwatch phaseWatch = Stopwatch.StartNew();
            if (_model.Mesh != null)
            {
                ViewGeometryModelResults view = ViewGeometryModelResults.Model;
                string[] names = meshPartNamesToRemove.ToArray();
                _annotations.RemoveCurrentArrowAnnotationsByParts(names, view);
                _model.Mesh.RemoveParts(names, out _, true);
                // The node and element sets of an earlier QuadWild debug visualization
                foreach (GeneratedMeshData generatedMesh in generatedMeshes)
                {
                    if (generatedMesh.QuadWildInputFileInfo == null) continue;
                    string partName = generatedMesh.GeometryPart.Name;
                    foreach (string name in _model.Mesh.NodeSets.Keys.Where(name =>
                             QuadWildDebugVisualization.IsDebugItemName(name, partName)).ToArray())
                        _model.Mesh.NodeSets.Remove(name);
                    foreach (string name in _model.Mesh.ElementSets.Keys.Where(name =>
                             QuadWildDebugVisualization.IsDebugItemName(name, partName)).ToArray())
                        _model.Mesh.ElementSets.Remove(name);
                }
            }
            phaseWatch.Stop();
            performance.Removal = phaseWatch.Elapsed.TotalSeconds;
            //
            bool renumbered = false;
            int numOfMeshedParts = 0;
            List<string> invertedPartNames = new List<string>();
            phaseWatch.Restart();
            foreach (GeneratedMeshData generatedMesh in generatedMeshes)
            {
                _model.TransferMissingGeometryDataToMesh(generatedMesh.GeometryPart, generatedMesh.Mesh);
                _model.ImportGeneratedMesh(generatedMesh.Mesh, false);
                //
                foreach (string partName in generatedMesh.RelatedPartNames)
                {
                    if (_model.Mesh.Parts.TryGetValue(partName, out BasePart meshPart))
                    {
                        numOfMeshedParts++;
                        _form.WriteDataToOutput(partName + ": " + meshPart.NodeLabels.Length + " nodes, " +
                                                meshPart.Labels.Length + " elements");
                        int numOfInvertedElements = InvertedElements.GetElementIds(_model.Mesh, meshPart).Length;
                        if (numOfInvertedElements > 0)
                        {
                            _form.WriteDataToOutput(MessageInvertedElements.GetMessage(partName, numOfInvertedElements));
                            invertedPartNames.Add(partName);
                        }
                        //
                        GeometryPart geometryPart = GetGeometryPartOfMeshPart(partName);
                        if (geometryPart != null)
                        {
                            _model.Mesh.ChangePartId(partName, GetPartIdOfMeshPart(partName, geometryPart));
                            renumbered = true;
                            if (geometryPart.Name != partName) meshPart.Color = geometryPart.Color;
                        }
                        //
                        if (oldMeshPartNames.Contains(partName) && meshPart is MeshPart modelPart &&
                            geometryPart != null)
                            modelPart.SetElementTypeEnums(geometryPart.GetElementTypeEnums());
                        //
                        if (generatedMesh.SmoothShaded) meshPart.SmoothShaded = true;
                    }
                }
            }
            phaseWatch.Stop();
            performance.Import = phaseWatch.Elapsed.TotalSeconds;
            //
            if (numOfMeshedParts > 1)
                _form.WriteDataToOutput("Model mesh: " + _model.Mesh.Nodes.Count + " nodes, " +
                                        _model.Mesh.Elements.Count + " elements");
            //
            phaseWatch.Restart();
            _model.Mesh.UpdateNodeIdElementIds();
            phaseWatch.Stop();
            performance.Adjacency = phaseWatch.Elapsed.TotalSeconds;
            //
            if (oldMeshPartLayout != null) _model.Mesh.Parts.RestoreItemLayout(oldMeshPartLayout);
            CreateNewMeshPartGroups(generatedMeshes, oldMeshPartNames);
            _model.UpdateMeshPartsElementTypes(false);
            //
            phaseWatch.Restart();
            UpdateAfterPartsChanged();
            phaseWatch.Stop();
            performance.Finalization += phaseWatch.Elapsed.TotalSeconds;
            //
            phaseWatch.Restart();
            _form.Clear3D();
            _currentView = ViewGeometryModelResults.Model;
            _form.SetCurrentView(_currentView);
            FeModelUpdate(UpdateType.DrawModel);
            phaseWatch.Stop();
            performance.Drawing = phaseWatch.Elapsed.TotalSeconds;
            //
            phaseWatch.Restart();
            if (renumbered) UpdateGeometryBasedItems(false, true);
            FeModelUpdate(UpdateType.Check | UpdateType.RedrawSymbols);
            _form.RegenerateTree(true);
            _lastInvertedElementPartNames = invertedPartNames.ToArray();
            phaseWatch.Stop();
            performance.Finalization += phaseWatch.Elapsed.TotalSeconds;
        }
        private void CreateNewMeshPartGroups(List<GeneratedMeshData> generatedMeshes,
                                             HashSet<string> oldMeshPartNames)
        {
            foreach (GeneratedMeshData generatedMesh in generatedMeshes)
            {
                string[] meshPartNames = generatedMesh.Mesh.Parts.Keys.ToArray();
                string[] newMeshPartNames =
                    meshPartNames.Where(name => !oldMeshPartNames.Contains(name)).ToArray();
                if (newMeshPartNames.Length == 0) continue;
                PlaceNewMeshedPartsInLinkedGroups(generatedMesh.GeometryPart, meshPartNames, newMeshPartNames);
            }
        }
        private void PlaceNewMeshedPartsInLinkedGroups(GeometryPart geometryPart, string[] meshPartNames,
                                                       string[] newMeshPartNames)
        {
            if (geometryPart == null || newMeshPartNames == null || newMeshPartNames.Length == 0 ||
                _model.Geometry?.Parts == null || _model.Mesh?.Parts == null)
                return;
            //
            OrderedDictionaryItemLayout<string> geometryLayout =
                _model.Geometry.Parts.GetItemLayoutSnapshot();
            List<OrderedDictionaryItemNode<string>> geometryGroupPath =
                new List<OrderedDictionaryItemNode<string>>();
            TryGetOrderedDictionaryItemGroupPath(geometryLayout.Nodes, geometryPart.Name,
                                                 _model.Geometry.Parts.Comparer, geometryGroupPath);
            //
            Guid? targetGroupId = null;
            foreach (OrderedDictionaryItemNode<string> geometryGroup in geometryGroupPath)
            {
                targetGroupId = EnsureModelPartGroup(geometryGroup.Id, geometryGroup.Name, targetGroupId);
            }
            //
            if (geometryPart is CompoundGeometryPart compoundPart && meshPartNames.Length > 1)
            {
                targetGroupId = EnsureModelPartGroup(compoundPart.LinkedGroupId, compoundPart.Name,
                                                     targetGroupId);
            }
            //
            MoveOrderedDictionaryItemsToGroup(_model.Mesh.Parts, newMeshPartNames, targetGroupId);
        }
        private static bool TryGetOrderedDictionaryItemGroupPath(
            IEnumerable<OrderedDictionaryItemNode<string>> nodes, string itemName,
            IEqualityComparer<string> comparer, List<OrderedDictionaryItemNode<string>> groupPath)
        {
            foreach (OrderedDictionaryItemNode<string> node in nodes)
            {
                if (node.IsItem)
                {
                    if (comparer.Equals(node.Key, itemName)) return true;
                }
                else
                {
                    groupPath.Add(node);
                    if (TryGetOrderedDictionaryItemGroupPath(node.Children, itemName, comparer, groupPath))
                        return true;
                    groupPath.RemoveAt(groupPath.Count - 1);
                }
            }
            return false;
        }
        private void PlaceDuplicatedOrderedDictionaryItem(
            IOrderedDictionaryItemLayout<string> dictionary, string sourceItemName, NamedClass duplicatedItem,
            ViewGeometryModelResults view, string parentName = null)
        {
            Guid? targetGroupId = GetLastOrderedDictionaryItemParentGroupId(
                dictionary, new string[] { sourceItemName });
            if (!targetGroupId.HasValue) return;
            //
            MoveOrderedDictionaryItemsToGroup(dictionary, new string[] { duplicatedItem.Name }, targetGroupId);
            _form.UpdateTreeNodeLayout(view, duplicatedItem.Name, duplicatedItem, parentName);
        }
        private bool PlacePropagatedOrderedDictionaryItem(
            IOrderedDictionaryItemLayout<string> sourceDictionary,
            IOrderedDictionaryItemLayout<string> targetDictionary,
            string itemName, NamedClass propagatedItem, string targetStepName)
        {
            List<OrderedDictionaryItemNode<string>> sourceGroupPath =
                new List<OrderedDictionaryItemNode<string>>();
            if (!TryGetOrderedDictionaryItemGroupPath(sourceDictionary.GetItemLayoutSnapshot().Nodes, itemName,
                                                       sourceDictionary.Comparer, sourceGroupPath))
                throw new KeyNotFoundException("The source item was not found in the ordered dictionary layout.");
            //
            Guid? targetGroupId = EnsureOrderedDictionaryGroupPath(targetDictionary, sourceGroupPath,
                                                                   out bool groupsCreated);
            MoveOrderedDictionaryItemsToParent(targetDictionary, new string[] { itemName }, targetGroupId);
            if (!groupsCreated)
                _form.UpdateTreeNodeLayout(ViewGeometryModelResults.Model, itemName, propagatedItem, targetStepName);
            return groupsCreated;
        }
        private static Guid? EnsureOrderedDictionaryGroupPath(
            IOrderedDictionaryItemLayout<string> targetDictionary,
            IEnumerable<OrderedDictionaryItemNode<string>> sourceGroupPath, out bool groupsCreated)
        {
            groupsCreated = false;
            Guid? targetParentGroupId = null;
            foreach (OrderedDictionaryItemNode<string> sourceGroup in sourceGroupPath)
            {
                OrderedDictionaryItemLayout<string> targetLayout = targetDictionary.GetItemLayoutSnapshot();
                IList<OrderedDictionaryItemNode<string>> targetSiblings = targetLayout.Nodes;
                if (targetParentGroupId.HasValue)
                {
                    OrderedDictionaryItemNode<string> targetParentGroup =
                        GetOrderedDictionaryGroupNode(targetLayout.Nodes, targetParentGroupId.Value);
                    if (targetParentGroup == null)
                        throw new KeyNotFoundException("The propagated parent group was not found.");
                    targetSiblings = targetParentGroup.Children;
                }
                // Groups in different step collections remain independent and are matched by their path names.
                OrderedDictionaryItemNode<string> targetGroup = targetSiblings.FirstOrDefault(
                    node => node.IsGroup &&
                            String.Equals(node.Name, sourceGroup.Name, StringComparison.OrdinalIgnoreCase));
                if (targetGroup == null)
                {
                    targetParentGroupId = targetDictionary.CreateGroup(
                        sourceGroup.Name, targetParentGroupId, targetSiblings.Count);
                    groupsCreated = true;
                }
                else targetParentGroupId = targetGroup.Id;
            }
            return targetParentGroupId;
        }
        private Guid EnsureModelPartGroup(Guid groupId, string groupName, Guid? parentGroupId)
        {
            OrderedDictionaryItemLayout<string> layout = _model.Mesh.Parts.GetItemLayoutSnapshot();
            if (GetOrderedDictionaryGroupNode(layout.Nodes, groupId) != null) return groupId;
            //
            IList<OrderedDictionaryItemNode<string>> siblings;
            if (parentGroupId.HasValue)
            {
                OrderedDictionaryItemNode<string> parentGroup =
                    GetOrderedDictionaryGroupNode(layout.Nodes, parentGroupId.Value);
                if (parentGroup == null)
                    throw new KeyNotFoundException("The linked parent group was not found.");
                siblings = parentGroup.Children;
            }
            else siblings = layout.Nodes;
            //
            OrderedDictionaryItemNode<string> existingGroup = siblings.FirstOrDefault(
                node => node.IsGroup && String.Equals(node.Name, groupName, StringComparison.OrdinalIgnoreCase));
            if (existingGroup != null) return existingGroup.Id;
            //
            _model.Mesh.Parts.CreateGroup(groupId, groupName, parentGroupId, siblings.Count);
            return groupId;
        }
        internal static Guid? GetLastOrderedDictionaryItemParentGroupId(
            IOrderedDictionaryItemLayout<string> dictionary, IEnumerable<string> itemNames)
        {
            if (dictionary == null || itemNames == null) return null;
            HashSet<string> names = new HashSet<string>(itemNames, dictionary.Comparer);
            if (names.Count == 0) return null;
            //
            Guid? lastParentGroupId = null;
            FindLastOrderedDictionaryItemParentGroupId(dictionary.GetItemLayoutSnapshot().Nodes, null, names,
                                                       ref lastParentGroupId);
            return lastParentGroupId;
        }
        private static void FindLastOrderedDictionaryItemParentGroupId(
            IEnumerable<OrderedDictionaryItemNode<string>> nodes, Guid? parentGroupId,
            HashSet<string> itemNames, ref Guid? lastParentGroupId)
        {
            foreach (OrderedDictionaryItemNode<string> node in nodes)
            {
                if (node.IsItem)
                {
                    if (itemNames.Contains(node.Key)) lastParentGroupId = parentGroupId;
                }
                else FindLastOrderedDictionaryItemParentGroupId(node.Children, node.Id, itemNames,
                                                                ref lastParentGroupId);
            }
        }
        private static void MoveOrderedDictionaryItemsToGroup(
            IOrderedDictionaryItemLayout<string> dictionary, IEnumerable<string> itemNames, Guid? targetGroupId)
        {
            if (!targetGroupId.HasValue) return;
            MoveOrderedDictionaryItemsToParent(dictionary, itemNames, targetGroupId);
        }
        private static void MoveOrderedDictionaryItemsToParent(
            IOrderedDictionaryItemLayout<string> dictionary, IEnumerable<string> itemNames, Guid? targetGroupId)
        {
            if (dictionary == null || itemNames == null) return;
            HashSet<string> requestedNames = new HashSet<string>(itemNames, dictionary.Comparer);
            string[] existingNames = dictionary.Keys.Where(name => requestedNames.Contains(name)).ToArray();
            if (existingNames.Length == 0) return;
            //
            OrderedDictionaryItemLayout<string> layout = dictionary.GetItemLayoutSnapshot();
            IList<OrderedDictionaryItemNode<string>> targetChildren = layout.Nodes;
            if (targetGroupId.HasValue)
            {
                OrderedDictionaryItemNode<string> targetGroup =
                    GetOrderedDictionaryGroupNode(layout.Nodes, targetGroupId.Value);
                if (targetGroup == null) throw new KeyNotFoundException("The target parent group was not found.");
                targetChildren = targetGroup.Children;
            }
            int movedFromTargetCount = targetChildren
                .Count(node => node.IsItem && requestedNames.Contains(node.Key));
            int targetIndex = targetChildren.Count - movedFromTargetCount;
            dictionary.MoveItems(existingNames, targetGroupId, targetIndex);
        }
        internal static HashSet<string> CaptureOrderedDictionaryItemNamesForGroupPlacement(
            IOrderedDictionaryItemLayout<string> dictionary, Guid? targetGroupId)
        {
            return targetGroupId.HasValue
                ? new HashSet<string>(dictionary.Keys, dictionary.Comparer)
                : null;
        }
        internal static void MoveAddedOrderedDictionaryItemsToGroup(
            IOrderedDictionaryItemLayout<string> dictionary, HashSet<string> oldItemNames,
            Guid? targetGroupId)
        {
            if (oldItemNames == null) return;
            string[] addedItemNames = dictionary.Keys.Where(name => !oldItemNames.Contains(name)).ToArray();
            MoveOrderedDictionaryItemsToGroup(dictionary, addedItemNames, targetGroupId);
        }
        private void WriteMeshBatchPerformance(MeshBatchPerformance performance)
        {
            _form.WriteDataToOutput("");
            _form.WriteDataToOutput("Batch meshing performance [s]");
            _form.WriteDataToOutput("  Generation: " + performance.Generation.ToString("0.000"));
            _form.WriteDataToOutput("  Validation/parsing: " + performance.Validation.ToString("0.000"));
            _form.WriteDataToOutput("  Bulk removal: " + performance.Removal.ToString("0.000"));
            _form.WriteDataToOutput("  Import: " + performance.Import.ToString("0.000"));
            _form.WriteDataToOutput("  Adjacency rebuild: " + performance.Adjacency.ToString("0.000"));
            _form.WriteDataToOutput("  Drawing: " + performance.Drawing.ToString("0.000"));
            _form.WriteDataToOutput("  Finalization: " + performance.Finalization.ToString("0.000"));
            _form.WriteDataToOutput("  Total: " + performance.Total.ToString("0.000"));
        }
