        private MeshSetupItem[] GetActiveValidMesherSetupItems(string partName,
                                                               OrderedDictionary<string, MeshSetupItem> meshSetupItems = null)
        {
            MeshSetupItem[] mesherSetupItems = GetUserMesherSetupItems(partName, meshSetupItems);
            if (mesherSetupItems.Length > 0) return mesherSetupItems;
            //
            MeshSetupItem defaultMesherSetupItem = GetDefaultMesherSetupItem(partName);
            if (defaultMesherSetupItem == null) return mesherSetupItems;
            //
            return new MeshSetupItem[] { defaultMesherSetupItem };
        }
        private MeshSetupItem[] GetUserMesherSetupItems(string partName,
                                                       OrderedDictionary<string, MeshSetupItem> meshSetupItems = null)
        {
            HashSet<int> selectedPartIds;
            string[] meshablePartNames = GetMeshablePartNames(new string[] { partName });
            int[] meshablePartIds = _model.Geometry.GetPartIdsFomPartNames(meshablePartNames);
            List<MeshSetupItem> meshSetupItemsToCheck = new List<MeshSetupItem>();
            //
            if (meshSetupItems == null) meshSetupItems = _model.Geometry.MeshSetupItems;
            //
            foreach (var entry in meshSetupItems)
            {
                if (entry.Value.MesherType != MesherTypeEnum.None && entry.Value.Active && entry.Value.Valid)
                {
                    if (entry.Value.CreationIds != null && entry.Value.CreationIds.Length > 0)
                    {
                        selectedPartIds = new HashSet<int>(FeMesh.GetPartIdsFromGeometryIds(entry.Value.CreationIds));
                        //
                        if (_model.DoesMeshSetupItemCoverPart(entry.Value, selectedPartIds, meshablePartIds))
                            meshSetupItemsToCheck.Add(entry.Value);
                    }
                }
            }
            //
            return meshSetupItemsToCheck.ToArray();
        }
        /// <summary>
        /// The setup item that meshes a part the user defined none for. The geometry is given the most
        /// structured mesh it supports, which is the mesh type the recognition keeps on the parts; a part the
        /// recognition leaves at tetrahedra is meshed by Netgen as it always was and needs no item at all.
        /// The item is built for the meshing that asks for it and is neither recorded nor kept in the model
        /// tree, so the geometry alone decides it and a regenerated model reaches the same one.
        /// </summary>
        private MeshSetupItem GetDefaultMesherSetupItem(string partName)
        {
            if (_model == null || _model.Geometry == null) return null;
            // An older model is meshed the way the version that wrote it meshed it
            if (_defaultMeshTypesDisabled) return null;
            //
            MeshTypeEnum meshType = GetMeshTypeOfMeshedPart(partName);
            // The recognition costs nothing once it has been made, so it is asked for rather than assumed
            if (meshType == MeshTypeEnum.Unknown)
            {
                DetectMeshTypes();
                meshType = GetMeshTypeOfMeshedPart(partName);
            }
            //
            MeshSetupItem mesherSetupItem;
            if (meshType == MeshTypeEnum.Transfinite) mesherSetupItem = new TransfiniteMesh("Default_Transfinite_Mesh");
            else if (meshType == MeshTypeEnum.Sweep)
            {
                SweepMesh sweepMesh = new SweepMesh("Default_Sweep_Mesh");
                sweepMesh.SourceType = SweepSourceTypeEnum.Automatic;
                mesherSetupItem = sweepMesh;
            }
            else return null;
            //
            string[] meshablePartNames = GetMeshablePartNames(new string[] { partName });
            mesherSetupItem.CreationIds = _model.Geometry.GetPartIdsFomPartNames(meshablePartNames);
            // The sweep finds its blocks here, so the item is not only checked but also completed. The cells it
            // cannot reach are meshed by tetrahedra, so what is left is a part whose cells can be swept but not
            // in a way that fits together; it is not meshed by tetrahedra instead: its cells have to be split
            // further or its sources selected by hand
            string error = _model.IsMeshSetupItemProperlyDefined(mesherSetupItem);
            if (error != null)
            {
                throw new CaeException("The cells of the part " + partName + " can be meshed by a " +
                                       (meshType == MeshTypeEnum.Transfinite ? "transfinite mesh" : "sweep") +
                                       " on their own, but not together: " + error +
                                       " Split the cells further or define a mesh setup item for the part.");
            }
            //
            return mesherSetupItem;
        }
        /// <summary>
        /// The most structured mesh the parts that are meshed together support, which is the least structured
        /// of theirs: the sub-parts of a compound part are meshed as one, and a mesh the compound cannot carry
        /// as a whole is used for none of them. The exception is a compound of solids in which some cells can be
        /// swept and others cannot, which is swept: the sweep leaves the cells it cannot reach to tetrahedra.
        /// </summary>
        private MeshTypeEnum GetMeshTypeOfMeshedPart(string partName)
        {
            string[] meshablePartNames = GetMeshablePartNames(new string[] { partName });
            if (meshablePartNames == null || meshablePartNames.Length == 0) return MeshTypeEnum.Unknown;
            //
            BasePart part;
            GeometryPart geometryPart;
            bool anyStructured = false;
            MeshTypeEnum meshType = MeshTypeEnum.Unknown;
            foreach (var meshablePartName in meshablePartNames)
            {
                if (!_model.Geometry.Parts.TryGetValue(meshablePartName, out part)) return MeshTypeEnum.Unknown;
                geometryPart = part as GeometryPart;
                if (geometryPart == null || geometryPart.MeshType == MeshTypeEnum.Unknown) return MeshTypeEnum.Unknown;
                if (geometryPart.MeshType > meshType) meshType = geometryPart.MeshType;
                if (geometryPart.MeshType == MeshTypeEnum.Transfinite || geometryPart.MeshType == MeshTypeEnum.Sweep)
                    anyStructured = true;
            }
            if (meshType == MeshTypeEnum.Tetrahedral && anyStructured) meshType = MeshTypeEnum.Sweep;
            return meshType;
        }
        private MeshSetupItem[] GetActiveValidMeshSetupItems<T>(string partName,
                                                                  OrderedDictionary<string, MeshSetupItem> meshSetupItems = null)
                                                                  where T : MeshSetupItem
        {
            HashSet<int> selectedPartIds;
            string[] meshablePartNames = GetMeshablePartNames(new string[] { partName });
            int[] meshablePartIds = _model.Geometry.GetPartIdsFomPartNames(meshablePartNames);
            List<MeshSetupItem> meshSetupItemsToCheck = new List<MeshSetupItem>();
            //
            if (meshSetupItems == null) meshSetupItems = _model.Geometry.MeshSetupItems;
            //
            foreach (var entry in meshSetupItems)
            {
                if (entry.Value is T msi && msi.Active && msi.Valid)
                {
                    if (msi.CreationIds != null && msi.CreationIds.Length > 0)
                    {
                        selectedPartIds = new HashSet<int>(FeMesh.GetPartIdsFromGeometryIds(msi.CreationIds));
                        //
                        if (_model.DoesMeshSetupItemCoverPart(msi, selectedPartIds, meshablePartIds))
                            meshSetupItemsToCheck.Add(msi);
                    }
                }
            }
            //
            return meshSetupItemsToCheck.ToArray();
        }
        // Returns the name of the compound part carrying each sub-part
        private Dictionary<string, string> GetCompoundPartNamesBySubPartName()
        {
            Dictionary<string, string> compoundPartNames = new Dictionary<string, string>();
            FeMesh geometry = _model?.Geometry;
            if (geometry == null) return compoundPartNames;
            //
            foreach (var entry in geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart cgp)
                {
                    foreach (var subPartName in cgp.SubPartNames) compoundPartNames.Add(subPartName, cgp.Name);
                }
            }
            return compoundPartNames;
        }
        // Returns the names of the parts the given mesh setup items are defined on, as they are meshed: a
        // selection lying on a sub-part of a compound part is reported through the compound part, since that
        // is the part the meshing is performed on.
        public string[] GetPartNamesToMeshFromMeshSetupItems(string[] meshSetupItemNames)
        {
            if (meshSetupItemNames == null || meshSetupItemNames.Length == 0) return null;
            FeMesh geometry = _model?.Geometry;
            if (geometry == null) return null;
            //
            List<MeshSetupItem> meshSetupItems = new List<MeshSetupItem>();
            foreach (string meshSetupItemName in meshSetupItemNames)
            {
                if (geometry.MeshSetupItems.TryGetValue(meshSetupItemName, out MeshSetupItem meshSetupItem))
                    meshSetupItems.Add(meshSetupItem);
            }
            return GetPartNamesToMeshFromMeshSetupItems(meshSetupItems.ToArray());
        }
        public string[] GetPartNamesToMeshFromMeshSetupItems(MeshSetupItem[] meshSetupItems)
        {
            if (meshSetupItems == null) return null;
            FeMesh geometry = _model?.Geometry;
            if (geometry == null) return null;
            //
            Dictionary<string, string> subPartNameCompoundPartName = GetCompoundPartNamesBySubPartName();
            //
            List<string> partNamesToMesh = new List<string>();
            HashSet<string> addedPartNames = new HashSet<string>();
            //
            foreach (MeshSetupItem meshSetupItem in meshSetupItems)
            {
                if (meshSetupItem.CreationIds == null || meshSetupItem.CreationIds.Length == 0) continue;
                //
                int[] partIds = FeMesh.GetPartIdsFromGeometryIds(meshSetupItem.CreationIds);
                string[] partNames = geometry.GetPartNamesFromPartIds(partIds);
                if (partNames == null) continue;
                //
                foreach (string partName in partNames)
                {
                    if (!subPartNameCompoundPartName.TryGetValue(partName, out string partNameToMesh))
                        partNameToMesh = partName;
                    //
                    if (addedPartNames.Add(partNameToMesh)) partNamesToMesh.Add(partNameToMesh);
                }
            }
            //
            return partNamesToMesh.ToArray();
        }
        // Returns the names of the geometry items related to the given focused items: for a part, the mesh
        // setup items that reference it; for a mesh setup item, the parts it references. Used by the model
        // tree to show these connections with the related (light green) highlight.
        public string[] GetRelatedGeometryItemNames(NamedClass[] items)
        {
            if (items == null || items.Length == 0) return null;
            FeMesh geometry = _model?.Geometry;
            if (geometry == null) return null;
            //
            OrderedDictionary<string, MeshSetupItem> meshSetupItems = geometry.MeshSetupItems;
            HashSet<string> relatedNames = new HashSet<string>();
            //
            foreach (NamedClass item in items)
            {
                if (item is MeshSetupItem msi)
                {
                    // Mesh setup item -> the parts it references. A selection lying on a sub-part references
                    // the compound part that carries it as well
                    if (msi.CreationIds != null && msi.CreationIds.Length > 0)
                    {
                        int[] partIds = FeMesh.GetPartIdsFromGeometryIds(msi.CreationIds);
                        string[] partNames = geometry.GetPartNamesFromPartIds(partIds);
                        if (partNames != null)
                        {
                            Dictionary<string, string> compoundPartNames = GetCompoundPartNamesBySubPartName();
                            foreach (string partName in partNames)
                            {
                                relatedNames.Add(partName);
                                if (compoundPartNames.TryGetValue(partName, out string compoundPartName))
                                    relatedNames.Add(compoundPartName);
                            }
                        }
                    }
                }
                else if (geometry.Parts.TryGetValue(item.Name, out BasePart part))
                {
                    // Part -> the mesh setup items that reference it. A mesh setup item created on a
                    // compound part carries the ids of its sub-parts, so the compound part is referenced
                    // through them
                    HashSet<int> partIds = new HashSet<int>();
                    partIds.Add(part.PartId);
                    if (part is CompoundGeometryPart compoundPart)
                        partIds.UnionWith(geometry.GetPartIdsFomPartNames(compoundPart.SubPartNames));
                    //
                    foreach (var entry in meshSetupItems)
                    {
                        MeshSetupItem meshSetupItem = entry.Value;
                        if (meshSetupItem.CreationIds == null || meshSetupItem.CreationIds.Length == 0) continue;
                        if (partIds.Overlaps(FeMesh.GetPartIdsFromGeometryIds(meshSetupItem.CreationIds)))
                            relatedNames.Add(meshSetupItem.Name);
                    }
                }
            }
            //
            return relatedNames.ToArray();
        }
        public void ActivateDeactivateMeshSetupItem(string meshSetupItemName, bool active)
        {
            MeshSetupItem meshSetupItem = _model.Geometry.MeshSetupItems[meshSetupItemName];
            meshSetupItem.Active = active;
            //
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, meshSetupItemName, meshSetupItem, null);
            //
            FeModelUpdate(UpdateType.Check | UpdateType.RedrawSymbols);
            UpdateMeshTypeColors();
        }
        public void ReplaceMeshSetupItem(string oldMeshSetupItemName, MeshSetupItem meshSetupItem,
                                         bool updateSelection = true)
        {
            if (meshSetupItem.CreationData != null)
            {
                Selection selection = _selection.DeepCopy(true, true);
                // In order for the Regenerate history to work perform the selection
                _selection = meshSetupItem.CreationData.DeepCopy(true, false);
                meshSetupItem.CreationIds = GetSelectionIds();
                _selection = selection;
            }
            else throw new NotSupportedException("The mesh setup item does not contain any selection data.");
            // A replacement is a new definition and is judged as one. Without this the item would keep the
            // verdict of the item it replaces, and a new selection could never make an invalid item valid
            meshSetupItem.Valid = true;
            //
            _model.Geometry.MeshSetupItems.Replace(oldMeshSetupItemName, meshSetupItem.Name, meshSetupItem);
            //
            _form.UpdateTreeNode(ViewGeometryModelResults.Geometry, oldMeshSetupItemName, meshSetupItem,
                                 null, updateSelection);
            //
            FeModelUpdate(UpdateType.Check | UpdateType.RedrawSymbols);
            UpdateMeshTypeColors(updateSelection);
        }
        public void RenameMeshSetupItem(string oldMeshSetupItemName, string newMeshSetupItemName)
        {
            MeshSetupItem meshSetupItem = _model.Geometry.MeshSetupItems[oldMeshSetupItemName];
            meshSetupItem.Name = newMeshSetupItemName;
            ReplaceMeshSetupItem(oldMeshSetupItemName, meshSetupItem);
        }
        public void DuplicateMeshSetupItems(string[] meshSetupItemNames)
        {
            BeginUpdateBatch();
            try
            {
                MeshSetupItem newMeshSetupItem;
                foreach (var name in meshSetupItemNames)
                {
                    newMeshSetupItem = _model.Geometry.MeshSetupItems[name].DeepClone();
                    newMeshSetupItem.Name = NamedClass.GetNameWithoutLastValue(newMeshSetupItem.Name);
                    newMeshSetupItem.Name = _model.Geometry.MeshSetupItems.GetNextNumberedKey(newMeshSetupItem.Name);
                    AddMeshSetupItem(newMeshSetupItem);
                    PlaceDuplicatedOrderedDictionaryItem(_model.Geometry.MeshSetupItems, name, newMeshSetupItem,
                                                         ViewGeometryModelResults.Geometry);
                }
            }
            finally
            {
                EndUpdateBatch();
            }
        }
        public void RemoveMeshSetupItems(string[] meshSetupItemNames)
        {
            foreach (var name in meshSetupItemNames)
            {
                _model.Geometry.MeshSetupItems.Remove(name);
                _form.RemoveTreeNode<MeshSetupItem>(ViewGeometryModelResults.Geometry, name, null);
            }
            //
            FeModelUpdate(UpdateType.Check | UpdateType.RedrawSymbols);
            UpdateMeshTypeColors();
            //
            ClearAllSelection();
        }
        //
        private void UpdateMeshSetupItems(bool updateSelection = true)
        {
            if (_model != null && _model.Geometry != null)
            {
                // Use array not to throw collection modified exception
                foreach (var meshSetupItem in _model.Geometry.MeshSetupItems.Values.ToArray())
                {
                    if (meshSetupItem.CreationData.IsGeometryBased())
                    {
                        meshSetupItem.Valid = true;
                        ReplaceMeshSetupItem(meshSetupItem.Name, meshSetupItem, updateSelection);
                    }
                }
            }
        }
