        public void ApplySettings()
        {
            // Called on property Settings Set when the user changes the setting values

            // General settings
            CaeMesh.Globals.EdgeAngle = _settings.General.EdgeAngle;
            DynamicTypeDescriptor.DynamicCustomTypeDescriptor.ShowAllProperties = _settings.General.ShowAllProperties;
            // Graphics settings
            GraphicsSettings gs = _settings.Graphics;
            _form.SetBackground(gs.BackgroundType == BackgroundType.Gradient, gs.TopColor, gs.BottomColor, false);
            _form.SetCoorSysVisibility(gs.CoorSysVisibility);
            _form.SetScaleWidgetVisibility(gs.ScaleWidgetVisibility);
            _form.SetWidgetHighlightEnabled(gs.WidgetHighlightEnabled);
            _form.SetSelectionDistance(_selectionDistanceInPixels);
            _form.SetLighting(gs.AmbientComponent, gs.DiffuseComponent, false);
            _form.SetSmoothing(gs.PointSmoothing, gs.LineSmoothing, false);
            // Navigation settings
            NavigationSettings ns = _settings.Navigation;
            _form.SetNavigationSensitivity(ns.RotateSensitivity, ns.ZoomSensitivity, ns.InvertZoom, ns.SmoothZoom);
            _form.SetTrackpadNavigation(ns.GesturesEnabled, ns.UseWheelFallback,
                                        ns.TwoFingerDrag == TwoFingerDragEnum.Pan, ns.PanSensitivity,
                                        ns.InvertX, ns.InvertY);
            // Color settings
            CaeMesh.Globals.ColorTable = _settings.Color.ColorTable;
            // Pre-processing settings
            PreSettings ps = _settings.Pre;
            _form.SetHighlightColor(ps.PrimaryHighlightColor, ps.SecondaryHighlightColor);
            _form.SetMouseHighlightColor(ps.MouseHighlightColor);
            _form.SetDrawSymbolEdges(ps.DrawSymbolEdges);
            //
            _form.DrawColorBarBackground(ps.ColorBarBackgroundType == AnnotationBackgroundType.White);
            _form.DrawColorBarBorder(ps.ColorBarDrawBorder);
            // Job settings
            if (_jobs != null)
            {
                SolverSettings ss = _settings.Solver;
                //
                foreach (var entry in _jobs)
                {
                    if (entry.Value.FEMSolver == FEMSolverEnum.Calculix)
                    {
                        if (!entry.Value.WorkDirectoryOverridden)
                            entry.Value.WorkDirectory = Settings.GetWorkDirectory();
                        if (!entry.Value.ExecutableOverridden)
                            entry.Value.Executable = ss.CalculixExe;
                        if (!entry.Value.NumCPUsOverridden)
                            entry.Value.NumCPUs = ss.NumCPUs;
                        if (!entry.Value.EnvironmentVariablesOverridden)
                            entry.Value.EnvironmentVariables = ss.EnvironmentVariables;
                    }
                    else if (entry.Value.FEMSolver == FEMSolverEnum.Abaqus)
                    {
                        if (!entry.Value.WorkDirectoryOverridden)
                            entry.Value.WorkDirectory = Settings.GetWorkDirectory();
                        if (!entry.Value.ExecutableOverridden)
                            entry.Value.Executable = ss.AbaqusExe;
                        if (!entry.Value.NumCPUsOverridden)
                            entry.Value.NumCPUs = ss.NumCPUs;
                    }
                    else if (entry.Value.FEMSolver == FEMSolverEnum.FEMaster)
                    {
                        if (!entry.Value.WorkDirectoryOverridden)
                            entry.Value.WorkDirectory = Settings.GetWorkDirectory();
                        if (!entry.Value.ExecutableOverridden)
                            entry.Value.Executable = ss.FEMasterExe;
                        if (!entry.Value.NumCPUsOverridden)
                            entry.Value.NumCPUs = ss.NumCPUs;
                    }
                    else throw new NotSupportedException();
                }
            }
        }
        /// <summary>
        /// The part id whose place in the color table colors a geometry part. The cells of a sub part of a
        /// split compound are one part to the user, and are meshed into one mesh part that carries the part
        /// id of the sub part, so they all take the color of that id.
        /// </summary>
        private int GetColorTablePartId(BasePart part)
        {
            foreach (var entry in _model.Geometry.Parts)
            {
                if (!(entry.Value is CompoundGeometryPart compoundPart) || !compoundPart.CreatedBySplit) continue;
                //
                int index = Array.IndexOf(compoundPart.SubPartNames, part.Name);
                if (index < 0 || compoundPart.CellSubPartNames[index] == null) continue;
                //
                int subPartId = GetSplitSubPartId(compoundPart, compoundPart.CellSubPartNames[index]);
                if (subPartId > 0) return subPartId;
            }
            return part.PartId;
        }
        private void SetGeometryPartColorFromColorTable(BasePart part)
        {
            Color[] colorTable = CaeMesh.Globals.ColorTable;
            part.Color = colorTable[(GetColorTablePartId(part) - 1) % colorTable.Length];
        }
        private void UpdatePartColorsFromColorTable(Color[] previousColorTable)
        {
            if (previousColorTable == null || previousColorTable == CaeMesh.Globals.ColorTable) return;
            //
            if (_model != null)
            {
                UpdatePartColorsFromColorTable(_model.Geometry, previousColorTable,
                                               ViewGeometryModelResults.Geometry);
                UpdatePartColorsFromColorTable(_model.Mesh, previousColorTable, ViewGeometryModelResults.Model);
                //
                if (_model.Geometry != null) UpdateCompoundTransparency();
            }
            if (_allResults != null && _allResults.CurrentResult != null)
                UpdatePartColorsFromColorTable(_allResults.CurrentResult.Mesh, previousColorTable,
                                               ViewGeometryModelResults.Results);
        }
        private void UpdatePartColorsFromColorTable(FeMesh mesh, Color[] previousColorTable,
                                                    ViewGeometryModelResults view)
        {
            if (mesh == null) return;
            //
            byte alpha;
            int colorPartId;
            Color previousColor;
            //
            foreach (var entry in mesh.Parts)
            {
                if (entry.Value is CompoundGeometryPart) continue;
                //
                colorPartId = view == ViewGeometryModelResults.Geometry ? GetColorTablePartId(entry.Value)
                                                                        : entry.Value.PartId;
                previousColor = previousColorTable[(colorPartId - 1) % previousColorTable.Length];
                if (entry.Value.Color.R != previousColor.R || entry.Value.Color.G != previousColor.G ||
                    entry.Value.Color.B != previousColor.B) continue;
                //
                alpha = entry.Value.Color.A;
                if (view == ViewGeometryModelResults.Geometry) SetGeometryPartColorFromColorTable(entry.Value);
                else mesh.SetPartColorFromColorTable(entry.Value);
                entry.Value.Color = Color.FromArgb(alpha, entry.Value.Color);
                //
                _form.UpdateTreeNode(view, entry.Key, entry.Value, null, false);
            }
        }

