        private void ResetUnfinishedJobStatuses()
        {
            foreach (var entry in _jobs)
            {
                if (entry.Value.JobStatus == JobStatus.Running || entry.Value.JobStatus == JobStatus.InQueue)
                    entry.Value.ResetJobStatus();
            }
        }
