        }
        public void ChangeOrderedDictionaryItemLayoutCommand(OrderedDictionaryTreeLayoutChange change)
        {
            if (change == null) throw new ArgumentNullException("change");
            //
            ViewGeometryModelResults view = GetViewGeometryModelResults(change.View);
            IOrderedDictionaryItemLayout<string> dictionary =
                GetOrderedDictionaryItemLayout(change.ItemType, view, change.ParentName);
            OrderedDictionaryItemLayout<string> oldLayout = dictionary.GetItemLayoutSnapshot();
            bool partLayout = (view == ViewGeometryModelResults.Geometry ||
                               view == ViewGeometryModelResults.Model) &&
                              typeof(BasePart).IsAssignableFrom(change.ItemType);
            if (partLayout &&
                (change.Action == OrderedDictionaryTreeLayoutAction.CreateGroup ||
                 change.Action == OrderedDictionaryTreeLayoutAction.RenameGroup))
                CheckPartGroupName(change.GroupId, change.GroupName);
            //
            OrderedDictionary<string, object> preview = CreateOrderedDictionaryItemLayoutPreview(
                dictionary, oldLayout, "Ordered dictionary item layout preview");
            //
            string commandName;
            string details;
            switch (change.Action)
            {
                case OrderedDictionaryTreeLayoutAction.CreateGroup:
                    if (!change.GroupId.HasValue)
                        throw new InvalidOperationException("The new tree group has no stable id.");
                    Guid newGroupId = preview.CreateGroup(change.GroupId.Value, change.GroupName,
                                                          change.TargetGroupId, change.TargetIndex);
                    if (change.ItemNames != null && change.ItemNames.Length > 0)
                        preview.MoveItems(change.ItemNames, newGroupId, 0);
                    commandName = "Create tree group";
                    details = change.GroupName;
                    if (change.ItemNames != null && change.ItemNames.Length > 0)
                        details += ": " + change.ItemNames.ToShortString();
                    break;
                case OrderedDictionaryTreeLayoutAction.RenameGroup:
                    string oldGroupName = GetOrderedDictionaryGroupName(oldLayout.Nodes, change.GroupId.Value);
                    preview.RenameGroup(change.GroupId.Value, change.GroupName);
                    commandName = "Rename tree group";
                    details = oldGroupName + " to " + change.GroupName;
                    break;
                case OrderedDictionaryTreeLayoutAction.RemoveGroup:
                    if (change.GroupIds == null || change.GroupIds.Length == 0)
                        throw new InvalidOperationException("No tree groups were selected for removal.");
                    string[] removedGroupNames = change.GroupIds
                        .Select(groupId => GetOrderedDictionaryGroupName(oldLayout.Nodes, groupId))
                        .ToArray();
                    foreach (Guid groupId in change.GroupIds) preview.RemoveGroup(groupId);
                    commandName = change.GroupIds.Length == 1 ? "Remove tree group" : "Remove tree groups";
                    details = removedGroupNames.ToShortString();
                    break;
                case OrderedDictionaryTreeLayoutAction.MoveItems:
                    preview.MoveItems(change.ItemNames, change.TargetGroupId, change.TargetIndex);
                    commandName = "Move tree items";
                    details = change.ItemNames.ToShortString();
                    break;
                case OrderedDictionaryTreeLayoutAction.MoveGroup:
                    preview.MoveGroup(change.GroupId.Value, change.TargetGroupId, change.TargetIndex);
                    commandName = "Move tree group";
                    details = GetOrderedDictionaryGroupName(oldLayout.Nodes, change.GroupId.Value);
                    break;
                default:
                    throw new NotSupportedException();
            }
            //
            OrderedDictionaryItemLayout<string> newLayout = preview.GetItemLayoutSnapshot();
            if (OrderedDictionaryItemLayoutsEqual(oldLayout.Nodes, newLayout.Nodes, dictionary.Comparer)) return;
            //
            Command command = null;
            if (partLayout && change.Action == OrderedDictionaryTreeLayoutAction.RenameGroup &&
                _model.Geometry?.Parts != null && _model.Mesh?.Parts != null)
            {
                IOrderedDictionaryItemLayout<string> linkedDictionary =
                    view == ViewGeometryModelResults.Geometry
                    ? (IOrderedDictionaryItemLayout<string>)_model.Mesh.Parts
                    : _model.Geometry.Parts;
                OrderedDictionaryItemLayout<string> linkedLayout = linkedDictionary.GetItemLayoutSnapshot();
                if (GetOrderedDictionaryGroupName(linkedLayout.Nodes, change.GroupId.Value) != null)
                {
                    OrderedDictionaryItemLayout<string> renamedLinkedLayout =
                        CreateRenamedGroupLayout(linkedDictionary, change.GroupId.Value, change.GroupName);
                    OrderedDictionaryItemLayout<string> geometryLayout =
                        view == ViewGeometryModelResults.Geometry ? newLayout : renamedLinkedLayout;
                    OrderedDictionaryItemLayout<string> modelLayout =
                        view == ViewGeometryModelResults.Model ? newLayout : renamedLinkedLayout;
                    command = new CSetLinkedPartGroupLayouts(commandName, geometryLayout, modelLayout, details);
                }
            }
            //
            if (command == null)
            {
                if (view == ViewGeometryModelResults.Results)
                    command = new CSetResultOrderedDictionaryItemLayout(commandName, change.ItemType, view,
                                                                        change.ParentName, newLayout, details);
                else
                    command = new CSetOrderedDictionaryItemLayout(commandName, change.ItemType, view,
                                                                  change.ParentName, newLayout, details);
            }
            _commands.AddAndExecute(command);
        }
        private static OrderedDictionaryItemLayout<string> CreateRenamedGroupLayout(
            IOrderedDictionaryItemLayout<string> dictionary, Guid groupId, string newName)
        {
            OrderedDictionary<string, object> preview = CreateOrderedDictionaryItemLayoutPreview(
                dictionary, dictionary.GetItemLayoutSnapshot(), "Linked part group layout preview");
            preview.RenameGroup(groupId, newName);
            return preview.GetItemLayoutSnapshot();
        }
        private static OrderedDictionary<string, object> CreateOrderedDictionaryItemLayoutPreview(
            IOrderedDictionaryItemLayout<string> dictionary, OrderedDictionaryItemLayout<string> layout,
            string name)
        {
            OrderedDictionary<string, object> preview =
                new OrderedDictionary<string, object>(name, dictionary.Comparer);
            foreach (string key in dictionary.Keys) preview.Add(key, null);
            preview.SetItemLayout(layout);
            return preview;
        }
        public void SetOrderedDictionaryItemLayout(Type itemType, ViewGeometryModelResults view, string parentName,
                                                   OrderedDictionaryItemLayout<string> itemLayout)
        {
            IOrderedDictionaryItemLayout<string> dictionary =
                GetOrderedDictionaryItemLayout(itemType, view, parentName);
            if (view == ViewGeometryModelResults.Model && typeof(BasePart).IsAssignableFrom(itemType))
            {
                OrderedDictionaryItemLayout<string> oldLayout = dictionary.GetItemLayoutSnapshot();
                SynchronizeCompoundPartGroupRenames(oldLayout.Nodes, itemLayout.Nodes);
            }
            dictionary.SetItemLayout(itemLayout);
            _form?.RegenerateTree(false);
        }
        public void SetLinkedPartGroupLayouts(OrderedDictionaryItemLayout<string> geometryLayout,
                                              OrderedDictionaryItemLayout<string> modelLayout)
        {
            if (_model.Geometry?.Parts == null || _model.Mesh?.Parts == null)
                throw new InvalidOperationException("The linked part-group layouts are not available.");
            //
            OrderedDictionaryItemLayout<string> oldModelLayout = _model.Mesh.Parts.GetItemLayoutSnapshot();
            SynchronizeCompoundPartGroupRenames(oldModelLayout.Nodes, modelLayout.Nodes);
            _model.Geometry.Parts.SetItemLayout(geometryLayout);
            _model.Mesh.Parts.SetItemLayout(modelLayout);
            _form?.RegenerateTree(false);
        }
        private bool RenameModelPartGroup(Guid groupId, string newGroupName)
        {
            if (_model.Mesh?.Parts == null) return false;
            //
            OrderedDictionaryItemLayout<string> layout = _model.Mesh.Parts.GetItemLayoutSnapshot();
            if (GetOrderedDictionaryGroupName(layout.Nodes, groupId) == null) return false;
            //
            _model.Mesh.Parts.RenameGroup(groupId, newGroupName);
            return true;
        }
        private void SynchronizeCompoundPartGroupRenames(
            IEnumerable<OrderedDictionaryItemNode<string>> oldNodes,
            IEnumerable<OrderedDictionaryItemNode<string>> newNodes)
        {
            foreach (OrderedDictionaryItemNode<string> oldNode in oldNodes)
            {
                if (!oldNode.IsGroup) continue;
                //
                string newGroupName = GetOrderedDictionaryGroupName(newNodes, oldNode.Id);
                CompoundGeometryPart compoundPart = _model.Geometry?.Parts?.Values
                    .OfType<CompoundGeometryPart>()
                    .FirstOrDefault(part => part.LinkedGroupId == oldNode.Id);
                if (newGroupName != null &&
                    !String.Equals(oldNode.Name, newGroupName, StringComparison.Ordinal) &&
                    compoundPart != null)
                {
                    PartProperties properties = compoundPart.GetProperties();
                    properties.Name = newGroupName;
                    ReplaceGeometryPartProperties(compoundPart.Name, properties, false);
                }
                //
                SynchronizeCompoundPartGroupRenames(oldNode.Children, newNodes);
            }
        }
        internal bool TryGetOrderedDictionaryItemLayout(
            Type itemType, ViewGeometryModelResults view, string parentName,
            out IOrderedDictionaryItemLayout<string> dictionary)
        {
            dictionary = null;
            if (typeof(Step).IsAssignableFrom(itemType) ||
                typeof(ResultFieldOutput).IsAssignableFrom(itemType) ||
                typeof(ResultHistoryOutput).IsAssignableFrom(itemType))
                return false;
            dictionary = GetOrderedDictionaryItemLayout(itemType, view, parentName);
            return true;
        }
        private IOrderedDictionaryItemLayout<string> GetOrderedDictionaryItemLayout(
            Type itemType, ViewGeometryModelResults view, string parentName)
        {
            IOrderedDictionaryItemLayout<string> dictionary = null;
            //
            if (view == ViewGeometryModelResults.Geometry)
            {
                // A script can name a collection of a view the model does not currently have
                if (_model.Geometry == null) { }
                else if (typeof(MeshSetupItem).IsAssignableFrom(itemType)) dictionary = _model.Geometry.MeshSetupItems;
                else if (typeof(BasePart).IsAssignableFrom(itemType)) dictionary = _model.Geometry.Parts;
            }
            else if (view == ViewGeometryModelResults.Model)
            {
                if (_model.Mesh == null && IsMeshEntityLayoutType(itemType)) { }
                else if (typeof(BasePart).IsAssignableFrom(itemType)) dictionary = _model.Mesh.Parts;
                else if (typeof(FeNodeSet).IsAssignableFrom(itemType)) dictionary = _model.Mesh.NodeSets;
                else if (typeof(FeElementSet).IsAssignableFrom(itemType)) dictionary = _model.Mesh.ElementSets;
                else if (typeof(FeSurface).IsAssignableFrom(itemType)) dictionary = _model.Mesh.Surfaces;
                else if (typeof(FeReferencePoint).IsAssignableFrom(itemType)) dictionary = _model.Mesh.ReferencePoints;
                else if (typeof(CoordinateSystem).IsAssignableFrom(itemType)) dictionary = _model.Mesh.CoordinateSystems;
                else if (typeof(Material).IsAssignableFrom(itemType)) dictionary = _model.Materials;
                else if (typeof(Section).IsAssignableFrom(itemType)) dictionary = _model.Sections;
                else if (typeof(CaeModel.Constraint).IsAssignableFrom(itemType)) dictionary = _model.Constraints;
                else if (typeof(SurfaceInteraction).IsAssignableFrom(itemType)) dictionary = _model.SurfaceInteractions;
                else if (typeof(ContactPair).IsAssignableFrom(itemType)) dictionary = _model.ContactPairs;
                else if (typeof(Distribution).IsAssignableFrom(itemType)) dictionary = _model.Distributions;
                else if (typeof(Amplitude).IsAssignableFrom(itemType)) dictionary = _model.Amplitudes;
                else if (typeof(InitialCondition).IsAssignableFrom(itemType)) dictionary = _model.InitialConditions;
                else if (typeof(AnalysisJob).IsAssignableFrom(itemType)) dictionary = _jobs;
                else
                {
                    Step step = _model.StepCollection.GetStep(parentName);
                    if (step == null) throw new KeyNotFoundException("The owning step was not found.");
                    //
                    if (typeof(HistoryOutput).IsAssignableFrom(itemType)) dictionary = step.HistoryOutputs;
                    else if (typeof(FieldOutput).IsAssignableFrom(itemType)) dictionary = step.FieldOutputs;
                    else if (typeof(BoundaryCondition).IsAssignableFrom(itemType)) dictionary = step.BoundaryConditions;
                    else if (typeof(Load).IsAssignableFrom(itemType)) dictionary = step.Loads;
                    else if (typeof(DefinedField).IsAssignableFrom(itemType)) dictionary = step.DefinedFields;
                }
            }
            else if (view == ViewGeometryModelResults.Results)
            {
                FeResults results = CurrentResult;
                if (results?.Mesh != null)
                {
                    if (typeof(BasePart).IsAssignableFrom(itemType)) dictionary = results.Mesh.Parts;
                    else if (typeof(FeNodeSet).IsAssignableFrom(itemType)) dictionary = results.Mesh.NodeSets;
                    else if (typeof(FeElementSet).IsAssignableFrom(itemType)) dictionary = results.Mesh.ElementSets;
                    else if (typeof(FeSurface).IsAssignableFrom(itemType)) dictionary = results.Mesh.Surfaces;
                    else if (typeof(FeReferencePoint).IsAssignableFrom(itemType)) dictionary = results.Mesh.ReferencePoints;
                    else if (typeof(CoordinateSystem).IsAssignableFrom(itemType)) dictionary = results.Mesh.CoordinateSystems;
                }
            }
            //
            if (dictionary == null)
                throw new NotSupportedException("The selected model-tree collection cannot be organized.");
            return dictionary;
        }
        private static bool IsMeshEntityLayoutType(Type itemType)
        {
            return typeof(BasePart).IsAssignableFrom(itemType) || typeof(FeNodeSet).IsAssignableFrom(itemType) ||
                   typeof(FeElementSet).IsAssignableFrom(itemType) || typeof(FeSurface).IsAssignableFrom(itemType) ||
                   typeof(FeReferencePoint).IsAssignableFrom(itemType) ||
                   typeof(CoordinateSystem).IsAssignableFrom(itemType);
        }
        private static ViewGeometryModelResults GetViewGeometryModelResults(ViewType view)
        {
            if (view == ViewType.Geometry) return ViewGeometryModelResults.Geometry;
            else if (view == ViewType.Model) return ViewGeometryModelResults.Model;
            else if (view == ViewType.Results) return ViewGeometryModelResults.Results;
            else throw new NotSupportedException();
        }
        private static string GetOrderedDictionaryGroupName(
            IEnumerable<OrderedDictionaryItemNode<string>> nodes, Guid groupId)
        {
            return GetOrderedDictionaryGroupNode(nodes, groupId)?.Name;
        }
        private static OrderedDictionaryItemNode<string> GetOrderedDictionaryGroupNode(
            IEnumerable<OrderedDictionaryItemNode<string>> nodes, Guid groupId)
        {
            foreach (OrderedDictionaryItemNode<string> node in nodes)
            {
                if (!node.IsGroup) continue;
                if (node.Id == groupId) return node;
                OrderedDictionaryItemNode<string> group =
                    GetOrderedDictionaryGroupNode(node.Children, groupId);
                if (group != null) return group;
            }
            return null;
        }
        private static bool OrderedDictionaryItemLayoutsEqual(
            IEnumerable<OrderedDictionaryItemNode<string>> first,
            IEnumerable<OrderedDictionaryItemNode<string>> second,
            IEqualityComparer<string> comparer)
        {
            OrderedDictionaryItemNode<string>[] firstNodes = first.ToArray();
            OrderedDictionaryItemNode<string>[] secondNodes = second.ToArray();
            if (firstNodes.Length != secondNodes.Length) return false;
            //
            for (int i = 0; i < firstNodes.Length; i++)
            {
                OrderedDictionaryItemNode<string> firstNode = firstNodes[i];
                OrderedDictionaryItemNode<string> secondNode = secondNodes[i];
                if (firstNode.NodeType != secondNode.NodeType) return false;
                if (firstNode.IsItem)
                {
                    if (!comparer.Equals(firstNode.Key, secondNode.Key)) return false;
                }
                else
                {
                    if (firstNode.Id != secondNode.Id ||
                        !String.Equals(firstNode.Name, secondNode.Name, StringComparison.Ordinal) ||
                        !OrderedDictionaryItemLayoutsEqual(firstNode.Children, secondNode.Children, comparer))
                        return false;
                }
            }
            return true;
        }

