        public int[][] GetSurfaceCellsByGeometryId(int[] geometrySurfaceIds, out ElementFaceType[] elementFaceTypes)
        {
            return GetSurfaceCellsByGeometryId(geometrySurfaceIds, out elementFaceTypes, out _);
        }
        public int[][] GetSurfaceCellsByGeometryId(int[] geometrySurfaceIds, out ElementFaceType[] elementFaceTypes,
                                                   out int[] cellElementIds)
        {
            if (geometrySurfaceIds.Length != 1) throw new NotSupportedException();
            //
            int[][] cells = DisplayedMesh.GetSurfaceCells(geometrySurfaceIds[0], out elementFaceTypes,
                                                          out cellElementIds);
            //
            return cells;
        }
        public vtkMaxActorData GetPartActorData(int[] elementIds)
        {
            FeMesh mesh = DisplayedMesh;
            //
            HashSet<int> partIds = new HashSet<int>();
            for (int i = 0; i < elementIds.Length; i++)
            {
                partIds.Add(mesh.Elements[elementIds[i]].PartId);
            }
            //
            List<int> allElementIds = new List<int>();
            foreach (var entry in mesh.Parts)
            {
                if (partIds.Contains(entry.Value.PartId))
                {
                    allElementIds.AddRange(entry.Value.Labels);
                }
            }
            //
            FeGroup elementSet = new FeGroup("tmp", allElementIds.ToArray());
            //
            return GetCellActorData(elementSet);
        }
        public vtkMaxActorData GetGeometryActorData(double[] point, int elementId, int[] edgeNodeIds, int[] cellFaceNodeIds,
                                                    out string noEdgePartName)
        {
            // Used for mouse move selection
            noEdgePartName = null;
            double precision = _form.GetSelectionPrecision();
            FeMesh mesh = DisplayedMesh;
            int geomId = mesh.GetGeometryIdByPrecision(point, elementId, cellFaceNodeIds, false, precision);
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geomId);
            GeometryType geomType = (GeometryType)itemTypePartIds[1];
            //
            if (geomType == GeometryType.Vertex)
            {
                int[] nodeIds = mesh.GetNodeIdsFromGeometryId(geomId);
                return GetNodeActorData(nodeIds);
            }
            else if (geomType.IsEdge())
            {
                double[] edgePoint = null;
                bool hasPoint = _geometryFeaturePointPicking != GeometryFeaturePointPickingEnum.None &&
                                TryGetSplitGeometryDisplayPoint(geomId, out edgePoint);
                if (!hasPoint) return GetGeometryEdgeActorData(new int[] { geomId });
                // Coming close to the point leaves the point highlighted on its own, the way a hovered
                // vertex is. Where the direction the edge runs in can also be meant, that is what says the
                // click will take the point instead of the edge; where nothing but the point can be meant,
                // it only says the point has been found.
                if (IsSplitGeometryPickNearPoint(geomId, point, precision)) return GetPointActorData(edgePoint);
                // Away from the point the edge is shown the way a face is: highlighted, with the point it
                // carries pointed out on it
                vtkMaxActorData edgeData = GetGeometryEdgeActorData(new int[] { geomId });
                SetPointSymbol(edgeData, edgePoint);
                return edgeData;
            }
            else if (geomType.IsSurface())
            {
                vtkMaxActorData surfaceData = GetSurfaceEdgesActorDataFromElementId(elementId, cellFaceNodeIds,
                                                                                   out noEdgePartName);
                // A face carries a point too - the middle of a plane, the axis of a cylinder - and hovering
                // it points that point out the same way an edge does
                double[] facePoint;
                if (_geometryFeaturePointPicking != GeometryFeaturePointPickingEnum.None &&
                    _currentView == ViewGeometryModelResults.Geometry &&
                    TryGetSplitGeometryDisplayPoint(geomId, out facePoint))
                    SetPointSymbol(surfaceData, facePoint);
                //
                return surfaceData;
            }
            else throw new NotSupportedException();
        }
        /// <summary>
        /// One coordinate makes the mouse over selection draw the point marker a hovered vertex gets, so a
        /// point that the click would take looks exactly like a vertex that the click would take.
        /// </summary>
        private vtkMaxActorData GetPointActorData(double[] point)
        {
            vtkMaxActorData data = new vtkMaxActorData();
            data.Geometry.Nodes.Coor = new double[][] { point };
            data.NodeSize = _settings.Pre.NodeSymbolSize;
            return data;
        }
        /// <summary>
        /// Marks where the point of a hovered entity sits, with the marker a hovered vertex gets.
        /// </summary>
        private void SetPointSymbol(vtkMaxActorData data, double[] point)
        {
            if (data == null || point == null) return;
            //
            data.ExtraPointCoor = new double[][] { point };
            data.ExtraPointSize = _settings.Pre.NodeSymbolSize;
        }
        /// <summary>
        /// True when the pick landed on the point rather than on the rest of the edge. The threshold is
        /// the selection precision that already decides whether a pick means a vertex or the edge it lies
        /// on, so snapping to a point feels the same as snapping to a vertex.
        /// </summary>
        private bool IsSplitGeometryPickNearPoint(int geometryId, double[] pickedPoint, double precision)
        {
            if (pickedPoint == null) return false;
            // A mouse pick starts out with no precision of its own and is given one only when it is
            // resolved through the geometry path - and that happens on a copy, so the pick this is asked
            // about can still be carrying the -1 it was made with
            if (precision <= 0) precision = _form.GetSelectionPrecision();
            if (precision <= 0) return false;
            //
            double[] point;
            if (!TryGetSplitGeometryDisplayPoint(geometryId, out point)) return false;
            // On a short edge the whole edge is within the precision, which would leave it unpickable as
            // an edge, so the point only wins when it claims a part of the edge rather than all of it
            double length = GetSplitGeometryEdgeLength(geometryId);
            if (length > 0 && precision >= length / 3) return false;
            //
            double dx = pickedPoint[0] - point[0];
            double dy = pickedPoint[1] - point[1];
            double dz = pickedPoint[2] - point[2];
            return Math.Sqrt(dx * dx + dy * dy + dz * dz) < precision;
        }
        /// <summary>
        /// What the splitter picks of a feature are read as. A plane through three points and a line
        /// through two take the point out of every pick, while a plane through a point and a normal
        /// takes either the point or the direction. This follows from the feature alone and from
        /// nothing the dialog holds, so a regenerate reads the picks the way the dialog that recorded
        /// them did.
        /// </summary>
        public static GeometryFeaturePointPickingEnum GetSplitGeometryPointPicking(GeometryFeature geometryFeature)
        {
            if (geometryFeature is SplitByPlaneThreePoints || geometryFeature is SplitByLineTwoPoints)
                return GeometryFeaturePointPickingEnum.PointOnly;
            else if (geometryFeature is SplitByPointAndNormal)
                return GeometryFeaturePointPickingEnum.PointOrEntity;
            else return GeometryFeaturePointPickingEnum.None;
        }
        /// <summary>
        /// True when the pick that produced this id means the point the entity carries. Only an edge can
        /// mean something else, and only where the direction it runs in is also being asked for: there
        /// the point has to be aimed at, everywhere else an edge means its point wherever it was hit.
        /// </summary>
        private bool IsSplitGeometryPickOnThePoint(int geometryId, Dictionary<int, SelectionNodeMouse> pickNodes,
                                                   GeometryFeature geometryFeature)
        {
            GeometryType geometryType = (GeometryType)FeMesh.GetItemTypePartIdsFromGeometryId(geometryId)[1];
            if (!geometryType.IsEdge()) return true;
            if (GetSplitGeometryPointPicking(geometryFeature) != GeometryFeaturePointPickingEnum.PointOrEntity)
                return true;
            //
            SelectionNodeMouse pick;
            if (!pickNodes.TryGetValue(geometryId, out pick)) return true;
            //
            return IsSplitGeometryPickNearPoint(geometryId, pick.PickedPoint, pick.Precision);
        }
        private double GetSplitGeometryEdgeLength(int geometryId)
        {
            BasePart part;
            GeometryType geometryType;
            int itemId;
            GeometryMetadataEntity entity = GetSplitGeometryMetadataEntity(geometryId, out part,
                                                                          out geometryType, out itemId);
            double[] values;
            if (entity != null && entity.TryGetCanonicalNumbers("length", out values) && values.Length == 1)
                return values[0];
            // A mesh part keeps the length on the part rather than in the metadata
            if (part != null && part.Visualization != null && part.Visualization.EdgeLengths != null &&
                itemId >= 0 && itemId < part.Visualization.EdgeLengths.Length)
                return part.Visualization.EdgeLengths[itemId];
            return -1;
        }
        /// <summary>
        /// Pairs every id a selection resolves to with the mouse pick that produced it. The pick keeps the
        /// position and the precision it was made with and both are serialized, so the point or edge
        /// decision is recomputed on a regenerate rather than stored as a flag that ids would outlive.
        /// </summary>
        private Dictionary<int, SelectionNodeMouse> GetSplitGeometryPickNodes(Selection selection)
        {
            Dictionary<int, SelectionNodeMouse> pickNodes = new Dictionary<int, SelectionNodeMouse>();
            if (selection == null) return pickNodes;
            //
            // Resolving a selection replaces and then clears the live one, so it is put back afterwards
            Selection liveSelection = _selection;
            try
            {
                foreach (SelectionNode node in selection.Nodes)
                {
                    SelectionNodeMouse mouseNode = node as SelectionNodeMouse;
                    if (mouseNode == null) continue;
                    // The copy keeps the view the pick was made in. A fresh Selection has no view, and no
                    // view is read as the model view, which would switch the application over to it.
                    Selection singlePick = new Selection(selection, false, false);
                    singlePick.Add(mouseNode);
                    foreach (int id in GetIdsFromSelection(singlePick)) pickNodes[id] = mouseNode;
                }
            }
            finally
            {
                _selection = liveSelection;
            }
            return pickNodes;
        }
        private bool TryGetSplitGeometryDisplayPoint(int geometryId, out double[] point)
        {
            if (!TryGetSplitGeometryPoint(geometryId, out point)) return false;
            // The metadata holds the part's own coordinates while the viewport draws the exploded ones
            if (IsExplodedViewActive())
            {
                int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
                BasePart part = _model.Geometry.GetPartFromId(itemTypePartIds[2]);
                if (part != null)
                {
                    point[0] += part.Offset[0];
                    point[1] += part.Offset[1];
                    point[2] += part.Offset[2];
                }
            }
            return true;
        }
        public vtkMaxActorData GetGeometryVertexActorData(double[] point, int elementId,
                                                          int[] edgeNodeIds, int[] cellFaceNodeIds)
        {
            double precision = _form.GetSelectionPrecision();
            FeMesh mesh = DisplayedMesh;
            int geomId = mesh.GetGeometryVertexIdByPrecision(point, elementId, cellFaceNodeIds, precision);
            // If no vertex is selected
            if (geomId < 0) return null;
            else
            {
                int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geomId);
                GeometryType geomType = (GeometryType)itemTypePartIds[1];
                //
                if (geomType == GeometryType.Vertex)
                {
                    int[] nodeIds = mesh.GetNodeIdsFromGeometryId(geomId);
                    return GetNodeActorData(nodeIds);
                }
                else throw new NotSupportedException();
            }
        }

