        #region Draw  ##############################################################################################################
        // Redraw
        public void Redraw(bool resetCamera = false)
        {
            if (_currentView == ViewGeometryModelResults.Geometry) DrawGeometry(resetCamera);
            else if (_currentView == ViewGeometryModelResults.Model) DrawModel(resetCamera);
            else if (_currentView == ViewGeometryModelResults.Results) DrawResults(resetCamera);
            else throw new NotSupportedException();
        }
        // An operation that creates or removes several items updates the view once instead of once per item.
        // The batches nest, so an operation that loops over another batched operation still updates once.
        public void BeginUpdateBatch()
        {
            _updateBatchCount++;
        }
        public void EndUpdateBatch()
        {
            if (_updateBatchCount <= 0) throw new InvalidOperationException("The view update batching is not active.");
            //
            _updateBatchCount--;
            if (_updateBatchCount > 0) return;
            //
            UpdateType modelUpdateType = _batchedModelUpdateType;
            UpdateType resultsUpdateType = _batchedResultsUpdateType;
            _batchedModelUpdateType = UpdateType.None;
            _batchedResultsUpdateType = UpdateType.None;
            //
            if (modelUpdateType != UpdateType.None) FeModelUpdate(modelUpdateType);
            if (resultsUpdateType != UpdateType.None) FeResultsUpdate(resultsUpdateType);
        }
        // Update model
        public void FeModelUpdate(UpdateType updateType)
        {
            if (_updateBatchCount > 0) { _batchedModelUpdateType |= updateType; return; }
            // First check the validity to correctly draw the symbols
            if (updateType.HasFlag(UpdateType.Check)) CheckAndUpdateModelValidity();
            if (updateType.HasFlag(UpdateType.DrawModel)) DrawModel(updateType.HasFlag(UpdateType.ResetCamera));
            if (updateType.HasFlag(UpdateType.RedrawSymbols)) RedrawModelSymbols();
        }
        public void FeResultsUpdate(UpdateType updateType)
        {
            if (_updateBatchCount > 0) { _batchedResultsUpdateType |= updateType; return; }
            if (updateType.HasFlag(UpdateType.Check)) CheckAndUpdateResultValidity();
            if (updateType.HasFlag(UpdateType.DrawResults)) DrawResults(updateType.HasFlag(UpdateType.ResetCamera));
            if (updateType.HasFlag(UpdateType.RedrawSymbols)) RedrawResultSymbols();
        }
        
        private vtkMaxActorRepresentation GetRepresentation(BasePart part)
        {
            if (part.PartType == PartType.Solid) return vtkMaxActorRepresentation.Solid;
            else if (part.PartType == PartType.SolidAsShell) return vtkMaxActorRepresentation.SolidAsShell;
            else if (part.PartType == PartType.Shell) return vtkMaxActorRepresentation.Shell;
            else if (part.PartType == PartType.Wire) return vtkMaxActorRepresentation.Wire;
            else throw new NotSupportedException();
        }
        // Geometry mesh
        public void DrawGeometry(bool resetCamera)
        {
            bool rendering = _form.RenderingOn;
            //
            try
            {
                // Set the current view and call DrawGeometry
                if (_currentView != ViewGeometryModelResults.Geometry) CurrentView = ViewGeometryModelResults.Geometry;
                // Draw geometry
                else
                {
                    if (rendering) _form.RenderingOn = false;
                    _form.Clear3D();    // Removes section cut
                    //
                    if (_model != null)
                    {
                        if (_model.Geometry != null && _model.Geometry.Parts.Count > 0)
                        {
                            ApplyModelUnitSystem();
                            //
                            DetectMeshTypes();
                            //
                            DrawGeomParts();
                            AnnotateWithColorLegend();
                            _annotations.DrawAnnotations();
                            //
                            DrawItemIds();
                            //
                            ApplySectionView();
                        }
                        UpdateTreeSelection();
                    }
                    //
                    ApplyRotationPoint();
                    if (resetCamera) _form.SetFrontBackView(false, true);
                    _form.AdjustCameraDistanceAndClipping();
                }
            }
            catch (Exception ex)
            {
                // Do not throw an error - it might cancel a procedure
                Debug.WriteLine(ex);
            }
            finally
            {
                if (rendering) _form.RenderingOn = true;
            }
        }
        public void DrawGeomParts()
        {
            if (_model == null) return;
            //
            vtkRendererLayer layer = vtkRendererLayer.Base;
            List<string> hiddenActors = new List<string>();
            //
            foreach (var entry in _model.Geometry.Parts)
            {
                if (entry.Value is CompoundGeometryPart) continue;
                //
                DrawGeomPart(_model.Geometry, entry.Value, layer, true, true);
                //
                if (!entry.Value.Visible) hiddenActors.Add(entry.Key);
            }
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), false);
            //
            _form.AdjustCameraDistanceAndClipping();
        }
        private void DrawGeomPart(FeMesh mesh, BasePart part, vtkRendererLayer layer, bool canHaveElementEdges,
                                  bool pickable)
        {
            vtkMaxActorData data = GetGeometryPartActorData(mesh, part, layer, canHaveElementEdges, pickable);
            //
            if (data != null)
            {
                ApplyLighting(data);
                _form.Add3DCells(data);
            }
        }
        private PartExchangeData GetModelEdgesToDraw(FeMesh mesh, BasePart part)
        {
            CompoundGeometryPart compoundPart = GetCompoundPartOfSubPart(mesh, part.Name);
            if (compoundPart == null) return null;
            //
            HashSet<int> edgeCellIds =
                compoundPart.GetSharedEdges(mesh).GetEdgeCellIdsDrawnByAnotherSubPart(part.Name, mesh);
            if (edgeCellIds == null) return null;
            //
            PartExchangeData modelEdges = new PartExchangeData();
            mesh.GetNodesAndCellsForModelEdges(part, edgeCellIds, out modelEdges.Nodes.Ids, out modelEdges.Nodes.Coor,
                                               out modelEdges.Cells.CellNodeIds, out modelEdges.Cells.Types);
            //
            return modelEdges;
        }
        private CompoundGeometryPart GetCompoundPartOfSubPart(FeMesh mesh, string subPartName)
        {
            if (mesh == null || _model == null || mesh != _model.Geometry) return null;
            //
            foreach (var entry in mesh.Parts)
            {
                if (entry.Value is CompoundGeometryPart compoundPart &&
                    Array.IndexOf(compoundPart.SubPartNames, subPartName) >= 0) return compoundPart;
            }
            return null;
        }
        private vtkMaxActorData GetGeometryPartActorData(FeMesh mesh, BasePart part,
                                                         vtkRendererLayer layer,
                                                         bool canHaveElementEdges,
                                                         bool pickable)
        {
            if (part.Labels.Length == 0) return null;
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = part.Name;
            GetPartColor(part, ref data.Color, ref data.BackfaceColor);
            data.Layer = layer;
            data.CanHaveElementEdges = canHaveElementEdges;
            data.Pickable = pickable;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            data.ActorRepresentation = GetRepresentation(part);
            // All nodes and elements are built on demand
            if (pickable) SetVolumeGridData(data, mesh, part);
            // Get only needed nodes and elements - renumbered
            mesh.GetVisualizationNodesAndCells(part, out data.Geometry.Nodes.Ids, out data.Geometry.Nodes.Coor,
                                               out data.Geometry.Cells.Ids, out data.Geometry.Cells.CellNodeIds,
                                               out data.Geometry.Cells.Types);
            // Model edges
            if (part.PartType.HasEdges() && part.Visualization.EdgeCells != null)
            {
                data.ModelEdges = new PartExchangeData();
                mesh.GetNodesAndCellsForModelEdges(part, out data.ModelEdges.Nodes.Ids, out data.ModelEdges.Nodes.Coor,
                                                   out data.ModelEdges.Cells.CellNodeIds, out data.ModelEdges.Cells.Types);
                //
                data.ModelEdgesToDraw = GetModelEdgesToDraw(mesh, part);
            }
            // Back face
            if (part.PartType == PartType.Shell) data.BackfaceCulling = false;
            //
            data.NodeSize = Globals.BeamNodeSize;
            //
            return data;
        }
        // Model
        public void DrawModel(bool resetCamera)
        {
            bool rendering = _form.RenderingOn;
            //
            try
            {
                // Set the current view and call DrawModel
                if (_currentView != ViewGeometryModelResults.Model) CurrentView = ViewGeometryModelResults.Model;
                // Draw model
                else
                {
                    if (rendering) _form.RenderingOn = false;
                    _form.Clear3D();    // Removes section cut
                    //
                    if (_model != null)
                    {
                        if (_model.Mesh != null && _model.Mesh.Parts.Count > 0)
                        {
                            ApplyModelUnitSystem();
                            // Must be inside to continue screen update
                            try
                            {
                                DrawAllModelParts();
                                AnnotateWithColorLegend();
                                _annotations.DrawAnnotations();
                                //
                                DrawModelSymbols();
                                //
                                DrawItemIds();
                                //
                                ApplySectionView();
                            }
                            catch { }
                        }
                        UpdateTreeSelection();
                    }
                    //
                    ApplyRotationPoint();
                    if (resetCamera) _form.SetFrontBackView(false, true);
                    //_form.AdjustCameraDistanceAndClipping();
                }
            }
            catch
            {
                // Do not throw an error - it might cancel a procedure
            }
            finally
            {
                if (rendering) _form.RenderingOn = true;
            }
        }
        public void DrawAllModelParts()
        {
            if (_model == null) return;
            //
            IDictionary<string, BasePart> parts = _model.Mesh.Parts;
            vtkRendererLayer layer = vtkRendererLayer.Base;
            //
            Dictionary<int, int> elementIdColorId = null;
            if (_annotateWithColor == AnnotateWithColorEnum.Sections)
                _model.GetSectionAssignments(out elementIdColorId);
            else if (_annotateWithColor == AnnotateWithColorEnum.Materials)
                _model.GetMaterialAssignments(out elementIdColorId);
            else if (_annotateWithColor == AnnotateWithColorEnum.SectionThicknesses)
                _model.GetSectionThicknessAssignments(out elementIdColorId);
            //
            ConcurrentBag<string> hiddenActors = new ConcurrentBag<string>();
            ConcurrentBag<vtkMaxActorData> allData = new ConcurrentBag<vtkMaxActorData>();
            //
            Parallel.ForEach(parts, entry =>
            //foreach (var entry in parts)
            {
                vtkMaxActorData data = GetModelPartActorData(_model.Mesh, entry.Value, layer, elementIdColorId);
                if (data != null)
                {
                    ApplyLighting(data);
                    allData.Add(data);
                }
                //
                if (!(entry.Value.Active && entry.Value.Visible)) hiddenActors.Add(entry.Key);
            }
            );
            //
            if (allData.Count > 0) _form.Add3DCells(allData.ToArray());
            //
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), false);
        }
        public void DrawModelPart(FeMesh mesh, BasePart part, vtkRendererLayer layer,
                                  Dictionary<int, int> elementIdColorId = null)
        {
            vtkMaxActorData data = GetModelPartActorData(mesh, part, layer, elementIdColorId);
            //
            if (data != null)
            {
                ApplyLighting(data);
                _form.Add3DCells(data);
            }
        }
        public vtkMaxActorData GetModelPartActorData(FeMesh mesh, BasePart part, vtkRendererLayer layer,
                                                     Dictionary<int, int> elementIdColorId = null)
        {
            if (part is CompoundGeometryPart) return null;
            if (part.Labels.Length == 0) return null;
            // Data
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = part.Name;
            GetPartColor(part, ref data.Color, ref data.BackfaceColor);
            data.Layer = layer;
            data.CanHaveElementEdges = true;
            data.Pickable = true;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            data.ActorRepresentation = GetRepresentation(part);
            // All nodes and elements for selection are built on demand
            SetVolumeGridData(data, mesh, part);
            // Get only needed nodes and elements - renumbered
            mesh.GetVisualizationNodesAndCells(part, out data.Geometry.Nodes.Ids, out data.Geometry.Nodes.Coor,
                                               out data.Geometry.Cells.Ids,
                                               out data.Geometry.Cells.CellNodeIds,
                                               out data.Geometry.Cells.Types);
            // Custom coloring of elements
            if (elementIdColorId != null)
            {
                int maxColor = -int.MaxValue;
                float value;
                Color cellColor;
                double sumR = 0;
                double sumG = 0;
                double sumB = 0;
                float[] values = new float[data.Geometry.Cells.Ids.Length];
                ColorSettings colorSettings = _settings.Color;
                for (int i = 0; i < values.Length; i++)
                {
                    value = elementIdColorId[data.Geometry.Cells.Ids[i]] % colorSettings.ColorTable.Length;
                    values[i] = value;
                    if (value > maxColor) maxColor = (int)value;
                    //
                    cellColor = value < 0 ? Color.White : colorSettings.ColorTable[(int)value];
                    sumR += cellColor.R;
                    sumG += cellColor.G;
                    sumB += cellColor.B;
                }
                data.Geometry.Cells.Values = values;
                // The shading and the highlights of the cell colors are taken from their mean color
                int alpha = maxColor < 0 ? data.Color.A / 2 : data.Color.A;
                data.Color = Color.FromArgb(alpha, (int)(sumR / values.Length), (int)(sumG / values.Length),
                                            (int)(sumB / values.Length));
                //
                maxColor++; // first color is 0 so add +1
                data.ColorTable = new Color[maxColor];
                Array.Copy(colorSettings.ColorTable, data.ColorTable, maxColor);
                //
                //data.ColorTable = colorSettings.ColorTable;
            }
            // Back face
            if (part.PartType == PartType.Shell) data.BackfaceCulling = false;
            // Model edges
            if (part.PartType.HasEdges() && part.Visualization.EdgeCells != null)
            {
                data.ModelEdges = new PartExchangeData();
                mesh.GetNodesAndCellsForModelEdges(part, out data.ModelEdges.Nodes.Ids, out data.ModelEdges.Nodes.Coor,
                                                   out data.ModelEdges.Cells.CellNodeIds, out data.ModelEdges.Cells.Types);
            }
            //
            data.NodeSize = Globals.BeamNodeSize;
            //
            return data;
        }
        //
        private void GetPartColor(BasePart part, ref Color color, ref Color backfaceColor)
        {
            color = part.Color;
            // wire part
            foreach (var elType in part.ElementTypes)
            {
                if (elType == typeof(LinearBeamElement) || elType == typeof(ParabolicBeamElement))
                {
                    color = Color.Black;
                    break;
                }
            }
            if (_annotateWithColor == AnnotateWithColorEnum.FaceOrientation)
            {
                if (part.PartType == PartType.Shell)
                {
                    ColorSettings colorSettings = _settings.Color;
                    color = colorSettings.FrontFaceColor;
                    backfaceColor = colorSettings.BackFaceColor;
                }
                else if (part.PartType == PartType.Solid || part.PartType == PartType.SolidAsShell)
                {
                    color = Color.White;
                }
            }
            // The mesh setup items are defined on the geometry, so the mesh type is shown on the geometry
            else if (_annotateWithColor == AnnotateWithColorEnum.MeshTypes &&
                     _currentView == ViewGeometryModelResults.Geometry && part is GeometryPart geometryPart)
            {
                color = GetMeshTypeColor(GetEffectiveMeshType(geometryPart.Name));
            }
        }
        private Color GetMeshTypeColor(MeshTypeEnum meshType)
        {
            ColorSettings colorSettings = _settings.Color;
            switch (meshType)
            {
                case MeshTypeEnum.Transfinite: return colorSettings.TransfiniteMeshColor;
                case MeshTypeEnum.Sweep: return colorSettings.SweepMeshColor;
                case MeshTypeEnum.Tetrahedral: return colorSettings.TetrahedralMeshColor;
                default: return colorSettings.OtherMeshColor;
            }
        }
        private static string GetMeshTypeName(MeshTypeEnum meshType)
        {
            switch (meshType)
            {
                case MeshTypeEnum.Transfinite: return "Transfinite - structured";
                case MeshTypeEnum.Sweep: return "Sweep";
                case MeshTypeEnum.Tetrahedral: return "Tetrahedral";
                default: return "Other";
            }
        }
        private void AnnotateWithColorLegend()
        {
            if (_annotateWithColor == AnnotateWithColorEnum.None) return;
            // Clears the contents
            _form.HideColorBar();
            //
            if (_currentView == ViewGeometryModelResults.Results &&
                (_viewResultsType == ViewResultsTypeEnum.ColorContours ||
                 _viewResultsType == ViewResultsTypeEnum.VectorPlot ||
                 _viewResultsType == ViewResultsTypeEnum.TensorPlot))
                return;
            // Face orientation legend
            ColorSettings colorSettings = _settings.Color;
            if (_annotateWithColor == AnnotateWithColorEnum.FaceOrientation)
            {
                _form.SetColorBarColorsAndLabels(new Color[] { colorSettings.FrontFaceColor, colorSettings.BackFaceColor },
                                                               new string[] { "Front face", "Back face" });
            }
            if (_annotateWithColor == AnnotateWithColorEnum.MeshTypes)
            {
                if (_currentView == ViewGeometryModelResults.Geometry)
                {
                    MeshTypeEnum[] meshTypes = new MeshTypeEnum[] { MeshTypeEnum.Transfinite, MeshTypeEnum.Sweep,
                                                                    MeshTypeEnum.Tetrahedral, MeshTypeEnum.Other };
                    List<Color> meshTypeColors = new List<Color>();
                    List<string> meshTypeNames = new List<string>();
                    foreach (var meshType in meshTypes)
                    {
                        foreach (var entry in _model.Geometry.Parts)
                        {
                            if (entry.Value is CompoundGeometryPart || !(entry.Value is GeometryPart geometryPart)) continue;
                            if (!geometryPart.Visible || GetEffectiveMeshType(geometryPart.Name) != meshType) continue;
                            //
                            meshTypeColors.Add(GetMeshTypeColor(meshType));
                            meshTypeNames.Add(GetMeshTypeName(meshType));
                            break;
                        }
                    }
                    _form.SetColorBarColorsAndLabels(meshTypeColors.ToArray(), meshTypeNames.ToArray());
                }
            }
            if (_annotateWithColor == AnnotateWithColorEnum.Parts)
            {
                FeMesh mesh = DisplayedMesh;
                List<Color> partColors = new List<Color>();
                List<string> partNames = new List<string>();
                foreach (var entry in mesh.Parts)
                {
                    if (entry.Value.Visible)
                    {
                        if (!(entry.Value is CompoundGeometryPart))
                        {
                            partColors.Add(entry.Value.Color);
                            partNames.Add(entry.Value.Name);
                        }
                    }
                }
                _form.SetColorBarColorsAndLabels(partColors.ToArray(), partNames.ToArray());
            }
            if (_annotateWithColor == AnnotateWithColorEnum.Materials)
            {
                if (_currentView == ViewGeometryModelResults.Model)
                {
                    // Get active materials
                    HashSet<string> activeMaterials = new HashSet<string>();
                    foreach (var entry in _model.Sections) activeMaterials.Add(entry.Value.MaterialName);
                    //
                    List<Color> materialColors = new List<Color>();
                    List<string> materialNames = new List<string>();
                    int count = 0;
                    foreach (var entry in _model.Materials)
                    {
                        if (activeMaterials.Contains(entry.Value.Name))
                        {
                            materialColors.Add(colorSettings.ColorTable[count++ % colorSettings.ColorTable.Length]);
                            materialNames.Add(entry.Value.Name);
                        }
                    }
                    _form.SetColorBarColorsAndLabels(materialColors.ToArray(), materialNames.ToArray());
                }
            }
            if (_annotateWithColor == AnnotateWithColorEnum.Sections)
            {
                if (_currentView == ViewGeometryModelResults.Model)
                {
                    List<Color> sectionColors = new List<Color>();
                    List<string> sectionNames = new List<string>();
                    int count = 0;
                    foreach (var entry in _model.Sections)
                    {
                        sectionColors.Add(colorSettings.ColorTable[count++ % colorSettings.ColorTable.Length]);
                        sectionNames.Add(entry.Value.Name);
                    }
                    _form.SetColorBarColorsAndLabels(sectionColors.ToArray(), sectionNames.ToArray());
                }
            }
            if (_annotateWithColor == AnnotateWithColorEnum.SectionThicknesses)
            {
                if (_currentView == ViewGeometryModelResults.Model)
                {
                    List<Color> sectionThicknessColors = new List<Color>();
                    HashSet<double> sectionThickness = new HashSet<double>();
                    int count = 0;
                    double thickness;
                    foreach (var entry in _model.Sections)
                    {
                        thickness = _model.GetSectionThickness(entry.Value);
                        //
                        if (thickness != -1 && !sectionThickness.Contains(thickness))
                        {
                            sectionThicknessColors.Add(colorSettings.ColorTable[count++ % colorSettings.ColorTable.Length]);
                            sectionThickness.Add(thickness);
                        }
                    }
                    // Sort thicknesses
                    double[] sectionThicknessArray = sectionThickness.ToArray();
                    Array.Sort(sectionThicknessArray);
                    // Add unit
                    string[] sectionThicknessNames = new string[sectionThicknessArray.Length];
                    for (int i = 0; i < sectionThicknessArray.Length; i++)
                        sectionThicknessNames[i] = sectionThicknessArray[i] + " " + _model.UnitSystem.LengthUnitAbbreviation;
                    //
                    _form.SetColorBarColorsAndLabels(sectionThicknessColors.ToArray(), sectionThicknessNames);
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.ReferencePoints))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null && _drawSymbolName != Globals.SymbolNone)
                { List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Reference points
                    foreach (var entry in _model.Mesh.ReferencePoints)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            itemColors.Add(entry.Value.Color);
                            itemNames.Add(entry.Value.Name);
                        }
                    }
                    _form.SetColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.Constraints))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null && _drawSymbolName != Globals.SymbolNone)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Constraints
                    foreach (var entry in _model.Constraints)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            if (entry.Value is PointSpring pts)
                            {
                                itemColors.Add(pts.MasterColor);
                                itemNames.Add(pts.Name);
                            }
                            else if (entry.Value is SurfaceSpring srs)
                            {
                                itemColors.Add(srs.MasterColor);
                                itemNames.Add(srs.Name);
                            }
                            else if (entry.Value is CompressionOnly co)
                            {
                                itemColors.Add(co.MasterColor);
                                itemNames.Add(co.Name);
                            }
                            else if (entry.Value is RigidBody rb)
                            {
                                itemColors.Add(rb.MasterColor);
                                itemNames.Add(rb.Name);
                            }
                            else if (entry.Value is Tie || entry.Value is Joint)
                            {
                                if (entry.Value.MasterColor != entry.Value.SlaveColor)
                                {
                                    itemColors.Add(entry.Value.MasterColor);
                                    itemNames.Add(entry.Value.Name + " Master");
                                    itemColors.Add(entry.Value.SlaveColor);
                                    itemNames.Add(entry.Value.Name + " Slave");
                                }
                                else
                                {
                                    itemColors.Add(entry.Value.MasterColor);
                                    itemNames.Add(entry.Value.Name);
                                }
                            }
                            else throw new NotSupportedException();
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.ContactPairs))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null && _drawSymbolName != Globals.SymbolNone)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Contact pairs
                    foreach (var entry in _model.ContactPairs)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            if (entry.Value.MasterColor != entry.Value.SlaveColor)
                            {
                                itemColors.Add(entry.Value.MasterColor);
                                itemNames.Add(entry.Value.Name + " Master");
                                itemColors.Add(entry.Value.SlaveColor);
                                itemNames.Add(entry.Value.Name + " Slave");
                            }
                            else
                            {
                                itemColors.Add(entry.Value.MasterColor);
                                itemNames.Add(entry.Value.Name);
                            }
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.InitialConditions))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null &&
                    _drawSymbolName != Globals.SymbolNone && _drawSymbolName != Globals.SymbolModel)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Initial conditions
                    foreach (var entry in _model.InitialConditions)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            itemColors.Add(entry.Value.Color);
                            itemNames.Add(entry.Value.Name);
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.BoundaryConditions))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null &&
                    _drawSymbolName != Globals.SymbolNone && _drawSymbolName != Globals.SymbolModel)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Boundary conditions
                    foreach (var entry in _model.StepCollection.GetStep(_drawSymbolName).BoundaryConditions)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            itemColors.Add(entry.Value.Color);
                            itemNames.Add(entry.Value.Name);
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.Loads))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null &&
                    _drawSymbolName != Globals.SymbolNone && _drawSymbolName != Globals.SymbolModel)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Loads
                    foreach (var entry in _model.StepCollection.GetStep(_drawSymbolName).Loads)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            itemColors.Add(entry.Value.Color);
                            itemNames.Add(entry.Value.Name);
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            if (_annotateWithColor.HasFlag(AnnotateWithColorEnum.DefinedFields))
            {
                if (_currentView == ViewGeometryModelResults.Model && _drawSymbolName != null &&
                    _drawSymbolName != Globals.SymbolNone && _drawSymbolName != Globals.SymbolModel)
                {
                    List<Color> itemColors = new List<Color>();
                    List<string> itemNames = new List<string>();
                    // Defined fields
                    foreach (var entry in _model.StepCollection.GetStep(_drawSymbolName).DefinedFields)
                    {
                        if (entry.Value.Visible && entry.Value.Active)
                        {
                            itemColors.Add(entry.Value.Color);
                            itemNames.Add(entry.Value.Name);
                        }
                    }
                    _form.AddColorBarColorsAndLabels(itemColors.ToArray(), itemNames.ToArray());
                }
            }
            // Pre-processing settings
            PreSettings ps = _settings.Pre;
            _form.DrawColorBarBackground(ps.ColorBarBackgroundType == AnnotationBackgroundType.White);
            _form.DrawColorBarBorder(ps.ColorBarDrawBorder);
            //
        }
        // Items
        private void DrawItemIds()
        {
            if (_showItemIds == ShowItemIdsEnum.None || _itemIdsSuppressed) return;
            //
            FeMesh mesh = DisplayedMesh;
            if (mesh == null) return;
            //
            List<double[]> positions = new List<double[]>();
            double fontScaleFactor = 0.9 * _settings.Pre.SymbolSize / 50d;
            vtkRendererLayer layer = vtkRendererLayer.Overlay;
            //
            List<string> labels = new List<string>();
            if (_showItemIds.HasFlag(ShowItemIdsEnum.Nodes)) DrawNodeIds(mesh, positions, labels);
            if (_showItemIds.HasFlag(ShowItemIdsEnum.Elements)) DrawElementIds(mesh, positions, labels);
            //
            foreach (var entry in mesh.Parts)
            {
                BasePart part = entry.Value;
                if (!IsPartVisibleForItemIds(part)) continue;
                //
                if (_showItemIds.HasFlag(ShowItemIdsEnum.Vertices))
                    DrawVertexIds(mesh, part, positions, labels);
                if (_showItemIds.HasFlag(ShowItemIdsEnum.Edges))
                    DrawEdgeIds(mesh, part, positions, labels);
                if (_showItemIds.HasFlag(ShowItemIdsEnum.Surfaces))
                    DrawSurfaceIds(part, positions, labels);
                if (_showItemIds.HasFlag(ShowItemIdsEnum.Parts))
                    DrawPartId(part, positions, labels);
                if (_showItemIds.HasFlag(ShowItemIdsEnum.PartNames))
                    DrawPartName(part, positions, labels);
            }
            //
            if (positions.Count > 0)
                _form.AddLabelActor(_itemLabelsActorName, positions.ToArray(), labels.ToArray(), Color.Black,
                                    fontScaleFactor, layer);
        }
        private void RedrawItemIds()
        {
            if (_showItemIds == ShowItemIdsEnum.None || _itemIdsSuppressed) return;
            //
            _form.RemoveOverlayActors(new string[] { _itemLabelsActorName });
            DrawItemIds();
        }
        private void SuppressItemIds()
        {
            _itemIdsSuppressed = true;
            _form.RemoveOverlayActors(new string[] { _itemLabelsActorName });
        }
        private void ResumeItemIds()
        {
            _itemIdsSuppressed = false;
            DrawItemIds();
        }
        private bool IsPartVisibleForItemIds(BasePart part)
        {
            if (part is CompoundGeometryPart || !part.Visible) return false;
            if (_currentView == ViewGeometryModelResults.Model && !part.Active) return false;
            return true;
        }
        private void DrawVertexIds(FeMesh mesh, BasePart part, List<double[]> positions, List<string> labels)
        {
            int[] nodeIds = part.Visualization?.VertexNodeIds;
            if (nodeIds == null) return;
            //
            for (int i = 0; i < nodeIds.Length; i++)
                AddItemIdLabel("V" + (i + 1), GetItemIdNodeCoor(mesh, nodeIds[i]), positions, labels);
        }
        private void DrawEdgeIds(FeMesh mesh, BasePart part, List<double[]> positions, List<string> labels)
        {
            VisualizationData visualization = part.Visualization;
            if (visualization?.EdgeCellIdsByEdge == null) return;
            //
            for (int i = 0; i < visualization.EdgeCellIdsByEdge.Length; i++)
            {
                mesh.GetEdgeNodeCoor(i, visualization, out int[] nodeIds, out _);
                if (nodeIds == null || nodeIds.Length == 0) continue;
                //
                double[] coor;
                if (nodeIds.Length == 2)
                {
                    double[] coor1 = GetItemIdNodeCoor(mesh, nodeIds[0]);
                    double[] coor2 = GetItemIdNodeCoor(mesh, nodeIds[1]);
                    coor = new double[] { (coor1[0] + coor2[0]) / 2,
                                          (coor1[1] + coor2[1]) / 2,
                                          (coor1[2] + coor2[2]) / 2 };
                }
                else coor = GetItemIdNodeCoor(mesh, nodeIds[nodeIds.Length / 2]);
                //
                AddItemIdLabel("E" + (i + 1), coor, positions, labels);
            }
        }
        private void DrawSurfaceIds(BasePart part, List<double[]> positions, List<string> labels)
        {
            VisualizationData visualization = part.Visualization;
            if (visualization == null || visualization.FaceCount == 0) return;
            if (!TryGetSurfaceGeometryType(part, out GeometryType geometryType)) return;
            //
            for (int i = 0; i < visualization.FaceCount; i++)
            {
                int geometryId = FeMesh.GetGeometryId(i, (int)geometryType, part.PartId);
                double[] coor = GetSurfaceCenter(geometryId);
                if (coor != null)
                    AddItemIdLabel("S" + (i + 1), coor, positions, labels);
            }
        }
        public double[] GetSurfaceCenter(int geometryId)
        {
            FeMesh mesh = DisplayedMesh;
            if (mesh == null) return null;
            //
            int[] itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(geometryId);
            BasePart part = mesh.GetPartFromId(itemTypePartIds[2]);
            VisualizationData visualization = part?.Visualization;
            int surfaceId = itemTypePartIds[0];
            if (visualization == null || surfaceId < 0 || surfaceId >= visualization.FaceCount) return null;
            //
            if (visualization.CellIdsByFace[surfaceId].Length == 0) return null;
            //
            List<double[]> possibleCoor = new List<double[]>(visualization.CellIdsByFace[surfaceId].Length);
            AddCellCenters(mesh, visualization, surfaceId, possibleCoor);
            if (possibleCoor.Count == 0) return null;
            //
            double[][] coor = possibleCoor.ToArray();
            int[] distributedIds = SpatialPointSampler.GetSampleIndicesBySpatialResolution(coor, 1, null);
            return coor[distributedIds[0]];
        }
        private void AddCellCenters(FeMesh mesh, VisualizationData visualization, int faceId,
                                    List<double[]> possibleCoor)
        {
            foreach (int cellId in visualization.CellIdsByFace[faceId])
            {
                int[] cell = visualization.Cells[cellId];
                int n;
                if (cell.Length == 3 || cell.Length == 6) n = 3;
                else if (cell.Length == 4 || cell.Length == 8) n = 4;
                else if (Debugger.IsAttached) throw new NotSupportedException();
                else continue;
                //
                double[] center = new double[3];
                for (int i = 0; i < n; i++)
                {
                    double[] coor = GetItemIdNodeCoor(mesh, cell[i]);
                    center[0] += coor[0];
                    center[1] += coor[1];
                    center[2] += coor[2];
                }
                center[0] /= n;
                center[1] /= n;
                center[2] /= n;
                possibleCoor.Add(center);
            }
        }
        private void DrawPartId(BasePart part, List<double[]> positions, List<string> labels)
        {
            double[] coor = GetPartAnchorPoint(part.PartId);
            if (coor != null) AddItemIdLabel("P" + part.PartId, coor, positions, labels);
        }
        private void DrawPartName(BasePart part, List<double[]> positions, List<string> labels)
        {
            double[] coor = GetPartAnchorPoint(part.PartId);
            if (coor != null)
            {
                positions.Add(coor);
                labels.Add(part.Name);
            }
        }
        public double[] GetPartCenterOfGravity(int partId)
        {
            return GetPartCenterOfGravity(partId, out _);
        }
        private double[] GetPartCenterOfGravity(int partId, out Dictionary<int, FeNode> displayedNodes)
        {
            displayedNodes = null;
            //
            FeMesh mesh = DisplayedMesh;
            BasePart part = mesh?.GetPartFromId(partId);
            if (part == null) return null;
            //
            double[] coor = null;
            if (_currentView == ViewGeometryModelResults.Results &&
                part.NodeLabels != null && part.NodeLabels.Length > 0)
            {
                FeNode[] scaledNodes = GetScaledNodes(GetScale(), part.NodeLabels);
                Dictionary<int, FeNode> nodes = new Dictionary<int, FeNode>();
                for (int i = 0; i < scaledNodes.Length; i++) nodes.Add(scaledNodes[i].Id, scaledNodes[i]);
                coor = mesh.ComputeVolumeArea(part, nodes).CenterOfMass;
                displayedNodes = nodes;
            }
            else if (part.MassProperties.CenterOfMass != null)
            {
                coor = part.MassProperties.CenterOfMass.ToArray();
                if (part.Offset != null)
                {
                    coor[0] += part.Offset[0];
                    coor[1] += part.Offset[1];
                    coor[2] += part.Offset[2];
                }
            }
            //
            if (coor == null && part.BoundingBox != null) coor = part.BoundingBox.GetCenter();
            return coor;
        }
        public double[] GetPartAnchorPoint(int partId)
        {
            FeMesh mesh = DisplayedMesh;
            BasePart part = mesh?.GetPartFromId(partId);
            if (part == null) return null;
            //
            Dictionary<int, FeNode> displayedNodes;
            double[] center = GetPartCenterOfGravity(partId, out displayedNodes);
            if (center == null) return null;
            //
            int[][] cells = part.Visualization?.Cells;
            if (cells == null || cells.Length == 0) return center;
            // The mesh node coordinates do not contain the exploded view offset, the center of gravity does
            double[] offset = null;
            if (displayedNodes == null && part.Offset != null &&
                (part.Offset[0] != 0 || part.Offset[1] != 0 || part.Offset[2] != 0)) offset = part.Offset;
            //
            double[][] triangle = new double[3][];
            double[] triangleClosestPoint = new double[3];
            double[] closestPoint = null;
            double minDistance = double.MaxValue;
            //
            foreach (int[] cell in cells)
            {
                int cornerCount;
                if (cell.Length == 3 || cell.Length == 6) cornerCount = 3;
                else if (cell.Length == 4 || cell.Length == 8) cornerCount = 4;
                else continue;
                //
                double[][] cornerCoor = new double[cornerCount][];
                bool allCornersFound = true;
                for (int i = 0; i < cornerCount; i++)
                {
                    cornerCoor[i] = GetPartAnchorNodeCoor(mesh, displayedNodes, offset, cell[i]);
                    if (cornerCoor[i] == null) { allCornersFound = false; break; }
                }
                if (!allCornersFound) continue;
                //
                for (int i = 0; i < cornerCount - 2; i++)
                {
                    triangle[0] = cornerCoor[0];
                    triangle[1] = cornerCoor[i + 1];
                    triangle[2] = cornerCoor[i + 2];
                    //
                    Geometry.PointToTriangleClosestPoint(center, triangle, ref triangleClosestPoint);
                    double distance = Geometry.VdistV2(center, triangleClosestPoint);
                    if (distance < minDistance)
                    {
                        minDistance = distance;
                        closestPoint = triangleClosestPoint.ToArray();
                    }
                }
            }
            //
            if (closestPoint == null) return center;
            return closestPoint;
        }
        private double[] GetPartAnchorNodeCoor(FeMesh mesh, Dictionary<int, FeNode> displayedNodes,
                                               double[] offset, int nodeId)
        {
            double[] coor;
            if (displayedNodes != null)
            {
                if (!displayedNodes.TryGetValue(nodeId, out FeNode node)) return null;
                coor = node.Coor;
            }
            else
            {
                if (!mesh.Nodes.TryGetValue(nodeId, out FeNode node)) return null;
                coor = node.Coor;
            }
            //
            if (offset == null) return coor;
            return new double[] { coor[0] + offset[0], coor[1] + offset[1], coor[2] + offset[2] };
        }
        private void DrawNodeIds(FeMesh mesh, List<double[]> positions, List<string> labels)
        {
            HashSet<int> nodeIds = new HashSet<int>();
            foreach (var entry in mesh.Parts)
            {
                BasePart part = entry.Value;
                VisualizationData visualization = part.Visualization;
                if (IsPartVisibleForItemIds(part) && visualization?.Cells != null)
                    nodeIds.UnionWith(visualization.GetNodeIds());
            }
            //
            foreach (int nodeId in nodeIds)
                AddItemIdLabel("N" + nodeId, GetItemIdNodeCoor(mesh, nodeId), positions, labels);
        }
        private void DrawElementIds(FeMesh mesh, List<double[]> positions, List<string> labels)
        {
            HashSet<int> elementIds = new HashSet<int>();
            foreach (var entry in mesh.Parts)
            {
                BasePart part = entry.Value;
                VisualizationData visualization = part.Visualization;
                if (IsPartVisibleForItemIds(part) && visualization?.CellIds != null)
                    elementIds.UnionWith(visualization.CellIds);
            }
            //
            foreach (int elementId in elementIds)
            {
                if (!mesh.Elements.TryGetValue(elementId, out FeElement element)) continue;
                double[] coor = element.GetCG(mesh.Nodes, out _);
                AddItemIdLabel("E" + elementId, coor, positions, labels);
            }
        }
        private bool TryGetSurfaceGeometryType(BasePart part, out GeometryType geometryType)
        {
            if (part.PartType == PartType.Shell || part.PartType == PartType.SolidAsShell)
            {
                geometryType = GeometryType.ShellFrontSurface;
                return true;
            }
            else if (part.PartType == PartType.Solid)
            {
                geometryType = GeometryType.SolidSurface;
                return true;
            }
            else
            {
                geometryType = GeometryType.Unknown;
                return false;
            }
        }
        private double[] GetItemIdNodeCoor(FeMesh mesh, int nodeId)
        {
            if (_currentView == ViewGeometryModelResults.Results)
                return GetScaledNode(GetScale(), nodeId).Coor;
            else
                return mesh.Nodes[nodeId].Coor;
        }
        private void AddItemIdLabel(string itemId, double[] coor, List<double[]> positions, List<string> labels)
        {
            positions.Add(coor);
            labels.Add(itemId);
        }
        // Symbols
        public void SetSymbolsName(string symbolName)
        {
            _drawSymbolName = symbolName;
        }
        public void DrawSymbols(string symbolName, bool updateHighlight)
        {
            if (symbolName != _drawSymbolName)
            {
                _drawSymbolName = symbolName;
                // Prevent the symbols from showing up first at: File open -> Regenerate tree
                if (!_form.IsStateOpening())
                {
                    if (_currentView == ViewGeometryModelResults.Model) RedrawModelSymbols(updateHighlight);
                    else if (_currentView == ViewGeometryModelResults.Results) RedrawResultSymbols(updateHighlight);
                }
            }
        }
        public string GetDrawSymbolsForStep()
        {
            return _drawSymbolName;
        }
        public void DrawModelSymbols()
        {
            if (_currentView != ViewGeometryModelResults.Model || _disableDrawSymbols) return;
            //
            if (_drawSymbolName != null && _drawSymbolName != Globals.SymbolNone)
            {
                DrawAllReferencePoints();
                DrawAllCoordinateSystems();
                DrawAllConstraints();
                DrawAllContactPairs();
                DrawAllInitialConditions();
                //
                if (_drawSymbolName != Globals.SymbolModel)
                {
                    DrawAllBoundaryConditions(_drawSymbolName);
                    DrawAllLoads(_drawSymbolName);
                    DrawAllDefinedFields(_drawSymbolName);
                }
            }
            // Update color legend
            AnnotateWithColorLegend();
            //
            _form.AdjustCameraDistanceAndClipping();
        }
        public void DrawResultSymbols()
        {
            if (_currentView != ViewGeometryModelResults.Results || _disableDrawSymbols) return;
            //
            if (_drawSymbolName != null && _drawSymbolName != Globals.SymbolNone)
            {
                DrawAllReferencePoints();
                DrawAllCoordinateSystems();
            }
            //
            _form.AdjustCameraDistanceAndClipping();
        }
        public void RedrawModelSymbols(bool updateHighlights = true)
        {
            try
            {
                // Clear all but parts
                if (_currentView != ViewGeometryModelResults.Model || _model == null || _model.Mesh == null) return;
                //
                _form.ClearButKeepParts();
                //
                try
                {
                    // Must be inside to continue screen update
                    if (_currentView != ViewGeometryModelResults.Model) CurrentView = ViewGeometryModelResults.Model;
                    DrawModelSymbols();
                    DrawItemIds();
                    ResetSectionView();
                }
                catch { }
                //
                if (updateHighlights) UpdateTreeSelection();
                _form.AdjustCameraDistanceAndClipping();
            }
            catch
            {
                // do not throw an error - it might cancel a procedure
            }
        }
        public void RedrawResultSymbols(bool updateHighlights = true)
        {
            try
            {

                if (_currentView != ViewGeometryModelResults.Results || _allResults.CurrentResult == null ||
                    _allResults.CurrentResult.Mesh == null || _allResults.CurrentResult.Mesh.Parts.Count == 0) return;
                // Clear
                _form.ClearButKeepParts();
                //
                try
                {
                    // Must be inside to continue screen update
                    if (_currentView != ViewGeometryModelResults.Results) CurrentView = ViewGeometryModelResults.Results;
                    DrawResultSymbols();
                    DrawItemIds();
                    ResetSectionView();
                }
                catch { }
                //
                if (updateHighlights) UpdateTreeSelection();
                _form.AdjustCameraDistanceAndClipping();
            }
            catch
            {
                // do not throw an error - it might cancel a procedure
            }
        }
        // Reference points
        public void DrawAllReferencePoints()
        {
            FeMesh mesh = DisplayedMesh;
            vtkRendererLayer layer = vtkRendererLayer.Overlay;
            //
            foreach (var entry in mesh.ReferencePoints)
            {
                DrawReferencePoint(entry.Value, entry.Value.Color, layer);
            }
        }
        public void DrawReferencePoint(FeReferencePoint referencePoint, Color color, vtkRendererLayer layer)
        {
            try
            {
                if (!((referencePoint.Active && referencePoint.Visible && referencePoint.Valid &&
                      !referencePoint.Internal) || layer == vtkRendererLayer.Selection)) return;
                //
                int nodeSize = _settings.Pre.NodeSymbolSize + 5;
                nodeSize = (int)(nodeSize * _settings.Pre.SymbolSize / 50.0);  // 50 is the default size
                //
                Color colorBorder = Color.Black;
                //
                double[][] coor = new double[][] { referencePoint.Coor() };
                // Draw the larger circle
                DrawNodes(referencePoint.Name + Globals.NameSeparator + "Border", coor, colorBorder, layer, nodeSize,
                          false, false);
                // Draw the smaller circle
                if (layer != vtkRendererLayer.Selection)
                    DrawNodes(referencePoint.Name, coor, color, layer, nodeSize - 3, false, false);
                // Name
                if (referencePoint.NameVisible)
                {
                    int symbolSize = _settings.Pre.SymbolSize;
                    double fontScaleFactor = 0.9 * symbolSize / 50d;
                    string caption = referencePoint.Name.Replace('-', ' ').Replace('_', ' ');
                    _form.AddCaptionActor("RP" + Globals.NameSeparator + referencePoint.Name + "_name", caption, Color.Black,
                                          coor[0], null, fontScaleFactor, layer);
                }
            }
            catch { } // do not show the exception to the user
        }
        // Coordinate systems
        public void DrawAllCoordinateSystems()
        {
            FeMesh mesh = DisplayedMesh;
            vtkRendererLayer layer = vtkRendererLayer.Overlay;
            //
            foreach (var entry in mesh.CoordinateSystems)
            {
                DrawCoordinateSystem(entry.Value, layer);
            }
        }
        public void DrawCoordinateSystem(CoordinateSystem coordinateSystem, vtkRendererLayer layer)
        {
            try
            {
                if (!((coordinateSystem.Active && coordinateSystem.Visible && coordinateSystem.Valid &&
                      !coordinateSystem.Internal) || layer == vtkRendererLayer.Selection)) return;
                //
                int symbolSize = _settings.Pre.SymbolSize;
                double fontScaleFactor = 0.9 * symbolSize / 50d;
                Color color = Color.Black;
                string[] labels;
                if (coordinateSystem.Type == CoordinateSystemTypeEnum.Cylindrical)
                    labels = new string[] { "R", "T", "Z" };
                else labels = new string[] { "X", "Y", "Z" };
                //
                double[] origin = coordinateSystem.Center().Coor;
                double[][] axisDirections = new double[][] { coordinateSystem.DirectionX().Coor,
                                                             coordinateSystem.DirectionY().Coor,
                                                             coordinateSystem.DirectionZ().Coor };
                _form.AddCoordinateSystemSymbol(origin, axisDirections, labels, symbolSize, layer);
                // Name
                if (coordinateSystem.NameVisible)
                {
                    string caption = coordinateSystem.Name.Replace('-', ' ').Replace('_', ' ');
                    _form.AddCaptionActor("CS" + Globals.NameSeparator + coordinateSystem.Name + "_name", caption, color,
                                          origin, null, fontScaleFactor, layer);
                }
                //
                _form.AdjustCameraDistanceAndClipping();
            }
            catch { } // do not show the exception to the user
        }
        // Constraints
        public void DrawAllConstraints()
        {
            int symbolSize = _settings.Pre.SymbolSize;
            int nodeSymbolSize = _settings.Pre.NodeSymbolSize;
            vtkRendererLayer layer = vtkRendererLayer.Base;
            //
            foreach (var entry in _model.Constraints)
            {
                DrawConstraint(entry.Value, entry.Value.MasterColor, entry.Value.SlaveColor, symbolSize,
                               nodeSymbolSize, layer, true);
            }
        }
        public void DrawConstraint(Constraint constraint, Color masterColor, Color slaveColor, int symbolSize,
                                   int nodeSymbolSize, vtkRendererLayer layer, bool onlyVisible)
        {
            try
            {
                if (!((constraint.Active && constraint.Visible && constraint.Valid && !constraint.Internal) ||
                      layer == vtkRendererLayer.Selection)) return;
                //
                double[][] coor = null;
                string prefixName = "CONSTRAINT" + Globals.NameSeparator + constraint.Name;
                vtkRendererLayer symbolLayer = layer == vtkRendererLayer.Selection ? layer : vtkRendererLayer.Overlay;
                //
                int count = 0;
                if (constraint is PointSpring ps)
                {
                    // Node set
                    if (ps.RegionType == RegionTypeEnum.NodeSetName)
                    {
                        if (!_model.Mesh.NodeSets.ContainsKey(ps.RegionName)) return;
                        FeNodeSet nodeSet = _model.Mesh.NodeSets[ps.RegionName];
                        if (nodeSet.Labels.Length < 10)
                        {
                            coor = new double[nodeSet.Labels.Length][];
                            for (int i = 0; i < nodeSet.Labels.Length; i++) coor[i] = _model.Mesh.Nodes[nodeSet.Labels[i]].Coor;
                        }
                        else coor = new double[][] { nodeSet.CenterOfGravity };
                        //
                        count += DrawNodeSet(prefixName, ps.MasterRegionName, masterColor, layer, true, nodeSymbolSize,
                                             false, onlyVisible);
                    }
                    else if (ps.RegionType == RegionTypeEnum.ReferencePointName)
                    {
                        if (!_model.Mesh.ReferencePoints.ContainsKey(ps.RegionName)) return;
                        FeReferencePoint referencePoint = _model.Mesh.ReferencePoints[ps.RegionName];
                        coor = new double[1][];
                        coor[0] = referencePoint.Coor();
                        count++;
                    }
                    else throw new NotSupportedException();
                    // Symbol
                    if (count > 0) DrawSpringSymbols(prefixName, ps, coor, masterColor, symbolSize, symbolLayer);
                }
                else if (constraint is SurfaceSpring ss)
                {
                    // Surface
                    if (ss.RegionType == RegionTypeEnum.SurfaceName)
                    {
                        if (!_model.Mesh.Surfaces.ContainsKey(ss.RegionName)) return;
                        coor = new double[1][];
                        coor[0] = _model.Mesh.GetSurfaceCG(ss.RegionName);
                        //
                        count += DrawSurface(prefixName, ss.RegionName, masterColor, layer, true, false, onlyVisible);
                        if (layer == vtkRendererLayer.Selection)
                            DrawSurfaceEdge(prefixName, ss.RegionName, masterColor, layer, true, false, onlyVisible);
                    }
                    else throw new NotSupportedException();
                    // Symbol
                    if (count > 0) DrawSpringSymbols(prefixName, ss, coor, masterColor, symbolSize, symbolLayer);
                }
                else if (constraint is CompressionOnly co)
                {
                    if (!_model.Mesh.Surfaces.ContainsKey(co.MasterRegionName)) return;
                    //
                    count += DrawSurface(prefixName, co.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    if (layer == vtkRendererLayer.Selection)
                        DrawSurfaceEdge(prefixName, co.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    //
                    if (count > 0)
                    {
                        // 2D
                        //if (co.TwoD)
                        //    DrawShellEdgeLoadSymbols(prefixName, dLoad.SurfaceName, dLoad.Magnitude.Value,
                        //                             color, symbolSize, layer);
                        // 3D
                        //else 
                        DrawCompressionOnlySymbols(prefixName, co, masterColor, symbolSize, layer, onlyVisible);
                    }
                }
                else if (constraint is RigidBody rb)
                {
                    // Master
                    // Only draw reference point during highlight
                    if (layer == vtkRendererLayer.Selection)
                    {
                        if (_model.Mesh.ReferencePoints.ContainsKey(rb.ReferencePointName))
                            DrawReferencePoint(_model.Mesh.ReferencePoints[rb.ReferencePointName], masterColor, layer);
                    }
                    // Slave
                    if (rb.RegionType == RegionTypeEnum.NodeSetName)
                        count += DrawNodeSet(prefixName, rb.RegionName, masterColor, layer, true, nodeSymbolSize,
                                             true, onlyVisible);
                    else if (rb.RegionType == RegionTypeEnum.SurfaceName)
                    {
                        count += DrawSurface(prefixName, rb.RegionName, masterColor, layer, true, true, onlyVisible);
                        if (layer == vtkRendererLayer.Selection)
                            DrawSurfaceEdge(prefixName, rb.RegionName, masterColor, layer, true, true, onlyVisible);
                    }
                    else throw new NotSupportedException();
                    // Symbol
                    if (count > 0)
                    {
                        DrawRigidBodySymbol(rb, masterColor, symbolLayer, onlyVisible);
                    }
                }
                else if (constraint is Coupling coupling)
                {
                    // Master
                    // Only draw reference point during highlight
                    if (layer == vtkRendererLayer.Selection)
                    {
                        if (_model.Mesh.ReferencePoints.ContainsKey(coupling.ReferencePointName))
                            DrawReferencePoint(_model.Mesh.ReferencePoints[coupling.ReferencePointName], masterColor, layer);
                    }
                    // Slave
                    if (coupling.RegionType == RegionTypeEnum.NodeSetName)
                        count += DrawNodeSet(prefixName, coupling.RegionName, masterColor, layer, true, nodeSymbolSize,
                                             true, onlyVisible);
                    else if (coupling.RegionType == RegionTypeEnum.SurfaceName)
                    {
                        count += DrawSurface(prefixName, coupling.RegionName, masterColor, layer, true, true, onlyVisible);
                        if (layer == vtkRendererLayer.Selection)
                            DrawSurfaceEdge(prefixName, coupling.RegionName, masterColor, layer, true, true, onlyVisible);
                    }
                    else throw new NotSupportedException();
                    // Symbol
                    if (count > 0)
                    {
                        DrawCouplingSymbol(coupling, masterColor, symbolLayer, onlyVisible);
                    }
                }
                else if (constraint is Tie tie)
                {
                    // Master
                    count += DrawSurface(prefixName, tie.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    if (layer == vtkRendererLayer.Selection)
                        DrawSurfaceEdge(prefixName, tie.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    // Slave
                    count += DrawSurface(prefixName, tie.SlaveRegionName, slaveColor, layer, true, true, onlyVisible);
                    if (layer == vtkRendererLayer.Selection)
                        DrawSurfaceEdge(prefixName, tie.SlaveRegionName, slaveColor, layer, true, true, onlyVisible);
                    //
                    if (tie is CyclicSymmetry cyclicSymmetry)
                        DrawCyclicSymmetryAxisSymbol(prefixName + Globals.NameSeparator + "Axis", cyclicSymmetry,
                                                      masterColor, symbolSize, symbolLayer);
                }
                else if (constraint is Joint joint)
                {
                    // Master
                    count += DrawSurface(prefixName, joint.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    if (layer == vtkRendererLayer.Selection)
                        DrawSurfaceEdge(prefixName, joint.MasterRegionName, masterColor, layer, true, false, onlyVisible);
                    // Slave
                    count += DrawSurface(prefixName, joint.SlaveRegionName, slaveColor, layer, true, true, onlyVisible);
                    if (layer == vtkRendererLayer.Selection)
                        DrawSurfaceEdge(prefixName, joint.SlaveRegionName, slaveColor, layer, true, true, onlyVisible);
                    //
                    if (count > 0)
                        DrawJointSymbol(prefixName + Globals.NameSeparator + "Joint", joint, masterColor, symbolSize,
                                        symbolLayer);
                }
                else throw new NotSupportedException();
            }
            catch { } // do not show the exception to the user
        }
        public void DrawJointSymbol(string prefixName, Joint joint, Color color, int symbolSize, vtkRendererLayer layer)
        {
            double[] center;
            double[] axis;
            if (!_model.TryGetJointCenterAndAxis(joint, out center, out axis)) return;
            //
            vtkJointSymbolEnum symbol;
            if (joint.JointType == JointTypeEnum.Hinge) symbol = vtkJointSymbolEnum.Hinge;
            else if (joint.JointType == JointTypeEnum.Cylindrical) symbol = vtkJointSymbolEnum.Cylindrical;
            else if (joint.JointType == JointTypeEnum.Slider) symbol = vtkJointSymbolEnum.Slider;
            else if (joint.JointType == JointTypeEnum.Ball) symbol = vtkJointSymbolEnum.Ball;
            else if (joint.JointType == JointTypeEnum.Weld) symbol = vtkJointSymbolEnum.Weld;
            else throw new NotSupportedException();
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = prefixName;
            data.Color = color;
            data.Layer = layer;
            data.Geometry.Nodes.Coor = new double[][] { center };
            data.Geometry.Nodes.Normals = new double[][] { axis != null ? axis : new double[] { 0, 0, 1 } };
            ApplyLighting(data);
            _form.AddOrientedJointActor(data, symbolSize, symbol);
        }
        public void DrawRigidBodySymbol(RigidBody rigidBody, Color color, vtkRendererLayer layer,
                                        bool onlyVisible)
        {
            int[][] cells;
            int[] cellsTypes;
            bool[] nodeVisibilities;
            double[][] nodeCoor;
            double[][] distributedNodeCoor;
            bool canHaveEdges = false;
            //
            FeReferencePoint rp;
            if (!_model.Mesh.ReferencePoints.TryGetValue(rigidBody.ReferencePointName, out rp)) return;
            if (onlyVisible && !rp.Visible) return;
            // Node set
            string nodeSetName;
            if (rigidBody.RegionType == RegionTypeEnum.NodeSetName) nodeSetName = rigidBody.RegionName;
            else if (rigidBody.RegionType == RegionTypeEnum.SurfaceName) nodeSetName = _model.Mesh.Surfaces[rigidBody.RegionName].NodeSetName;
            else throw new NotSupportedException();
            //
            if (nodeSetName != null && _model.Mesh.NodeSets.ContainsKey(nodeSetName))
            {
                FeNodeSet nodeSet = _model.Mesh.NodeSets[nodeSetName];
                if (nodeSet.Labels.Length == 0) return;     // after remeshing this is 0 before the node set update
                // Node visibilities
                if (onlyVisible) nodeVisibilities = _model.Mesh.GetNodeVisibilities(nodeSet.Labels);
                else nodeVisibilities = null;
                // All nodes
                nodeCoor = _model.Mesh.GetNodeSetCoor(nodeSet.Labels);
                // If all nodes are hidden
                if (nodeCoor == null || nodeCoor.Length == 0) return;
                // Ids go from 0 to Length
                int[] visibleIds = SpatialPointSampler.GetSampleIndicesBySpatialResolution(nodeCoor, 3, nodeVisibilities);
                // Distributed nodes
                distributedNodeCoor = new double[visibleIds.Length][];
                for (int i = 0; i < visibleIds.Length; i++) distributedNodeCoor[i] = nodeCoor[visibleIds[i]];
                // Create wire elements
                // Distributed coor +1 for reference point
                nodeCoor = new double[visibleIds.Length + 1][];
                nodeCoor[0] = rp.Coor();
                Array.Copy(distributedNodeCoor, 0, nodeCoor, 1, distributedNodeCoor.Length);
                //
                cells = new int[visibleIds.Length][];
                cellsTypes = new int[visibleIds.Length];
                LinearBeamElement element = new LinearBeamElement(0, null);
                for (int i = 0; i < visibleIds.Length; i++)
                {
                    cells[i] = new int[] { 0, i + 1 };
                    cellsTypes[i] = element.GetVtkCellType();
                }
                //
                if (cells.Length > 0)
                {
                    vtkMaxActorData data = new vtkMaxActorData();
                    data.Name = rigidBody.Name + "_lines";
                    data.Color = color;
                    data.Layer = layer;
                    data.CanHaveElementEdges = canHaveEdges;
                    data.Pickable = false;
                    data.ActorRepresentation = vtkMaxActorRepresentation.Wire;
                    data.Geometry.Nodes.Ids = null;
                    data.Geometry.Nodes.Coor = nodeCoor.ToArray();
                    data.Geometry.Cells.CellNodeIds = cells;
                    data.Geometry.Cells.Types = cellsTypes;
                    ApplyLighting(data);
                    _form.Add3DCells(data);
                }
            }
        }
