        public void HighlightMeshSetupItem(string meshSetupItemName)
        {
            MeshSetupItem meshSetupItem;
            //
            meshSetupItem = _model.Geometry.MeshSetupItems[meshSetupItemName];
            HighlightMeshSetupItem(meshSetupItem);
