        public void HighlightMeshSetupItem(MeshSetupItem meshSetupItem, bool highlightNodes = true,
                                           bool useSecondaryHighlightColor = false)
        {
            if (meshSetupItem is MeshingParameters || meshSetupItem is ShellMmg ||
                meshSetupItem is ShellGmsh || meshSetupItem is ShellQuadWild ||
                meshSetupItem is ThickenShellMesh || meshSetupItem is NetgenMesh ||
                meshSetupItem is TetrahedralGmsh || meshSetupItem is TransfiniteMesh)
                HighlightMeshSetupItemParts(meshSetupItem, useSecondaryHighlightColor);
            else if (meshSetupItem is LocalMeshSize lms) HighlightLocalMeshSize(lms, highlightNodes, useSecondaryHighlightColor);
            else if (meshSetupItem is ExtrudeMesh em) HighlightExtrudeMesh(em, useSecondaryHighlightColor);
            else if (meshSetupItem is SweepMesh sm) HighlightSweepMesh(sm, useSecondaryHighlightColor);
            else if (meshSetupItem is RevolveMesh rm) HighlightRevolveMesh(rm, useSecondaryHighlightColor);
            else throw new NotSupportedException();
        }
        // A hidden part shows nothing of itself, so a mesh setup item highlights only the parts on display
        public void HighlightMeshSetupItemParts(MeshSetupItem meshSetupItem, bool useSecondaryHighlightColor = false)
        {
            HashSet<int> selectedPartIds = new HashSet<int>(meshSetupItem.CreationIds);
            if (selectedPartIds.Count > 0)
            {
                string[] partNames = _model.Geometry.GetPartNamesFromPartIds(selectedPartIds.ToArray());
                HighlightGeometryParts(partNames, true);
            }
        }
        public void HighlightLocalMeshSize(LocalMeshSize localMeshSize, bool highlightNodes = true, 
                                           bool useSecondaryHighlightColor = false)
        {
            int[] ids;
            int[] itemTypePartIds;
            double[][] coor;
            double meshSize = -1;
            int numOfElements = -1;
            bool backfaceCulling;
            GeometryPart part;
            FeMesh mesh = DisplayedMesh;
            MeshingParameters meshingParameters;
            //
            ids = localMeshSize.CreationIds;
            if (ids.Length == 0) return;
            // The selection is limited to one part
            itemTypePartIds = FeMesh.GetItemTypePartIdsFromGeometryId(ids[0]);
            part = (GeometryPart)mesh.GetPartFromId(itemTypePartIds[2]);
            if (part == null) return;
            //
            meshingParameters = GetPartMeshingParameters(part.Name);
            //
            if (localMeshSize.Type == LocalMeshSizeTypeEnum.ElementSize) meshSize = localMeshSize.MeshSize;
            else if (localMeshSize.Type == LocalMeshSizeTypeEnum.NumberOfElements) numOfElements = localMeshSize.NumOfElements;
            //
            mesh.GetLocalMeshSizeCoor(ids, meshSize, numOfElements, out coor);
            if (highlightNodes) HighlightNodes(coor, useSecondaryHighlightColor);
            //
            backfaceCulling = part.PartType != PartType.Shell;
            //
            HighlightItemsByGeometryIds(ids, backfaceCulling, useSecondaryHighlightColor);
        }
        public void HighlightShellInMeshSetupItem(MeshSetupItem meshSetupItem, bool useSecondaryHighlightColor = false)
        {
            int[] ids = meshSetupItem.CreationIds;
            if (ids.Length == 0) return;
            // The selection is limited to one part
            int partId = FeMesh.GetPartIdFromGeometryId(ids[0]);
            BasePart part = (GeometryPart)_model.Geometry.GetPartFromId(partId);
            if (part == null) return;
            //
            bool backfaceCulling = part.PartType != PartType.Shell;
            //
            HighlightItemsByGeometryIds(ids, backfaceCulling, false, true);
        }
        public void HighlightExtrudeMesh(ExtrudeMesh extrudeMesh, bool useSecondaryHighlightColor = false)
        {
            HighlightShellInMeshSetupItem(extrudeMesh, useSecondaryHighlightColor);
            //
            string prefixName = extrudeMesh.Name + Globals.NameSeparator + "Arrows";
            if (extrudeMesh.ExtrudeCenter != null && extrudeMesh.Direction != null)
            {
                int symbolSize = 2 * _settings.Pre.SymbolSize;
                DrawArrowSymbols(prefixName, new double[][] { extrudeMesh.ExtrudeCenter },
                                 new double[][] { extrudeMesh.Direction }, Color.Empty, symbolSize,
                                 vtkRendererLayer.Selection, !useSecondaryHighlightColor);
            }
        }
        public void HighlightSweepMesh(SweepMesh sweepMesh, bool useSecondaryHighlightColor = false)
        {
            // Every surface the sweep starts from is worth seeing, the ones found automatically as well as the
            // ones the selection of a single surface reaches, together with an arrow per block for the
            // direction it is swept in. Until the blocks are known only the selection itself can be shown
            if (sweepMesh.BlockSourceSurfaceIds == null || sweepMesh.BlockSourceSurfaceIds.Length == 0)
            {
                // A sweep that finds its own sources is selected by part, and the ids of a part selection are
                // part ids carrying no geometry type at all, so they are shown the way every part selection is
                if (sweepMesh.SourceType == SweepSourceTypeEnum.Automatic)
                    HighlightMeshSetupItemParts(sweepMesh, useSecondaryHighlightColor);
                else HighlightShellInMeshSetupItem(sweepMesh, useSecondaryHighlightColor);
                return;
            }
            //
            List<int> geometryIds = new List<int>();
            foreach (var blockSourceSurfaceIds in sweepMesh.BlockSourceSurfaceIds)
            {
                foreach (var gmshTopologyId in blockSourceSurfaceIds)
                {
                    geometryIds.Add(FeMesh.GetGeometryId(FeMesh.GetItemIdFromGmshTopologyId(gmshTopologyId),
                                                         (int)GeometryType.SolidSurface,
                                                         FeMesh.GetPartIdFromGmshTopologyId(gmshTopologyId)));
                }
            }
            // The source surfaces filled. The visualization of a CAD part is a shell of two dimensional cells
            // and a solid surface resolves to their back side, whose winding points into the solid, so the
            // faces are drawn without backface culling or nothing of them is drawn at all. A sweep spans as
            // many parts as it has blocks and the hidden ones among them show nothing of their surfaces
            HighlightItemsByGeometryIds(geometryIds.ToArray(), false, useSecondaryHighlightColor, true);
            //
            if (sweepMesh.BlockArrowStarts == null || sweepMesh.BlockArrowDirections == null) return;
            //
            List<double[]> starts = new List<double[]>();
            List<double[]> directions = new List<double[]>();
            for (int i = 0; i < sweepMesh.BlockArrowStarts.Length; i++)
            {
                if (sweepMesh.BlockArrowStarts[i] == null || sweepMesh.BlockArrowDirections[i] == null) continue;
                // The exploded view moves every sub-part by its own offset
                BasePart part = _model.Geometry.GetPartFromId(
                    FeMesh.GetPartIdFromGmshTopologyId(sweepMesh.BlockSourceSurfaceIds[i][0]));
                // The block of a hidden part is not on display and neither is the arrow of its sweep direction
                if (part != null && !part.Visible) continue;
                double[] offset = part != null ? part.Offset : new double[3];
                starts.Add(new double[] { sweepMesh.BlockArrowStarts[i][0] + offset[0],
                                          sweepMesh.BlockArrowStarts[i][1] + offset[1],
                                          sweepMesh.BlockArrowStarts[i][2] + offset[2] });
                directions.Add(sweepMesh.BlockArrowDirections[i]);
            }
            if (starts.Count > 0)
            {
                string prefixName = sweepMesh.Name + Globals.NameSeparator + "Arrows";
                DrawArrowSymbols(prefixName, starts.ToArray(), directions.ToArray(), Color.Empty,
                                 _settings.Pre.SymbolSize, vtkRendererLayer.Selection, !useSecondaryHighlightColor);
            }
        }
        /// <summary>
        /// Highlights the surfaces and the edges the errors of the last meshing name, so that the user can find
        /// the one to select or split. They are parts of the geometry, which is shown only in its own view.
        /// </summary>
        public bool HighlightLastMeshingErrorGeometry()
        {
            if (_currentView != ViewGeometryModelResults.Geometry) return false;
            //
            int[] geometryIds = GetLastMeshingErrorGeometryIds();
            if (geometryIds.Length == 0) return false;
            // The parts that were being meshed are still highlighted, in the same color
            ClearAllSelection();
            // A solid surface is drawn without backface culling, as the sweep sources are
            HighlightItemsByGeometryIds(geometryIds, false, false, true);
            return true;
        }
        public int[] GetLastMeshingErrorGeometryIds()
        {
            List<int> geometryIds = new List<int>();
            foreach (var error in LastMeshingErrors)
                geometryIds.AddRange(MessageGeometryReferences.GetGeometryIds(error, _model.Geometry));
            return geometryIds.Distinct().ToArray();
        }
        /// <summary>
        /// Every name of a surface or an edge of the geometry in a line of text, as its start and its length, so
        /// that the output window can draw the names as links.
        /// </summary>
        public int[][] GetGeometryNameRanges(string text)
        {
            return MessageGeometryReferences.GetGeometryNameRanges(text, _model == null ? null : _model.Geometry);
        }
        /// <summary>
        /// Highlights the surface or the edge named at the given position of a line of text, in the geometry
        /// view, which is where it lies, so that a name in the output window can be followed to the geometry.
        /// </summary>
        public bool HighlightGeometryNamedAt(string text, int position)
        {
            int geometryId = MessageGeometryReferences.GetGeometryIdAt(text, position, _model.Geometry);
            if (geometryId < 0) return false;
            //
            CurrentView = ViewGeometryModelResults.Geometry;
            ClearAllSelection();
            HighlightItemsByGeometryIds(new int[] { geometryId }, false, false, true);
            return true;
        }
        /// <summary>
        /// Every report of the inverted elements of a part of the model mesh in a line of text, as its start and
        /// its length, so that the output window can draw the reports as links.
        /// </summary>
        public int[][] GetInvertedElementReferenceRanges(string text)
        {
            return MessageInvertedElements.GetReferenceRanges(text, _model == null ? null : _model.Mesh);
        }
        /// <summary>
        /// Highlights the inverted elements of the part reported at the given position of a line of text, found
        /// again on the mesh the part has now.
        /// </summary>
        public bool HighlightInvertedElementsNamedAt(string text, int position)
        {
            string partName = MessageInvertedElements.GetPartNameAt(text, position, _model.Mesh);
            if (partName == null) return false;
            //
            CurrentView = ViewGeometryModelResults.Model;
            ClearAllSelection();
            if (HighlightInvertedElements(new string[] { partName }) == 0)
                _form.WriteDataToOutput(partName + " has no inverted or degenerate elements.");
            return true;
        }
        public int HighlightInvertedElements(string[] partNames)
        {
            BasePart part;
            List<int> elementIds = new List<int>();
            foreach (string partName in partNames)
            {
                if (_model.Mesh.Parts.TryGetValue(partName, out part))
                    elementIds.AddRange(InvertedElements.GetElementIds(_model.Mesh, part));
            }
            if (elementIds.Count == 0) return 0;
            //
            HashSet<int> nodeIds = new HashSet<int>();
            foreach (int elementId in elementIds) nodeIds.UnionWith(_model.Mesh.Elements[elementId].NodeIds);
            HighlightElements(elementIds.ToArray());
            DrawNodes("Highlight", nodeIds.ToArray(), Color.Red, vtkRendererLayer.Selection, out _);
            return elementIds.Count;
        }
        public void HighlightRevolveMesh(RevolveMesh revolveMesh, bool useSecondaryHighlightColor = false)
        {
            HighlightShellInMeshSetupItem(revolveMesh, useSecondaryHighlightColor);
            //
            int[] ids = revolveMesh.CreationIds;
            if (ids.Length == 0) return;
            // The selection is limited to one part
            int partId = FeMesh.GetPartIdFromGeometryId(ids[0]);
            BasePart part = (GeometryPart)_model.Geometry.GetPartFromId(partId);
            if (part == null) return;
            //
            double[] offset = part.Offset;
            string prefixName = revolveMesh.Name + Globals.NameSeparator + "Arrows";
            if (revolveMesh.AxisCenter != null && revolveMesh.AxisDirection != null)
            {
                double[] axisCenter = new double[] {revolveMesh.AxisCenter[0] + offset[0],
                                                    revolveMesh.AxisCenter[1] + offset[1],
                                                    revolveMesh.AxisCenter[2] + offset[2]};
                int symbolSize = 2 * _settings.Pre.SymbolSize;
                DrawArrowSymbols(prefixName, new double[][] { axisCenter },
                                 new double[][] { revolveMesh.AxisDirection }, Color.Empty, symbolSize,
                                 vtkRendererLayer.Selection, !useSecondaryHighlightColor, true);
            }
        }
