            else if (resultHistoryOutput is ResultHistoryOutputFromAffineFit rhoaf) HighlightAffineFitRegion(rhoaf);
        }
        public void HighlightAffineFitRegion(ResultHistoryOutputFromAffineFit resultHistoryOutput)
        {
            FeResults currentResult = CurrentResult;
            if (currentResult == null || currentResult.Mesh == null) return;
            //
            FeMesh mesh = currentResult.Mesh;
            Dictionary<int, FeNode> undeformedNodes = currentResult.UndeformedNodes;
            if (undeformedNodes == null || undeformedNodes.Count == 0) return;
            //
            double planeZ = undeformedNodes.Values.First().Z;
            // Center point - secondary selection color
            double[] centerCoor = new double[] { resultHistoryOutput.CenterX, resultHistoryOutput.CenterY, planeZ };
            HighlightNodes(new double[][] { centerCoor }, true);
            // Outer radius circle, and the inner taper start circle if it differs from the outer one
            HighlightConnectedLines(GetAffineFitCirclePoints(resultHistoryOutput.CenterX, resultHistoryOutput.CenterY,
                resultHistoryOutput.Radius, planeZ), true);
            //
            if (resultHistoryOutput.TaperStartFraction < 1)
            {
                double taperRadius = resultHistoryOutput.TaperStartFraction * resultHistoryOutput.Radius;
                HighlightConnectedLines(GetAffineFitCirclePoints(resultHistoryOutput.CenterX, resultHistoryOutput.CenterY,
                    taperRadius, planeZ), true);
            }
            // Accepted fit points, evaluated on the undeformed geometry - primary selection color
            List<AffineFitPoint> points =
                AffineFitCalculator.BuildFitPoints(mesh, undeformedNodes, resultHistoryOutput, out _, out _);
            if (points.Count == 0) return;
            //
            if (resultHistoryOutput.PointSource == AffineFitPointSourceEnum.Nodes)
            {
                double[][] nodeCoor = new double[points.Count][];
                for (int i = 0; i < points.Count; i++)
                {
                    FeNode node = undeformedNodes[points[i].NodeIds[0]];
                    nodeCoor[i] = new double[] { node.X, node.Y, node.Z };
                }
                HighlightNodes(nodeCoor, false);
            }
            else
            {
                double[][][] cellEdges = new double[points.Count][][];
                double[][] centroidCoor = new double[points.Count][];
                for (int i = 0; i < points.Count; i++)
                {
                    AffineFitPoint point = points[i];
                    double[][] loop = new double[point.NodeIds.Length + 1][];
                    for (int j = 0; j < point.NodeIds.Length; j++)
                    {
                        FeNode node = undeformedNodes[point.NodeIds[j]];
                        loop[j] = new double[] { node.X, node.Y, node.Z };
                    }
                    loop[point.NodeIds.Length] = loop[0];
                    cellEdges[i] = loop;
                    centroidCoor[i] = new double[] { point.RefX, point.RefY, planeZ };
                }
                HighlightConnectedEdges(cellEdges, false);
                HighlightNodes(centroidCoor, false);
            }
        }
        private double[][] GetAffineFitCirclePoints(double centerX, double centerY, double radius, double z)
        {
            int circleSegmentCount = 96;
            double[][] circlePoints = new double[circleSegmentCount + 1][];
            for (int i = 0; i <= circleSegmentCount; i++)
            {
                double angle = 2 * Math.PI * i / circleSegmentCount;
                circlePoints[i] = new double[]
                {
                    centerX + radius * Math.Cos(angle),
                    centerY + radius * Math.Sin(angle),
                    z
                };
            }
            return circlePoints;
        }
        public void HighlightConnectedLines(double[][] lineNodeCoor, bool useSecondaryHighlightColor = false)
        {
            // Create wire elements
            Color color = Color.Red;
            vtkRendererLayer layer = vtkRendererLayer.Selection;
            //
            LinearBeamElement element = new LinearBeamElement(0, new int[] { 0, 1 });
            //
            int[][] cells = new int[lineNodeCoor.Length - 1][];
            int[] cellsTypes = new int[cells.Length];
            for (int i = 0; i < cells.Length; i++)
            {
                cells[i] = new int[] { i, i + 1 };
                cellsTypes[i] = element.GetVtkCellType();
            }
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Color = color;
            data.Layer = layer;
            data.Pickable = false;
            data.Geometry.Nodes.Ids = null;
            data.Geometry.Nodes.Coor = lineNodeCoor.ToArray();
            data.Geometry.Cells.CellNodeIds = cells;
            data.Geometry.Cells.Types = cellsTypes;
            data.UseSecondaryHighlightColor = useSecondaryHighlightColor;
            //
            ApplyLighting(data);
            _form.Add3DCells(data);
            //
            double[][] nodeCoor = new double[2][];
            nodeCoor[0] = lineNodeCoor[0];
            nodeCoor[1] = lineNodeCoor[lineNodeCoor.Length - 1];
            //
            //DrawNodes("short_edges", nodeCoor, color, layer, nodeSize);
        }
        public void HighlightLineWithArrow(double[] start, double[] end, bool startArrow, bool endArrow,
                                           bool useSecondaryHighlightColor = false, float width = 4)
        {
            // Create wire elements
            Color color = Color.Red;
            vtkRendererLayer layer = vtkRendererLayer.Selection;
            //
            LinearBeamElement element = new LinearBeamElement(0, new int[] { 0, 1 });
            //
            int[][] cells = new int[][] { new int[] { 0, 1 } };
            int[] cellsTypes = new int[] { element.GetVtkCellType() };
            //
            vtkMaxActorData data = new vtkMaxActorData();
            data.Name = "LineWithArrow";
            data.Color = color;
            data.Layer = layer;
            data.LineWidth = width;
            data.Pickable = false;
            data.Geometry.Nodes.Ids = null;
            data.Geometry.Nodes.Coor = new double[][] { start, end };
            data.Geometry.Cells.CellNodeIds = cells;
            data.Geometry.Cells.Types = cellsTypes;
            data.UseSecondaryHighlightColor = useSecondaryHighlightColor;
            //
            ApplyLighting(data);
            _form.Add3DCells(data);
            //
            List<double[]> points = new List<double[]>();
            List<double[]> normals = new List<double[]>();
            Vec3D normal = new Vec3D(end) - new Vec3D(start);
            normal.Normalize();
            //
            if (startArrow)
            {
                points.Add(start);
                normals.Add((normal * -1).Coor);
            }
            if (endArrow)
            {
                points.Add(end);
                normals.Add(normal.Coor);
            }
            if (points.Count > 0)
            {
                int symbolSize = _settings.Pre.SymbolSize;
                data = new vtkMaxActorData();
                data.Name = "LineWithArrowCones";
                data.Color = color;
                data.Layer = layer;
                data.Pickable = false;
                data.Geometry.Nodes.Ids = null;
                data.Geometry.Nodes.Coor = points.ToArray();
                data.Geometry.Nodes.Normals = normals.ToArray();
                data.UseSecondaryHighlightColor = useSecondaryHighlightColor;
                //
                ApplyLighting(data);
                _form.AddOrientedConeActors(data, symbolSize);
            }
            _form.AdjustCameraDistanceAndClipping();
        }
        public void DrawMeasurementAnnotation(string name, double[][] nodeCoordinates, double[][] lineCoordinates,
                                              bool drawEndArrows, bool visible)
        {
            if (nodeCoordinates == null || lineCoordinates == null || lineCoordinates.Length < 2) return;

            vtkMaxActorData nodeData = new vtkMaxActorData();
            nodeData.NodeSize = _settings.Pre.HighlightNodeSymbolSize;
            nodeData.Color = Color.Black;
            nodeData.Layer = vtkRendererLayer.Overlay;
            nodeData.Pickable = false;
            nodeData.Geometry.Nodes.Ids = null;
            nodeData.Geometry.Nodes.Coor = nodeCoordinates;
            ApplyLighting(nodeData);

            LinearBeamElement element = new LinearBeamElement(0, new int[] { 0, 1 });
            int[][] cells = new int[lineCoordinates.Length - 1][];
            int[] cellTypes = new int[cells.Length];
            for (int i = 0; i < cells.Length; i++)
            {
                cells[i] = new int[] { i, i + 1 };
                cellTypes[i] = element.GetVtkCellType();
            }

            vtkMaxActorData lineData = new vtkMaxActorData();
            lineData.LineWidth = 2;
            lineData.Color = Color.Black;
            lineData.Layer = vtkRendererLayer.Overlay;
            lineData.Pickable = false;
            lineData.Geometry.Nodes.Ids = null;
            lineData.Geometry.Nodes.Coor = lineCoordinates;
            lineData.Geometry.Cells.CellNodeIds = cells;
            lineData.Geometry.Cells.Types = cellTypes;
            ApplyLighting(lineData);

            GetMeasurementArrowData(lineCoordinates, drawEndArrows, out double[][] arrowCoordinates,
                                    out double[][] arrowNormals);
            _form.AddMeasurementAnnotation(name, nodeData, lineData, arrowCoordinates, arrowNormals,
                                           _settings.Pre.SymbolSize, visible);
        }
        public void UpdateMeasurementAnnotation(string name, double[][] nodeCoordinates, double[][] lineCoordinates,
                                                bool drawEndArrows, bool visible)
        {
            GetMeasurementArrowData(lineCoordinates, drawEndArrows, out double[][] arrowCoordinates,
                                    out double[][] arrowNormals);
            _form.UpdateMeasurementAnnotation(name, nodeCoordinates, lineCoordinates, arrowCoordinates,
                                              arrowNormals, visible);
        }
        private static void GetMeasurementArrowData(double[][] lineCoordinates, bool drawEndArrows,
                                                    out double[][] arrowCoordinates, out double[][] arrowNormals)
        {
            if (drawEndArrows && lineCoordinates != null && lineCoordinates.Length >= 2)
            {
                Vec3D direction = new Vec3D(lineCoordinates[lineCoordinates.Length - 1]) -
                                  new Vec3D(lineCoordinates[0]);
                direction.Normalize();
                arrowCoordinates = new double[][]
                {
                    lineCoordinates[0].ToArray(),
                    lineCoordinates[lineCoordinates.Length - 1].ToArray()
                };
                arrowNormals = new double[][]
                {
                    (-1 * direction).Coor,
                    direction.Coor
                };
            }
            else
            {
                arrowCoordinates = null;
                arrowNormals = null;
            }
        }
        // Transformations
        // A compound is drawn by its sub-parts, so the edges of a transformed compound are theirs
        private BasePart[] GetPartsDrawingEdges(FeMesh mesh, string[] partNames)
        {
            List<BasePart> parts = new List<BasePart>();
            foreach (var partName in partNames)
            {
                if (mesh.Parts[partName] is CompoundGeometryPart compoundPart)
                {
                    foreach (var subPartName in compoundPart.SubPartNames) parts.Add(mesh.Parts[subPartName]);
                }
                else parts.Add(mesh.Parts[partName]);
            }
            return parts.ToArray();
        }
        public void HighlightTranslatedEdges(string[] _partNames, double[] translateVector, int numCopies,
                                             bool useSecondaryHighlightColor = false)
        {
            Color color = Color.Red;
            vtkRendererLayer layer = vtkRendererLayer.Selection;
            //
            FeMesh mesh = DisplayedMesh;
            foreach (var part in GetPartsDrawingEdges(mesh, _partNames))
            {
                if (part.PartType.HasEdges() && part.Visualization.EdgeCells != null)
                {
                    vtkMaxActorData data = new vtkMaxActorData();
                    data.Color = color;
                    data.Layer = layer;
                    data.Pickable = false;
                    data.UseSecondaryHighlightColor = useSecondaryHighlightColor;
                    //
                    mesh.GetNodesAndCellsForModelEdges(part, out data.Geometry.Nodes.Ids, out data.Geometry.Nodes.Coor,
                                                       out data.Geometry.Cells.CellNodeIds, out data.Geometry.Cells.Types);
                    //
                    if (numCopies == -1) numCopies = 1;
                    for (int i = 0; i < numCopies; i++)
                    {
                        FeMesh.TranslatePoints(data.Geometry.Nodes.Coor, translateVector);
                        //
                        data.Name = "TranslatedEdges" + Globals.NameSeparator + i;
                        //
                        ApplyLighting(data);
                        _form.Add3DCells(data);
                    }
                }
                _form.AdjustCameraDistanceAndClipping();
            }
        }
