        #region Results  ###########################################################################################################
        public void DrawResults(bool resetCamera)
        {
            bool rendering = _form.RenderingOn;
            try
            {
                // Set the current view and call DrawResults
                if (_currentView != ViewGeometryModelResults.Results) CurrentView = ViewGeometryModelResults.Results;
                // Draw results
                else
                {
                    if (rendering) _form.RenderingOn = false;
                    _form.Clear3D();    // Removes section cut
                    ClearAnimationLocatorData();
                    //
                    if (_allResults.CurrentResult == null || _allResults.CurrentResult.Mesh == null) return;
                    if (_allResults.CurrentResult.GetAllComponentNames().Length == 0)
                        _viewResultsType = ViewResultsTypeEnum.Undeformed;
                    //
                    ApplyResultsUnitSystem();
                    // Settings - must be here before drawing parts to correctly set the numer of colors
                    SetPostLegendAndStatusBlockSettings();
                    AnnotateWithColorLegend();
                    //
                    float scale = GetScale();
                    SetStatusBlock(scale);
                    //
                    _allResults.CurrentResult.SetMeshDeformation(scale, _currentFieldData.StepId,
                                                                 _currentFieldData.StepIncrementId);
                    DrawAllResultParts(_currentFieldData, _settings.Post.UndeformedModelType,
                                       _settings.Post.UndeformedModelColor);
                    if (_viewResultsType == ViewResultsTypeEnum.VectorPlot) DrawVectorPlot(_currentFieldData);
                    else if (_viewResultsType == ViewResultsTypeEnum.TensorPlot) DrawTensorPlot(_currentFieldData);
                    // Transformation
                    ApplyTransformation();
                    // Symbols
                    DrawResultSymbols();
                    // Annotations
                    _annotations.DrawAnnotations();
                    // Item Ids
                    DrawItemIds();
                    // Section view
                    ApplySectionView();
                    // Follower view
                    _form.UpdateFollowerView();
                    // Selection
                    UpdateTreeSelection();
                    //
                    ApplyRotationPoint();
                    if (resetCamera) _form.SetFrontBackView(true, true); // animation:true is here to correctly draw max/min widgets 
                    //
                    _form.UpdateScalarsAndCameraAndRedraw();
                }
            }
            catch
            {
                // Do not throw an error - it might cancel a procedure
            }
            finally
            {
                if (rendering) _form.RenderingOn = true;
            }
        }
        private void DrawAllResultParts(FieldData fieldData, UndeformedModelTypeEnum undeformedModelType,
                                        Color undeformedModelColor)
        {
            vtkRendererLayer layer = vtkRendererLayer.Base;
            List<string> hiddenActors = new List<string>();
            //
            _form.InitializeResultWidgetPositions(); // reset the widget position after setting the status block content
            //
            foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
            {
                if (entry.Value is ResultPart resultPart)
                {
                    if (_viewResultsType == ViewResultsTypeEnum.Undeformed)
                    {
                        // Undeformed view
                        DrawModelPart(_allResults.CurrentResult.Mesh, resultPart, layer);
                    }
                    else
                    {
                        // Undeformed copy
                        if (undeformedModelType != UndeformedModelTypeEnum.None)
                            DrawUndeformedPartCopy(resultPart, undeformedModelType, undeformedModelColor, layer);
                        // Deformed
                        DrawResultPart(resultPart, fieldData, false);
                    }
                }
                // Draw geometry parts copied to the results
                else if (entry.Value is GeometryPart)
                {
                    // Pickable for the Section view to work
                    DrawGeomPart(_allResults.CurrentResult.Mesh, entry.Value, layer, false, true);
                }
                //
                if (!entry.Value.Visible) hiddenActors.Add(entry.Key);
            }
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), true);
        }
        private void DrawResultPart(ResultPart part, FieldData fieldData, bool update)
        {
            vtkMaxActorData data = GetResultPartActorData(part, fieldData);
            //
            if (data != null)
            {
                ApplyLighting(data);
                _form.AddScalarFieldOn3DCells(data, update);
            }
        }
        private vtkMaxActorData GetResultPartActorData(ResultPart part, FieldData fieldData)
        {
            if (part.Labels.Length == 0) return null;
            // Get visualization nodes and renumbered elements           
            PartExchangeData actorResultData = _allResults.CurrentResult.GetVisualizationNodesCellsAndValues(part, fieldData);
            // Model edges
            PartExchangeData modelEdgesResultData = null;
            if (part.PartType.HasEdges() && part.Visualization.EdgeCells != null)
            {
                modelEdgesResultData = _allResults.CurrentResult.GetEdgesNodesAndCells(part, fieldData);
            }
            //
            vtkMaxActorData data = GetVtkData(actorResultData, modelEdgesResultData);
            SetVolumeGridData(data, _allResults.CurrentResult.Mesh, part);
            data.Name = part.Name;
            GetPartColor(part, ref data.Color, ref data.BackfaceColor);
            data.ColorContours = _viewResultsType == ViewResultsTypeEnum.ColorContours &&
                                 part.ResultRepresentation;
            data.CanHaveElementEdges = true;
            data.Pickable = true;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            data.ActorRepresentation = GetRepresentation(part);
            data.NodeSize = Globals.BeamNodeSize;
            if (_viewResultsType == ViewResultsTypeEnum.VectorPlot ||
                _viewResultsType == ViewResultsTypeEnum.TensorPlot)
            {
                data.ColorContours = false;
            }
            // Back face                                                    
            if (part.PartType == PartType.Shell) data.BackfaceCulling = false;
            //
            return data;
        }
        private void DrawVectorPlot(FieldData fieldData)
        {
            Field field = _allResults.CurrentResult.GetField(fieldData);
            DataTypeEnum dataType = field != null ? field.DataType :
                                    _allResults.CurrentResult.GetFieldDataType(fieldData.Name);
            if (dataType != DataTypeEnum.Vector) return;
            if (field != null && field.Complex)
            {
                ComplexResultTypeEnum complexType = _form.GetComplexResultType();
                if (complexType != ComplexResultTypeEnum.Real &&
                    complexType != ComplexResultTypeEnum.Imaginary &&
                    complexType != ComplexResultTypeEnum.RealAtAngle) return;
            }
            //
            FeMesh mesh = _allResults.CurrentResult.Mesh;
            List<vtkMaxActorData> vectorActorData = new List<vtkMaxActorData>();
            List<string> hiddenPartNames = new List<string>();
            List<string> hiddenRepresentationPartNames = new List<string>();
            BoundingBox boundingBox = new BoundingBox();
            double maxMagnitude = 0;
            //
            foreach (var entry in mesh.Parts)
            {
                if (!(entry.Value is ResultPart part) || part.Labels.Length == 0) continue;
                //
                mesh.GetVisualizationNodesAndCells(part, out int[] visualizationNodeIds,
                                                   out double[][] visualizationNodeCoor, out _, out _, out _);
                HashSet<int> addedNodeIds = new HashSet<int>();
                List<int> nodeIds = new List<int>();
                List<double[]> nodeCoor = new List<double[]>();
                for (int i = 0; i < visualizationNodeIds.Length; i++)
                {
                    if (addedNodeIds.Add(visualizationNodeIds[i]))
                    {
                        nodeIds.Add(visualizationNodeIds[i]);
                        nodeCoor.Add(visualizationNodeCoor[i]);
                    }
                }
                int[] vectorNodeIds = nodeIds.ToArray();
                if (!_allResults.CurrentResult.GetVectorValues(fieldData, vectorNodeIds,
                                                               out double[][] vectors, out float[] magnitudes)) return;
                float[] colorValues = _allResults.CurrentResult.GetValues(fieldData, vectorNodeIds);
                if (colorValues == null) return;
                //
                for (int i = 0; i < magnitudes.Length; i++)
                {
                    if (!float.IsNaN(magnitudes[i]) && !float.IsInfinity(magnitudes[i]) &&
                        magnitudes[i] > maxMagnitude) maxMagnitude = magnitudes[i];
                }
                double[][] allNodeCoor = nodeCoor.ToArray();
                int[] sampleIndices = GetVectorPlotSampleIndices(vectorNodeIds, allNodeCoor,
                                                                  GetExtremeValueIndices(colorValues));
                vectorNodeIds = GetIndexedIds(vectorNodeIds, sampleIndices);
                double[][] vectorNodeCoor = GetIndexedCoordinates(allNodeCoor, sampleIndices);
                vectors = GetIndexedCoordinates(vectors, sampleIndices);
                colorValues = GetIndexedValues(colorValues, sampleIndices);
                // Keep the glyph size independent of the exploded-view spacing.
                double[] offset = part.Offset;
                if (offset != null && (offset[0] != 0 || offset[1] != 0 || offset[2] != 0))
                {
                    foreach (double[] coor in nodeCoor)
                        boundingBox.IncludeCoorFast(new double[] { coor[0] - offset[0], coor[1] - offset[1], coor[2] - offset[2] });
                }
                else boundingBox.IncludeCoors(allNodeCoor);
                //
                vtkMaxActorData data = new vtkMaxActorData();
                data.Name = part.Name + Globals.NameSeparator + "Vector plot";
                data.ParentName = part.Name;
                data.Geometry.Nodes.Ids = vectorNodeIds;
                data.Geometry.Nodes.Coor = vectorNodeCoor;
                data.Geometry.Nodes.Normals = vectors;
                data.Geometry.Nodes.Values = colorValues;
                data.Geometry.ExtremeNodes = _allResults.CurrentResult.GetScaledExtremeValues(part.Name, fieldData, 1);
                data.NodeSize = (float)(5 * _settings.Post.VectorPlotScaleFactor);
                data.Color = Color.White;
                data.ColorContours = true;
                data.Lighting = false;
                data.UseGlobalLighting = false;
                data.UseEdgeVisibility = false;
                data.LineWidth = 1.5f;
                data.Pickable = false;
                data.SectionViewPossible = true;
                data.Layer = vtkRendererLayer.Base;
                vectorActorData.Add(data);
                //
                if (!part.Visible) hiddenPartNames.Add(part.Name);
                if (!part.ResultRepresentation) hiddenRepresentationPartNames.Add(part.Name);
            }
            //
            double diagonal = boundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0)
                diagonal = mesh.BoundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0) diagonal = 1;
            double arrowSize = 0.05 * diagonal * _settings.Post.VectorPlotScaleFactor;
            double maxArrowLength = arrowSize * _settings.Post.VectorPlotLengthScaleFactor;
            foreach (vtkMaxActorData data in vectorActorData)
                _form.AddVectorFieldActor(data, maxMagnitude, maxArrowLength, arrowSize);
            //
            if (hiddenRepresentationPartNames.Count > 0)
                _form.UpdateResultRepresentationVisibility(hiddenRepresentationPartNames.ToArray(), false, false);
            if (hiddenPartNames.Count > 0) _form.HideActors(hiddenPartNames.ToArray(), true);
        }
        private void DrawTensorPlot(FieldData fieldData)
        {
            Field field = _allResults.CurrentResult.GetField(fieldData);
            DataTypeEnum dataType = field != null ? field.DataType :
                                    _allResults.CurrentResult.GetFieldDataType(fieldData.Name);
            if (dataType != DataTypeEnum.Tensor ||
                !_allResults.CurrentResult.IsTensorPlotComponent(fieldData)) return;
            if (field != null && field.Complex)
            {
                ComplexResultTypeEnum complexType = _form.GetComplexResultType();
                if (complexType != ComplexResultTypeEnum.Real &&
                    complexType != ComplexResultTypeEnum.Imaginary &&
                    complexType != ComplexResultTypeEnum.RealAtAngle) return;
            }
            //
            FeMesh mesh = _allResults.CurrentResult.Mesh;
            List<vtkMaxActorData> tensorActorData = new List<vtkMaxActorData>();
            List<string> hiddenPartNames = new List<string>();
            List<string> hiddenRepresentationPartNames = new List<string>();
            BoundingBox boundingBox = new BoundingBox();
            double maxAbsValue = 0;
            //
            foreach (var entry in mesh.Parts)
            {
                if (!(entry.Value is ResultPart part) || part.Labels.Length == 0) continue;
                //
                mesh.GetVisualizationNodesAndCells(part, out int[] visualizationNodeIds,
                                                   out double[][] visualizationNodeCoor, out _, out _, out _);
                HashSet<int> addedNodeIds = new HashSet<int>();
                List<int> nodeIds = new List<int>();
                List<double[]> nodeCoor = new List<double[]>();
                for (int i = 0; i < visualizationNodeIds.Length; i++)
                {
                    if (addedNodeIds.Add(visualizationNodeIds[i]))
                    {
                        nodeIds.Add(visualizationNodeIds[i]);
                        nodeCoor.Add(visualizationNodeCoor[i]);
                    }
                }
                int[] tensorNodeIds = nodeIds.ToArray();
                if (!_allResults.CurrentResult.GetTensorPlotValues(fieldData, tensorNodeIds,
                                                                   out double[][] directions,
                                                                   out float[] values)) return;
                //
                for (int i = 0; i < values.Length; i++)
                {
                    if (directions[i] != null &&
                        !float.IsNaN(values[i]) && !float.IsInfinity(values[i]) &&
                        Math.Abs(values[i]) > maxAbsValue) maxAbsValue = Math.Abs(values[i]);
                }
                double[][] allNodeCoor = nodeCoor.ToArray();
                int[] sampleIndices = GetVectorPlotSampleIndices(tensorNodeIds, allNodeCoor,
                                                                  GetExtremeValueIndices(values));
                tensorNodeIds = GetIndexedIds(tensorNodeIds, sampleIndices);
                double[][] tensorNodeCoor = GetIndexedCoordinates(allNodeCoor, sampleIndices);
                directions = GetIndexedCoordinates(directions, sampleIndices);
                values = GetIndexedValues(values, sampleIndices);
                // Keep the glyph size independent of the exploded-view spacing.
                double[] offset = part.Offset;
                if (offset != null && (offset[0] != 0 || offset[1] != 0 || offset[2] != 0))
                {
                    foreach (double[] coor in nodeCoor)
                        boundingBox.IncludeCoorFast(new double[] { coor[0] - offset[0],
                                                                  coor[1] - offset[1],
                                                                  coor[2] - offset[2] });
                }
                else boundingBox.IncludeCoors(allNodeCoor);
                //
                vtkMaxActorData data = new vtkMaxActorData();
                data.Name = part.Name + Globals.NameSeparator + "Tensor plot";
                data.ParentName = part.Name;
                data.Geometry.Nodes.Ids = tensorNodeIds;
                data.Geometry.Nodes.Coor = tensorNodeCoor;
                data.Geometry.Nodes.Normals = directions;
                data.Geometry.Nodes.Values = values;
                data.Geometry.ExtremeNodes = _allResults.CurrentResult.GetScaledExtremeValues(part.Name, fieldData, 1);
                data.NodeSize = (float)(5 * _settings.Post.VectorPlotScaleFactor);
                data.Color = Color.White;
                data.ColorContours = true;
                data.Lighting = false;
                data.UseGlobalLighting = false;
                data.UseEdgeVisibility = false;
                data.LineWidth = 1.5f;
                data.Pickable = false;
                data.SectionViewPossible = true;
                data.Layer = vtkRendererLayer.Base;
                tensorActorData.Add(data);
                //
                if (!part.Visible) hiddenPartNames.Add(part.Name);
                if (!part.ResultRepresentation) hiddenRepresentationPartNames.Add(part.Name);
            }
            //
            double diagonal = boundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0)
                diagonal = mesh.BoundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0) diagonal = 1;
            double arrowSize = 2 * 0.05 * diagonal * _settings.Post.VectorPlotScaleFactor;
            double maxGlyphLength = arrowSize * _settings.Post.VectorPlotLengthScaleFactor;
            foreach (vtkMaxActorData data in tensorActorData)
                _form.AddTensorFieldActor(data, maxAbsValue, maxGlyphLength, arrowSize);
            //
            if (hiddenRepresentationPartNames.Count > 0)
                _form.UpdateResultRepresentationVisibility(hiddenRepresentationPartNames.ToArray(), false, false);
            if (hiddenPartNames.Count > 0) _form.HideActors(hiddenPartNames.ToArray(), true);
        }
        private vtkMaxActorData GetScaleFactorAnimatedPlotActorData(ResultPart part, FieldData fieldData,
                                                                    vtkMaxActorData resultData, int numFrames,
                                                                    out double maxValue)
        {
            maxValue = 0;
            if (_viewResultsType != ViewResultsTypeEnum.VectorPlot &&
                _viewResultsType != ViewResultsTypeEnum.TensorPlot) return null;
            if (!GetUniqueNodes(resultData.Geometry.Nodes.Ids, out int[] nodeIds, out int[] sourceIndices))
                return null;
            //
            double[][] baseDirections;
            if (_viewResultsType == ViewResultsTypeEnum.VectorPlot)
            {
                if (!_allResults.CurrentResult.GetVectorValues(fieldData, nodeIds, out baseDirections, out _))
                    return null;
            }
            else
            {
                if (!_allResults.CurrentResult.GetTensorPlotValues(fieldData, nodeIds, out baseDirections, out _))
                    return null;
            }
            //
            NodesExchangeData[] frames = new NodesExchangeData[numFrames];
            float[] ratios = GetScaleFactorAnimationRatios(fieldData, numFrames);
            for (int i = 0; i < frames.Length; i++)
            {
                NodesExchangeData resultFrame = resultData.Geometry.NodesAnimation[i];
                frames[i] = new NodesExchangeData();
                frames[i].Ids = nodeIds;
                frames[i].Coor = GetIndexedCoordinates(resultFrame, sourceIndices);
                frames[i].Values = GetIndexedValues(resultFrame.Values, sourceIndices);
                frames[i].Normals = _viewResultsType == ViewResultsTypeEnum.VectorPlot
                    ? ScaleDirections(baseDirections, ratios[i])
                    : baseDirections;
                //
                UpdateAnimatedPlotMaximum(frames[i], _viewResultsType == ViewResultsTypeEnum.TensorPlot, ref maxValue);
            }
            int[] sampleIndices = GetVectorPlotSampleIndices(nodeIds,
                GetIndexedCoordinates(resultData.Geometry.Nodes.Coor, sourceIndices),
                GetExtremeValueIndices(frames));
            ApplyAnimatedPlotSampling(frames, sampleIndices);
            return CreateAnimatedPlotActorData(part, frames, resultData.Geometry.ExtremeNodesAnimation);
        }
        private vtkMaxActorData GetTimeIncrementAnimatedPlotActorData(ResultPart part, vtkMaxActorData resultData,
                                                                      FieldData[] frameFieldData, out double maxValue)
        {
            maxValue = 0;
            if (_viewResultsType != ViewResultsTypeEnum.VectorPlot &&
                _viewResultsType != ViewResultsTypeEnum.TensorPlot) return null;
            if (!GetUniqueNodes(resultData.Geometry.Nodes.Ids, out int[] nodeIds, out int[] sourceIndices))
                return null;
            if (resultData.Geometry.NodesAnimation == null ||
                resultData.Geometry.NodesAnimation.Length != frameFieldData.Length) return null;
            //
            NodesExchangeData[] frames = new NodesExchangeData[frameFieldData.Length];
            for (int i = 0; i < frames.Length; i++)
            {
                double[][] directions;
                bool valuesAvailable;
                if (_viewResultsType == ViewResultsTypeEnum.VectorPlot)
                    valuesAvailable = _allResults.CurrentResult.GetVectorValues(frameFieldData[i], nodeIds,
                                                                                out directions, out _);
                else
                    valuesAvailable = _allResults.CurrentResult.GetTensorPlotValues(frameFieldData[i], nodeIds,
                                                                                    out directions, out _);
                if (!valuesAvailable) directions = new double[nodeIds.Length][];
                //
                NodesExchangeData resultFrame = resultData.Geometry.NodesAnimation[i];
                frames[i] = new NodesExchangeData();
                frames[i].Ids = nodeIds;
                frames[i].Coor = GetIndexedCoordinates(resultFrame, sourceIndices);
                frames[i].Normals = directions;
                frames[i].Values = GetIndexedValues(resultFrame.Values, sourceIndices);
                UpdateAnimatedPlotMaximum(frames[i], _viewResultsType == ViewResultsTypeEnum.TensorPlot, ref maxValue);
            }
            int[] sampleIndices = GetVectorPlotSampleIndices(nodeIds,
                GetIndexedCoordinates(resultData.Geometry.Nodes.Coor, sourceIndices),
                GetExtremeValueIndices(frames));
            ApplyAnimatedPlotSampling(frames, sampleIndices);
            return CreateAnimatedPlotActorData(part, frames, resultData.Geometry.ExtremeNodesAnimation);
        }
        private bool GetCurrentPlotFrameNodes(ResultPart part, FieldData fieldData,
                                              out NodesExchangeData nodes, out double maxValue)
        {
            nodes = null;
            maxValue = 0;
            if (_viewResultsType != ViewResultsTypeEnum.VectorPlot &&
                _viewResultsType != ViewResultsTypeEnum.TensorPlot) return false;
            //
            _allResults.CurrentResult.Mesh.GetVisualizationNodesAndCells(part, out int[] visualizationNodeIds,
                                                                         out double[][] visualizationNodeCoor,
                                                                         out _, out _, out _);
            if (!GetUniqueNodes(visualizationNodeIds, out int[] nodeIds, out int[] sourceIndices)) return false;
            //
            nodes = new NodesExchangeData();
            nodes.Ids = nodeIds;
            nodes.Coor = GetIndexedCoordinates(visualizationNodeCoor, sourceIndices);
            if (_viewResultsType == ViewResultsTypeEnum.VectorPlot)
            {
                if (!_allResults.CurrentResult.GetVectorValues(fieldData, nodeIds, out nodes.Normals, out _))
                    return false;
                nodes.Values = _allResults.CurrentResult.GetValues(fieldData, nodeIds);
            }
            else
            {
                if (!_allResults.CurrentResult.GetTensorPlotValues(fieldData, nodeIds, out nodes.Normals,
                                                                   out nodes.Values)) return false;
            }
            if (nodes.Values == null) return false;
            //
            UpdateAnimatedPlotMaximum(nodes, _viewResultsType == ViewResultsTypeEnum.TensorPlot, ref maxValue);
            return true;
        }
        private vtkMaxActorData CreateAnimatedPlotActorData(ResultPart part, NodesExchangeData[] frames,
                                                            NodesExchangeData[] extremeFrames)
        {
            if (frames == null || frames.Length == 0) return null;
            //
            vtkMaxActorData data = new vtkMaxActorData();
            string plotName = _viewResultsType == ViewResultsTypeEnum.TensorPlot ? "Tensor plot" : "Vector plot";
            data.Name = part.Name + Globals.NameSeparator + plotName;
            data.ParentName = part.Name;
            data.Geometry.Nodes = frames[0];
            data.Geometry.NodesAnimation = frames;
            data.Geometry.ExtremeNodes =
                extremeFrames != null && extremeFrames.Length > 0 ? extremeFrames[0] : null;
            data.Geometry.ExtremeNodesAnimation = extremeFrames;
            data.NodeSize = (float)(5 * _settings.Post.VectorPlotScaleFactor);
            data.Color = Color.White;
            data.ColorContours = true;
            data.Lighting = false;
            data.UseGlobalLighting = false;
            data.UseEdgeVisibility = false;
            data.LineWidth = 1.5f;
            data.Pickable = false;
            data.SectionViewPossible = true;
            data.Layer = vtkRendererLayer.Base;
            return data;
        }
        private bool AddAnimatedPlotActors(List<vtkMaxActorData> actorData, double maxValue)
        {
            if (actorData == null || actorData.Count == 0) return true;
            //
            double diagonal = GetPlotActorDiagonal(actorData);
            double arrowSize = 0.05 * diagonal * _settings.Post.VectorPlotScaleFactor;
            double maxLength = arrowSize * _settings.Post.VectorPlotLengthScaleFactor;
            if (_viewResultsType == ViewResultsTypeEnum.TensorPlot) { maxLength *= 2; arrowSize *= 2; }
            //
            foreach (vtkMaxActorData data in actorData)
            {
                bool added = _viewResultsType == ViewResultsTypeEnum.TensorPlot
                    ? _form.AddAnimatedTensorFieldActor(data, maxValue, maxLength, arrowSize)
                    : _form.AddAnimatedVectorFieldActor(data, maxValue, maxLength, arrowSize);
                if (!added) return false;
            }
            return true;
        }
        private double GetPlotActorDiagonal(List<vtkMaxActorData> actorData)
        {
            BoundingBox boundingBox = new BoundingBox();
            foreach (vtkMaxActorData data in actorData)
            {
                double[] offset = null;
                if (data.ParentName != null &&
                    _allResults.CurrentResult.Mesh.Parts.TryGetValue(data.ParentName, out BasePart part))
                    offset = part.Offset;
                //
                foreach (double[] coor in data.Geometry.Nodes.Coor)
                {
                    if (offset != null)
                        boundingBox.IncludeCoorFast(new double[] { coor[0] - offset[0],
                                                                  coor[1] - offset[1],
                                                                  coor[2] - offset[2] });
                    else
                        boundingBox.IncludeCoorFast(coor);
                }
            }
            double diagonal = boundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0)
                diagonal = _allResults.CurrentResult.Mesh.BoundingBox.GetDiagonal();
            if (double.IsNaN(diagonal) || double.IsInfinity(diagonal) || diagonal <= 0) diagonal = 1;
            return diagonal;
        }
        private int[] GetVectorPlotSampleIndices(int[] nodeIds, double[][] fallbackCoordinates,
                                                 int[] protectedIndices)
        {
            if (nodeIds == null || nodeIds.Length == 0 || _settings.Post.VectorPlotDensity <= 0)
                return new int[0];
            if (_settings.Post.VectorPlotDensity >= 100)
                return Enumerable.Range(0, nodeIds.Length).ToArray();
            // Use undeformed coordinates so the retained node IDs stay unchanged through
            // deformation-scale, time-increment, harmonic, and exploded-view animations.
            double[][] samplingCoordinates = new double[nodeIds.Length][];
            for (int i = 0; i < nodeIds.Length; i++)
            {
                if (_allResults.CurrentResult.UndeformedNodes.TryGetValue(nodeIds[i], out FeNode node))
                    samplingCoordinates[i] = node.Coor;
                else if (fallbackCoordinates != null && i < fallbackCoordinates.Length)
                    samplingCoordinates[i] = fallbackCoordinates[i];
                else
                    samplingCoordinates[i] = new double[3];
            }
            int targetCount = (int)Math.Ceiling(nodeIds.Length * _settings.Post.VectorPlotDensity / 100.0);
            return SpatialPointSampler.GetSampleIndicesByCount(samplingCoordinates, targetCount,
                                                              protectedIndices);
        }
        private static int[] GetExtremeValueIndices(float[] values)
        {
            if (values == null || values.Length == 0) return new int[0];
            int minIndex = -1;
            int maxIndex = -1;
            float minValue = float.MaxValue;
            float maxValue = -float.MaxValue;
            for (int i = 0; i < values.Length; i++)
            {
                float value = values[i];
                if (float.IsNaN(value) || float.IsInfinity(value)) continue;
                if (value < minValue) { minValue = value; minIndex = i; }
                if (value > maxValue) { maxValue = value; maxIndex = i; }
            }
            if (minIndex == -1) return new int[0];
            else if (minIndex == maxIndex) return new int[] { minIndex };
            else return new int[] { minIndex, maxIndex };
        }
        private static int[] GetExtremeValueIndices(NodesExchangeData[] frames)
        {
            if (frames == null || frames.Length == 0) return new int[0];
            int minIndex = -1;
            int maxIndex = -1;
            float minValue = float.MaxValue;
            float maxValue = -float.MaxValue;
            foreach (NodesExchangeData frame in frames)
            {
                if (frame == null || frame.Values == null) continue;
                for (int i = 0; i < frame.Values.Length; i++)
                {
                    float value = frame.Values[i];
                    if (float.IsNaN(value) || float.IsInfinity(value)) continue;
                    if (value < minValue) { minValue = value; minIndex = i; }
                    if (value > maxValue) { maxValue = value; maxIndex = i; }
                }
            }
            if (minIndex == -1) return new int[0];
            else if (minIndex == maxIndex) return new int[] { minIndex };
            else return new int[] { minIndex, maxIndex };
        }
        private static int[] GetIndexedIds(int[] ids, int[] indices)
        {
            int[] indexedIds = new int[indices.Length];
            for (int i = 0; i < indices.Length; i++) indexedIds[i] = ids[indices[i]];
            return indexedIds;
        }
        private static void ApplyAnimatedPlotSampling(NodesExchangeData[] frames, int[] sampleIndices)
        {
            HashSet<NodesExchangeData> sampledFrames = new HashSet<NodesExchangeData>();
            foreach (NodesExchangeData frame in frames)
            {
                if (frame == null || !sampledFrames.Add(frame)) continue;
                frame.Ids = GetIndexedIds(frame.Ids, sampleIndices);
                frame.Coor = GetIndexedCoordinates(frame.Coor, sampleIndices);
                frame.Normals = GetIndexedCoordinates(frame.Normals, sampleIndices);
                frame.Values = GetIndexedValues(frame.Values, sampleIndices);
            }
        }
        private static bool GetUniqueNodes(int[] nodeIds, out int[] uniqueNodeIds, out int[] sourceIndices)
        {
            uniqueNodeIds = null;
            sourceIndices = null;
            if (nodeIds == null || nodeIds.Length == 0) return false;
            //
            HashSet<int> addedNodeIds = new HashSet<int>();
            List<int> uniqueIds = new List<int>();
            List<int> indices = new List<int>();
            for (int i = 0; i < nodeIds.Length; i++)
            {
                if (addedNodeIds.Add(nodeIds[i]))
                {
                    uniqueIds.Add(nodeIds[i]);
                    indices.Add(i);
                }
            }
            uniqueNodeIds = uniqueIds.ToArray();
            sourceIndices = indices.ToArray();
            return uniqueNodeIds.Length > 0;
        }
        private static double[][] GetIndexedCoordinates(double[][] coordinates, int[] indices)
        {
            double[][] indexedCoordinates = new double[indices.Length][];
            for (int i = 0; i < indices.Length; i++)
                indexedCoordinates[i] = coordinates[indices[i]];
            return indexedCoordinates;
        }
        private static double[][] GetIndexedCoordinates(NodesExchangeData nodes, int[] indices)
        {
            if (nodes.FlatCoor == null) return GetIndexedCoordinates(nodes.Coor, indices);
            //
            int index;
            double[][] indexedCoordinates = new double[indices.Length][];
            for (int i = 0; i < indices.Length; i++)
            {
                index = 3 * indices[i];
                indexedCoordinates[i] = new double[] { nodes.FlatCoor[index], nodes.FlatCoor[index + 1],
                                                       nodes.FlatCoor[index + 2] };
            }
            return indexedCoordinates;
        }
        private static float[] GetIndexedValues(float[] values, int[] indices)
        {
            float[] indexedValues = new float[indices.Length];
            if (values == null)
            {
                for (int i = 0; i < indexedValues.Length; i++) indexedValues[i] = float.NaN;
            }
            else
            {
                for (int i = 0; i < indices.Length; i++) indexedValues[i] = values[indices[i]];
            }
            return indexedValues;
        }
        private static double[][] ScaleDirections(double[][] directions, float scale)
        {
            double[][] scaledDirections = new double[directions.Length][];
            for (int i = 0; i < directions.Length; i++)
            {
                if (directions[i] != null)
                    scaledDirections[i] = new double[] { scale * directions[i][0],
                                                         scale * directions[i][1],
                                                         scale * directions[i][2] };
            }
            return scaledDirections;
        }
        private static float[] GetScaleFactorAnimationRatios(FieldData fieldData, int numFrames)
        {
            float[] ratios = new float[numFrames];
            if (numFrames == 1)
            {
                ratios[0] = 1;
                return ratios;
            }
            //
            if (fieldData.StepType == StepTypeEnum.Frequency || fieldData.StepType == StepTypeEnum.Buckling)
            {
                float ratio = 2f / (numFrames - 1);
                for (int i = 0; i < numFrames; i++)
                    ratios[i] = (float)Math.Sin((-1 + i * ratio) * Math.PI / 2);
            }
            else
            {
                float ratio = 1f / (numFrames - 1);
                for (int i = 0; i < numFrames; i++) ratios[i] = i * ratio;
            }
            return ratios;
        }
        private static void UpdateAnimatedPlotMaximum(NodesExchangeData nodes, bool tensorGlyph,
                                                      ref double maxValue)
        {
            for (int i = 0; i < nodes.Coor.Length; i++)
            {
                if (nodes.Values == null || i >= nodes.Values.Length ||
                    float.IsNaN(nodes.Values[i]) || float.IsInfinity(nodes.Values[i])) continue;
                double[] direction = nodes.Normals != null && i < nodes.Normals.Length ? nodes.Normals[i] : null;
                if (direction == null || direction.Length != 3) continue;
                //
                double value;
                if (tensorGlyph)
                    value = Math.Abs(nodes.Values[i]);
                else
                    value = Math.Sqrt(direction[0] * direction[0] +
                                      direction[1] * direction[1] +
                                      direction[2] * direction[2]);
                if (!double.IsNaN(value) && !double.IsInfinity(value) && value > maxValue) maxValue = value;
            }
        }
        private FieldData[] GetTimeIncrementAnimationFieldData(FieldData fieldData)
        {
            List<FieldData> frameData = new List<FieldData>();
            Dictionary<int, int[]> existingIncrements =
                _allResults.CurrentResult.GetExistingIncrementIds(fieldData.Name, fieldData.Component);
            foreach (var entry in existingIncrements)
            {
                foreach (int incrementId in entry.Value)
                    frameData.Add(_allResults.CurrentResult.GetFieldData(fieldData.Name, fieldData.Component,
                                                                         entry.Key, incrementId, true));
            }
            return frameData.ToArray();
        }
        // Animation
        public void AnimationFrameChanged(int frameNumber, bool initializeAnnotationAnchors)
        {
            _updatingAnimationAnnotations = true;
            _initializingAnimationAnnotationAnchors = initializeAnnotationAnchors;
            try
            {
                _annotations.UpdateAnimationAnnotations(initializeAnnotationAnchors);
            }
            finally
            {
                _initializingAnimationAnnotationAnchors = false;
                _updatingAnimationAnnotations = false;
            }
        }
        public bool DrawScaleFactorAnimation(int numFrames)
        {
            _form.Clear3D();
            ClearAnimationLocatorData();
            //
            if (_allResults.CurrentResult == null || _allResults.CurrentResult.Mesh == null) return false;
            if (_allResults.CurrentResult.GetAllComponentNames().Length == 0) _viewResultsType = ViewResultsTypeEnum.Undeformed;
            //
            ApplyResultsUnitSystem();
            // Settings - must be here before drawing parts to correctly set the numer of colors
            float scale = GetScale();
            SetPostLegendAndStatusBlockSettings();
            SetStatusBlock(scale);
            // The volume grid nodes of each frame are regenerated on demand
            FieldData[] frameFieldData = new FieldData[numFrames];
            for (int i = 0; i < numFrames; i++) frameFieldData[i] = _currentFieldData;
            SetAnimationLocatorData(frameFieldData, scale,
                                    _allResults.CurrentResult.GetAnimationScaleRatios(_currentFieldData, numFrames),
                                    null);
            //
            vtkMaxActorData data;
            vtkRendererLayer layer = vtkRendererLayer.Base;
            //
            bool result = true;
            PostSettings postSettings = _settings.Post;
            List<string> hiddenActors = new List<string>();
            List<string> hiddenRepresentationPartNames = new List<string>();
            List<vtkMaxActorData> animatedPlotActorData = new List<vtkMaxActorData>();
            double animatedPlotMaxValue = 0;
            double[] allFramesScalarRange = new double[] { double.MaxValue, -double.MaxValue };
            foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
            {
                if (entry.Value is ResultPart resultPart)
                {
                    // Undeformed
                    if (postSettings.UndeformedModelType != UndeformedModelTypeEnum.None)
                        DrawUndeformedPartCopy(resultPart, postSettings.UndeformedModelType,
                                               postSettings.UndeformedModelColor, layer);
                    // Deformed
                    data = GetScaleFactorAnimationDataFromPart(resultPart, _currentFieldData, scale, numFrames);
                    vtkMaxActorData plotData =
                        GetScaleFactorAnimatedPlotActorData(resultPart, _currentFieldData, data, numFrames,
                                                            out double partPlotMaxValue);
                    if (plotData != null)
                    {
                        animatedPlotActorData.Add(plotData);
                        if (partPlotMaxValue > animatedPlotMaxValue) animatedPlotMaxValue = partPlotMaxValue;
                        if (!resultPart.ResultRepresentation) hiddenRepresentationPartNames.Add(resultPart.Name);
                    }
                    // Min max
                    if (entry.Value.Visible)
                    {
                        foreach (NodesExchangeData nData in data.Geometry.ExtremeNodesAnimation)
                        {
                            if (nData != null)
                            {
                                if (nData.Values[0] < allFramesScalarRange[0]) allFramesScalarRange[0] = nData.Values[0];
                                if (nData.Values[1] > allFramesScalarRange[1]) allFramesScalarRange[1] = nData.Values[1];
                            }
                        }
                    }
                    //
                    ApplyLighting(data);
                    result = _form.AddAnimatedScalarFieldOn3DCells(data);                    
                    if (result == false) {_form.Clear3D(); return false;}
                }
                else if (entry.Value is GeometryPart)
                {
                    // For the Section view to work: pickable = true 
                    DrawGeomPart(_allResults.CurrentResult.Mesh, entry.Value, layer, false, true);
                }
                if (!entry.Value.Visible) hiddenActors.Add(entry.Key);
            }
            if (!AddAnimatedPlotActors(animatedPlotActorData, animatedPlotMaxValue))
            {
                _form.Clear3D();
                return false;
            }
            if (hiddenRepresentationPartNames.Count > 0)
                _form.UpdateResultRepresentationVisibility(hiddenRepresentationPartNames.ToArray(), false, false);
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), true);
            // Transformation
            ApplyTransformation();
            // Symbols
            DrawResultSymbols();
            // Annotations
            _annotations.DrawAnnotations();
            // Section view
            ApplySectionView();
            // Animation field data
            float[] time = new float[numFrames];
            int[] stepId = new int[numFrames];
            int[] stepIncrementId = new int[numFrames];
            int[] modeNumber = new int[numFrames];
            int[] nodalDiameter = new int[numFrames];
            float[] animationScale = new float[numFrames];
            float ratio = 1f / (numFrames - 1);
            for (int i = 0; i < numFrames; i++)
            {
                time[i] = _currentFieldData.Time;
                stepId[i] = _currentFieldData.StepId;
                stepIncrementId[i] = _currentFieldData.StepIncrementId;
                modeNumber[i] = _currentFieldData.ModeNumber;
                nodalDiameter[i] = _currentFieldData.NodalDiameter;
                animationScale[i] = i * ratio;
            }
            //
            _form.SetAnimationFrameData(time, stepId, stepIncrementId, modeNumber, nodalDiameter, animationScale,
                                        allFramesScalarRange, vtkMaxAnimationType.ScaleFactor);
            //
            return result;
        }
        public bool DrawTimeIncrementAnimation(out int numFrames)
        {
            _form.Clear3D();
            //
            numFrames = -1;
            if (_allResults.CurrentResult == null || _allResults.CurrentResult.Mesh == null) return false;
            if (_allResults.CurrentResult.GetAllComponentNames().Length == 0) _viewResultsType = ViewResultsTypeEnum.Undeformed;
            //
            ApplyResultsUnitSystem();
            // Settings - must be here before drawing parts to correctly set the numer of colors
            float scale = GetScaleForAllStepsAndIncrements();
            SetPostLegendAndStatusBlockSettings();
            SetStatusBlock(scale);
            FieldData[] animationFieldData = GetTimeIncrementAnimationFieldData(_currentFieldData);
            // The volume grid nodes of each frame are regenerated on demand
            SetAnimationLocatorData(animationFieldData, scale, null, null);
            //
            vtkMaxActorData data = null;
            vtkRendererLayer layer = vtkRendererLayer.Base;
            //
            bool result = true;
            PostSettings postSettings = _settings.Post;
            List<string> hiddenActors = new List<string>();
            List<string> hiddenRepresentationPartNames = new List<string>();
            List<vtkMaxActorData> animatedPlotActorData = new List<vtkMaxActorData>();
            double animatedPlotMaxValue = 0;
            double[] allFramesScalarRange = new double[] { double.MaxValue, -double.MaxValue };
            foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
            {
                if (entry.Value is ResultPart resultPart)
                {
                    // Undeformed shape
                    if (postSettings.UndeformedModelType != UndeformedModelTypeEnum.None)
                        DrawUndeformedPartCopy(resultPart, postSettings.UndeformedModelType,
                                               postSettings.UndeformedModelColor, layer);
                    // Results
                    data = GetTimeIncrementAnimationDataFromPart(resultPart, _currentFieldData, scale);
                    vtkMaxActorData plotData =
                        GetTimeIncrementAnimatedPlotActorData(resultPart, data, animationFieldData,
                                                              out double partPlotMaxValue);
                    if (plotData != null)
                    {
                        animatedPlotActorData.Add(plotData);
                        if (partPlotMaxValue > animatedPlotMaxValue) animatedPlotMaxValue = partPlotMaxValue;
                        if (!resultPart.ResultRepresentation) hiddenRepresentationPartNames.Add(resultPart.Name);
                    }
                    // Min max
                    if (entry.Value.Visible)
                    {
                        foreach (NodesExchangeData nData in data.Geometry.ExtremeNodesAnimation)
                        {
                            if (nData != null && nData.Values != null)
                            {
                                if (nData.Values[0] < allFramesScalarRange[0]) allFramesScalarRange[0] = nData.Values[0];
                                if (nData.Values[1] > allFramesScalarRange[1]) allFramesScalarRange[1] = nData.Values[1];
                            }
                        }
                    }
                    //
                    ApplyLighting(data);
                    result = _form.AddAnimatedScalarFieldOn3DCells(data);
                    if (result == false) { _form.Clear3D(); return false; }
                }
                else if (entry.Value is GeometryPart)
                {
                    // For the Section view to work: pickable = true 
                    DrawGeomPart(_allResults.CurrentResult.Mesh, entry.Value, layer, false, true);
                }
                if (!entry.Value.Visible) hiddenActors.Add(entry.Key);
            }
            if (!AddAnimatedPlotActors(animatedPlotActorData, animatedPlotMaxValue))
            {
                _form.Clear3D();
                return false;
            }
            if (hiddenRepresentationPartNames.Count > 0)
                _form.UpdateResultRepresentationVisibility(hiddenRepresentationPartNames.ToArray(), false, false);
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), true);
            // Transformation
            ApplyTransformation();
            // Symbols
            DrawResultSymbols();
            // Annotations
            _annotations.DrawAnnotations();
            // Section view
            ApplySectionView();
            // Follower view
            List<float> time = new List<float>();
            List<int> stepId = new List<int>();
            List<int> stepIncrementId = new List<int>();
            List<int> modeNumber = new List<int>();
            List<int> nodalDiameter = new List<int>();
            List<float> animationScale = new List<float>();
            foreach (FieldData frameFieldData in animationFieldData)
            {
                time.Add(frameFieldData.Time);
                stepId.Add(frameFieldData.StepId);
                stepIncrementId.Add(frameFieldData.StepIncrementId);
                modeNumber.Add(frameFieldData.ModeNumber);
                nodalDiameter.Add(frameFieldData.NodalDiameter);
                animationScale.Add(1);
            }
            _form.SetAnimationFrameData(time.ToArray(), stepId.ToArray(), stepIncrementId.ToArray(), modeNumber.ToArray(),
                                        nodalDiameter.ToArray(), animationScale.ToArray(), allFramesScalarRange,
                                        vtkMaxAnimationType.TimeIncrements);
            //
            numFrames = animationFieldData.Length;
            //
            return result;
        }
        public NodesExchangeData GetAnimationLocatorNodes(string actorName, int frameNumber)
        {
            if (_animationLocatorNodeIds == null || _animationLocatorFieldData == null) return null;
            if (frameNumber < 0 || frameNumber >= _animationLocatorFieldData.Length) return null;
            if (!_animationLocatorNodeIds.TryGetValue(actorName, out int[] nodeIds) || nodeIds == null) return null;
            if (_allResults.CurrentResult == null ||
                !_allResults.CurrentResult.Mesh.Parts.TryGetValue(actorName, out BasePart part)) return null;
            //
            return GetAnimationFrameNodes(part, nodeIds, frameNumber);
        }
        public NodesExchangeData GetAnimationNodes(string actorName, int frameNumber, int[] nodeIds)
        {
            // The frame coordinates and values of the given nodes only - an anchor or an interior annotation
            if (_animationLocatorFieldData == null || nodeIds == null) return null;
            if (frameNumber < 0 || frameNumber >= _animationLocatorFieldData.Length) return null;
            if (_allResults.CurrentResult == null ||
                !_allResults.CurrentResult.Mesh.Parts.TryGetValue(actorName, out BasePart part)) return null;
            //
            return GetAnimationFrameNodes(part, nodeIds, frameNumber);
        }
        private NodesExchangeData GetAnimationFrameNodes(BasePart part, int[] nodeIds, int frameNumber)
        {
            FeResults result = _allResults.CurrentResult;
            FieldData fieldData = _animationLocatorFieldData[frameNumber];
            // Scale factor animation
            if (_animationLocatorRatios != null)
                return result.GetScaledDeformedNodes(part, nodeIds, fieldData, _animationLocatorScale,
                                                     _animationLocatorRatios[frameNumber]);
            // Time increment animation
            if (_animationLocatorAngles == null)
                return result.GetDeformedNodes(part, nodeIds, fieldData, _animationLocatorScale);
            // Harmonic animation - the frame angle replaces the displayed one and is restored
            ComplexResultTypeEnum complexResultType = result.ComplexResultType;
            float complexAngleDeg = result.ComplexAngleDeg;
            try
            {
                result.SetComplexResultTypeAndAngle(ComplexResultTypeEnum.RealAtAngle,
                                                    _animationLocatorAngles[frameNumber], fieldData);
                return result.GetDeformedNodes(part, nodeIds, fieldData, _animationLocatorScale);
            }
            finally
            {
                result.SetComplexResultTypeAndAngle(complexResultType, complexAngleDeg, fieldData);
            }
        }
        private void SetAnimationLocatorData(FieldData[] frameFieldData, float scale, float[] frameRatios,
                                             float[] frameAngles)
        {
            _animationLocatorNodeIds = new Dictionary<string, int[]>();
            _animationLocatorFieldData = frameFieldData;
            _animationLocatorScale = scale;
            _animationLocatorRatios = frameRatios;
            _animationLocatorAngles = frameAngles;
        }
        private void ClearAnimationLocatorData()
        {
            _animationLocatorNodeIds = null;
            _animationLocatorFieldData = null;
            _animationLocatorScale = 0;
            _animationLocatorRatios = null;
            _animationLocatorAngles = null;
        }
        public bool DrawHarmonicAnimation(int numFrames)
        {
            ClearAnimationLocatorData();
            if (_allResults.CurrentResult == null || _allResults.CurrentResult.Mesh == null) return false;
            if (_allResults.CurrentResult.GetAllComponentNames().Length == 0) _viewResultsType = ViewResultsTypeEnum.Undeformed;
            //
            float scale = GetScale();
            // Prepare data - first prepare data, than clear the vtk data
            float delta = 360f / numFrames; // skip the final angle which is the same as the first angle
            float[] angles = new float[numFrames];
            for (int i = 0; i < numFrames; i++) angles[i] = i * delta;
            // The volume grid nodes of each frame are regenerated on demand
            FieldData[] frameFieldData = new FieldData[numFrames];
            for (int i = 0; i < numFrames; i++) frameFieldData[i] = _currentFieldData;
            SetAnimationLocatorData(frameFieldData, scale, null, angles);
            //
            vtkMaxActorData frameData;
            vtkMaxActorData existingData;
            Dictionary<ResultPart, vtkMaxActorData> partData = new Dictionary<ResultPart, vtkMaxActorData>();
            Dictionary<ResultPart, vtkMaxActorData> plotPartData = new Dictionary<ResultPart, vtkMaxActorData>();
            double animatedPlotMaxValue = 0;
            for (int i = 0; i < angles.Length; i++)
            {
                CurrentResult.SetComplexResultTypeAndAngle(ComplexResultTypeEnum.RealAtAngle, angles[i], _currentFieldData);
                //
                _allResults.CurrentResult.SetMeshDeformation(scale, _currentFieldData.StepId,
                                                             _currentFieldData.StepIncrementId);
                //
                foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
                {
                    if (entry.Value is ResultPart resultPart)
                    {
                        frameData = GetResultPartActorData(resultPart, _currentFieldData);
                        bool plotFrameAvailable =
                            GetCurrentPlotFrameNodes(resultPart, _currentFieldData,
                                                     out NodesExchangeData plotFrameNodes,
                                                     out double framePlotMaxValue);
                        if (framePlotMaxValue > animatedPlotMaxValue)
                            animatedPlotMaxValue = framePlotMaxValue;
                        //
                        if (i == 0)
                        {
                            frameData.Geometry.NodesAnimation = new NodesExchangeData[numFrames];
                            frameData.Geometry.ExtremeNodesAnimation = new NodesExchangeData[numFrames];
                            frameData.ModelEdges.NodesAnimation = new NodesExchangeData[numFrames];
                            //
                            frameData.Geometry.NodesAnimation[i] = frameData.Geometry.Nodes;
                            frameData.Geometry.ExtremeNodesAnimation[i] = frameData.Geometry.ExtremeNodes;
                            frameData.ModelEdges.NodesAnimation[i] = frameData.ModelEdges.Nodes;
                            //
                            partData.Add(resultPart, frameData);
                            //
                            if (plotFrameNodes != null)
                            {
                                NodesExchangeData[] plotFrames = new NodesExchangeData[numFrames];
                                NodesExchangeData[] plotExtremeFrames = new NodesExchangeData[numFrames];
                                plotFrames[i] = plotFrameNodes;
                                plotExtremeFrames[i] = frameData.Geometry.ExtremeNodes;
                                vtkMaxActorData plotData =
                                    CreateAnimatedPlotActorData(resultPart, plotFrames, plotExtremeFrames);
                                plotPartData.Add(resultPart, plotData);
                            }
                        }
                        else
                        {
                            if (partData.TryGetValue(resultPart, out existingData))
                            {
                                existingData.Geometry.NodesAnimation[i] = frameData.Geometry.Nodes;
                                existingData.Geometry.ExtremeNodesAnimation[i] = frameData.Geometry.ExtremeNodes;
                                existingData.ModelEdges.NodesAnimation[i] = frameData.ModelEdges.Nodes;
                            }
                            if (plotPartData.TryGetValue(resultPart, out vtkMaxActorData existingPlotData))
                            {
                                if (!plotFrameAvailable && plotFrameNodes == null)
                                    plotFrameNodes = existingPlotData.Geometry.Nodes;
                                existingPlotData.Geometry.NodesAnimation[i] = plotFrameNodes;
                                existingPlotData.Geometry.ExtremeNodesAnimation[i] = frameData.Geometry.ExtremeNodes;
                            }
                        }
                    }
                }
            }
            // Use one stable sample for all harmonic angles and preserve the global extrema.
            foreach (vtkMaxActorData plotData in plotPartData.Values)
            {
                NodesExchangeData[] frames = plotData.Geometry.NodesAnimation;
                int[] sampleIndices = GetVectorPlotSampleIndices(frames[0].Ids, frames[0].Coor,
                                                                  GetExtremeValueIndices(frames));
                ApplyAnimatedPlotSampling(frames, sampleIndices);
                plotData.Geometry.Nodes = frames[0];
            }
            // Start drawing
            _form.Clear3D();
            //
            ApplyResultsUnitSystem();
            // Settings - must be here before drawing parts to correctly set the numer of colors
            SetPostLegendAndStatusBlockSettings();
            SetStatusBlock(scale);
            //
            vtkMaxActorData data;
            vtkRendererLayer layer = vtkRendererLayer.Base;
            //
            bool result = true;
            PostSettings postSettings = _settings.Post;
            List<string> hiddenActors = new List<string>();
            List<string> hiddenRepresentationPartNames = new List<string>();
            double[] allFramesScalarRange = new double[] { double.MaxValue, -double.MaxValue };
            //
            foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
            {
                if (entry.Value is ResultPart resultPart)
                {
                    // Undeformed
                    if (postSettings.UndeformedModelType != UndeformedModelTypeEnum.None)
                        DrawUndeformedPartCopy(resultPart, postSettings.UndeformedModelType,
                                               postSettings.UndeformedModelColor, layer);
                    // Deformed
                    data = partData[resultPart];
                    // Min max
                    if (entry.Value.Visible)
                    {
                        foreach (NodesExchangeData nData in data.Geometry.ExtremeNodesAnimation)
                        {
                            if (nData != null)
                            {
                                if (nData.Values[0] < allFramesScalarRange[0]) allFramesScalarRange[0] = nData.Values[0];
                                if (nData.Values[1] > allFramesScalarRange[1]) allFramesScalarRange[1] = nData.Values[1];
                            }
                        }
                    }
                    //
                    ApplyLighting(data);
                    result = _form.AddAnimatedScalarFieldOn3DCells(data);
                    if (result == false) { _form.Clear3D(); return false; }
                    if (plotPartData.ContainsKey(resultPart) && !resultPart.ResultRepresentation)
                        hiddenRepresentationPartNames.Add(resultPart.Name);
                }
                else if (entry.Value is GeometryPart)
                {
                    // For the Section view to work: pickable = true 
                    DrawGeomPart(_allResults.CurrentResult.Mesh, entry.Value, layer, false, true);
                }
                if (!entry.Value.Visible) hiddenActors.Add(entry.Key);
            }
            if (!AddAnimatedPlotActors(plotPartData.Values.ToList(), animatedPlotMaxValue))
            {
                _form.Clear3D();
                return false;
            }
            if (hiddenRepresentationPartNames.Count > 0)
                _form.UpdateResultRepresentationVisibility(hiddenRepresentationPartNames.ToArray(), false, false);
            if (hiddenActors.Count > 0) _form.HideActors(hiddenActors.ToArray(), true);
            // Transformation
            ApplyTransformation();
            // Annotations
            _annotations.DrawAnnotations();
            // Section view
            ApplySectionView();
            // Animation field data
            float[] time = new float[numFrames];
            int[] stepId = new int[numFrames];
            int[] stepIncrementId = new int[numFrames];
            int[] modeNumber = new int[numFrames];
            int[] nodalDiameter = new int[numFrames];
            float[] animationScale = angles;
            for (int i = 0; i < numFrames; i++)
            {
                time[i] = _currentFieldData.Time;
                stepId[i] = _currentFieldData.StepId;
                stepIncrementId[i] = _currentFieldData.StepIncrementId;
                modeNumber[i] = _currentFieldData.ModeNumber;
                nodalDiameter[i] = _currentFieldData.NodalDiameter;
            }
            //
            _form.SetAnimationFrameData(time, stepId, stepIncrementId, modeNumber, nodalDiameter, animationScale,
                                        allFramesScalarRange, vtkMaxAnimationType.Harmonic);
            //
            return result;
        }
        private vtkMaxActorData GetScaleFactorAnimationDataFromPart(ResultPart part, FieldData fieldData,
                                                                    float scale, int numFrames)
        {
            // Get visualization nodes and renumbered elements
            PartExchangeData modelResultData;
            PartExchangeData modelEdgesResultData;
            _allResults.CurrentResult.GetScaleFactorAnimationData(part, fieldData, scale, numFrames,
                                                                  out modelResultData, out modelEdgesResultData);
            //
            vtkMaxActorData data = GetVtkData(modelResultData, modelEdgesResultData);
            SetVolumeGridData(data, _allResults.CurrentResult.Mesh, part);
            data.Name = part.Name;
            GetPartColor(part, ref data.Color, ref data.BackfaceColor);
            data.ColorContours = _viewResultsType == ViewResultsTypeEnum.ColorContours &&
                                 part.ResultRepresentation;
            data.CanHaveElementEdges = true;
            data.Pickable = false;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            data.ActorRepresentation = GetRepresentation(part);
            data.NodeSize = Globals.BeamNodeSize;
            // Back face
            if (part.PartType == PartType.Shell) data.BackfaceCulling = false;
            //
            return data;
        }
        private vtkMaxActorData GetTimeIncrementAnimationDataFromPart(ResultPart part, FieldData fieldData,
                                                                      float scale)
        {
            // Get visualization nodes and renumbered elements
            PartExchangeData modelResultData;
            PartExchangeData modelEdgesResultData;
            _allResults.CurrentResult.GetTimeIncrementAnimationData(part, fieldData, scale,
                                                                    out modelResultData, out modelEdgesResultData);
            //
            vtkMaxActorData data = GetVtkData(modelResultData, modelEdgesResultData);
            SetVolumeGridData(data, _allResults.CurrentResult.Mesh, part);
            data.Name = part.Name;
            GetPartColor(part, ref data.Color, ref data.BackfaceColor);
            data.ColorContours = _viewResultsType == ViewResultsTypeEnum.ColorContours &&
                                 part.ResultRepresentation;
            data.CanHaveElementEdges = true;
            data.Pickable = false;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            data.ActorRepresentation = GetRepresentation(part);
            data.NodeSize = Globals.BeamNodeSize;
            // Back face
            if (part.PartType == PartType.Shell) data.BackfaceCulling = false;
            //
            return data;
        }
        // Common
        private void SetPostLegendAndStatusBlockSettings()
        {
            if (_allResults.CurrentResult != null)
            {
                _allResults.CurrentResult.DeformationFieldOutputName = _form.GetDeformationVariable();
                _allResults.CurrentResult.SetComplexResultTypeAndAngle(_form.GetComplexResultType(),
                                                                       (float)_form.GetComplexAngleDeg());
                UpdateCurrentFieldData();
            }
            //
            // the legend and the status block are drawn only while the results view is displayed
            bool resultPlotActive = _currentView == ViewGeometryModelResults.Results &&
                                    (_viewResultsType == ViewResultsTypeEnum.ColorContours ||
                                     _viewResultsType == ViewResultsTypeEnum.VectorPlot ||
                                     _viewResultsType == ViewResultsTypeEnum.TensorPlot);
            _form.SetScalarBarVisibility(resultPlotActive);
            //
            if (resultPlotActive)
            {
                SettingsContainer settings = Settings;    // use Settings property to account for the results view
                LegendSettings legendSettings = settings.Legend;
                NumberFormatSettings numberFormatSettings = settings.NumberFormat;
                StatusBlockSettings statusBlockSettings = settings.StatusBlock;
                // Legend settings
                _form.SetScalarBarColorSpectrum(legendSettings.ColorSpectrum);
                string complexComponent;
                Field field = _allResults.CurrentResult.GetField(_currentFieldData);
                if (field != null && field.Complex)
                {
                    ComplexResultTypeEnum resultType = _form.GetComplexResultType();
                    complexComponent = resultType.GetDisplayedName();
                    if (resultType == ComplexResultTypeEnum.RealAtAngle)
                    {
                        complexComponent += " " + _form.GetComplexAngleDeg() + " " +
                                            StringAngleDegConverter.GetUnitAbbreviation();
                    }
                }
                else complexComponent = null;
                //
                _form.SetScalarBarText(_currentFieldData.Name, _currentFieldData.Component,
                                       GetCurrentResultsUnitAbbreviation(),
                                       complexComponent,
                                       legendSettings.ColorSpectrum.MinMaxType.ToString());
                //
                _form.SetScalarBarNumberFormat(numberFormatSettings.GetNumberFormat());
                _form.DrawLegendBackground(legendSettings.BackgroundType == AnnotationBackgroundType.White);
                _form.DrawLegendBorder(legendSettings.DrawBorder);
                // Status block
                _form.SetStatusBlockNumberFormat(numberFormatSettings.GetNumberFormat());
                _form.SetStatusBlockVisibility(statusBlockSettings.Visible);
                _form.DrawStatusBlockBackground(statusBlockSettings.BackgroundType == AnnotationBackgroundType.White);
                _form.DrawStatusBlockBorder(statusBlockSettings.DrawBorder);
            }
        }
        private void SetStatusBlock(float scale)
        {
            string unit;
            if (_currentFieldData.StepType == StepTypeEnum.Static)
                unit = _allResults.CurrentResult.UnitSystem.TimeUnitAbbreviation;
            else if (_currentFieldData.StepType == StepTypeEnum.Frequency)
                unit = _allResults.CurrentResult.UnitSystem.FrequencyUnitAbbreviation;
            else if (_currentFieldData.StepType == StepTypeEnum.FrequencySensitivity)
                unit = _allResults.CurrentResult.UnitSystem.FrequencyUnitAbbreviation;
            else if (_currentFieldData.StepType == StepTypeEnum.Buckling)
                unit = "";
            else if (_currentFieldData.StepType == StepTypeEnum.SteadyStateDynamics)
                unit = _allResults.CurrentResult.UnitSystem.FrequencyUnitAbbreviation;
            else if (_currentFieldData.StepType == StepTypeEnum.LastIterations)
                unit = _allResults.CurrentResult.UnitSystem.TimeUnitAbbreviation;
            else throw new NotSupportedException();
            // Deformation variable
            string deformationVariable = _form.GetDeformationVariable();
            //
            vtkMaxFieldDataType fieldType = ConvertStepType(_currentFieldData);
            //
            int stepNumber = _currentFieldData.StepId;
            int incrementNumber = _currentFieldData.StepIncrementId;
            if (_currentFieldData.StepType == StepTypeEnum.Frequency && _currentFieldData.ModeNumber >= 0)
                incrementNumber = _currentFieldData.ModeNumber;
            int nodalDiameter = _currentFieldData.NodalDiameter;
            //
            _form.SetStatusBlock(Path.GetFileName(_allResults.CurrentResult.FileName), _allResults.CurrentResult.DateTime,
                                 _currentFieldData.Time, unit, deformationVariable, scale, fieldType, stepNumber, incrementNumber,
                                 nodalDiameter);
        }
        private vtkMaxFieldDataType ConvertStepType(FieldData fieldData)
        {
            vtkMaxFieldDataType fieldType;
            if (fieldData.StepType == StepTypeEnum.Static) fieldType = vtkMaxFieldDataType.Static;
            else if (fieldData.StepType == StepTypeEnum.Frequency) fieldType = vtkMaxFieldDataType.Frequency;
            else if (fieldData.StepType == StepTypeEnum.FrequencySensitivity) fieldType = vtkMaxFieldDataType.FrequencySensitivity;
            else if (fieldData.StepType == StepTypeEnum.Buckling) fieldType = vtkMaxFieldDataType.Buckling;
            else if (fieldData.StepType == StepTypeEnum.SteadyStateDynamics) fieldType = vtkMaxFieldDataType.SteadyStateDynamic;
            else if (fieldData.StepType == StepTypeEnum.LastIterations) fieldType = vtkMaxFieldDataType.LastIterations;
            else throw new NotSupportedException();
            return fieldType;
        }
        public void UpdatePartsScalarFields()
        {
            if (_allResults.CurrentResult == null || _allResults.CurrentResult.Mesh == null) return;
            // Settings                                                              
            SetPostLegendAndStatusBlockSettings();
            //
            Octree.Plane plane = _sectionViews.GetCurrentSectionViewPlane();
            if (plane != null) _form.RemoveSectionView();
            //
            foreach (var entry in _allResults.CurrentResult.Mesh.Parts)
            {
                if (entry.Value is ResultPart)
                {
                    // Get visualization nodes and renumbered elements - to scale min nad max nodes coor
                    PartExchangeData actorResultData =
                        _allResults.CurrentResult.GetVisualizationNodesCellsAndValues(entry.Value, _currentFieldData);
                    // The volume grid values are fetched when the grid is next built
                    _form.UpdateActorSurfaceScalarField(entry.Key, actorResultData.Nodes.Values, actorResultData.ExtremeNodes,
                                                        actorResultData.Nodes.ResultField, false);
                }
            }
            // Annotations
            _annotations.DrawAnnotations();
            //
            if (plane != null) ApplySectionView();
            //
            _form.UpdateScalarsAndRedraw();
        }
        public void DrawUndeformedPartCopy(BasePart part, UndeformedModelTypeEnum undeformedModelType,
                                           Color color, vtkRendererLayer layer)
        {
            vtkMaxActorData data;
            data = new vtkMaxActorData();
            data.Name = part.Name + "_undeformed";
            data.Color = color;
            data.Layer = layer;
            data.CanHaveElementEdges = false;
            data.SmoothShaded = part.SmoothShaded;
            data.IsAPart = true;
            //
            if (undeformedModelType == UndeformedModelTypeEnum.WireframeBody)
            {
                data.ActorRepresentation = vtkMaxActorRepresentation.Wire;
                data.UseEdgeVisibility = false;
                //
                if (data.Color.A == 255) data.Color = Color.FromArgb(254, data.Color);
                _allResults.CurrentResult.GetUndeformedModelEdges(part, out data.Geometry.Nodes.Coor,
                                                                  out data.Geometry.Cells.CellNodeIds,
                                                                  out data.Geometry.Cells.Types);
            }
            else if(undeformedModelType == UndeformedModelTypeEnum.SolidBody)
            {
                data.ActorRepresentation = vtkMaxActorRepresentation.Solid;
                _allResults.CurrentResult.GetUndeformedNodesAndCells(part, out data.Geometry.Nodes.Coor,
                                                                     out data.Geometry.Cells.CellNodeIds,
                                                                     out data.Geometry.Cells.Types);
            }
            //
            ApplyLighting(data);
            _form.Add3DCells(data);
        }        
        private void ApplyTransformation()
        {
            List<Transformation> transformations = _transformations.GetCurrentTransformations();
            if (transformations != null && transformations.Count >= 1)
            {
                foreach (var transformation in transformations)
                {
                    if (transformation is Symmetry sym)
                    {
                        _form.AddSymmetry((int)sym.SymmetryPlane, sym.PointCoor);
                    }
                    else if (transformation is LinearPattern lp)
                    {
                        _form.AddLinearPattern(lp.Displacement, lp.NumberOfItems);
                    }
                    else if (transformation is CircularPattern cp)
                    {
                        _form.AddCircularPattern(cp.AxisFirstPoint, cp.AxisNormal, cp.Angle, cp.NumberOfItems);
                    }
                    else throw new NotSupportedException();
                }
                _form.ApplyTransformations();
            }
        }
